window.NEWQ={"questions":[{"id":5001,"img":"newq-art/5001.png","c":"7.18","sda":"Du vil standse og sætte en passager af. Den ledige plads ved kantstenen ligger lige før fodgængerfeltet. Hvad gælder?","sfa":"می‌خواهید بایستید و مسافری را پیاده کنید. جای خالی کنار جدول درست پیش از گذرگاه عابر پیاده است. چه قاعده‌ای برقرار است؟","sen":"You want to stop and let a passenger out. The free space at the kerb is right before the pedestrian crossing. What applies?","st":[{"da":"Jeg må gerne standse her, fordi det kun er et kort ophold.","fa":"می‌توانم این‌جا بایستم، چون فقط توقفی کوتاه است.","ok":0,"eda":"Nej. Standsning er forbudt på fodgængerfeltet og inden for 5 m før det, også et kort ophold.","efa":"خیر. توقف روی گذرگاه عابر و تا ۵ متر پیش از آن ممنوع است، حتی کوتاه.","en":"I may stop here because it is only a short stop.","een":"No. Stopping is forbidden on the crossing and within 5 m before it, even for a short while."},{"da":"Jeg må ikke standse nærmere end 5 m før fodgængerfeltet.","fa":"نباید نزدیک‌تر از ۵ متر پیش از گذرگاه عابر بایستم.","ok":1,"eda":"Ja. Færdselsloven § 29 forbyder standsning og parkering på fodgængerfeltet og inden for 5 m før det.","efa":"بله. ماده‌ی ۲۹ قانون، توقف و پارک روی گذرگاه عابر و تا ۵ متر پیش از آن را ممنوع می‌کند.","en":"I must not stop closer than 5 m before the pedestrian crossing.","een":"Yes. Færdselsloven § 29 forbids stopping and parking on the crossing and within 5 m before it."},{"da":"Jeg må standse på selve fodgængerfeltet, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم روی خود گذرگاه بایستم.","ok":0,"eda":"Nej. Havariblink giver ikke ret til at standse på et fodgængerfelt.","efa":"خیر. چراغ خطر اجازه‌ی توقف روی گذرگاه عابر را نمی‌دهد.","en":"I may stop on the crossing itself if I switch on the hazard lights.","een":"No. Hazard lights do not give a right to stop on a pedestrian crossing."},{"da":"En bil, der holder lige før feltet, kan skjule fodgængere for andre trafikanter.","fa":"خودرویی که درست پیش از گذرگاه ایستاده، می‌تواند عابران را از دید دیگران پنهان کند.","ok":1,"eda":"Ja. Det er grunden til forbuddet: andre kan ikke se den, der går ud foran den holdende bil.","efa":"بله. دلیل این ممنوعیت همین است: دیگران کسی را که از جلوی خودروی ایستاده وارد خیابان می‌شود نمی‌بینند.","en":"A car standing right before the crossing can hide pedestrians from other road users.","een":"Yes. That is why it is forbidden: others cannot see someone stepping out in front of the standing car."}]},{"id":5002,"img":"newq-art/5002.png","c":"7.18","sda":"Du vil standse et øjeblik for at aflevere en pakke i butikken til højre. Hvor må du holde?","sfa":"می‌خواهید لحظه‌ای بایستید تا بسته‌ای را به مغازه‌ی سمت راست بدهید. کجا می‌توانید بایستید؟","sen":"You want to stop for a moment to drop off a parcel at the shop on the right. Where may you stop?","st":[{"da":"Halvt oppe på fortovet, så jeg ikke generer trafikken.","fa":"نیمی روی پیاده‌رو، تا مزاحم ترافیک نباشم.","ok":0,"eda":"Nej. Det er forbudt at standse eller parkere på fortovet.","efa":"خیر. توقف یا پارک روی پیاده‌رو ممنوع است.","en":"Half up on the pavement, so that I am not in the way of traffic.","een":"No. It is forbidden to stop or park on the pavement."},{"da":"På kørebanen ved siden af en bil, der holder ved kanten.","fa":"روی سواره‌رو، کنار خودرویی که لب جدول ایستاده.","ok":0,"eda":"Nej. Du skal holde ved kørebanens yderkant; ved siden af en anden bil spærrer du for trafikken.","efa":"خیر. باید کنار لبه‌ی سواره‌رو بایستید؛ کنار خودروی دیگر راه ترافیک را می‌بندید.","en":"On the carriageway beside a car that is standing at the edge.","een":"No. You must stop at the edge of the carriageway; beside another car you block the traffic."},{"da":"På cykelstien, hvis jeg tænder havariblinket.","fa":"روی مسیر دوچرخه، اگر چراغ خطر را روشن کنم.","ok":0,"eda":"Nej. Standsning og parkering er forbudt på cykelstier, også med havariblink.","efa":"خیر. توقف و پارک روی مسیر دوچرخه ممنوع است، با چراغ خطر یا بدون آن.","en":"On the cycle path, if I switch on the hazard lights.","een":"No. Stopping and parking are forbidden on cycle paths, hazard lights or not."},{"da":"Ved kørebanens yderkant, hvis der ikke gælder andre forbud.","fa":"کنار لبه‌ی سواره‌رو، اگر ممنوعیت دیگری نباشد.","ok":1,"eda":"Ja. Man standser i vejens højre side ved kørebanens yderkant, når det ikke er forbudt eller til fare.","efa":"بله. توقف در سمت راست جاده و کنار لبه‌ی سواره‌رو است، جایی که ممنوع یا خطرناک نباشد.","en":"At the edge of the carriageway, if no other ban applies.","een":"Yes. You stop on the right side of the road at the edge of the carriageway, where it is not forbidden or dangerous."}]},{"id":5003,"img":"newq-art/5003.png","c":"7.18","sda":"Du vil parkere på den ledige plads lige før sidevejen til højre. Pladsen ligger omkring 5 m fra hjørnet. Hvad gælder?","sfa":"می‌خواهید در جای خالی درست پیش از فرعیِ سمت راست پارک کنید. این جا حدود ۵ متر با گوشه فاصله دارد. چه قاعده‌ای برقرار است؟","sen":"You want to park in the free space just before the side road on the right. The space is about 5 m from the corner. What applies?","st":[{"da":"Jeg må hverken standse eller parkere nærmere end 10 m fra den tværgående kørebanes nærmeste kant.","fa":"نه می‌توانم بایستم و نه پارک کنم، اگر کمتر از ۱۰ متر با نزدیک‌ترین لبه‌ی سواره‌روی متقاطع فاصله داشته باشم.","ok":1,"eda":"Ja. Færdselsloven § 29 forbyder standsning og parkering inden for 10 m fra et vejkryds.","efa":"بله. ماده‌ی ۲۹ قانون، توقف و پارک تا ۱۰ متری تقاطع را ممنوع می‌کند.","en":"I may neither stop nor park closer than 10 m to the nearest edge of the crossing carriageway.","een":"Yes. Færdselsloven § 29 forbids stopping and parking within 10 m of a junction."},{"da":"Forbuddet gælder kun i kryds med lyssignal.","fa":"این ممنوعیت فقط در تقاطع‌های چراغ‌دار است.","ok":0,"eda":"Nej. Forbuddet gælder ved alle vejkryds.","efa":"خیر. این ممنوعیت در همه‌ی تقاطع‌ها برقرار است.","en":"The ban only applies at junctions with traffic lights.","een":"No. The ban applies at every junction."},{"da":"Reglen om de 10 m gælder kun parkering, ikke en kort standsning.","fa":"قاعده‌ی ۱۰ متر فقط برای پارک است، نه توقف کوتاه.","ok":0,"eda":"Nej. Både standsning og parkering er forbudt nærmere end 10 m fra krydset, fordi en holdende bil tager oversigten fra andre.","efa":"خیر. هم توقف و هم پارک در فاصله‌ی کمتر از ۱۰ متر از تقاطع ممنوع است، چون خودروی ایستاده دید دیگران را می‌گیرد.","en":"The 10 m rule only applies to parking, not to a short stop.","een":"No. Both stopping and parking are forbidden closer than 10 m to the junction, because a standing car blocks other people's view."},{"da":"Jeg må gerne parkere her, hvis jeg holder helt inde ved kantstenen.","fa":"اگر کاملاً کنار جدول بایستم، می‌توانم این‌جا پارک کنم.","ok":0,"eda":"Nej. Afstanden til krydset er for kort, uanset hvor tæt på kantstenen bilen holder.","efa":"خیر. فاصله تا تقاطع کم است، هر قدر هم خودرو به جدول نزدیک باشد.","en":"I may park here if I stand right in at the kerb.","een":"No. The distance to the junction is too short, however close to the kerb the car stands."}]},{"id":5004,"img":"newq-art/5004.png","c":"7.18","sda":"Du vil standse ved stoppestedet for at hente en ven. Der er ingen afmærkning på kørebanen. Hvad gælder?","sfa":"می‌خواهید کنار ایستگاه اتوبوس بایستید تا دوستی را سوار کنید. روی سواره‌رو خط‌کشی نیست. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the bus stop to pick up a friend. There are no markings on the road. What applies?","st":[{"da":"Jeg må ikke standse inden for 12 m på hver side af stoppestedsskiltet.","fa":"نباید تا ۱۲ متر در هر دو طرف تابلوی ایستگاه بایستم.","ok":1,"eda":"Ja. Uden afmærkning gælder forbuddet mod standsning og parkering 12 m på hver side af skiltet.","efa":"بله. بدون خط‌کشی، ممنوعیت توقف و پارک ۱۲ متر در هر طرف تابلو است.","en":"I must not stop within 12 m on either side of the bus-stop sign.","een":"Yes. Without markings, the ban on stopping and parking covers 12 m on each side of the sign."},{"da":"Jeg må standse, hvis jeg bliver siddende i bilen.","fa":"اگر داخل خودرو بمانم، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder også, selv om føreren bliver i bilen.","efa":"خیر. این ممنوعیت حتی اگر راننده در خودرو بماند هم برقرار است.","en":"I may stop if I stay sitting in the car.","een":"No. The ban applies even if the driver stays in the car."},{"da":"Jeg må standse, når der ikke er nogen bus i nærheden.","fa":"وقتی اتوبوسی نزدیک نیست، می‌توانم بایستم.","ok":0,"eda":"Nej. Forbuddet gælder hele tiden, ikke kun når der kommer en bus.","efa":"خیر. این ممنوعیت همیشه هست، نه فقط وقتی اتوبوس می‌آید.","en":"I may stop when there is no bus nearby.","een":"No. The ban applies all the time, not only when a bus is coming."},{"da":"Forbuddet gælder kun parkering, ikke en kort standsning.","fa":"این ممنوعیت فقط برای پارک است، نه توقف کوتاه.","ok":0,"eda":"Nej. Ved stoppestedet er både standsning og parkering forbudt.","efa":"خیر. کنار ایستگاه، هم توقف و هم پارک ممنوع است.","en":"The ban only covers parking, not a short stop.","een":"No. At the bus stop both stopping and parking are forbidden."}]},{"id":5005,"img":"newq-art/5005.png","c":"7.18","sda":"Du kører i en ensrettet gade og vil parkere i venstre side. Hvad gælder?","sfa":"در یک خیابان یک‌طرفه می‌رانید و می‌خواهید در سمت چپ پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You are driving in a one-way street and want to park on the left side. What applies?","st":[{"da":"Bilen skal holde i vejens længderetning ved kanten.","fa":"خودرو باید در امتداد طول جاده و کنار لبه بایستد.","ok":1,"eda":"Ja. Køretøjer skal holde parallelt med vejen ved kørebanens yderkant.","efa":"بله. خودروها باید موازی جاده و کنار لبه‌ی سواره‌رو بایستند.","en":"The car must stand lengthwise along the road at the edge.","een":"Yes. Vehicles must stand parallel to the road at the edge of the carriageway."},{"da":"Man må aldrig parkere i venstre side af vejen.","fa":"هرگز نمی‌توان در سمت چپ جاده پارک کرد.","ok":0,"eda":"Nej. På ensrettede veje og mindre befærdede veje er det tilladt.","efa":"خیر. در جاده‌های یک‌طرفه و کم‌تردد مجاز است.","en":"You may never park on the left side of the road.","een":"No. On one-way roads and roads with little traffic it is allowed."},{"da":"På en vej med ensrettet færdsel må jeg standse og parkere i venstre side.","fa":"در جاده‌ی یک‌طرفه می‌توانم در سمت چپ بایستم و پارک کنم.","ok":1,"eda":"Ja. Færdselsloven § 28 tillader standsning og parkering i venstre side på ensrettede veje og mindre befærdede veje.","efa":"بله. ماده‌ی ۲۸ قانون، توقف و پارک در سمت چپ را در جاده‌های یک‌طرفه و کم‌تردد مجاز می‌داند.","en":"On a one-way road I may stop and park on the left side.","een":"Yes. Færdselsloven § 28 allows stopping and parking on the left on one-way roads and roads with little traffic."}]},{"id":5006,"img":"newq-art/5006.png","c":"7.18","sda":"Du parkerer kl. 14.05 ved denne tavle. Hvordan stiller du P-skiven?","sfa":"ساعت ۱۴:۰۵ کنار این تابلو پارک می‌کنید. صفحه‌ی پارک (P-skive) را چطور تنظیم می‌کنید؟","sen":"You park at 14:05 at this sign. How do you set the parking disc?","st":[{"da":"På kl. 14.05.","fa":"روی ساعت ۱۴:۰۵.","ok":0,"eda":"Nej. Skiven stilles ikke på det præcise klokkeslæt, men på det næste hele kvarter efter ankomsten, her 14.15.","efa":"خیر. صفحه روی ساعت دقیق تنظیم نمی‌شود، بلکه روی ربع‌ساعت بعد از رسیدن؛ این‌جا ۱۴:۱۵.","en":"To 14:05.","een":"No. The disc is not set to the exact time but to the next quarter hour after you arrive, here 14:15."},{"da":"På kl. 14.15.","fa":"روی ساعت ۱۴:۱۵.","ok":1,"eda":"Ja. P-skiven stilles på det kvarter, der kommer efter ankomsttidspunktet.","efa":"بله. صفحه‌ی پارک روی ربع‌ساعتی تنظیم می‌شود که بعد از زمان رسیدن می‌آید.","en":"To 14:15.","een":"Yes. The disc is set to the quarter hour that follows the time you arrived."},{"da":"På kl. 16.05, når jeg skal køre igen.","fa":"روی ساعت ۱۶:۰۵، وقتی باید دوباره حرکت کنم.","ok":0,"eda":"Nej. Skiven viser ankomsten, ikke hvornår du kører; tavlen siger, hvor længe du må holde.","efa":"خیر. صفحه زمان رسیدن را نشان می‌دهد، نه زمان رفتن را؛ تابلو می‌گوید چقدر می‌توانید بمانید.","en":"To 16:05, when I have to drive off again.","een":"No. The disc shows when you arrived, not when you leave; the sign says how long you may stay."},{"da":"På kl. 14.00.","fa":"روی ساعت ۱۴:۰۰.","ok":0,"eda":"Nej. Skiven må ikke stilles på et tidspunkt før ankomsten.","efa":"خیر. صفحه را نباید روی زمانی پیش از رسیدن تنظیم کرد.","en":"To 14:00.","een":"No. The disc must not be set to a time before you arrived."}]},{"id":5007,"img":"newq-art/5007.png","c":"7.18","sda":"Langs kantstenen er der en ubrudt gul linje. Du vil hente brød i bageren og regner med at være væk i 2 minutter. Hvad gælder?","sfa":"کنار جدول خط زرد ممتدی کشیده شده است. می‌خواهید از نانوایی نان بخرید و فکر می‌کنید ۲ دقیقه طول بکشد. چه قاعده‌ای برقرار است؟","sen":"There is an unbroken yellow line along the kerb. You want to fetch bread at the bakery and expect to be gone for 2 minutes. What applies?","st":[{"da":"Jeg må holde her i 2 minutter, fordi det ikke er parkering.","fa":"می‌توانم ۲ دقیقه این‌جا بایستم، چون پارک حساب نمی‌شود.","ok":0,"eda":"Nej. En ubrudt gul linje betyder, at også standsning er forbudt.","efa":"خیر. خط زرد ممتد یعنی توقف هم ممنوع است.","en":"I may stand here for 2 minutes because it is not parking.","een":"No. An unbroken yellow line means that stopping is forbidden too."},{"da":"Den gule linje gælder kun om natten.","fa":"خط زرد فقط شب‌ها معتبر است.","ok":0,"eda":"Nej. Linjen gælder hele døgnet, medmindre en tavle siger andet.","efa":"خیر. این خط در تمام شبانه‌روز معتبر است، مگر تابلویی چیز دیگری بگوید.","en":"The yellow line only applies at night.","een":"No. The line applies all day and night unless a sign says otherwise."},{"da":"Den gule linje betyder, at jeg højst må holde her i 15 minutter.","fa":"خط زرد یعنی حداکثر ۱۵ دقیقه می‌توانم این‌جا بایستم.","ok":0,"eda":"Nej. En ubrudt gul linje giver ingen tid at holde i; den forbyder standsning og parkering.","efa":"خیر. خط زرد ممتد هیچ زمانی برای ایستادن نمی‌دهد؛ توقف و پارک را ممنوع می‌کند.","en":"The yellow line means that I may stand here for at most 15 minutes.","een":"No. An unbroken yellow line gives no time to stand at all; it forbids stopping and parking."},{"da":"Her er både standsning og parkering forbudt.","fa":"این‌جا هم توقف و هم پارک ممنوع است.","ok":1,"eda":"Ja. Den ubrudte gule kantlinje forbyder standsning og parkering i den side af vejen.","efa":"بله. خط زرد ممتد کنار جدول، توقف و پارک را در آن سمت جاده ممنوع می‌کند.","en":"Here both stopping and parking are forbidden.","een":"Yes. The unbroken yellow kerb line forbids stopping and parking on that side of the road."}]},{"id":5008,"img":"newq-art/5008.png","c":"7.18","sda":"Du parkerer på en stejl vej ned ad bakke. Hvordan sikrer du bilen?","sfa":"در یک سراشیبی تند پارک می‌کنید. خودرو را چطور ایمن می‌کنید؟","sen":"You park on a steep road going downhill. How do you secure the car?","st":[{"da":"Jeg drejer forhjulene ind mod kantstenen.","fa":"چرخ‌های جلو را به سمت جدول می‌چرخانم.","ok":1,"eda":"Ja. Så stopper kantstenen bilen, hvis den alligevel begynder at rulle.","efa":"بله. این‌طور اگر خودرو باز هم راه بیفتد، جدول جلویش را می‌گیرد.","en":"I turn the front wheels in towards the kerb.","een":"Yes. Then the kerb stops the car if it starts to roll anyway."},{"da":"Jeg sætter bilen i bakgear, eller i P, hvis den har automatgear.","fa":"خودرو را در دنده‌عقب می‌گذارم، یا اگر اتوماتیک است، روی P.","ok":1,"eda":"Ja. Et gear, der modvirker bakken, holder bilen ekstra igen, hvis bremsen skulle svigte.","efa":"بله. دنده‌ای که خلاف شیب کار می‌کند، اگر ترمز از کار بیفتد، خودرو را بیشتر نگه می‌دارد.","en":"I put the car in reverse gear, or in P if it is an automatic.","een":"Yes. A gear that works against the slope holds the car back further if the brake should fail."},{"da":"Det er nok at sætte gearet i frigear.","fa":"کافی است دنده را خلاص بگذارم.","ok":0,"eda":"Nej. I frigear kan bilen rulle; det sikrer den ikke.","efa":"خیر. در دنده‌ی خلاص خودرو می‌تواند حرکت کند؛ ایمنش نمی‌کند.","en":"Putting the gear in neutral is enough.","een":"No. In neutral the car can roll; it does not secure it."},{"da":"Jeg trækker parkeringsbremsen.","fa":"ترمز دستی را می‌کشم.","ok":1,"eda":"Ja. Når du forlader bilen, skal du sikre, at den ikke kan sætte i gang af sig selv.","efa":"بله. وقتی خودرو را ترک می‌کنید، باید مطمئن شوید خودبه‌خود راه نمی‌افتد.","en":"I apply the parking brake.","een":"Yes. When you leave the car you must make sure it cannot start moving by itself."}]},{"id":5009,"img":"newq-art/5009.png","c":"7.18","sda":"Du har parkeret og vil stige ud. Bag dig kommer en cyklist. Hvordan forholder du dig?","sfa":"پارک کرده‌اید و می‌خواهید پیاده شوید. از پشت سر دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You have parked and want to get out. A cyclist is coming up behind you. What do you do?","st":[{"da":"Jeg kigger i spejlet og over skulderen, før jeg åbner døren.","fa":"پیش از باز کردن در، در آینه و از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. Så ser du cyklister og biler bagfra, også i den blinde vinkel.","efa":"بله. این‌طور دوچرخه‌ها و خودروهای پشت سر را، حتی در نقطه‌ی کور، می‌بینید.","en":"I look in the mirror and over my shoulder before I open the door.","een":"Yes. That way you see cyclists and cars behind you, also in the blind spot."},{"da":"Jeg venter med at åbne døren, til cyklisten er kørt forbi.","fa":"باز کردن در را تا رد شدن دوچرخه‌سوار عقب می‌اندازم.","ok":1,"eda":"Ja. Når du åbner døren eller stiger ud, må der ikke opstå fare for andre.","efa":"بله. باز کردن در یا پیاده شدن نباید دیگران را به خطر بیندازد.","en":"I wait to open the door until the cyclist has passed.","een":"Yes. Opening the door or getting out must not put others in danger."},{"da":"Mine passagerer skal også sikre sig, at de kan åbne døren uden fare.","fa":"مسافرانم هم باید مطمئن شوند که می‌توانند بی‌خطر در را باز کنند.","ok":1,"eda":"Ja. Pligten til at åbne døre uden fare for andre gælder alle i bilen, ikke kun føreren.","efa":"بله. وظیفه‌ی باز کردن در بدون خطر برای دیگران، برای همه‌ی سرنشینان است، نه فقط راننده.","en":"My passengers must also make sure that they can open the door safely.","een":"Yes. The duty to open doors without danger to others applies to everyone in the car, not only the driver."},{"da":"Jeg åbner døren langsomt, så cyklisten kan nå at se den.","fa":"در را آهسته باز می‌کنم تا دوچرخه‌سوار فرصت دیدنش را داشته باشد.","ok":0,"eda":"Nej. Også en dør, der åbnes langsomt, kan få cyklisten til at styrte.","efa":"خیر. حتی دری که آهسته باز شود، می‌تواند دوچرخه‌سوار را زمین بزند.","en":"I open the door slowly so that the cyclist has time to see it.","een":"No. Even a door opened slowly can make the cyclist crash."}]},{"id":5010,"img":"newq-art/5010.png","c":"7.9","sda":"Du vil overhale traktoren. Hvad skal du sikre dig, før du begynder?","sfa":"می‌خواهید از تراکتور سبقت بگیرید. پیش از شروع، از چه چیزهایی باید مطمئن شوید؟","sen":"You want to overtake the tractor. What must you make sure of before you start?","st":[{"da":"At der ikke er andre hindringer for overhalingen længere fremme.","fa":"این‌که جلوتر مانع دیگری برای سبقت نباشد.","ok":1,"eda":"Ja. Ud over modkørende må der heller ikke være andre hindringer, fx en vejindsnævring eller et kryds.","efa":"بله. به‌جز ترافیک روبه‌رو، نباید مانع دیگری هم باشد، مثلاً باریک شدن جاده یا تقاطع.","en":"That there are no other obstacles to the overtaking further ahead.","een":"Yes. Besides oncoming traffic, there must be no other obstacles either, for example a narrowing of the road or a junction."},{"da":"At ingen bagfra er begyndt at overhale mig.","fa":"این‌که کسی از پشت شروع به سبقت از من نکرده است.","ok":1,"eda":"Ja. Du må ikke begynde at overhale, hvis en bagfra allerede er i gang med at overhale dig.","efa":"بله. اگر کسی از پشت سبقت از شما را شروع کرده، نباید سبقت را آغاز کنید.","en":"That nobody behind me has started to overtake me.","een":"Yes. You must not start overtaking if someone behind has already started to overtake you."},{"da":"At den modkørende vognbane er fri over en tilstrækkelig lang strækning.","fa":"این‌که خط روبه‌رو به اندازه‌ی کافی خالی است.","ok":1,"eda":"Ja. Den, der overhaler, skal sikre sig, at vognbanen er fri for modkørende og andre hindringer langt nok frem.","efa":"بله. سبقت‌گیرنده باید مطمئن شود که خط تا فاصله‌ی کافی از خودروی روبه‌رو و مانع خالی است.","en":"That the oncoming lane is clear over a long enough distance.","een":"Yes. The overtaking driver must make sure the lane is free of oncoming traffic and obstacles far enough ahead."},{"da":"At jeg kan komme tilbage i højre side uden fare for traktoren.","fa":"این‌که بتوانم بی‌خطر برای تراکتور به سمت راست برگردم.","ok":1,"eda":"Ja. Du skal kunne vende tilbage til højre side, uden at den overhalede kommer i fare eller ulejlighed.","efa":"بله. باید بتوانید بی‌آنکه وسیله‌ی سبقت‌گرفته به خطر یا زحمت بیفتد، به سمت راست برگردید.","en":"That I can get back to the right without danger to the tractor.","een":"Yes. You must be able to return to the right without putting the overtaken vehicle in danger or trouble."}]},{"id":5011,"img":"newq-art/5011.png","c":"7.9","sda":"En bil er ved at overhale dig. Hvordan forholder du dig?","sfa":"خودرویی در حال سبقت از شماست. چه می‌کنید؟","sen":"A car is overtaking you. What do you do?","st":[{"da":"Jeg blinker til venstre for at vise, at bilen kan overhale.","fa":"راهنمای چپ می‌زنم تا نشان دهم خودرو می‌تواند سبقت بگیرد.","ok":0,"eda":"Nej. Et blink til venstre betyder, at du selv vil ud til venstre, og kan misforstås farligt.","efa":"خیر. راهنمای چپ یعنی خودتان می‌خواهید به چپ بروید و ممکن است به‌طرز خطرناکی اشتباه فهمیده شود.","en":"I signal left to show that the car can overtake.","een":"No. A left signal means that you yourself are going to move left, and it can be dangerously misunderstood."},{"da":"Jeg holder så langt til højre som muligt.","fa":"تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Den, der bliver overhalet, skal holde så langt til højre som muligt.","efa":"بله. کسی که از او سبقت می‌گیرند، باید تا جای ممکن سمت راست بماند.","en":"I keep as far to the right as possible.","een":"Yes. The driver being overtaken must keep as far to the right as possible."},{"da":"Jeg bremser hårdt, så bilen hurtigt kan komme forbi.","fa":"محکم ترمز می‌کنم تا خودرو زود رد شود.","ok":0,"eda":"Nej. Pludselig hård opbremsning kan skabe fare for bilerne bag dig.","efa":"خیر. ترمز ناگهانی و محکم می‌تواند خودروهای پشت سر را به خطر بیندازد.","en":"I brake hard so that the car can get past quickly.","een":"No. Sudden hard braking can put the cars behind you in danger."},{"da":"Jeg øger farten, så overhalingen går hurtigere.","fa":"سرعتم را زیاد می‌کنم تا سبقت زودتر تمام شود.","ok":0,"eda":"Nej. Det gør overhalingen længere og farligere; du må ikke øge hastigheden.","efa":"خیر. این کار سبقت را طولانی‌تر و خطرناک‌تر می‌کند؛ نباید سرعت را زیاد کنید.","en":"I speed up so that the overtaking goes faster.","een":"No. That makes the overtaking longer and more dangerous; you must not increase your speed."}]},{"id":5012,"img":"newq-art/5012.png","c":"7.9","sda":"Bussen i højre vognbane holder stille lige før fodgængerfeltet. Du kører i venstre vognbane. Hvordan forholder du dig?","sfa":"اتوبوس در خط راست درست پیش از گذرگاه عابر ایستاده است. شما در خط چپ می‌رانید. چه می‌کنید؟","sen":"The bus in the right-hand lane has stopped just before the pedestrian crossing. You are in the left-hand lane. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at standse før feltet.","fa":"سرعتم را کم می‌کنم و آماده‌ی ایستادن پیش از گذرگاه هستم.","ok":1,"eda":"Ja. Bussen kan holde for en fodgænger, du ikke kan se.","efa":"بله. ممکن است اتوبوس برای عابری ایستاده باشد که شما نمی‌بینید.","en":"I slow down and am ready to stop before the crossing.","een":"Yes. The bus may be waiting for a pedestrian you cannot see."},{"da":"Der kan gå en fodgænger ud foran bussen, som jeg ikke kan se.","fa":"ممکن است عابری که نمی‌بینم از جلوی اتوبوس وارد گذرگاه شود.","ok":1,"eda":"Ja. Derfor forbyder Færdselsloven § 25 at køre forbi.","efa":"بله. به همین دلیل ماده‌ی ۲۵ قانون، رد شدن از کنار آن را ممنوع کرده است.","en":"A pedestrian I cannot see may step out in front of the bus.","een":"Yes. That is why Færdselsloven § 25 forbids driving past."},{"da":"Jeg kører forbi bussen, fordi min vognbane er fri.","fa":"از کنار اتوبوس رد می‌شوم، چون خط من خالی است.","ok":0,"eda":"Nej. Du må ikke køre forbi et køretøj, der skjuler udsynet over fodgængerfeltet.","efa":"خیر. نباید از کنار وسیله‌ای که دیدتان را به گذرگاه عابر بسته است رد شوید.","en":"I drive past the bus because my lane is free.","een":"No. You must not drive past a vehicle that blocks your view of the pedestrian crossing."}]},{"id":5013,"img":"newq-art/5013.png","c":"7.9","sda":"Du kører på en vej, hvor trafikken fra sidevejen har ubetinget vigepligt. Hvad gælder for overhaling af varevognen lige før krydset?","sfa":"در جاده‌ای هستید که ترافیک فرعی باید بی‌قیدوشرط راه بدهد. درباره‌ی سبقت از ون درست پیش از تقاطع چه قاعده‌ای برقرار است؟","sen":"You are on a road where traffic from the side road must give way unconditionally. What applies to overtaking the van just before the junction?","st":[{"da":"Jeg må overhale, fordi den tværgående trafik har ubetinget vigepligt, hvis det i øvrigt kan ske uden fare.","fa":"می‌توانم سبقت بگیرم، چون ترافیک متقاطع باید بی‌قیدوشرط راه بدهد، به شرط آن‌که از نظر دیگر هم بی‌خطر باشد.","ok":1,"eda":"Ja. Forbuddet mod overhaling i kryds gælder ikke, når den tværgående trafik har ubetinget vigepligt.","efa":"بله. ممنوعیت سبقت در تقاطع، وقتی ترافیک متقاطع باید بی‌قیدوشرط راه بدهد، اعمال نمی‌شود.","en":"I may overtake because the crossing traffic must give way unconditionally, if it can otherwise be done safely.","een":"Yes. The ban on overtaking at junctions does not apply when the crossing traffic must give way unconditionally."},{"da":"Det er altid forbudt at overhale i et vejkryds.","fa":"سبقت در تقاطع همیشه ممنوع است.","ok":0,"eda":"Nej. Der er undtagelser, blandt andet når den tværgående trafik har ubetinget vigepligt.","efa":"خیر. استثنا وجود دارد، از جمله وقتی ترافیک متقاطع باید بی‌قیدوشرط راه بدهد.","en":"Overtaking at a junction is always forbidden.","een":"No. There are exceptions, for example when the crossing traffic must give way unconditionally."},{"da":"Jeg skal sikre mig, at ingen bagfra er begyndt at overhale mig.","fa":"باید مطمئن شوم که کسی از پشت شروع به سبقت از من نکرده است.","ok":1,"eda":"Ja. Det skal du altid sikre dig, før du begynder at overhale.","efa":"بله. همیشه پیش از شروع سبقت باید از این مطمئن شوید.","en":"I must make sure that nobody behind has started to overtake me.","een":"Yes. You must always make sure of that before you start overtaking."},{"da":"Jeg skal stadig sikre mig, at varevognen ikke skal svinge til venstre.","fa":"باز هم باید مطمئن شوم که ون قصد گردش به چپ ندارد.","ok":1,"eda":"Ja. En bil, der svinger til venstre, må ikke overhales i venstre side.","efa":"بله. از خودرویی که به چپ می‌پیچد نباید از سمت چپ سبقت گرفت.","en":"I must still make sure the van is not going to turn left.","een":"Yes. A car turning left must not be overtaken on its left."}]},{"id":5014,"img":"newq-art/5014.png","c":"7.9","sda":"Lige før krydset kører en cyklist foran dig. Hvad gælder for overhaling af cyklisten?","sfa":"درست پیش از تقاطع، دوچرخه‌سواری جلوی شما می‌رود. درباره‌ی سبقت از او چه قاعده‌ای برقرار است؟","sen":"Just before the junction a cyclist is riding in front of you. What applies to overtaking the cyclist?","st":[{"da":"Jeg behøver ikke holde tilbage for trafik fra højre, når jeg er i gang med at overhale.","fa":"وقتی در حال سبقت هستم، لازم نیست به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Højrevigepligten i krydset gælder stadig.","efa":"خیر. حق تقدم دست راست در تقاطع همچنان برقرار است.","en":"I do not need to give way to traffic from the right while I am overtaking.","een":"No. The duty to give way to the right in the junction still applies."},{"da":"Jeg holder øje med, om cyklisten vil svinge, fx til venstre i krydset.","fa":"مراقبم که آیا دوچرخه‌سوار می‌خواهد بپیچد، مثلاً در تقاطع به چپ.","ok":1,"eda":"Ja. Cyklisten kan svinge i krydset; se efter tegn, før du overhaler.","efa":"بله. دوچرخه‌سوار ممکن است در تقاطع بپیچد؛ پیش از سبقت دنبال علامتش باشید.","en":"I watch whether the cyclist is going to turn, for example left at the junction.","een":"Yes. The cyclist may turn at the junction; look for signals before you overtake."},{"da":"Forbuddet mod overhaling i kryds gælder ikke overhaling af en tohjulet cykel.","fa":"ممنوعیت سبقت در تقاطع شامل دوچرخه‌ی دوچرخ نمی‌شود.","ok":1,"eda":"Ja. Færdselsloven § 23 undtager overhaling af tohjulede cykler og små knallerter.","efa":"بله. ماده‌ی ۲۳ قانون، سبقت از دوچرخه و موپد کوچک دوچرخ را استثنا کرده است.","en":"The ban on overtaking at junctions does not apply to a two-wheeled bicycle.","een":"Yes. Færdselsloven § 23 makes an exception for overtaking two-wheeled bicycles and small mopeds."},{"da":"Det skal kunne ske uden fare, og jeg skal holde god afstand til siden.","fa":"باید بی‌خطر باشد و باید فاصله‌ی پهلوی خوبی نگه دارم.","ok":1,"eda":"Ja. Undtagelsen fritager ikke for kravet om sikkerhed og sideafstand.","efa":"بله. این استثنا نیاز به ایمنی و فاصله‌ی پهلوی را از بین نمی‌برد.","en":"It must be safe, and I must keep a good side distance.","een":"Yes. The exception does not remove the need for safety and side distance."}]},{"id":5015,"img":"newq-art/5015.png","c":"7.9","sda":"Foran dig kører en langsom varevogn op mod en bakketop, hvor du ikke kan se, hvad der kommer. Hvad gælder?","sfa":"جلوی شما ونی آهسته به سمت بالای تپه‌ای می‌رود که نمی‌بینید پشتش چه می‌آید. چه قاعده‌ای برقرار است؟","sen":"In front of you a slow van is driving up towards a hilltop where you cannot see what is coming. What applies?","st":[{"da":"Jeg må ikke overhale ved en uoverskuelig bakketop.","fa":"در بالای تپه‌ی بی‌دید نباید سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling er forbudt, hvor udsynet fremad er begrænset ved bakker og sving.","efa":"بله. سبقت جایی که دید جلو به‌خاطر تپه یا پیچ محدود است، ممنوع است.","en":"I must not overtake at a blind hilltop.","een":"Yes. Overtaking is forbidden where the view ahead is restricted by hills and bends."},{"da":"Forbuddet gælder ikke, hvis der er mindst to vognbaner i min retning, som modkørende ikke må bruge.","fa":"اگر در جهت من دست‌کم دو خط باشد که ترافیک روبه‌رو اجازه‌ی استفاده از آن را ندارد، این ممنوعیت نیست.","ok":1,"eda":"Ja. Så kan du overhale uden at komme over i de modkørendes side.","efa":"بله. در این حالت می‌توانید بدون رفتن به سمت ترافیک روبه‌رو سبقت بگیرید.","en":"The ban does not apply if there are at least two lanes in my direction that oncoming traffic may not use.","een":"Yes. Then you can overtake without moving into the oncoming side."},{"da":"Jeg må overhale, hvis jeg giver fuld gas og skynder mig.","fa":"اگر گاز بدهم و عجله کنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Fart ændrer ikke, at en modkørende kan dukke op over bakken.","efa":"خیر. سرعت این واقعیت را عوض نمی‌کند که ممکن است خودرویی از روبه‌رو از پشت تپه برسد.","en":"I may overtake if I accelerate hard and hurry.","een":"No. Speed does not change that an oncoming car may appear over the hill."}]},{"id":5016,"img":"newq-art/5016.png","c":"7.9","sda":"Den grå bil foran dig blinker til venstre og holder ved midterlinjen for at svinge. Hvordan må du køre forbi?","sfa":"خودروی خاکستری جلوی شما راهنمای چپ زده و کنار خط وسط ایستاده تا بپیچد. چطور می‌توانید از کنارش رد شوید؟","sen":"The grey car in front of you is indicating left and waiting at the centre line to turn. How may you pass it?","st":[{"da":"Jeg skal overhale den i venstre side.","fa":"باید از سمت چپش سبقت بگیرم.","ok":0,"eda":"Nej. Det ville være farligt: bilen er ved at svinge den vej, og der kommer en modkørende.","efa":"خیر. خطرناک است: خودرو در حال پیچیدن به همان سمت است و از روبه‌رو هم خودرویی می‌آید.","en":"I must overtake it on the left.","een":"No. That would be dangerous: the car is about to turn that way, and an oncoming car is coming."},{"da":"Jeg må overhale den i højre side, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم از سمت راستش سبقت بگیرم.","ok":1,"eda":"Ja. En bil, der svinger til venstre, må overhales i højre side.","efa":"بله. از خودرویی که به چپ می‌پیچد، می‌توان از سمت راست سبقت گرفت.","en":"I may overtake it on the right, if it can be done safely.","een":"Yes. A car turning left may be overtaken on its right."},{"da":"Jeg holder øje med cyklister og fodgængere i højre side.","fa":"مراقب دوچرخه‌سواران و عابران سمت راست هستم.","ok":1,"eda":"Ja. Når du kører forbi i højre side, er du tæt på vejkanten, hvor der kan være bløde trafikanter.","efa":"بله. وقتی از سمت راست رد می‌شوید، به لبه‌ی جاده نزدیکید و ممکن است کاربران آسیب‌پذیر آن‌جا باشند.","en":"I watch out for cyclists and pedestrians on the right.","een":"Yes. When you pass on the right you are close to the road edge, where there may be vulnerable road users."}]},{"id":5017,"img":"newq-art/5017.png","c":"7.9","sda":"Foran dig kører en traktor. Lidt længere fremme er en jernbaneoverkørsel. Hvad gælder for overhaling?","sfa":"جلوی شما تراکتوری می‌رود. کمی جلوتر تقاطع راه‌آهن است. درباره‌ی سبقت چه قاعده‌ای برقرار است؟","sen":"A tractor is driving in front of you. A little further ahead there is a level crossing. What applies to overtaking?","st":[{"da":"Jeg må ikke overhale umiddelbart før og på overkørslen.","fa":"درست پیش از تقاطع راه‌آهن و روی آن نباید سبقت بگیرم.","ok":1,"eda":"Ja. Det står i Færdselsloven § 23.","efa":"بله. این در ماده‌ی ۲۳ قانون آمده است.","en":"I must not overtake immediately before and on the level crossing.","een":"Yes. That is in Færdselsloven § 23."},{"da":"Jeg må heller ikke standse på selve overkørslen.","fa":"روی خود تقاطع راه‌آهن هم نباید بایستم.","ok":1,"eda":"Ja. Det er forbudt at standse og parkere på en jernbaneoverkørsel.","efa":"بله. توقف و پارک روی تقاطع راه‌آهن ممنوع است.","en":"I must not stop on the level crossing itself either.","een":"Yes. Stopping and parking on a level crossing are forbidden."},{"da":"Jeg må overhale, hvis der ikke kommer noget tog.","fa":"اگر قطاری نیاید، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Overhaling er forbudt umiddelbart før og på en jernbaneoverkørsel, uanset tog.","efa":"خیر. سبقت درست پیش از تقاطع راه‌آهن و روی آن ممنوع است، چه قطار بیاید چه نه.","en":"I may overtake if no train is coming.","een":"No. Overtaking is forbidden immediately before and on a level crossing, train or not."},{"da":"Jeg venter, til vi er over overkørslen, og det i øvrigt er sikkert.","fa":"صبر می‌کنم تا از تقاطع رد شویم و سبقت از نظر دیگر هم بی‌خطر باشد.","ok":1,"eda":"Ja. Efter overkørslen gælder de almindelige regler for overhaling igen.","efa":"بله. بعد از تقاطع، قاعده‌های معمول سبقت دوباره برقرارند.","en":"I wait until we are over the crossing and it is otherwise safe.","een":"Yes. After the crossing the ordinary overtaking rules apply again."}]},{"id":5018,"img":"newq-art/5018.png","c":"7.9","sda":"Du kører langsomt med campingvogn på en smal, snoet vej, og der er dannet kø bag dig. Hvordan forholder du dig?","sfa":"با کاروان در جاده‌ای باریک و پرپیچ آهسته می‌رانید و پشت سرتان صف تشکیل شده است. چه می‌کنید؟","sen":"You are driving slowly with a caravan on a narrow, winding road, and a queue has formed behind you. What do you do?","st":[{"da":"Jeg sænker farten og kører ind til siden, så snart det er muligt, så de andre kan komme forbi.","fa":"به محض این‌که شد، سرعت را کم می‌کنم و کنار می‌کشم تا بقیه رد شوند.","ok":1,"eda":"Ja. Færdselsloven § 22 kræver, at du gør det lettere at overhale dig, og om nødvendigt standser.","efa":"بله. ماده‌ی ۲۲ قانون می‌خواهد که سبقت از خودتان را آسان کنید و در صورت لزوم بایستید.","en":"I slow down and pull over as soon as possible so that the others can get past.","een":"Yes. Færdselsloven § 22 requires you to make it easier to overtake you, stopping if necessary."},{"da":"Det er de andres ansvar at vente; jeg behøver ikke gøre noget.","fa":"صبر کردن وظیفه‌ی بقیه است؛ من لازم نیست کاری بکنم.","ok":0,"eda":"Nej. Loven giver også den langsomme et ansvar for at lette overhalingen.","efa":"خیر. قانون به راننده‌ی کندرو هم وظیفه‌ی آسان کردن سبقت را می‌دهد.","en":"It is the others' job to wait; I do not need to do anything.","een":"No. The law also gives the slow driver a duty to make overtaking easier."},{"da":"Jeg kører hurtigere end sikkert, så køen kan følge med.","fa":"تندتر از حد ایمن می‌رانم تا صف بتواند همراهم بیاید.","ok":0,"eda":"Nej. Du må aldrig køre hurtigere, end forholdene og vogntoget tillader.","efa":"خیر. هرگز نباید تندتر از آن‌چه شرایط و خودرو با یدک اجازه می‌دهد برانید.","en":"I drive faster than is safe so that the queue can keep up.","een":"No. You must never drive faster than the conditions and the combination allow."},{"da":"Jeg holder øje med trafikken bagfra.","fa":"ترافیک پشت سر را زیر نظر دارم.","ok":1,"eda":"Ja. Den, der kører langsomt eller fylder meget, skal være særligt opmærksom på trafikken bagfra.","efa":"بله. کسی که آهسته می‌رود یا جای زیادی می‌گیرد، باید به ترافیک پشت سر توجه ویژه داشته باشد.","en":"I keep an eye on the traffic behind.","een":"Yes. Someone driving slowly or taking up much space must pay special attention to the traffic behind."}]},{"id":5019,"img":"newq-art/5019.png","c":"6.1","sda":"Du nærmer dig dette kryds. Hvad betyder tavlen og hajtænderne?","sfa":"به این تقاطع نزدیک می‌شوید. تابلو و دندان‌کوسه‌ها یعنی چه؟","sen":"You are approaching this junction. What do the sign and the shark teeth mean?","st":[{"da":"Jeg har kun vigepligt for trafikken fra højre.","fa":"فقط باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Ubetinget vigepligt gælder for trafikken fra begge sider.","efa":"خیر. راه دادن بی‌قیدوشرط برای ترافیک هر دو طرف است.","en":"I only have to give way to traffic from the right.","een":"No. Unconditional give-way applies to traffic from both sides."},{"da":"Jeg har ubetinget vigepligt for trafikken på den tværgående vej fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک جاده‌ی متقاطع از هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Tavle B 11 og hajtænder betyder ubetinget vigepligt.","efa":"بله. تابلوی B 11 و دندان‌کوسه یعنی باید بی‌قیدوشرط راه بدهید.","en":"I must give way unconditionally to the traffic on the crossing road from both sides.","een":"Yes. Sign B 11 and shark teeth mean you must give way unconditionally."},{"da":"Jeg må køre ud foran en bil på den tværgående vej, hvis den kan nå at bremse.","fa":"می‌توانم جلوی خودرویی در جاده‌ی متقاطع وارد شوم، اگر فرصت ترمز کردن داشته باشد.","ok":0,"eda":"Nej. Du må kun køre ud, hvis det kan ske uden fare eller ulempe for dem, du skal holde tilbage for; de må ikke skulle bremse for dig.","efa":"خیر. فقط وقتی می‌توانید وارد شوید که برای کسانی که باید به آن‌ها راه بدهید خطر یا مزاحمتی نداشته باشد؛ آن‌ها نباید مجبور شوند برایتان ترمز کنند.","en":"I may drive out in front of a car on the crossing road if it has time to brake.","een":"No. You may only drive out if it can be done without danger or inconvenience to those you must give way to; they must not have to brake for you."},{"da":"Jeg skal altid standse helt, selv om vejen er fri.","fa":"باید همیشه کامل بایستم، حتی اگر جاده خالی باشد.","ok":0,"eda":"Nej. Fuldt stop kræves ved stoptavlen B 13, ikke ved B 11.","efa":"خیر. توقف کامل برای تابلوی ایست B 13 لازم است، نه برای B 11.","en":"I must always stop completely, even if the road is clear.","een":"No. A full stop is required at the stop sign B 13, not at B 11."}]},{"id":5020,"img":"newq-art/5020.png","c":"6.1","sda":"Vejen på tværs er helt fri. Hvordan forholder du dig ved tavlen?","sfa":"جاده‌ی متقاطع کاملاً خالی است. کنار این تابلو چه می‌کنید؟","sen":"The crossing road is completely clear. What do you do at the sign?","st":[{"da":"Jeg standser helt ved stoplinjen.","fa":"کنار خط ایست کاملاً می‌ایستم.","ok":1,"eda":"Ja. Ved stoptavlen B 13 skal du altid standse helt ved stoplinjen.","efa":"بله. کنار تابلوی ایست B 13 همیشه باید پشت خط ایست کاملاً بایستید.","en":"I stop completely at the stop line.","een":"Yes. At the stop sign B 13 you must always stop completely at the stop line."},{"da":"Jeg har ubetinget vigepligt for trafikken fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Stoptavlen giver både stoppligt og ubetinget vigepligt.","efa":"بله. تابلوی ایست هم وظیفه‌ی ایستادن می‌دهد و هم راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to traffic from both sides.","een":"Yes. The stop sign gives both a duty to stop and unconditional give-way."},{"da":"Jeg må køre over uden at standse, når der ikke kommer nogen.","fa":"وقتی کسی نمی‌آید، می‌توانم بدون ایستادن رد شوم.","ok":0,"eda":"Nej. Stoppligten gælder også, når vejen er fri.","efa":"خیر. وظیفه‌ی ایستادن حتی وقتی جاده خالی است هم برقرار است.","en":"I may drive across without stopping when nobody is coming.","een":"No. The duty to stop applies even when the road is clear."}]},{"id":5021,"img":"newq-art/5021.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Hvad betyder den?","sfa":"بیرون شهر از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign outside town. What does it mean?","st":[{"da":"Trafikken fra sidevejene skal holde tilbage for mig, men jeg skal stadig være opmærksom.","fa":"ترافیک فرعی‌ها باید به من راه بدهد، ولی باز هم باید مراقب باشم.","ok":1,"eda":"Ja. Trafikken ud fra sidevejene har ubetinget vigepligt, men du skal altid være agtpågivende.","efa":"بله. ترافیکی که از فرعی‌ها می‌آید باید بی‌قیدوشرط راه بدهد، ولی شما همیشه باید هوشیار باشید.","en":"Traffic from the side roads must give way to me, but I must still pay attention.","een":"Yes. Traffic coming out of the side roads must give way unconditionally, but you must always be attentive."},{"da":"Jeg kører på en hovedvej.","fa":"در جاده‌ی اصلی می‌رانم.","ok":1,"eda":"Ja. Den gule rombe med hvid kant (B 16) betyder hovedvej.","efa":"بله. لوزی زرد با حاشیه‌ی سفید (B 16) یعنی جاده‌ی اصلی.","en":"I am driving on a main road.","een":"Yes. The yellow diamond with a white border (B 16) means main road."},{"da":"Uden for tættere bebygget område må jeg ikke parkere på kørebanen på denne vej.","fa":"بیرون از منطقه‌ی مسکونی، نباید روی سواره‌روی این جاده پارک کنم.","ok":1,"eda":"Ja. Parkering på kørebanen af hovedveje uden for tættere bebygget område er forbudt.","efa":"بله. پارک روی سواره‌روی جاده‌های اصلی بیرون از مناطق مسکونی ممنوع است.","en":"Outside built-up areas I must not park on the carriageway of this road.","een":"Yes. Parking on the carriageway of main roads outside built-up areas is forbidden."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. På hovedvejen gælder højrereglen ikke over for sidevejene.","efa":"خیر. در جاده‌ی اصلی، قاعده‌ی دست راست در برابر فرعی‌ها اعمال نمی‌شود.","en":"I must give way to traffic from the right.","een":"No. On the main road the right-hand rule does not apply towards the side roads."}]},{"id":5022,"img":"newq-art/5022.png","c":"6.1","sda":"Du kører forbi denne tavle. Foran dig kører en cyklist og længere fremme en bil. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. جلوی شما یک دوچرخه‌سوار و جلوتر یک خودرو می‌رود. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. In front of you there is a cyclist, and further ahead a car. What applies?","st":[{"da":"Jeg må overhale cyklisten, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانم از دوچرخه‌سوار سبقت بگیرم.","ok":1,"eda":"Ja. Forbuddet (C 51) gælder ikke overhaling af tohjulede cykler og tohjulede små knallerter.","efa":"بله. این ممنوعیت (C 51) شامل سبقت از دوچرخه و موپد کوچک دوچرخ نمی‌شود.","en":"I may overtake the cyclist if it can be done safely.","een":"Yes. The ban (C 51) does not cover overtaking two-wheeled bicycles and two-wheeled small mopeds."},{"da":"Jeg må overhale en motorcykel på strækningen.","fa":"در این مسیر می‌توانم از موتورسیکلت سبقت بگیرم.","ok":0,"eda":"Nej. Undtagelsen gælder kun tohjulede cykler og små knallerter, ikke motorcykler.","efa":"خیر. این استثنا فقط برای دوچرخه و موپد کوچک دوچرخ است، نه موتورسیکلت.","en":"I may overtake a motorcycle on this stretch.","een":"No. The exception only covers two-wheeled bicycles and small mopeds, not motorcycles."},{"da":"Jeg må overhale alle køretøjer, når der ikke er modkørende.","fa":"وقتی ترافیک روبه‌رو نیست، می‌توانم از هر وسیله‌ای سبقت بگیرم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset om der er modkørende.","efa":"خیر. این ممنوعیت برقرار است، چه ترافیک روبه‌رو باشد چه نباشد.","en":"I may overtake any vehicle when there is no oncoming traffic.","een":"No. The ban applies whether there is oncoming traffic or not."},{"da":"Jeg må ikke overhale bilen på strækningen.","fa":"در این مسیر نباید از خودرو سبقت بگیرم.","ok":1,"eda":"Ja. Tavlen forbyder overhaling af alle andre køretøjer end tohjulede cykler og små knallerter, medmindre de svinger bort fra vejen.","efa":"بله. این تابلو سبقت از همه‌ی وسایل به‌جز دوچرخه و موپد کوچک دوچرخ را ممنوع می‌کند، مگر وسیله‌ای که از جاده خارج می‌شود.","en":"I must not overtake the car on this stretch.","een":"Yes. The sign forbids overtaking any vehicles other than two-wheeled bicycles and small mopeds, unless they are turning off the road."}]},{"id":5023,"img":"newq-art/5023.png","c":"6.1","sda":"Du kører forbi denne tavle uden for byen. Vejen er våd. Hvad gælder?","sfa":"بیرون شهر از کنار این تابلو رد می‌شوید. جاده خیس است. چه قاعده‌ای برقرار است؟","sen":"You pass this sign outside town. The road is wet. What applies?","st":[{"da":"Jeg må højst køre 70 km/t på strækningen.","fa":"در این مسیر حداکثر ۷۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Tavle C 55 angiver den højst tilladte hastighed.","efa":"بله. تابلوی C 55 حداکثر سرعت مجاز را نشان می‌دهد.","en":"I may drive at most 70 km/h on this stretch.","een":"Yes. Sign C 55 gives the highest permitted speed."},{"da":"Jeg skal mindst køre 70 km/t.","fa":"باید دست‌کم ۷۰ کیلومتر بر ساعت برانم.","ok":0,"eda":"Nej. Den røde ring betyder et forbud, altså en højeste hastighed, ikke en mindste.","efa":"خیر. حلقه‌ی قرمز یعنی ممنوعیت، یعنی حداکثر سرعت، نه حداقل.","en":"I must drive at least 70 km/h.","een":"No. The red ring means a ban, a highest speed, not a lowest one."},{"da":"Jeg skal køre langsommere, hvis forholdene kræver det.","fa":"اگر شرایط ایجاب کند، باید آهسته‌تر برانم.","ok":1,"eda":"Ja. Hastigheden skal altid afpasses efter forholdene, fx en våd vej.","efa":"بله. سرعت همیشه باید با شرایط، مثلاً جاده‌ی خیس، جور باشد.","en":"I must drive slower if the conditions call for it.","een":"Yes. Your speed must always suit the conditions, for example a wet road."}]},{"id":5024,"img":"newq-art/5024.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad er den højst tilladte hastighed herefter, når der ikke er andre tavler?","sfa":"از کنار این تابلو رد می‌شوید. اگر تابلوی دیگری نباشد، از این‌جا به بعد حداکثر سرعت مجاز چقدر است؟","sen":"You pass this sign. What is the highest permitted speed after it when there are no other signs?","st":[{"da":"50 km/t.","fa":"۵۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Tavlen (E 55) markerer tættere bebygget område, hvor grænsen er 50 km/t.","efa":"بله. این تابلو (E 55) شروع منطقه‌ی مسکونی است که حد سرعتش ۵۰ کیلومتر بر ساعت است.","en":"50 km/h.","een":"Yes. The sign (E 55) marks a built-up area, where the limit is 50 km/h."},{"da":"70 km/t.","fa":"۷۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 70 km/t gælder kun, hvor en tavle viser det.","efa":"خیر. ۷۰ کیلومتر بر ساعت فقط جایی است که تابلویی آن را نشان دهد.","en":"70 km/h.","een":"No. 70 km/h only applies where a sign shows it."},{"da":"60 km/t.","fa":"۶۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. Den generelle grænse i tættere bebygget område er 50 km/t.","efa":"خیر. حد عمومی سرعت در مناطق مسکونی ۵۰ کیلومتر بر ساعت است.","en":"60 km/h.","een":"No. The general limit in built-up areas is 50 km/h."},{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 80 km/t gælder uden for tættere bebygget område.","efa":"خیر. ۸۰ کیلومتر بر ساعت برای بیرون از مناطق مسکونی است.","en":"80 km/h.","een":"No. 80 km/h applies outside built-up areas."}]},{"id":5025,"img":"newq-art/5025.png","c":"6.1","sda":"Midt på vejen er der to ubrudte hvide linjer side om side. Hvad gælder?","sfa":"وسط جاده دو خط سفید ممتد کنار هم کشیده شده است. چه قاعده‌ای برقرار است؟","sen":"In the middle of the road there are two unbroken white lines side by side. What applies?","st":[{"da":"Linjerne adskiller de to kørselsretninger.","fa":"این خط‌ها دو جهت حرکت را از هم جدا می‌کنند.","ok":1,"eda":"Ja. En dobbelt spærrelinje midt på vejen adskiller de modsatte kørselsretninger.","efa":"بله. خط ممتد دوبل وسط جاده، دو جهت مخالف را از هم جدا می‌کند.","en":"The lines separate the two directions of traffic.","een":"Yes. A double barrier line in the middle of the road separates the opposite directions."},{"da":"Jeg må overskride dem for at overhale, hvis vejen er fri.","fa":"اگر جاده خالی باشد، برای سبقت می‌توانم از آن‌ها رد شوم.","ok":0,"eda":"Nej. Linjerne må ikke overskrides for at overhale, heller ikke når vejen er fri.","efa":"خیر. حتی وقتی جاده خالی است، برای سبقت نباید از این خط‌ها عبور کرد.","en":"I may cross them to overtake if the road is clear.","een":"No. The lines must not be crossed to overtake, not even when the road is clear."},{"da":"Det er spærrelinjer, som jeg ikke må overskride.","fa":"این‌ها خط ممتدند و نباید از آن‌ها رد شوم.","ok":1,"eda":"Ja. Spærrelinjer (Q 44) må ikke overskrides eller krydses.","efa":"بله. از خط‌های ممتد (Q 44) نباید عبور کرد.","en":"They are barrier lines that I must not cross.","een":"Yes. Barrier lines (Q 44) must not be crossed."},{"da":"Jeg må heller ikke køre over dem for at svinge ind til ejendommen til venstre.","fa":"برای پیچیدن به ملک سمت چپ هم نباید از آن‌ها رد شوم.","ok":1,"eda":"Ja. Der er ingen undtagelse for at svinge ind til en ejendom.","efa":"بله. برای پیچیدن به یک ملک استثنایی وجود ندارد.","en":"I must not drive over them to turn into the property on the left either.","een":"Yes. There is no exception for turning into a property."}]},{"id":5026,"img":"newq-art/5026.png","c":"7.6","sda":"Bussen ved stoppestedet blinker til venstre. Hvordan forholder du dig?","sfa":"اتوبوس کنار ایستگاه راهنمای چپ زده است. چه می‌کنید؟","sen":"The bus at the stop is indicating left. What do you do?","st":[{"da":"Jeg sænker farten og standser om nødvendigt, så bussen kan køre ud.","fa":"سرعتم را کم می‌کنم و در صورت لزوم می‌ایستم تا اتوبوس بتواند حرکت کند.","ok":1,"eda":"Ja. I tættere bebygget område skal du give bussen mulighed for at køre fra stoppestedet, når den giver tegn.","efa":"بله. در منطقه‌ی مسکونی، وقتی اتوبوس علامت می‌دهد، باید بگذارید از ایستگاه حرکت کند.","en":"I slow down and stop if necessary so that the bus can pull out.","een":"Yes. In built-up areas you must let the bus pull away from the stop when it signals."},{"da":"Reglen gælder kun uden for byen.","fa":"این قاعده فقط بیرون شهر است.","ok":0,"eda":"Nej. Reglen gælder netop i tættere bebygget område.","efa":"خیر. این قاعده دقیقاً برای مناطق مسکونی است.","en":"The rule only applies outside town.","een":"No. The rule applies precisely in built-up areas."},{"da":"Buschaufføren skal stadig være forsigtig, når bussen kører ud.","fa":"راننده‌ی اتوبوس هم هنگام حرکت باید مراقب باشد.","ok":1,"eda":"Ja. Reglen fritager ikke bussens fører for at udvise særlig forsigtighed.","efa":"بله. این قاعده راننده‌ی اتوبوس را از احتیاط ویژه معاف نمی‌کند.","en":"The bus driver must still be careful when pulling out.","een":"Yes. The rule does not free the bus driver from taking special care."},{"da":"Jeg har forkørselsret, fordi jeg allerede er på kørebanen.","fa":"حق تقدم با من است، چون از قبل روی سواره‌رو هستم.","ok":0,"eda":"Nej. Færdselsloven § 19 pålægger dig at give bussen plads til at køre ud.","efa":"خیر. ماده‌ی ۱۹ قانون از شما می‌خواهد به اتوبوس جا بدهید تا حرکت کند.","en":"I have the right of way because I am already on the carriageway.","een":"No. Færdselsloven § 19 requires you to give the bus room to pull out."}]},{"id":5027,"img":"newq-art/5027.png","c":"7.6","sda":"Skolebussen holder for at lade børn stige af. Hvordan forholder du dig?","sfa":"اتوبوس مدرسه ایستاده تا بچه‌ها پیاده شوند. چه می‌کنید؟","sen":"The school bus has stopped to let children off. What do you do?","st":[{"da":"Jeg viser særlig agtpågivenhed og sænker farten.","fa":"احتیاط ویژه می‌کنم و سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved en skolebus, der holder for at lade passagerer stige af, skal du vise særlig agtpågivenhed.","efa":"بله. کنار اتوبوس مدرسه‌ای که برای پیاده شدن مسافران ایستاده، باید احتیاط ویژه کنید.","en":"I take special care and slow down.","een":"Yes. Near a school bus stopped to let passengers off you must take special care."},{"da":"Jeg kører forbi med uændret fart, fordi bussen holder i sin egen side.","fa":"با همان سرعت رد می‌شوم، چون اتوبوس در سمت خودش ایستاده است.","ok":0,"eda":"Nej. Børnene kan komme ud på vejen; du skal være klar til at standse.","efa":"خیر. بچه‌ها ممکن است وارد جاده شوند؛ باید آماده‌ی ایستادن باشید.","en":"I drive past at the same speed because the bus is on its own side.","een":"No. The children may come out onto the road; you must be ready to stop."},{"da":"Jeg dytter, så børnene ved, at jeg kommer.","fa":"بوق می‌زنم تا بچه‌ها بفهمند می‌آیم.","ok":0,"eda":"Nej. Et dyt kan forskrække børnene, så de gør noget uventet; hornet bruges kun for at afværge fare.","efa":"خیر. بوق ممکن است بچه‌ها را بترساند و کار غیرمنتظره‌ای بکنند؛ بوق فقط برای دفع خطر است.","en":"I sound the horn so that the children know I am coming.","een":"No. A horn can startle the children into doing something unexpected; the horn is only for averting danger."},{"da":"Et barn kan løbe ud foran eller bag bussen.","fa":"ممکن است بچه‌ای از جلو یا پشت اتوبوس وارد جاده شود.","ok":1,"eda":"Ja. Børn ser ikke altid efter trafikken, når de skal over vejen.","efa":"بله. بچه‌ها همیشه هنگام عبور از جاده به ترافیک نگاه نمی‌کنند.","en":"A child may run out in front of or behind the bus.","een":"Yes. Children do not always look out for traffic when they cross the road."}]},{"id":5028,"img":"newq-art/5028.png","c":"7.6","sda":"To fodgængere går i venstre side af vejen og kommer imod dig. Hvordan forholder du dig?","sfa":"دو عابر در سمت چپ جاده به طرف شما می‌آیند. چه می‌کنید؟","sen":"Two pedestrians are walking on the left side of the road towards you. What do you do?","st":[{"da":"Jeg dytter, så de går ud i rabatten.","fa":"بوق می‌زنم تا به کنار جاده بروند.","ok":0,"eda":"Nej. Hornet må kun bruges for at afværge fare, ikke for at få andre til at flytte sig.","efa":"خیر. بوق فقط برای دفع خطر است، نه برای کنار زدن دیگران.","en":"I sound the horn so that they step onto the verge.","een":"No. The horn may only be used to avert danger, not to make others move."},{"da":"Hvis den modkørende bil og fodgængerne mødes ved mig, venter jeg bag fodgængerne.","fa":"اگر خودروی روبه‌رو و عابران هم‌زمان به من برسند، پشت عابران صبر می‌کنم.","ok":1,"eda":"Ja. Så kan du give fodgængerne plads uden at komme for tæt på den modkørende.","efa":"بله. این‌طور می‌توانید به عابران جا بدهید بی‌آنکه به خودروی روبه‌رو خیلی نزدیک شوید.","en":"If the oncoming car and the pedestrians meet where I am, I wait behind the pedestrians.","een":"Yes. That way you can give the pedestrians room without getting too close to the oncoming car."},{"da":"Fodgængerne går forkert, fordi de går i venstre side af vejen.","fa":"عابران اشتباه راه می‌روند، چون در سمت چپ جاده‌اند.","ok":0,"eda":"Nej. Gående på vejen skal gå yderst i venstre side, så de møder trafikken.","efa":"خیر. عابرانی که روی جاده راه می‌روند باید در منتهی‌الیه سمت چپ، رو به ترافیک، بروند.","en":"The pedestrians are walking wrongly because they are on the left side.","een":"No. Pedestrians on the road must walk at the far left, facing the traffic."},{"da":"Jeg sænker farten og giver dem god plads, når jeg passerer.","fa":"سرعتم را کم می‌کنم و هنگام رد شدن جای زیادی به آن‌ها می‌دهم.","ok":1,"eda":"Ja. Når du passerer gående, skal du give dem tid til at vige og god plads på vejen.","efa":"بله. هنگام رد شدن از کنار عابران، باید به آن‌ها فرصت کنار رفتن و جای کافی بدهید.","en":"I slow down and give them plenty of room when I pass.","een":"Yes. When you pass pedestrians you must give them time to step aside and plenty of room on the road."}]},{"id":5029,"img":"newq-art/5029.png","c":"7.6","sda":"En lastbil holder i din side af vejen. En bil kommer imod dig. Hvordan forholder du dig?","sfa":"کامیونی در سمت شما ایستاده است. خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"A lorry has stopped on your side of the road. A car is coming towards you. What do you do?","st":[{"da":"Jeg holder tilbage for den modkørende, fordi forhindringen er i min side.","fa":"به خودروی روبه‌رو راه می‌دهم، چون مانع در سمت من است.","ok":1,"eda":"Ja. Den, der har forhindringen i sin side, skal holde tilbage.","efa":"بله. کسی که مانع در سمت اوست، باید راه بدهد.","en":"I give way to the oncoming car because the obstacle is on my side.","een":"Yes. The driver who has the obstacle on their side must give way."},{"da":"Jeg kører tæt op bag lastbilen, så jeg hurtigt kan komme forbi.","fa":"نزدیک پشت کامیون می‌روم تا زود رد شوم.","ok":0,"eda":"Nej. Tæt bag lastbilen kan du ikke se forbi den, og du får svært ved at køre ud; vent med god afstand.","efa":"خیر. نزدیک پشت کامیون نه جلو را می‌بینید و نه به‌راحتی می‌توانید بیرون بیایید؛ با فاصله‌ی خوب صبر کنید.","en":"I drive up close behind the lorry so that I can get past quickly.","een":"No. Close behind the lorry you cannot see past it, and it is hard to pull out; wait at a good distance."},{"da":"Jeg kører ud og blinker med lyset, så den modkørende standser.","fa":"وارد خط روبه‌رو می‌شوم و چراغ می‌زنم تا راننده‌ی روبه‌رو بایستد.","ok":0,"eda":"Nej. Lyssignaler giver ikke forkørselsret; du skal holde tilbage.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد؛ باید راه بدهید.","en":"I pull out and flash my lights so that the oncoming driver stops.","een":"No. Flashing lights does not give you the right of way; you must give way."},{"da":"Den modkørende skal holde tilbage, fordi jeg kom først.","fa":"راننده‌ی روبه‌رو باید راه بدهد، چون من اول رسیدم.","ok":0,"eda":"Nej. Det afgørende er, i hvis side forhindringen er, ikke hvem der kom først.","efa":"خیر. مهم این است که مانع در سمت کیست، نه این‌که چه کسی اول رسید.","en":"The oncoming driver must give way because I came first.","een":"No. What matters is whose side the obstacle is on, not who came first."}]},{"id":5030,"img":"newq-art/5030.png","c":"7.6","sda":"Du kører forbi denne tavle nær en skole. Hvordan forholder du dig?","sfa":"نزدیک یک مدرسه از کنار این تابلو رد می‌شوید. چه می‌کنید؟","sen":"You pass this sign near a school. What do you do?","st":[{"da":"Jeg kan køre med normal fart, når jeg ikke kan se nogen børn på kørebanen.","fa":"وقتی کودکی روی سواره‌رو نمی‌بینم، می‌توانم با سرعت معمول برانم.","ok":0,"eda":"Nej. Børn kan pludselig komme frem mellem de parkerede biler; tavlen varsler, at der kan være børn, og der skal vises særligt hensyn.","efa":"خیر. بچه‌ها ممکن است ناگهان از میان خودروهای پارک‌شده بیرون بیایند؛ تابلو هشدار می‌دهد که ممکن است بچه باشد و باید ملاحظه‌ی ویژه داشت.","en":"I can drive at normal speed when I cannot see any children on the carriageway.","een":"No. Children may suddenly appear between the parked cars; the sign warns that there may be children, and special consideration must be shown."},{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Nær børn skal hastigheden være passende lav.","efa":"بله. نزدیک بچه‌ها، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down and am ready to brake.","een":"Yes. Near children your speed must be suitably low."},{"da":"Tavlen gælder kun i skolens åbningstid.","fa":"این تابلو فقط در ساعات کار مدرسه معتبر است.","ok":0,"eda":"Nej. Tavlen gælder hele tiden, når der ikke er en undertavle med tidspunkter.","efa":"خیر. وقتی زیر تابلو تابلوی کوچکی با ساعت نیست، همیشه معتبر است.","en":"The sign only applies during school hours.","een":"No. The sign applies all the time when there is no plate under it with times."},{"da":"Jeg kan regne med, at børnene har set mig.","fa":"می‌توانم مطمئن باشم که بچه‌ها مرا دیده‌اند.","ok":0,"eda":"Nej. Børn har svært ved at vurdere trafikken og ser ikke altid bilerne.","efa":"خیر. بچه‌ها در سنجیدن ترافیک مشکل دارند و همیشه خودروها را نمی‌بینند.","en":"I can count on the children having seen me.","een":"No. Children find it hard to judge traffic and do not always see the cars."}]},{"id":5031,"img":"newq-art/5031.png","c":"7.6","sda":"En person med en hvid stok står ved fodgængerfeltet. Hvordan forholder du dig?","sfa":"کسی با عصای سفید کنار گذرگاه عابر ایستاده است. چه می‌کنید؟","sen":"A person with a white cane is standing at the pedestrian crossing. What do you do?","st":[{"da":"Jeg dytter, så personen ved, at jeg kommer.","fa":"بوق می‌زنم تا آن شخص بفهمد می‌آیم.","ok":0,"eda":"Nej. Et dyt kan forskrække og forvirre; du skal i stedet standse.","efa":"خیر. بوق می‌تواند بترساند و گیج کند؛ باید به‌جایش بایستید.","en":"I sound the horn so that the person knows I am coming.","een":"No. A horn can startle and confuse; you must stop instead."},{"da":"Den hvide stok viser, at personen ser dårligt eller er blind.","fa":"عصای سفید نشان می‌دهد که آن شخص کم‌بیناست یا نابیناست.","ok":1,"eda":"Ja. Over for personer med nedsat syn skal der vises særligt hensyn.","efa":"بله. باید نسبت به افراد کم‌بینا ملاحظه‌ی ویژه داشت.","en":"The white cane shows that the person has poor sight or is blind.","een":"Yes. Special consideration must be shown to people with impaired sight."},{"da":"Jeg standser og lader personen gå over.","fa":"می‌ایستم و می‌گذارم آن شخص رد شود.","ok":1,"eda":"Ja. Før et fodgængerfelt skal du afpasse hastigheden og om nødvendigt standse for den, der er på vej ud.","efa":"بله. پیش از گذرگاه عابر باید سرعت را تنظیم کنید و در صورت لزوم برای کسی که می‌خواهد رد شود بایستید.","en":"I stop and let the person cross.","een":"Yes. Before a crossing you must adjust your speed and stop if necessary for someone about to step out."},{"da":"Jeg kører forbi, fordi personen ikke kan se, om der kommer biler.","fa":"رد می‌شوم، چون آن شخص نمی‌تواند ببیند خودرویی می‌آید یا نه.","ok":0,"eda":"Nej. Netop derfor skal du tage særligt hensyn og lade personen gå over.","efa":"خیر. دقیقاً به همین دلیل باید ملاحظه کنید و بگذارید رد شود.","en":"I drive past because the person cannot see whether cars are coming.","een":"No. That is exactly why you must take special care and let the person cross."}]},{"id":5032,"img":"newq-art/5032.png","c":"7.3","sda":"Du kører i en almindelig bil på motorvejen. Der er ingen hastighedstavler. Hvad gælder?","sfa":"با خودروی معمولی در بزرگراه می‌رانید. تابلوی سرعتی نیست. چه قاعده‌ای برقرار است؟","sen":"You are driving an ordinary car on the motorway. There are no speed-limit signs. What applies?","st":[{"da":"Jeg må højst køre 130 km/t.","fa":"حداکثر ۱۳۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Den generelle grænse på motorvej er 130 km/t.","efa":"بله. حد عمومی سرعت در بزرگراه ۱۳۰ کیلومتر بر ساعت است.","en":"I may drive at most 130 km/h.","een":"Yes. The general limit on the motorway is 130 km/h."},{"da":"Der er ingen hastighedsgrænse på motorvejen.","fa":"در بزرگراه حد سرعتی وجود ندارد.","ok":0,"eda":"Nej. Der gælder altid en højeste hastighed, også på motorvej.","efa":"خیر. همیشه حداکثر سرعتی هست، در بزرگراه هم.","en":"There is no speed limit on the motorway.","een":"No. There is always a highest speed, also on the motorway."},{"da":"Jeg må køre hurtigere end 130 km/t, mens jeg overhaler.","fa":"هنگام سبقت می‌توانم تندتر از ۱۳۰ کیلومتر بر ساعت برانم.","ok":0,"eda":"Nej. Hastighedsgrænsen gælder også under overhaling.","efa":"خیر. حد سرعت هنگام سبقت هم برقرار است.","en":"I may drive faster than 130 km/h while I am overtaking.","een":"No. The speed limit also applies while overtaking."},{"da":"Jeg må højst køre 110 km/t.","fa":"حداکثر ۱۱۰ کیلومتر بر ساعت می‌توانم برانم.","ok":0,"eda":"Nej. 110 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۱۱۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"I may drive at most 110 km/h.","een":"No. 110 km/h only applies where it is signed."}]},{"id":5033,"img":"newq-art/5033.png","c":"7.3","sda":"Du kører med en almindelig trailer på en landevej uden hastighedstavler. Hvad gælder?","sfa":"با یک تریلر معمولی در جاده‌ای بیرون شهر و بدون تابلوی سرعت می‌رانید. چه قاعده‌ای برقرار است؟","sen":"You are towing an ordinary trailer on a country road with no speed-limit signs. What applies?","st":[{"da":"Jeg må højst køre 80 km/t.","fa":"حداکثر ۸۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Bil med påhængskøretøj må højst køre 80 km/t uden for motorvej.","efa":"بله. خودرو با یدک بیرون از بزرگراه حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود.","en":"I may drive at most 80 km/h.","een":"Yes. A car with a trailer may drive at most 80 km/h off the motorway."},{"da":"Jeg må køre lige så hurtigt som uden trailer.","fa":"می‌توانم به همان سرعتِ بدون تریلر برانم.","ok":0,"eda":"Nej. Med trailer gælder en lavere grænse end for bilen alene.","efa":"خیر. با تریلر حد سرعت پایین‌تری از خودروی تنها برقرار است.","en":"I may drive as fast as without a trailer.","een":"No. With a trailer a lower limit applies than for the car alone."},{"da":"En trailer påvirker ikke bremselængden.","fa":"تریلر روی مسافت ترمز اثری ندارد.","ok":0,"eda":"Nej. Et vogntog er tungere og får længere bremselængde.","efa":"خیر. خودرو با یدک سنگین‌تر است و مسافت ترمزش بیشتر است.","en":"A trailer does not affect the braking distance.","een":"No. A combination is heavier and has a longer braking distance."},{"da":"På motorvej må jeg højst køre 100 km/t, hvis vogntoget opfylder betingelserne for det.","fa":"در بزرگراه اگر خودرو با یدک شرایطش را داشته باشد، حداکثر ۱۰۰ کیلومتر بر ساعت می‌توانم برانم.","ok":1,"eda":"Ja. Færdselsloven § 43 tillader 100 km/t på motorvej for vogntog, der opfylder bestemte krav.","efa":"بله. ماده‌ی ۴۳ قانون برای خودرو با یدکی که شرایط خاصی دارد، ۱۰۰ کیلومتر بر ساعت در بزرگراه را مجاز می‌داند.","en":"On the motorway I may drive at most 100 km/h if the combination meets the conditions for it.","een":"Yes. Færdselsloven § 43 allows 100 km/h on the motorway for combinations that meet certain requirements."}]},{"id":5034,"img":"newq-art/5034.png","c":"7.3","sda":"Der er tæt tåge. Hvordan forholder du dig?","sfa":"مه غلیظی است. چه می‌کنید؟","sen":"There is dense fog. What do you do?","st":[{"da":"Jeg må bruge tågeforlygter.","fa":"می‌توانم از چراغ‌های مه‌شکن جلو استفاده کنم.","ok":1,"eda":"Ja. Tågelygter må bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن در مه و بارش شدید مجاز است.","en":"I may use front fog lights.","een":"Yes. Fog lights may be used in fog and heavy precipitation."},{"da":"Jeg kører tæt bag bilen foran og følger dens baglygter.","fa":"نزدیک پشت خودروی جلو می‌رانم و چراغ‌های عقبش را دنبال می‌کنم.","ok":0,"eda":"Nej. Tæt afstand giver ingen tid til at bremse, hvis bilen foran standser.","efa":"خیر. فاصله‌ی کم، اگر خودروی جلو بایستد، فرصتی برای ترمز نمی‌گذارد.","en":"I drive close behind the car ahead and follow its rear lights.","een":"No. A short distance leaves no time to brake if the car ahead stops."},{"da":"Jeg kører så langsomt, at jeg kan standse på den strækning, jeg kan se.","fa":"آن‌قدر آهسته می‌رانم که بتوانم در فاصله‌ای که می‌بینم بایستم.","ok":1,"eda":"Ja. Du skal altid kunne standse på den del af vejen, du har udsyn over.","efa":"بله. همیشه باید بتوانید در بخشی از جاده که می‌بینید بایستید.","en":"I drive so slowly that I can stop within the distance I can see.","een":"Yes. You must always be able to stop within the part of the road you can see."},{"da":"Jeg tænder fjernlyset, så jeg kan se længere.","fa":"نور بالا را روشن می‌کنم تا دورتر را ببینم.","ok":0,"eda":"Nej. I tåge kaster fjernlyset lyset tilbage og blænder dig selv.","efa":"خیر. در مه، نور بالا بازمی‌تابد و خودتان را خیره می‌کند.","en":"I switch on the high beam so that I can see further.","een":"No. In fog the high beam reflects back and dazzles you."}]},{"id":5035,"img":"newq-art/5035.png","c":"7.3","sda":"Du kører med fjernlys, og langt fremme kommer en bil imod dig. Hvordan forholder du dig?","sfa":"با نور بالا می‌رانید و دورتر خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You are driving with high beam, and far ahead a car is coming towards you. What do you do?","st":[{"da":"Jeg beholder fjernlyset, til bilen er lige ud for mig.","fa":"نور بالا را تا رسیدن خودرو به کنارم روشن نگه می‌دارم.","ok":0,"eda":"Nej. Så bliver den modkørende blændet i lang tid.","efa":"خیر. این‌طور راننده‌ی روبه‌رو مدت زیادی خیره می‌شود.","en":"I keep the high beam on until the car is right beside me.","een":"No. Then the oncoming driver is dazzled for a long time."},{"da":"Jeg blinker med fjernlyset, så den modkørende ved, at jeg er her.","fa":"با نور بالا چراغ می‌زنم تا راننده‌ی روبه‌رو بداند من این‌جا هستم.","ok":0,"eda":"Nej. Det blænder og er ikke nødvendigt; den modkørende kan se dit lys.","efa":"خیر. این کار خیره می‌کند و لازم نیست؛ راننده‌ی روبه‌رو چراغ‌های شما را می‌بیند.","en":"I flash my high beam so that the oncoming driver knows I am here.","een":"No. It dazzles and is not needed; the oncoming driver can see your lights."},{"da":"Jeg afpasser farten efter det kortere udsyn med nærlys.","fa":"سرعتم را با دید کوتاه‌ترِ نور پایین تنظیم می‌کنم.","ok":1,"eda":"Ja. Før du skifter til nærlys, skal hastigheden passe til det nye, kortere udsyn.","efa":"بله. پیش از رفتن به نور پایین، سرعت باید با دید تازه و کوتاه‌تر جور باشد.","en":"I adjust my speed to the shorter view with dipped beam.","een":"Yes. Before you dip, your speed must suit the new, shorter view."},{"da":"Jeg skifter til nærlys i god tid, så den modkørende ikke bliver blændet.","fa":"به موقع به نور پایین می‌روم تا راننده‌ی روبه‌رو خیره نشود.","ok":1,"eda":"Ja. Fjernlys må ikke bruges, når en modkørende kan blive blændet.","efa":"بله. وقتی ممکن است راننده‌ی روبه‌رو خیره شود، نباید از نور بالا استفاده کرد.","en":"I switch to dipped beam in good time so that the oncoming driver is not dazzled.","een":"Yes. High beam must not be used when an oncoming driver could be dazzled."}]},{"id":5036,"img":"newq-art/5036.png","c":"7.3","sda":"Du nærmer dig et vejarbejde, hvor der arbejder folk tæt ved vejen. Hvordan forholder du dig?","sfa":"به محل کار جاده‌ای نزدیک می‌شوید که کارگرانی نزدیک جاده کار می‌کنند. چه می‌کنید؟","sen":"You are approaching road works with people working close to the road. What do you do?","st":[{"da":"Jeg følger de gule linjer på kørebanen.","fa":"خط‌های زرد روی جاده را دنبال می‌کنم.","ok":1,"eda":"Ja. Midlertidig gul afmærkning gælder forud for den hvide.","efa":"بله. خط‌کشی موقت زرد بر خط‌کشی سفید مقدم است.","en":"I follow the yellow lines on the road.","een":"Yes. Temporary yellow markings take priority over the white ones."},{"da":"Jeg holder farten, så jeg hurtigt er forbi.","fa":"سرعتم را حفظ می‌کنم تا زود رد شوم.","ok":0,"eda":"Nej. Vejarbejdere kan træde ud på vejen; der skal være tid til at reagere.","efa":"خیر. کارگران ممکن است وارد جاده شوند؛ باید فرصت واکنش داشت.","en":"I keep my speed so that I am past quickly.","een":"No. Road workers may step onto the road; there must be time to react."},{"da":"Tavlen gælder kun, når der er maskiner på vejen.","fa":"این تابلو فقط وقتی ماشین‌آلات روی جاده‌اند معتبر است.","ok":0,"eda":"Nej. Tavlen advarer om vejarbejde, uanset om der er maskiner.","efa":"خیر. این تابلو از کار جاده‌ای هشدار می‌دهد، چه ماشین‌آلات باشند چه نه.","en":"The sign only applies when there are machines on the road.","een":"No. The sign warns of road works whether there are machines or not."},{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved vejarbejde skal hastigheden være passende lav.","efa":"بله. در محل کار جاده‌ای سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. At road works your speed must be suitably low."}]},{"id":5037,"img":"newq-art/5037.png","c":"7.3","sda":"Du er i tvivl om vejen og kører meget langsomt. Bag dig er der dannet kø. Hvad gælder?","sfa":"مسیر را مطمئن نیستید و خیلی آهسته می‌رانید. پشت سرتان صف تشکیل شده است. چه قاعده‌ای برقرار است؟","sen":"You are unsure of the way and are driving very slowly. A queue has formed behind you. What applies?","st":[{"da":"Jeg bremser pludseligt, hver gang jeg skal læse et vejskilt.","fa":"هر بار که باید تابلویی را بخوانم، ناگهان ترمز می‌کنم.","ok":0,"eda":"Nej. Pludselig opbremsning uden grund kan få bilerne bag dig til at køre ind i dig.","efa":"خیر. ترمز ناگهانی بی‌دلیل ممکن است باعث شود خودروهای پشت سر به شما بزنند.","en":"I brake suddenly every time I need to read a road sign.","een":"No. Sudden braking without reason can make the cars behind run into you."},{"da":"Jeg må ikke uden rimelig grund køre så langsomt, at jeg hindrer andre.","fa":"نباید بی‌دلیل آن‌قدر آهسته برانم که مانع دیگران شوم.","ok":1,"eda":"Ja. Færdselsloven § 41 forbyder at hindre andre ved unødigt lav hastighed.","efa":"بله. ماده‌ی ۴۱ قانون مانع شدن دیگران با سرعت بی‌دلیل کم را ممنوع می‌کند.","en":"I must not, without good reason, drive so slowly that I hinder others.","een":"Yes. Færdselsloven § 41 forbids hindering others by needlessly low speed."},{"da":"Det er altid sikrest at køre så langsomt som muligt.","fa":"همیشه امن‌ترین کار آهسته‌ترین رانندگی است.","ok":0,"eda":"Nej. En meget lav fart kan skabe farlige overhalinger og kø.","efa":"خیر. سرعت خیلی کم می‌تواند به سبقت‌های خطرناک و صف منجر شود.","en":"It is always safest to drive as slowly as possible.","een":"No. Very low speed can cause dangerous overtaking and queues."},{"da":"Jeg kører ind i rastepladsen og finder vejen, når jeg holder stille.","fa":"وارد توقفگاه کنار جاده می‌شوم و وقتی ایستاده‌ام مسیر را پیدا می‌کنم.","ok":1,"eda":"Ja. Så kan køen komme forbi, og du kan læse kort eller skilte i ro.","efa":"بله. این‌طور صف رد می‌شود و شما با خیال راحت نقشه یا تابلو را می‌خوانید.","en":"I pull into the lay-by and work out the way while I am standing still.","een":"Yes. Then the queue can get past, and you can read a map or signs in peace."}]},{"id":5038,"img":"newq-art/5038.png","c":"7.12","sda":"Du vil køre ligeud i krydset. Fra højre kommer en bil, og fra venstre kommer en cyklist. Hvordan forholder du dig?","sfa":"می‌خواهید مستقیم از تقاطع رد شوید. از راست خودرویی و از چپ دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You want to drive straight on in the junction. A car is coming from the right and a cyclist from the left. What do you do?","st":[{"da":"Jeg kan regne med, at cyklisten holder tilbage, så jeg behøver ikke se efter den.","fa":"می‌توانم مطمئن باشم دوچرخه‌سوار راه می‌دهد، پس لازم نیست حواسم به او باشد.","ok":0,"eda":"Nej. Du skal altid være opmærksom på, om andre overholder deres vigepligt.","efa":"خیر. همیشه باید ببینید دیگران به وظیفه‌ی راه دادنشان عمل می‌کنند یا نه.","en":"I can count on the cyclist giving way, so I do not need to watch it.","een":"No. You must always watch whether others keep their duty to give way."},{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ikke forkørselsret over for trafik fra højre.","efa":"خیر. مستقیم رفتن در برابر ترافیک سمت راست حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on does not give you the right of way over traffic from the right."},{"da":"Cyklisten fra venstre skal holde tilbage for mig.","fa":"دوچرخه‌سوار سمت چپ باید به من راه بدهد.","ok":1,"eda":"Ja. Højrereglen gælder også for cyklister: cyklisten har dig på sin højre side.","efa":"بله. قاعده‌ی دست راست برای دوچرخه‌سواران هم هست: شما در سمت راست او هستید.","en":"The cyclist from the left must give way to me.","een":"Yes. The right-hand rule also applies to cyclists: the cyclist has you on their right."},{"da":"Jeg holder tilbage for bilen fra højre.","fa":"به خودروی سمت راست راه می‌دهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen: du holder tilbage for trafik fra højre.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است: به ترافیک سمت راست راه می‌دهید.","en":"I give way to the car from the right.","een":"Yes. Without signs or markings the right-hand rule applies: you give way to traffic from the right."}]},{"id":5039,"img":"newq-art/5039.png","c":"7.12","sda":"Der er hajtænder på kørebanen foran dig, men ingen tavle. Hvad gælder?","sfa":"روی جاده جلوی شما دندان‌کوسه هست، ولی تابلویی نیست. چه قاعده‌ای برقرار است؟","sen":"There are shark teeth on the road ahead of you, but no sign. What applies?","st":[{"da":"Hajtænder gælder kun sammen med en vigepligtstavle.","fa":"دندان‌کوسه فقط همراه تابلوی راه بدهید معتبر است.","ok":0,"eda":"Nej. Afmærkningen alene giver vigepligt.","efa":"خیر. خود خط‌کشی به‌تنهایی وظیفه‌ی راه دادن می‌دهد.","en":"Shark teeth only apply together with a give-way sign.","een":"No. The marking alone gives the duty to give way."},{"da":"Bilen fra venstre skal have lov at køre først.","fa":"باید بگذارم خودروی سمت چپ اول برود.","ok":1,"eda":"Ja. Ubetinget vigepligt gælder for trafikken fra begge sider.","efa":"بله. راه دادن بی‌قیدوشرط برای ترافیک هر دو طرف است.","en":"The car from the left must be allowed to go first.","een":"Yes. Unconditional give-way applies to traffic from both sides."},{"da":"Jeg har ubetinget vigepligt for trafikken på den tværgående vej.","fa":"باید بی‌قیدوشرط به ترافیک جاده‌ی متقاطع راه بدهم.","ok":1,"eda":"Ja. Hajtænderne betyder ubetinget vigepligt, også uden tavle.","efa":"بله. دندان‌کوسه حتی بدون تابلو یعنی راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to the traffic on the crossing road.","een":"Yes. The shark teeth mean unconditional give-way, also without a sign."}]},{"id":5040,"img":"newq-art/5040.png","c":"7.12","sda":"Du har grønt lys, men der holder en kø lige efter krydset. Hvordan forholder du dig?","sfa":"چراغ سبز است، ولی درست بعد از تقاطع صف ایستاده است. چه می‌کنید؟","sen":"You have a green light, but there is a queue just after the junction. What do you do?","st":[{"da":"Jeg må køre ind i krydset, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم وارد تقاطع شوم.","ok":0,"eda":"Nej. Havariblinket ændrer ikke, at du spærrer krydset for den tværgående trafik.","efa":"خیر. چراغ خطر این را تغییر نمی‌دهد که تقاطع را برای ترافیک متقاطع می‌بندید.","en":"I may drive into the junction if I switch on the hazard lights.","een":"No. The hazard lights do not change the fact that you block the junction for the crossing traffic."},{"da":"Jeg kører frem og stiller mig skråt, så andre kan komme forbi.","fa":"جلو می‌روم و کج می‌ایستم تا دیگران رد شوند.","ok":0,"eda":"Nej. Du skal slet ikke køre ind i krydset, når der ikke er plads.","efa":"خیر. وقتی جا نیست، اصلاً نباید وارد تقاطع شوید.","en":"I drive forward and stand at an angle so that others can get past.","een":"No. You must not drive into the junction at all when there is no room."},{"da":"Jeg kører ind i krydset, fordi jeg har grønt.","fa":"وارد تقاطع می‌شوم، چون چراغم سبز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at blive holdende midt i krydset.","efa":"خیر. چراغ سبز اجازه‌ی ماندن وسط تقاطع را نمی‌دهد.","en":"I drive into the junction because I have a green light.","een":"No. A green light does not give a right to stand in the middle of the junction."},{"da":"Jeg venter før krydset, til der er plads på den anden side.","fa":"پیش از تقاطع صبر می‌کنم تا آن طرف جا باز شود.","ok":1,"eda":"Ja. Du må ikke køre ind på grønt, hvis du ikke kan komme ud af krydset, før de tværgående får grønt.","efa":"بله. اگر نتوانید پیش از سبز شدن چراغ ترافیک متقاطع از تقاطع خارج شوید، نباید با چراغ سبز واردش شوید.","en":"I wait before the junction until there is room on the other side.","een":"Yes. You must not drive in on green if you cannot get out of the junction before the crossing traffic gets green."}]},{"id":5041,"img":"newq-art/5041.png","c":"7.12","sda":"Du vil køre ud fra tankstationen. Hvordan forholder du dig?","sfa":"می‌خواهید از پمپ بنزین خارج شوید. چه می‌کنید؟","sen":"You want to drive out of the petrol station. What do you do?","st":[{"da":"Jeg har ubetinget vigepligt for trafikken på vejen.","fa":"باید بی‌قیدوشرط به ترافیک جاده راه بدهم.","ok":1,"eda":"Ja. Kørsel ud fra en tankstation giver ubetinget vigepligt.","efa":"بله. خروج از پمپ بنزین یعنی راه دادن بی‌قیدوشرط.","en":"I must give way unconditionally to the traffic on the road.","een":"Yes. Driving out of a petrol station means unconditional give-way."},{"da":"Fodgængeren skal vente, fordi jeg skal over fortovet.","fa":"عابر باید صبر کند، چون من باید از پیاده‌رو رد شوم.","ok":0,"eda":"Nej. Det er dig, der skal vente på fodgængeren.","efa":"خیر. شما هستید که باید منتظر عابر بمانید.","en":"The pedestrian must wait because I have to cross the pavement.","een":"No. It is you who must wait for the pedestrian."},{"da":"Jeg skal holde tilbage for fodgængeren og cyklisten.","fa":"باید به عابر و دوچرخه‌سوار راه بدهم.","ok":1,"eda":"Ja. Du skal holde tilbage for gående på fortovet og for cyklister på cykelstien, når du krydser dem.","efa":"بله. هنگام عبور از پیاده‌رو و مسیر دوچرخه، باید به عابران و دوچرخه‌سواران راه بدهید.","en":"I must give way to the pedestrian and the cyclist.","een":"Yes. You must give way to pedestrians on the pavement and cyclists on the cycle path when you cross them."},{"da":"Højrereglen gælder, fordi der ikke er nogen tavle.","fa":"قاعده‌ی دست راست برقرار است، چون تابلویی نیست.","ok":0,"eda":"Nej. Højrereglen gælder ikke ved udkørsel fra en tankstation.","efa":"خیر. قاعده‌ی دست راست در خروج از پمپ بنزین اعمال نمی‌شود.","en":"The right-hand rule applies because there is no sign.","een":"No. The right-hand rule does not apply when driving out of a petrol station."}]},{"id":5042,"img":"newq-art/5042.png","c":"7.12","sda":"Lyssignalet i krydset blinker gult. Hvordan forholder du dig?","sfa":"چراغ راهنمایی تقاطع زرد چشمک‌زن است. چه می‌کنید؟","sen":"The traffic light at the junction is flashing yellow. What do you do?","st":[{"da":"Lastbilen skal holde tilbage for mig, fordi den kommer fra venstre.","fa":"کامیون باید به من راه بدهد، چون از سمت چپ می‌آید.","ok":0,"eda":"Nej. Med vigepligtstavlen holder du tilbage for trafikken fra begge sider.","efa":"خیر. با تابلوی راه بدهید، به ترافیک هر دو طرف راه می‌دهید.","en":"The lorry must give way to me because it comes from the left.","een":"No. With the give-way sign you give way to traffic from both sides."},{"da":"Jeg følger tavlen og hajtænderne og har ubetinget vigepligt.","fa":"از تابلو و دندان‌کوسه پیروی می‌کنم و بی‌قیدوشرط راه می‌دهم.","ok":1,"eda":"Ja. Når signalet blinker gult, gælder tavler og afmærkning.","efa":"بله. وقتی چراغ زرد چشمک می‌زند، تابلوها و خط‌کشی‌ها معتبرند.","en":"I follow the sign and the shark teeth and give way unconditionally.","een":"Yes. When the signal flashes yellow, the signs and markings apply."},{"da":"Blinkende gult betyder, at jeg har forkørselsret.","fa":"زرد چشمک‌زن یعنی حق تقدم با من است.","ok":0,"eda":"Nej. Blinkende gult giver ikke forkørselsret; tavlen giver dig vigepligt.","efa":"خیر. زرد چشمک‌زن حق تقدم نمی‌دهد؛ تابلو شما را موظف به راه دادن می‌کند.","en":"A flashing yellow light means I have the right of way.","een":"No. A flashing yellow light gives no right of way; the sign makes you give way."},{"da":"Jeg kører frem med særlig forsigtighed.","fa":"با احتیاط ویژه جلو می‌روم.","ok":1,"eda":"Ja. Blinkende gult advarer om, at du skal være ekstra opmærksom.","efa":"بله. زرد چشمک‌زن هشدار می‌دهد که باید بیشتر مراقب باشید.","en":"I drive on with special care.","een":"Yes. A flashing yellow light warns you to be extra attentive."}]},{"id":5043,"img":"newq-art/5043.png","c":"7.12","sda":"Du får grønt lys, men en ældre mand er stadig på fodgængerfeltet foran dig. Hvordan forholder du dig?","sfa":"چراغ شما سبز می‌شود، ولی مرد مسنی هنوز روی گذرگاه عابر جلوی شماست. چه می‌کنید؟","sen":"You get a green light, but an elderly man is still on the pedestrian crossing in front of you. What do you do?","st":[{"da":"Jeg dytter, så han skynder sig.","fa":"بوق می‌زنم تا عجله کند.","ok":0,"eda":"Nej. Et dyt kan forskrække og få ham til at falde.","efa":"خیر. بوق می‌تواند او را بترساند و باعث افتادنش شود.","en":"I sound the horn so that he hurries.","een":"No. A horn can startle him and make him fall."},{"da":"Jeg holder tilbage og lader ham komme over.","fa":"صبر می‌کنم تا رد شود.","ok":1,"eda":"Ja. Ved et reguleret fodgængerfelt skal du holde tilbage for gående, der allerede er på feltet.","efa":"بله. در گذرگاه چراغ‌دار، باید به عابرانی که روی گذرگاه‌اند راه بدهید.","en":"I wait and let him get across.","een":"Yes. At a controlled crossing you must give way to pedestrians already on it."},{"da":"Jeg kører, fordi jeg har grønt, og han har rødt.","fa":"حرکت می‌کنم، چون چراغ من سبز و چراغ او قرمز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at køre ind på en, der allerede er på feltet.","efa":"خیر. چراغ سبز اجازه نمی‌دهد به سمت کسی که روی گذرگاه است برانید.","en":"I drive because I have green and he has red.","een":"No. A green light gives no right to drive at someone who is already on the crossing."},{"da":"Ældre mennesker kan have brug for længere tid til at gå over.","fa":"افراد مسن ممکن است برای رد شدن به زمان بیشتری نیاز داشته باشند.","ok":1,"eda":"Ja. Der skal vises særligt hensyn over for ældre mennesker.","efa":"بله. نسبت به افراد مسن باید ملاحظه‌ی ویژه داشت.","en":"Elderly people may need more time to cross.","een":"Yes. Special consideration must be shown to elderly people."}]},{"id":5044,"img":"newq-art/5044.png","c":"7.14","sda":"Du har grønt lys og vil svinge til venstre. En bil og en cyklist kommer imod dig. Hvordan forholder du dig?","sfa":"چراغ سبز است و می‌خواهید به چپ بپیچید. یک خودرو و یک دوچرخه‌سوار از روبه‌رو می‌آیند. چه می‌کنید؟","sen":"You have a green light and want to turn left. A car and a cyclist are coming towards you. What do you do?","st":[{"da":"Jeg holder tilbage for den modkørende bil.","fa":"به خودروی روبه‌رو راه می‌دهم.","ok":1,"eda":"Ja. Når du svinger til venstre, må du ikke genere de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I give way to the oncoming car.","een":"Yes. When you turn left you must not inconvenience oncoming traffic."},{"da":"Jeg kan køre lidt frem i krydset og vente der, hvis det ikke generer andre.","fa":"اگر مزاحم دیگران نباشد، می‌توانم کمی وارد تقاطع شوم و آن‌جا صبر کنم.","ok":1,"eda":"Ja. Så er du klar til at svinge, når de modkørende er passeret.","efa":"بله. این‌طور وقتی ترافیک روبه‌رو رد شد، آماده‌ی پیچیدن هستید.","en":"I may drive a little into the junction and wait there if it does not hinder others.","een":"Yes. Then you are ready to turn when the oncoming traffic has passed."},{"da":"Jeg har forkørselsret, fordi jeg har grønt.","fa":"حق تقدم با من است، چون چراغم سبز است.","ok":0,"eda":"Nej. De modkørende har også grønt, og den venstresvingende skal vente.","efa":"خیر. ترافیک روبه‌رو هم سبز است و کسی که به چپ می‌پیچد باید صبر کند.","en":"I have the right of way because I have green.","een":"No. The oncoming traffic also has green, and the left-turner must wait."},{"da":"Jeg holder også tilbage for den modkørende cyklist.","fa":"به دوچرخه‌سوار روبه‌رو هم راه می‌دهم.","ok":1,"eda":"Ja. Reglen gælder alle modkørende, også cyklister.","efa":"بله. این قاعده برای همه‌ی ترافیک روبه‌رو، از جمله دوچرخه‌سواران، است.","en":"I also give way to the oncoming cyclist.","een":"Yes. The rule applies to all oncoming traffic, cyclists too."}]},{"id":5045,"img":"newq-art/5045.png","c":"7.14","sda":"Du vil svinge til venstre ind på sidevejen. Hvordan placerer du bilen?","sfa":"می‌خواهید به چپ وارد فرعی شوید. خودرو را چطور قرار می‌دهید؟","sen":"You want to turn left into the side road. How do you position the car?","st":[{"da":"Jeg kører først ind til højre kant for at få et bredere sving.","fa":"اول به لبه‌ی راست می‌روم تا گردش بازتری داشته باشم.","ok":0,"eda":"Nej. Det forvirrer trafikken bag dig, som tror, du vil svinge til højre.","efa":"خیر. این کار ترافیک پشت سر را که خیال می‌کنند به راست می‌پیچید، گیج می‌کند.","en":"I first move to the right edge to get a wider turn.","een":"No. It confuses the traffic behind you, who think you are turning right."},{"da":"Jeg skærer svinget, så jeg hurtigt kommer ud af krydset.","fa":"گوشه را میان‌بر می‌زنم تا زود از تقاطع بیرون بروم.","ok":0,"eda":"Nej. Så kommer du over i venstre side af sidevejen og kan ramme en, der kommer ud.","efa":"خیر. این‌طور به سمت چپ فرعی می‌روید و ممکن است با کسی که بیرون می‌آید برخورد کنید.","en":"I cut the corner so that I get out of the junction quickly.","een":"No. Then you end up on the left side of the side road and may hit someone coming out."},{"da":"Så tæt på midten af vejen som muligt, før jeg svinger.","fa":"پیش از پیچیدن، تا جای ممکن نزدیک وسط جاده.","ok":1,"eda":"Ja. Ved venstresving skal du holde nær midten af kørebanen.","efa":"بله. در گردش به چپ باید نزدیک وسط سواره‌رو بمانید.","en":"As close to the middle of the road as possible before I turn.","een":"Yes. When turning left you must keep near the middle of the carriageway."},{"da":"Efter svinget kører jeg i højre side af sidevejen.","fa":"بعد از پیچیدن در سمت راست فرعی می‌رانم.","ok":1,"eda":"Ja. Svinget skal ende i højre side af den vej, du kører ind på.","efa":"بله. گردش باید در سمت راستِ جاده‌ای که واردش می‌شوید تمام شود.","en":"After the turn I drive on the right side of the side road.","een":"Yes. The turn must end on the right side of the road you enter."}]},{"id":5046,"img":"newq-art/5046.png","c":"7.14","sda":"Du vil svinge til venstre. To fodgængere går over sidevejen, du skal ind på. Hvordan forholder du dig?","sfa":"می‌خواهید به چپ بپیچید. دو عابر در حال عبور از فرعی‌ای هستند که می‌خواهید واردش شوید. چه می‌کنید؟","sen":"You want to turn left. Two pedestrians are crossing the side road you are turning into. What do you do?","st":[{"da":"Fodgængerne skal vente, fordi jeg allerede er i gang med at svinge.","fa":"عابران باید صبر کنند، چون من در حال پیچیدن هستم.","ok":0,"eda":"Nej. Det er dig, der skal tage hensyn til fodgængerne.","efa":"خیر. شما هستید که باید مراقب عابران باشید.","en":"The pedestrians must wait because I am already turning.","een":"No. It is you who must take care of the pedestrians."},{"da":"Jeg ser efter fodgængere i sidevejen, før jeg begynder at svinge.","fa":"پیش از شروع پیچیدن، عابران فرعی را نگاه می‌کنم.","ok":1,"eda":"Ja. Så kan du vente det rigtige sted uden at spærre for andre.","efa":"بله. این‌طور می‌توانید در جای درست صبر کنید بی‌آنکه راه را ببندید.","en":"I look for pedestrians in the side road before I start to turn.","een":"Yes. Then you can wait in the right place without blocking others."},{"da":"Jeg venter, til fodgængerne er kommet over.","fa":"صبر می‌کنم تا عابران رد شوند.","ok":1,"eda":"Ja. Når du svinger, må du ikke være til fare for gående, der går over den vej, du svinger ind på.","efa":"بله. هنگام پیچیدن نباید عابرانی را که از جاده‌ی مقصد رد می‌شوند به خطر بیندازید.","en":"I wait until the pedestrians are across.","een":"Yes. When you turn you must not endanger pedestrians crossing the road you turn into."}]},{"id":5047,"img":"newq-art/5047.png","c":"7.14","sda":"Både du og den modkørende vil svinge til venstre i krydset. Hvad gælder?","sfa":"هم شما و هم راننده‌ی روبه‌رو می‌خواهید در تقاطع به چپ بپیچید. چه قاعده‌ای برقرار است؟","sen":"Both you and the oncoming driver want to turn left in the junction. What applies?","st":[{"da":"Den, der kom først til krydset, har forkørselsret og svinger først.","fa":"هر کس اول به تقاطع رسیده، حق تقدم دارد و اول می‌پیچد.","ok":0,"eda":"Nej. Der er ingen sådan regel; I kan svinge samtidig og passere hinanden til venstre.","efa":"خیر. چنین قاعده‌ای نیست؛ می‌توانید هم‌زمان بپیچید و از سمت چپ از کنار هم رد شوید.","en":"Whoever reached the junction first has the right of way and turns first.","een":"No. There is no such rule; you can turn at the same time and pass each other on the left."},{"da":"Vi kan køre forbi hinanden til venstre, hvis det kan ske uden fare.","fa":"اگر بی‌خطر باشد، می‌توانیم از سمت چپ از کنار هم رد شویم.","ok":1,"eda":"Ja. Modkørende venstresvingende må køre forbi hinanden til venstre.","efa":"بله. دو خودروی روبه‌رو که به چپ می‌پیچند، می‌توانند از سمت چپ از کنار هم رد شوند.","en":"We may pass each other on the left if it can be done safely.","een":"Yes. Oncoming left-turners may pass each other on the left."},{"da":"Vi skal begge holde tilbage for modkørende, der kører ligeud.","fa":"هر دو باید به ترافیک روبه‌رویی که مستقیم می‌رود راه بدهیم.","ok":1,"eda":"Ja. Den grå bil, der kører ligeud, skal kunne passere først.","efa":"بله. باید بگذاریم خودروی خاکستری که مستقیم می‌رود اول رد شود.","en":"We must both give way to oncoming traffic going straight on.","een":"Yes. The grey car going straight on must be allowed to pass first."}]},{"id":5048,"img":"newq-art/5048.png","c":"7.14","sda":"Du kører på en ensrettet vej og vil svinge til venstre. Hvordan placerer du dig?","sfa":"در جاده‌ی یک‌طرفه می‌رانید و می‌خواهید به چپ بپیچید. چطور قرار می‌گیرید؟","sen":"You are on a one-way road and want to turn left. How do you position yourself?","st":[{"da":"Jeg blinker i god tid og sikrer mig, at svinget kan ske uden fare for trafikken bag mig.","fa":"به موقع راهنما می‌زنم و مطمئن می‌شوم گردش برای ترافیک پشت سرم بی‌خطر است.","ok":1,"eda":"Ja. Signalet skal gives i god tid, og du må ikke bringe trafikken bag dig i fare.","efa":"بله. علامت باید به موقع داده شود و نباید ترافیک پشت سر را به خطر بیندازید.","en":"I indicate in good time and make sure the turn can be made without danger to the traffic behind me.","een":"Yes. The signal must be given in good time, and you must not endanger the traffic behind you."},{"da":"Så langt til venstre som muligt.","fa":"تا جای ممکن سمت چپ.","ok":1,"eda":"Ja. På en ensrettet vej skal du ved venstresving holde nær venstre kant.","efa":"بله. در جاده‌ی یک‌طرفه برای گردش به چپ باید نزدیک لبه‌ی چپ باشید.","en":"As far to the left as possible.","een":"Yes. On a one-way road you keep near the left edge when turning left."},{"da":"Nær midten af vejen, som når jeg svinger til venstre fra en almindelig vej.","fa":"نزدیک وسط جاده، مثل گردش به چپ از یک جاده‌ی معمولی.","ok":0,"eda":"Nej. Der er ingen modkørende; du placerer dig ved venstre kant.","efa":"خیر. ترافیک روبه‌رو نیست؛ کنار لبه‌ی چپ قرار می‌گیرید.","en":"Near the middle of the road, as when I turn left from an ordinary road.","een":"No. There is no oncoming traffic; you position yourself at the left edge."}]},{"id":5049,"img":"newq-art/5049.png","c":"7.13","sda":"Du vil svinge til højre. På cykelstien til højre for dig kører en cyklist ligeud. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. روی مسیر دوچرخه‌ی سمت راستتان دوچرخه‌سواری مستقیم می‌رود. چه می‌کنید؟","sen":"You want to turn right. On the cycle path to your right a cyclist is going straight on. What do you do?","st":[{"da":"Jeg skynder mig at svinge, før cyklisten når krydset.","fa":"عجله می‌کنم پیش از رسیدن دوچرخه‌سوار به تقاطع بپیچم.","ok":0,"eda":"Nej. Det er farligt; cyklisten kan være tættere på, end du tror.","efa":"خیر. خطرناک است؛ ممکن است دوچرخه‌سوار نزدیک‌تر از آن باشد که فکر می‌کنید.","en":"I hurry to turn before the cyclist reaches the junction.","een":"No. That is dangerous; the cyclist may be closer than you think."},{"da":"Cyklisten skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سوار باید راه بدهد، چون من راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke forkørselsret.","efa":"خیر. راهنما به شما حق تقدم نمی‌دهد.","en":"The cyclist must give way because I am indicating.","een":"No. The indicator does not give you the right of way."},{"da":"Jeg kigger over højre skulder for at se i den blinde vinkel.","fa":"از روی شانه‌ی راست به نقطه‌ی کور نگاه می‌کنم.","ok":1,"eda":"Ja. En cyklist tæt ved bilen kan være skjult i den blinde vinkel.","efa":"بله. دوچرخه‌سواری نزدیک خودرو ممکن است در نقطه‌ی کور پنهان باشد.","en":"I look over my right shoulder to check the blind spot.","een":"Yes. A cyclist close to the car may be hidden in the blind spot."},{"da":"Jeg holder tilbage for cyklisten, der kører ligeud.","fa":"به دوچرخه‌سواری که مستقیم می‌رود راه می‌دهم.","ok":1,"eda":"Ja. Ved højresving må du ikke genere cyklister, der kører ligeud.","efa":"بله. در گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I give way to the cyclist going straight on.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."}]},{"id":5050,"img":"newq-art/5050.png","c":"7.13","sda":"Du vil svinge til højre ind på sidevejen. Hvordan kører du?","sfa":"می‌خواهید به راست وارد فرعی شوید. چطور می‌رانید؟","sen":"You want to turn right into the side road. How do you drive?","st":[{"da":"Jeg holder farten i svinget, så jeg ikke generer trafikken bag mig.","fa":"سرعتم را در پیچ حفظ می‌کنم تا مزاحم ترافیک پشت سرم نشوم.","ok":0,"eda":"Nej. Ved sving skal farten ned, så du kan svinge sikkert og se efter cyklister og gående.","efa":"خیر. هنگام پیچیدن باید سرعت را کم کنید تا ایمن بپیچید و دوچرخه‌سواران و عابران را ببینید.","en":"I keep my speed in the turn so that I do not hold up the traffic behind me.","een":"No. When turning your speed must come down so that you can turn safely and look for cyclists and pedestrians."},{"da":"Jeg trækker først ud mod midten for at få et bredere sving.","fa":"اول به سمت وسط می‌روم تا گردش بازتری داشته باشم.","ok":0,"eda":"Nej. Så kan en bagfra eller en cyklist komme ind i højre side af dig.","efa":"خیر. این‌طور ممکن است کسی از پشت یا دوچرخه‌سواری از سمت راستتان بیاید.","en":"I first pull out towards the middle to get a wider turn.","een":"No. Then someone from behind or a cyclist may come up on your right."},{"da":"Jeg svinger ind i venstre side af sidevejen for ikke at ramme kantstenen.","fa":"به سمت چپ فرعی می‌پیچم تا به جدول نخورم.","ok":0,"eda":"Nej. Du skal ende i højre side af den vej, du kører ind på.","efa":"خیر. باید در سمت راستِ جاده‌ای که واردش می‌شوید قرار بگیرید.","en":"I turn into the left side of the side road so as not to hit the kerb.","een":"No. You must end up on the right side of the road you enter."},{"da":"Jeg holder så tæt ind til højre kant som muligt og gør svinget lille.","fa":"تا جای ممکن نزدیک لبه‌ی راست می‌مانم و گردش را کوچک می‌گیرم.","ok":1,"eda":"Ja. Ved højresving skal du holde nær højre kant og svinge så lidt som muligt.","efa":"بله. در گردش به راست باید نزدیک لبه‌ی راست بمانید و تا جای ممکن کوچک بپیچید.","en":"I keep as close to the right edge as possible and make the turn small.","een":"Yes. When turning right you keep near the right edge and turn as tightly as possible."}]},{"id":5051,"img":"newq-art/5051.png","c":"7.13","sda":"Du har grønt lys og vil svinge til højre. Fodgængere går over den vej, du skal ind på. Hvordan forholder du dig?","sfa":"چراغ شما سبز است و می‌خواهید به راست بپیچید. عابران از جاده‌ای که می‌خواهید واردش شوید رد می‌شوند. چه می‌کنید؟","sen":"You have a green light and want to turn right. Pedestrians are crossing the road you are turning into. What do you do?","st":[{"da":"Jeg dytter for at advare dem om, at jeg svinger.","fa":"بوق می‌زنم تا بدانند می‌پیچم.","ok":0,"eda":"Nej. Hornet bruges kun for at afværge fare; her skal du blot vente.","efa":"خیر. بوق فقط برای دفع خطر است؛ این‌جا فقط باید صبر کنید.","en":"I sound the horn to warn them that I am turning.","een":"No. The horn is only for averting danger; here you just wait."},{"da":"Jeg kører forsigtigt ind mellem fodgængerne.","fa":"با احتیاط از میان عابران رد می‌شوم.","ok":0,"eda":"Nej. Du må ikke køre ind på feltet, mens de gående er på det.","efa":"خیر. وقتی عابران روی گذرگاه‌اند، نباید واردش شوید.","en":"I drive carefully in between the pedestrians.","een":"No. You must not drive onto the crossing while the pedestrians are on it."},{"da":"Jeg holder tilbage for fodgængerne, til de er kommet over.","fa":"تا رد شدن عابران صبر می‌کنم.","ok":1,"eda":"Ja. Når du svinger gennem et fodgængerfelt, skal du sænke farten og om nødvendigt standse for de gående.","efa":"بله. وقتی از روی گذرگاه عابر می‌پیچید، باید سرعت را کم کنید و در صورت لزوم برای عابران بایستید.","en":"I wait for the pedestrians until they are across.","een":"Yes. When you turn through a pedestrian crossing you must slow down and stop if necessary for the pedestrians."},{"da":"Fodgængerne skal vente, fordi jeg også har grønt.","fa":"عابران باید صبر کنند، چون چراغ من هم سبز است.","ok":0,"eda":"Nej. Fodgængerne har grønt samtidig med dig; du skal vente på dem.","efa":"خیر. عابران هم‌زمان با شما سبزند؛ شما باید منتظرشان بمانید.","en":"The pedestrians must wait because I have green too.","een":"No. The pedestrians have green at the same time as you; you must wait for them."}]},{"id":5052,"img":"newq-art/5052.png","c":"7.13","sda":"Du vil svinge til højre. Cykelstien er dobbeltrettet, og en cyklist kommer imod dig på den. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. مسیر دوچرخه دوطرفه است و دوچرخه‌سواری روی آن از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You want to turn right. The cycle path is two-way, and a cyclist is coming towards you on it. What do you do?","st":[{"da":"Cyklister på cykelstien kommer kun fra én retning.","fa":"دوچرخه‌سواران روی این مسیر فقط از یک جهت می‌آیند.","ok":0,"eda":"Nej. Pilene viser, at stien er dobbeltrettet.","efa":"خیر. فلش‌ها نشان می‌دهند که مسیر دوطرفه است.","en":"Cyclists on the cycle path only come from one direction.","een":"No. The arrows show that the path is two-way."},{"da":"Jeg holder tilbage for cyklisten, der kommer imod mig på cykelstien.","fa":"به دوچرخه‌سواری که روی مسیر دوچرخه از روبه‌رو می‌آید راه می‌دهم.","ok":1,"eda":"Ja. Ved højresving må du ikke være til ulempe for cyklister, der kører ligeud; på en dobbeltrettet cykelsti også dem, der kommer imod dig.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند؛ در مسیر دوچرخه‌ی دوطرفه، این شامل کسانی هم می‌شود که از روبه‌رو می‌آیند.","en":"I give way to the cyclist coming towards me on the cycle path.","een":"Yes. When turning right you must not inconvenience cyclists going straight ahead; on a two-way cycle path that includes those coming towards you."},{"da":"Jeg ser efter cyklister fra begge retninger.","fa":"دوچرخه‌سواران هر دو جهت را نگاه می‌کنم.","ok":1,"eda":"Ja. På en dobbeltrettet cykelsti kan der komme cyklister både bagfra og forfra.","efa":"بله. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سواران هم از پشت و هم از جلو می‌آیند.","en":"I look for cyclists coming from both directions.","een":"Yes. On a two-way cycle path cyclists can come both from behind and from ahead."},{"da":"Jeg har forkørselsret, fordi cyklisten kører mod færdselsretningen.","fa":"حق تقدم با من است، چون دوچرخه‌سوار خلاف جهت ترافیک می‌رود.","ok":0,"eda":"Nej. På en dobbeltrettet cykelsti kører cyklisten lovligt i begge retninger.","efa":"خیر. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سوار مجاز است در هر دو جهت برود.","en":"I have the right of way because the cyclist is riding against the traffic.","een":"No. On a two-way cycle path the cyclist may lawfully ride in both directions."}]},{"id":5053,"img":"newq-art/5053.png","c":"1.2","sda":"Hvad er den mindste lovlige mønsterdybde i hovedmønsteret på en almindelig bils dæk?","sfa":"کمترین عمق مجاز آج در شیارهای اصلی لاستیک یک خودروی معمولی چقدر است؟","sen":"What is the smallest legal tread depth in the main grooves of an ordinary car's tyres?","st":[{"da":"1,6 mm.","fa":"۱٫۶ میلی‌متر.","ok":1,"eda":"Ja. Mønsterdybden skal være mindst 1,6 mm i hovedmønsteret.","efa":"بله. عمق آج در شیارهای اصلی باید دست‌کم ۱٫۶ میلی‌متر باشد.","en":"1.6 mm.","een":"Yes. The tread depth must be at least 1.6 mm in the main grooves."},{"da":"Der er intet krav, så længe dækket holder luft.","fa":"تا وقتی لاستیک باد نگه دارد، شرطی نیست.","ok":0,"eda":"Nej. Der er et lovkrav til mønsterdybden.","efa":"خیر. برای عمق آج حد قانونی وجود دارد.","en":"There is no requirement as long as the tyre holds air.","een":"No. There is a legal requirement for the tread depth."},{"da":"3 mm.","fa":"۳ میلی‌متر.","ok":0,"eda":"Nej. Mere mønster er godt især om vinteren, men kravet er 1,6 mm.","efa":"خیر. آج بیشتر به‌ویژه در زمستان خوب است، ولی حد قانونی ۱٫۶ میلی‌متر است.","en":"3 mm.","een":"No. More tread is good, especially in winter, but the requirement is 1.6 mm."},{"da":"1,0 mm.","fa":"۱٫۰ میلی‌متر.","ok":0,"eda":"Nej. 1,0 mm er under den lovlige grænse.","efa":"خیر. ۱٫۰ میلی‌متر کمتر از حد مجاز است.","en":"1.0 mm.","een":"No. 1.0 mm is below the legal limit."}]},{"id":5054,"img":"newq-art/5054.png","c":"1.2","sda":"Du opdager, at det ene af bilens bremselys ikke virker. Hvad gælder?","sfa":"متوجه می‌شوید یکی از چراغ‌های ترمز خودرو کار نمی‌کند. چه قاعده‌ای برقرار است؟","sen":"You find out that one of the car's brake lights is not working. What applies?","st":[{"da":"Bilen er ikke i lovlig stand, og jeg skal have det repareret.","fa":"خودرو در وضعیت قانونی نیست و باید تعمیرش کنم.","ok":1,"eda":"Ja. Alle påbudte lygter skal virke.","efa":"بله. همه‌ی چراغ‌های الزامی باید کار کنند.","en":"The car is not in a lawful condition and I must get it repaired.","een":"Yes. All required lights must work."},{"da":"Det er lovligt, så længe det andet bremselys virker.","fa":"تا وقتی چراغ ترمز دیگر کار کند، قانونی است.","ok":0,"eda":"Nej. Begge bremselys skal virke.","efa":"خیر. هر دو چراغ ترمز باید کار کنند.","en":"It is legal as long as the other brake light works.","een":"No. Both brake lights must work."},{"da":"Jeg kan bruge havariblinket i stedet, når jeg bremser.","fa":"هنگام ترمز می‌توانم به‌جایش چراغ خطر بزنم.","ok":0,"eda":"Nej. Havariblinket er ikke en erstatning for bremselyset.","efa":"خیر. چراغ خطر جایگزین چراغ ترمز نیست.","en":"I can use the hazard lights instead when I brake.","een":"No. The hazard lights are no substitute for the brake light."},{"da":"Jeg kan vente med at få det repareret, til bilen skal til syn næste gang.","fa":"می‌توانم تعمیرش را تا معاینه‌ی فنی بعدی خودرو عقب بیندازم.","ok":0,"eda":"Nej. Bilen skal være i lovlig stand, hver gang du kører; bremselyset advarer dem bag dig og skal virke.","efa":"خیر. خودرو هر بار که رانندگی می‌کنید باید در وضعیت قانونی باشد؛ چراغ ترمز به پشت‌سری‌ها هشدار می‌دهد و باید کار کند.","en":"I can wait to have it repaired until the car's next inspection.","een":"No. The car must be in a lawful condition every time you drive; the brake light warns those behind you and must work."}]},{"id":5055,"img":"newq-art/5055.png","c":"1.2","sda":"Det er vinter, og der ligger sne og sjap på vejen. Hvad gælder om bilens dæk?","sfa":"زمستان است و روی جاده برف و برفابه است. درباره‌ی لاستیک‌های خودرو چه قاعده‌ای برقرار است؟","sen":"It is winter, and there is snow and slush on the road. What applies to the car's tyres?","st":[{"da":"Det er mig som fører, der har ansvaret for, at dækkene passer til føret.","fa":"این من، یعنی راننده، هستم که مسئولم لاستیک‌ها با وضعیت جاده جور باشند.","ok":1,"eda":"Ja. Føreren skal selv sørge for, at bilen, også dækkene, er i forsvarlig stand til den kørsel, der skal ske.","efa":"بله. راننده خودش باید مطمئن شود خودرو، از جمله لاستیک‌ها، برای رانندگی پیش رو در وضعیت ایمنی است.","en":"It is me, the driver, who is responsible for the tyres suiting the conditions.","een":"Yes. The driver must make sure that the car, including its tyres, is in a safe condition for the driving to be done."},{"da":"Sommerdæk er lovlige i alt slags føre, når bare mønsterdybden er mindst 1,6 mm.","fa":"لاستیک تابستانی در هر وضعیتی از جاده قانونی است، به شرط آن‌که عمق آجش دست‌کم ۱٫۶ میلی‌متر باشد.","ok":0,"eda":"Nej. Sommerdæk i sne, sjap og slud anses i praksis for uegnede og dermed ulovlige.","efa":"خیر. لاستیک تابستانی در برف، برفابه و باران‌برف در عمل نامناسب و در نتیجه غیرقانونی شمرده می‌شود.","en":"Summer tyres are legal in all road conditions as long as the tread depth is at least 1.6 mm.","een":"No. Summer tyres in snow, slush and sleet are in practice considered unsuitable and so illegal."},{"da":"Jeg må ikke køre med dæk, der er åbenbart uegnede til føret.","fa":"نباید با لاستیک‌هایی برانم که آشکارا برای وضعیت جاده مناسب نیستند.","ok":1,"eda":"Ja. Siden 1. juli 2025 er det ulovligt at køre med dæk, der er åbenbart uegnede til føret, fx sommerdæk i sne og sjap.","efa":"بله. از ۱ ژوئیه‌ی ۲۰۲۵ رانندگی با لاستیک‌هایی که آشکارا برای وضعیت جاده نامناسب‌اند، مثلاً لاستیک تابستانی در برف و برفابه، غیرقانونی است.","en":"I must not drive on tyres that are obviously unsuitable for the road conditions.","een":"Yes. Since 1 July 2025 it is illegal to drive on tyres that are obviously unsuitable for the conditions, for example summer tyres in snow and slush."},{"da":"Pigdæk må bruges i perioden fra 1. november til 15. april.","fa":"لاستیک میخ‌دار را می‌توان از ۱ نوامبر تا ۱۵ آوریل استفاده کرد.","ok":1,"eda":"Ja. I Danmark er pigdæk tilladt fra 1. november til 15. april.","efa":"بله. در دانمارک لاستیک میخ‌دار از ۱ نوامبر تا ۱۵ آوریل مجاز است.","en":"Studded tyres may be used in the period from 1 November to 15 April.","een":"Yes. In Denmark studded tyres are allowed from 1 November to 15 April."}]},{"id":5056,"img":"newq-art/5056.png","c":"1.2","sda":"Hvordan skal nakkestøtten være indstillet?","sfa":"پشت‌سری صندلی چطور باید تنظیم شود؟","sen":"How should the head restraint be set?","st":[{"da":"Den beskytter mod nakkeskader ved påkørsel bagfra.","fa":"در تصادف از پشت، از آسیب گردن جلوگیری می‌کند.","ok":1,"eda":"Ja. Nakkestøtten forhindrer, at hovedet slynges bagover.","efa":"بله. پشت‌سری نمی‌گذارد سر به عقب پرتاب شود.","en":"It protects against neck injuries in a rear-end collision.","een":"Yes. The head restraint stops the head from being thrown backwards."},{"da":"Overkanten skal være i højde med toppen af hovedet og tæt ved hovedet.","fa":"لبه‌ی بالایش باید هم‌سطح بالای سر و نزدیک سر باشد.","ok":1,"eda":"Ja. Så støtter den hovedet bedst ved et stød bagfra.","efa":"بله. این‌طور در ضربه از پشت، بهترین پشتیبانی را از سر می‌کند.","en":"Its top edge should be level with the top of the head and close to the head.","een":"Yes. Then it supports the head best in an impact from behind."},{"da":"Den skal sidde så lavt som muligt for at give udsyn bagud.","fa":"باید تا جای ممکن پایین باشد تا دید عقب بهتر شود.","ok":0,"eda":"Nej. En lav nakkestøtte kan give alvorlige nakkeskader.","efa":"خیر. پشت‌سری پایین می‌تواند آسیب جدی به گردن بزند.","en":"It should be as low as possible to give a view to the rear.","een":"No. A low head restraint can cause serious neck injuries."},{"da":"Nakkestøtten skal indstilles efter den, der sidder i sædet.","fa":"پشت‌سری باید برای همان کسی تنظیم شود که روی صندلی نشسته است.","ok":1,"eda":"Ja. Folk er forskellige høje; tjek indstillingen, når en anden skal sidde i sædet.","efa":"بله. قد آدم‌ها فرق دارد؛ وقتی کس دیگری روی صندلی می‌نشیند، تنظیم را بررسی کنید.","en":"The head restraint must be set for the person sitting in the seat.","een":"Yes. People are of different heights; check the setting when someone else is going to sit in the seat."}]},{"id":5057,"img":"newq-art/5057.png","c":"1.2","sda":"Du skal køre med tunge kasser i bilen. Hvordan forholder du dig?","sfa":"باید با جعبه‌های سنگین در خودرو رانندگی کنید. چه می‌کنید؟","sen":"You are going to drive with heavy boxes in the car. What do you do?","st":[{"da":"Jeg sikrer lasten, så den ikke kan flytte sig.","fa":"بار را محکم می‌کنم تا جابه‌جا نشود.","ok":1,"eda":"Ja. Løs last kan blive kastet frem ved en kraftig opbremsning.","efa":"بله. بار شل در ترمز شدید به جلو پرتاب می‌شود.","en":"I secure the load so that it cannot move.","een":"Yes. A loose load can be thrown forward in hard braking."},{"da":"Tunge ting lægges så lavt og så langt frem i bagagerummet som muligt.","fa":"وسایل سنگین تا جای ممکن پایین و جلوی صندوق گذاشته می‌شوند.","ok":1,"eda":"Ja. Så påvirker de bilens køreegenskaber mindst og bliver bedst holdt på plads.","efa":"بله. این‌طور کمترین اثر را بر رفتار خودرو دارند و بهتر سر جایشان می‌مانند.","en":"Heavy items go as low and as far forward in the boot as possible.","een":"Yes. Then they affect the car's handling least and are held in place best."},{"da":"Værktøjskassen kan godt ligge løst på hattehylden.","fa":"جعبه‌ابزار می‌تواند شل روی طاقچه‌ی عقب بماند.","ok":0,"eda":"Nej. En tung, løs genstand på hattehylden kan ramme dem i bilen ved et brat stop.","efa":"خیر. شیء سنگین و شل روی طاقچه‌ی عقب، در توقف ناگهانی به سرنشینان می‌خورد.","en":"The toolbox can lie loose on the parcel shelf.","een":"No. A heavy loose object on the parcel shelf can hit the people in the car in a sudden stop."},{"da":"Lasten påvirker ikke bilens bremselængde.","fa":"بار روی مسافت ترمز خودرو اثری ندارد.","ok":0,"eda":"Nej. En tungt lastet bil har længere bremselængde.","efa":"خیر. خودروی پربار مسافت ترمز بیشتری دارد.","en":"The load does not affect the car's braking distance.","een":"No. A heavily loaded car has a longer braking distance."}]},{"id":5058,"img":"newq-art/5058.png","c":"7.7","sda":"Vejen er så smal, at to biler ikke kan passere hinanden. En varevogn kommer imod dig. Hvordan forholder du dig?","sfa":"جاده آن‌قدر باریک است که دو خودرو نمی‌توانند از کنار هم رد شوند. ونی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"The road is so narrow that two cars cannot pass each other. A van is coming towards you. What do you do?","st":[{"da":"Jeg sænker farten og holder så langt til højre som muligt.","fa":"سرعتم را کم می‌کنم و تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde skal du holde til højre og tilpasse farten.","efa":"بله. در برخورد با خودروی روبه‌رو باید سمت راست بمانید و سرعت را تنظیم کنید.","en":"I slow down and keep as far to the right as possible.","een":"Yes. When meeting you must keep right and adjust your speed."},{"da":"Jeg kører ind på vigepladsen i min side og lader varevognen passere.","fa":"وارد جای کنار جاده در سمت خودم می‌شوم و می‌گذارم ون رد شود.","ok":1,"eda":"Ja. Ved møde på smal vej skal den, der kan, give plads; her har du vigepladsen i din side.","efa":"بله. در برخورد در جاده‌ی باریک، هر که بتواند باید جا بدهد؛ این‌جا جای کنار جاده در سمت شماست.","en":"I pull into the passing place on my side and let the van pass.","een":"Yes. When meeting on a narrow road, whoever can must make room; here the passing place is on your side."},{"da":"Jeg blinker med lyset for at få varevognen til at bakke.","fa":"چراغ می‌زنم تا ون دنده‌عقب برود.","ok":0,"eda":"Nej. Lyssignaler giver ikke forkørselsret, og bakning er ofte farligere.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد و دنده‌عقب رفتن اغلب خطرناک‌تر است.","en":"I flash my lights to make the van reverse.","een":"No. Flashing lights gives no right of way, and reversing is often more dangerous."},{"da":"Den, der kører hurtigst, skal holde tilbage.","fa":"هر که تندتر می‌رود باید راه بدهد.","ok":0,"eda":"Nej. Der er ingen sådan regel; I skal sammen finde en sikker løsning.","efa":"خیر. چنین قاعده‌ای نیست؛ باید با هم راه ایمنی پیدا کنید.","en":"Whoever is driving fastest must give way.","een":"No. There is no such rule; together you must find a safe solution."}]},{"id":5059,"img":"newq-art/5059.png","c":"7.7","sda":"Du bliver blændet af en modkørende bil. Hvordan forholder du dig?","sfa":"خودروی روبه‌رو چشم شما را خیره کرده است. چه می‌کنید؟","sen":"You are dazzled by an oncoming car. What do you do?","st":[{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du ikke kan se, hvad der er foran, skal hastigheden ned.","efa":"بله. وقتی جلو را نمی‌بینید، باید سرعت را کم کنید.","en":"I slow down.","een":"Yes. When you cannot see what is ahead, your speed must come down."},{"da":"Jeg ser mod højre vejkant.","fa":"به لبه‌ی راست جاده نگاه می‌کنم.","ok":1,"eda":"Ja. Så bliver du mindre blændet og kan holde din plads på vejen.","efa":"بله. این‌طور کمتر خیره می‌شوید و جایتان را در جاده حفظ می‌کنید.","en":"I look towards the right edge of the road.","een":"Yes. That way you are dazzled less and can keep your place on the road."},{"da":"Jeg tænder fjernlyset for at blænde den modkørende igen.","fa":"نور بالا را روشن می‌کنم تا راننده‌ی روبه‌رو را هم خیره کنم.","ok":0,"eda":"Nej. Så kan I begge ikke se noget; det er farligt.","efa":"خیر. این‌طور هیچ‌کدام چیزی نمی‌بینید؛ خطرناک است.","en":"I switch on my high beam to dazzle the oncoming driver back.","een":"No. Then neither of you can see anything; it is dangerous."},{"da":"Jeg er klar til at standse, hvis jeg ikke kan se vejen.","fa":"اگر جاده را نبینم، آماده‌ی ایستادن هستم.","ok":1,"eda":"Ja. Du skal kunne standse på den strækning, du kan overskue.","efa":"بله. باید بتوانید در فاصله‌ای که می‌بینید بایستید.","en":"I am ready to stop if I cannot see the road.","een":"Yes. You must be able to stop within the distance you can see."}]},{"id":5060,"img":"newq-art/5060.png","c":"7.7","sda":"En bred lastbil kommer imod dig på en smal vej. Hvordan forholder du dig?","sfa":"کامیون پهنی در جاده‌ای باریک از روبه‌رو می‌آید. چه می‌کنید؟","sen":"A wide lorry is coming towards you on a narrow road. What do you do?","st":[{"da":"Jeg sænker farten og holder godt til højre.","fa":"سرعتم را کم می‌کنم و خوب سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde skal du give den modkørende tilstrækkelig plads.","efa":"بله. در برخورد باید به وسیله‌ی روبه‌رو جای کافی بدهید.","en":"I slow down and keep well to the right.","een":"Yes. When meeting you must give the oncoming vehicle enough room."},{"da":"Luftsuget fra lastbilen kan rykke i min bil.","fa":"جریان هوای کامیون ممکن است خودروی مرا تکان بدهد.","ok":1,"eda":"Ja. Hold derfor godt fast i rattet og god afstand.","efa":"بله. پس فرمان را محکم نگه دارید و فاصله‌ی خوبی بگیرید.","en":"The air pressure from the lorry may pull at my car.","een":"Yes. So hold the wheel firmly and keep a good distance."},{"da":"Jeg holder fast i midten af min vognbane, fordi det er min side.","fa":"وسط خط خودم می‌مانم، چون سمت من است.","ok":0,"eda":"Nej. Du skal tilpasse dig og give plads, når den modkørende fylder meget.","efa":"خیر. وقتی وسیله‌ی روبه‌رو جای زیادی می‌گیرد، باید خودتان را تطبیق دهید و جا بدهید.","en":"I stay in the middle of my lane because it is my side.","een":"No. You must adapt and make room when the oncoming vehicle takes up a lot of space."},{"da":"Jeg standser om nødvendigt, hvor der er plads nok.","fa":"در صورت لزوم جایی که جای کافی هست می‌ایستم.","ok":1,"eda":"Ja. Det er bedre at vente kort end at møde lastbilen, hvor der ikke er plads.","efa":"بله. بهتر است کمی صبر کنید تا این‌که جایی که جا نیست با کامیون روبه‌رو شوید.","en":"I stop if necessary where there is enough room.","een":"Yes. It is better to wait briefly than to meet the lorry where there is no room."}]},{"id":5061,"img":"newq-art/5061.png","c":"7.11","sda":"Du skal ud på den tværgående vej. Hækkene skjuler udsynet. Hvordan forholder du dig?","sfa":"می‌خواهید وارد جاده‌ی متقاطع شوید. پرچین‌ها جلوی دید را گرفته‌اند. چه می‌کنید؟","sen":"You are going to drive onto the crossing road. The hedges hide the view. What do you do?","st":[{"da":"Jeg kører langsomt frem, til jeg kan se, om der kommer nogen.","fa":"آهسته جلو می‌روم تا ببینم کسی می‌آید یا نه.","ok":1,"eda":"Ja. Først når du kan se, at vejen er fri, kan du køre ud uden fare.","efa":"بله. فقط وقتی ببینید جاده خالی است، می‌توانید بی‌خطر وارد شوید.","en":"I edge forward slowly until I can see whether anyone is coming.","een":"Yes. Only when you can see that the road is clear can you drive out safely."},{"da":"Jeg kører ud, når jeg ikke kan høre nogen biler.","fa":"وقتی صدای خودرویی نمی‌شنوم، وارد می‌شوم.","ok":0,"eda":"Nej. Du kan ikke høre alle køretøjer, fx cyklister og elbiler.","efa":"خیر. صدای همه‌ی وسایل، مثلاً دوچرخه و خودروی برقی، را نمی‌شنوید.","en":"I drive out when I cannot hear any cars.","een":"No. You cannot hear every vehicle, for example cyclists and electric cars."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Du har ubetinget vigepligt og skal vise det i god tid.","efa":"بله. باید بی‌قیدوشرط راه بدهید و این را به موقع نشان دهید.","en":"I slow down in good time.","een":"Yes. You must give way unconditionally and show it in good time."},{"da":"Hajtænderne gælder kun trafikken fra venstre.","fa":"دندان‌کوسه فقط برای ترافیک سمت چپ است.","ok":0,"eda":"Nej. Du har ubetinget vigepligt for trafikken fra begge sider.","efa":"خیر. باید بی‌قیدوشرط به ترافیک هر دو طرف راه بدهید.","en":"The shark teeth only apply to traffic from the left.","een":"No. You must give way unconditionally to traffic from both sides."}]},{"id":5062,"img":"newq-art/5062.png","c":"7.11","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Der kommer et kryds, hvor trafikken fra sidevejene har ubetinget vigepligt.","fa":"تقاطعی در پیش است که ترافیک فرعی‌ها در آن باید بی‌قیدوشرط راه بدهد.","ok":1,"eda":"Ja. Tavle A 11 varsler et farligt vejkryds, hvor den krydsende trafik har ubetinget vigepligt.","efa":"بله. تابلوی A 11 از تقاطع خطرناکی هشدار می‌دهد که ترافیک متقاطع در آن باید بی‌قیدوشرط راه بدهد.","en":"A junction is coming where traffic from the side roads must give way unconditionally.","een":"Yes. Sign A 11 warns of a dangerous junction where the crossing traffic must give way unconditionally."},{"da":"Tavlen betyder, at jeg skal standse ved krydset.","fa":"این تابلو یعنی باید در تقاطع بایستم.","ok":0,"eda":"Nej. Tavlen er en advarsel; det er den krydsende trafik, der har ubetinget vigepligt, men vær klar til at reagere.","efa":"خیر. این تابلو هشدار است؛ ترافیک متقاطع است که باید بی‌قیدوشرط راه بدهد، ولی آماده‌ی واکنش باشید.","en":"The sign means that I must stop at the junction.","een":"No. The sign is a warning; it is the crossing traffic that must give way unconditionally, but be ready to react."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":0,"eda":"Nej. Det er trafikken fra sidevejene, der skal holde tilbage for dig.","efa":"خیر. ترافیک فرعی‌هاست که باید به شما راه بدهد.","en":"I must give way to traffic from the right.","een":"No. It is the traffic from the side roads that must give way to you."},{"da":"Tavlen betyder, at krydset er reguleret med lyssignal.","fa":"این تابلو یعنی تقاطع چراغ راهنمایی دارد.","ok":0,"eda":"Nej. Lyssignaler varsles med en anden tavle.","efa":"خیر. برای چراغ راهنمایی تابلوی هشدار دیگری هست.","en":"The sign means the junction is controlled by traffic lights.","een":"No. Traffic lights are warned of with a different sign."}]},{"id":5063,"img":"newq-art/5063.png","c":"7.11","sda":"Du kører forbi denne tavle. Lidt fremme kommer en sidevej fra højre uden tavler. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید. کمی جلوتر فرعی‌ای بدون تابلو از سمت راست می‌آید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign. A little further on there is a side road from the right with no signs. What applies?","st":[{"da":"Tavlen betyder, at vejen bliver ensrettet.","fa":"این تابلو یعنی جاده یک‌طرفه می‌شود.","ok":0,"eda":"Nej. Ensretning har sin egen tavle.","efa":"خیر. یک‌طرفه بودن تابلوی خودش را دارد.","en":"The sign means the road becomes one-way.","een":"No. One-way traffic has its own sign."},{"da":"Ved sidevejen gælder højrereglen, fordi der ikke er andre tavler.","fa":"کنار آن فرعی قاعده‌ی دست راست برقرار است، چون تابلوی دیگری نیست.","ok":1,"eda":"Ja. Uden tavler og afmærkning skal du holde tilbage for trafik fra højre.","efa":"بله. بدون تابلو و خط‌کشی باید به ترافیک سمت راست راه بدهید.","en":"At the side road the right-hand rule applies because there are no other signs.","een":"Yes. Without signs or markings you must give way to traffic from the right."},{"da":"Jeg har stadig forkørselsret i alle kryds.","fa":"هنوز در همه‌ی تقاطع‌ها حق تقدم دارم.","ok":0,"eda":"Nej. Forkørselsretten på hovedvejen ophører med tavlen.","efa":"خیر. حق تقدم جاده‌ی اصلی با این تابلو تمام می‌شود.","en":"I still have the right of way at every junction.","een":"No. The right of way of the main road ends with the sign."},{"da":"Hovedvejen ophører.","fa":"جاده‌ی اصلی تمام می‌شود.","ok":1,"eda":"Ja. Tavle B 17 viser, at hovedvejen ophører.","efa":"بله. تابلوی B 17 نشان می‌دهد جاده‌ی اصلی تمام شده است.","en":"The main road ends.","een":"Yes. Sign B 17 shows that the main road ends."}]},{"id":5064,"img":"newq-art/5064.png","c":"7.11","sda":"En cyklist kommer fra højre ad en sti gennem parken og skal over vejen. Hvad gælder?","sfa":"دوچرخه‌سواری از سمت راست، از مسیری در پارک، می‌آید و می‌خواهد از جاده رد شود. چه قاعده‌ای برقرار است؟","sen":"A cyclist is coming from the right along a path through the park and is going to cross the road. What applies?","st":[{"da":"Højrereglen gælder, så jeg skal holde tilbage for cyklisten.","fa":"قاعده‌ی دست راست برقرار است، پس باید به دوچرخه‌سوار راه بدهم.","ok":0,"eda":"Nej. Højrereglen gælder ikke for den, der kommer fra en sådan sti.","efa":"خیر. قاعده‌ی دست راست برای کسی که از چنین مسیری می‌آید اعمال نمی‌شود.","en":"The right-hand rule applies, so I must give way to the cyclist.","een":"No. The right-hand rule does not apply to someone coming from such a path."},{"da":"Cyklisten har ubetinget vigepligt, fordi stien ikke hører til en vej.","fa":"دوچرخه‌سوار باید بی‌قیدوشرط راه بدهد، چون این مسیر جزو جاده نیست.","ok":1,"eda":"Ja. Cyklister fra en sti, der ikke er anlagt i forbindelse med en vej, har ubetinget vigepligt.","efa":"بله. دوچرخه‌سوارانی که از مسیری جدا از جاده می‌آیند، باید بی‌قیدوشرط راه بدهند.","en":"The cyclist must give way unconditionally because the path is not part of a road.","een":"Yes. Cyclists coming from a path not built as part of a road must give way unconditionally."},{"da":"Jeg er alligevel klar til at bremse, hvis cyklisten ikke holder tilbage.","fa":"با این حال آماده‌ی ترمزم، اگر دوچرخه‌سوار راه ندهد.","ok":1,"eda":"Ja. Du skal altid være opmærksom på, om andre overholder deres vigepligt.","efa":"بله. همیشه باید ببینید دیگران وظیفه‌ی راه دادن را رعایت می‌کنند یا نه.","en":"I am still ready to brake if the cyclist does not give way.","een":"Yes. You must always watch whether others keep their duty to give way."}]},{"id":5065,"img":"newq-art/5065.png","c":"7.4","sda":"Du vil skifte til venstre vognbane. Hvordan forholder du dig?","sfa":"می‌خواهید به خط چپ بروید. چه می‌کنید؟","sen":"You want to change to the left-hand lane. What do you do?","st":[{"da":"Jeg giver tegn med blinklyset i god tid, før jeg skifter vognbane.","fa":"پیش از تغییر خط، به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. Andre skal kunne nå at se, hvad du vil gøre.","efa":"بله. دیگران باید فرصت داشته باشند ببینند چه می‌خواهید بکنید.","en":"I signal with the indicator in good time before I change lanes.","een":"Yes. Others must have time to see what you are going to do."},{"da":"Jeg skifter først, når det kan ske uden fare eller unødig ulempe for bilen i venstre vognbane.","fa":"فقط وقتی تغییر خط می‌دهم که برای خودروی خط چپ خطر یا مزاحمت بی‌جا نداشته باشد.","ok":1,"eda":"Ja. Færdselsloven § 18 kræver, at vognbaneskift kan ske uden fare eller unødig ulempe for andre.","efa":"بله. ماده‌ی ۱۸ قانون می‌خواهد تغییر خط بدون خطر یا مزاحمت بی‌جا برای دیگران باشد.","en":"I only change when it can be done without danger or undue inconvenience to the car in the left lane.","een":"Yes. Færdselsloven § 18 requires a lane change to be possible without danger or undue inconvenience to others."},{"da":"Jeg ser i spejlet og over skulderen, før jeg skifter vognbane.","fa":"پیش از تغییر خط، در آینه و از روی شانه نگاه می‌کنم.","ok":1,"eda":"Ja. Et skulderkig viser det, der er i den blinde vinkel.","efa":"بله. نگاه از روی شانه آن‌چه را در نقطه‌ی کور است نشان می‌دهد.","en":"I look in the mirror and over my shoulder before I change lanes.","een":"Yes. A look over the shoulder shows what is in the blind spot."},{"da":"Bilen i venstre vognbane skal sænke farten, når jeg blinker.","fa":"خودروی خط چپ وقتی راهنما می‌زنم، باید سرعتش را کم کند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at skifte vognbane.","efa":"خیر. راهنما به شما حق تغییر خط نمی‌دهد.","en":"The car in the left lane must slow down when I indicate.","een":"No. The indicator does not give you the right to change lanes."}]},{"id":5066,"img":"newq-art/5066.png","c":"7.4","sda":"Den ene vognbane ophører, og der er tæt trafik i begge vognbaner. Hvad gælder?","sfa":"یکی از خط‌ها تمام می‌شود و در هر دو خط ترافیک سنگین است. چه قاعده‌ای برقرار است؟","sen":"One of the lanes ends, and there is dense traffic in both lanes. What applies?","st":[{"da":"Det er en god idé at flette skiftevis, én bil fra hver vognbane.","fa":"خوب است به نوبت، یکی از هر خط، ادغام شویم.","ok":1,"eda":"Ja. Fletning på skift får trafikken til at glide bedst.","efa":"بله. ادغام نوبتی باعث می‌شود ترافیک روان‌تر حرکت کند.","en":"It is a good idea to merge in turn, one car from each lane.","een":"Yes. Merging in turn makes the traffic flow best."},{"da":"Den, der kører i den vognbane, der fortsætter, behøver ikke tage hensyn.","fa":"کسی که در خطی می‌رود که ادامه دارد، لازم نیست ملاحظه کند.","ok":0,"eda":"Nej. Hensynet gælder begge veje.","efa":"خیر. ملاحظه از هر دو طرف لازم است.","en":"Whoever drives in the lane that continues need not show any consideration.","een":"No. Consideration applies both ways."},{"da":"Vi skal vise gensidigt hensyn og tilpasse farten.","fa":"باید به هم ملاحظه نشان دهیم و سرعت را تنظیم کنیم.","ok":1,"eda":"Ja. Når antallet af vognbaner bliver mindre, skal de kørende tilpasse sig under gensidig hensyntagen.","efa":"بله. وقتی تعداد خط‌ها کم می‌شود، رانندگان باید با ملاحظه‌ی متقابل خود را تطبیق دهند.","en":"We must show each other consideration and adjust our speed.","een":"Yes. When the number of lanes decreases, drivers must adapt with mutual consideration."}]},{"id":5067,"img":"newq-art/5067.png","c":"7.16","sda":"Du kører på accelerationsbanen ind mod motorvejen. Hvordan forholder du dig?","sfa":"در خط شتاب‌گیری به سمت بزرگراه می‌رانید. چه می‌کنید؟","sen":"You are on the acceleration lane onto the motorway. What do you do?","st":[{"da":"Jeg tilpasser farten til trafikken på motorvejen.","fa":"سرعتم را با ترافیک بزرگراه هماهنگ می‌کنم.","ok":1,"eda":"Ja. På accelerationsbanen skal du tilpasse farten til trafikken i den vognbane, du skal over i.","efa":"بله. در خط شتاب‌گیری باید سرعت را با ترافیک خطی که واردش می‌شوید هماهنگ کنید.","en":"I adjust my speed to the traffic on the motorway.","een":"Yes. On the acceleration lane you must match your speed to the traffic in the lane you are joining."},{"da":"Trafikken på motorvejen skal altid skifte vognbane for at lukke mig ind.","fa":"ترافیک بزرگراه همیشه باید خط عوض کند تا مرا راه بدهد.","ok":0,"eda":"Nej. De på motorvejen skal om nødvendigt lette din indkørsel, men du skal selv tilpasse farten og finde et sikkert hul.","efa":"خیر. رانندگان بزرگراه در صورت لزوم ورود شما را آسان‌تر می‌کنند، ولی خودتان باید سرعت را هماهنگ کنید و فاصله‌ی امنی پیدا کنید.","en":"The motorway traffic must always change lanes to let me in.","een":"No. Those on the motorway should make it easier for you to join if needed, but you must match your speed and find a safe gap yourself."},{"da":"Jeg standser for enden af banen og venter på et stort hul.","fa":"در انتهای خط می‌ایستم و منتظر فاصله‌ای بزرگ می‌مانم.","ok":0,"eda":"Nej. At standse er farligt; brug banens længde til at tilpasse farten og find et hul.","efa":"خیر. ایستادن خطرناک است؛ از طول خط برای هماهنگ کردن سرعت و پیدا کردن فاصله استفاده کنید.","en":"I stop at the end of the lane and wait for a big gap.","een":"No. Stopping is dangerous; use the lane's length to match your speed and find a gap."},{"da":"Jeg kører ud på motorvejen, når det kan ske uden fare.","fa":"وقتی بی‌خطر باشد وارد بزرگراه می‌شوم.","ok":1,"eda":"Ja. Du skal forlade accelerationsbanen, når det kan ske uden fare.","efa":"بله. وقتی بی‌خطر باشد، باید خط شتاب‌گیری را ترک کنید.","en":"I move onto the motorway when it can be done safely.","een":"Yes. You must leave the acceleration lane when it can be done safely."}]},{"id":5068,"img":"newq-art/5068.png","c":"7.1","sda":"Du holder ved kantstenen og vil køre ud. Bag dig kommer en cyklist. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و می‌خواهید حرکت کنید. از پشت دوچرخه‌سواری می‌آید. چه می‌کنید؟","sen":"You are parked at the kerb and want to drive off. A cyclist is coming up behind you. What do you do?","st":[{"da":"Jeg lader cyklisten passere, før jeg kører ud.","fa":"می‌گذارم دوچرخه‌سوار رد شود و بعد حرکت می‌کنم.","ok":1,"eda":"Ja. Du må kun køre ud fra vejkanten, når det kan ske uden fare eller unødig ulempe for andre.","efa":"بله. فقط وقتی می‌توانید از کنار جاده حرکت کنید که برای دیگران خطر یا مزاحمت بی‌جا نداشته باشد.","en":"I let the cyclist pass before I drive off.","een":"Yes. You may only pull away from the kerb when it can be done without danger or undue inconvenience to others."},{"da":"Når jeg blinker, skal cyklisten holde tilbage.","fa":"وقتی راهنما بزنم، دوچرخه‌سوار باید راه بدهد.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre ud.","efa":"خیر. راهنما به شما حق حرکت نمی‌دهد.","en":"When I indicate, the cyclist must give way.","een":"No. The indicator does not give you the right to pull out."},{"da":"Jeg blinker og kigger over venstre skulder, før jeg kører ud.","fa":"راهنما می‌زنم و پیش از حرکت از روی شانه‌ی چپ نگاه می‌کنم.","ok":1,"eda":"Ja. Du skal give tegn, før du kører ud fra vejkanten, og tjekke den blinde vinkel.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید و نقطه‌ی کور را بررسی کنید.","en":"I indicate and look over my left shoulder before I pull out.","een":"Yes. You must signal before pulling away from the kerb and check the blind spot."},{"da":"Spejlene er nok; jeg behøver ikke dreje hovedet.","fa":"آینه‌ها کافی‌اند؛ لازم نیست سرم را بچرخانم.","ok":0,"eda":"Nej. Spejlene viser ikke den blinde vinkel.","efa":"خیر. آینه‌ها نقطه‌ی کور را نشان نمی‌دهند.","en":"The mirrors are enough; I do not need to turn my head.","een":"No. The mirrors do not show the blind spot."}]},{"id":5069,"img":"newq-art/5069.png","c":"7.1","sda":"Du vil standse ved kantstenen lidt fremme. Hvordan forholder du dig?","sfa":"می‌خواهید کمی جلوتر کنار جدول بایستید. چه می‌کنید؟","sen":"You want to stop at the kerb a little further ahead. What do you do?","st":[{"da":"Jeg holder øje med cyklisten i højre side.","fa":"مراقب دوچرخه‌سوار سمت راست هستم.","ok":1,"eda":"Ja. Du må ikke klemme cyklisten mellem bilen og kantstenen.","efa":"بله. نباید دوچرخه‌سوار را بین خودرو و جدول گیر بیندازید.","en":"I keep an eye on the cyclist on the right.","een":"Yes. You must not squeeze the cyclist between the car and the kerb."},{"da":"Jeg ser i spejlet og giver tegn i god tid.","fa":"در آینه نگاه می‌کنم و به موقع علامت می‌دهم.","ok":1,"eda":"Ja. Bilerne bag dig skal kunne forstå, hvad du vil.","efa":"بله. خودروهای پشت سر باید بفهمند چه قصدی دارید.","en":"I look in the mirror and signal in good time.","een":"Yes. The cars behind you must be able to understand what you are doing."},{"da":"Jeg bremser hårdt, så jeg hurtigt kommer ind til kanten.","fa":"محکم ترمز می‌کنم تا زود کنار جدول برسم.","ok":0,"eda":"Nej. Pludselig opbremsning kan skabe fare for dem bag dig.","efa":"خیر. ترمز ناگهانی ممکن است پشت‌سری‌ها را به خطر بیندازد.","en":"I brake hard so that I get to the kerb quickly.","een":"No. Sudden braking can endanger those behind you."}]},{"id":5070,"img":"newq-art/5070.png","c":"7.2","sda":"Der er ingen modkørende. Hvordan placerer du bilen på vejen?","sfa":"ترافیک روبه‌رو نیست. خودرو را در جاده چطور قرار می‌دهید؟","sen":"There is no oncoming traffic. How do you position the car on the road?","st":[{"da":"Manden går forkert, fordi han går i højre side.","fa":"آن مرد اشتباه می‌رود، چون در سمت راست است.","ok":0,"eda":"Nej. Den, der trækker en cykel, skal gå i vejens højre side.","efa":"خیر. کسی که دوچرخه را با دست می‌برد، باید در سمت راست جاده برود.","en":"The man is walking wrongly because he is on the right side.","een":"No. Someone pushing a bicycle must walk on the right side of the road."},{"da":"Jeg holder så langt til højre, som forholdene tillader.","fa":"تا جایی که شرایط اجازه دهد سمت راست می‌مانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt under hensyn til anden færdsel og forholdene.","efa":"بله. رانندگان باید با در نظر گرفتن ترافیک و شرایط، تا جای ممکن سمت راست بمانند.","en":"I keep as far to the right as the conditions allow.","een":"Yes. Drivers must keep as far right as possible, considering other traffic and the conditions."},{"da":"Jeg kører midt på vejen, fordi der ikke er nogen modkørende.","fa":"وسط جاده می‌رانم، چون ترافیک روبه‌رو نیست.","ok":0,"eda":"Nej. Reglen om at holde til højre gælder også på en tom vej.","efa":"خیر. قاعده‌ی سمت راست ماندن در جاده‌ی خالی هم برقرار است.","en":"I drive in the middle of the road because there is no oncoming traffic.","een":"No. The keep-right rule applies on an empty road too."},{"da":"Når jeg passerer manden med cyklen, giver jeg ham god plads.","fa":"وقتی از کنار مرد دوچرخه‌به‌دست رد می‌شوم، جای زیادی به او می‌دهم.","ok":1,"eda":"Ja. Gående skal have god plads, når du passerer dem.","efa":"بله. هنگام رد شدن از کنار عابران باید جای کافی به آن‌ها بدهید.","en":"When I pass the man with the bicycle, I give him plenty of room.","een":"Yes. Pedestrians must be given plenty of room when you pass them."}]},{"id":5071,"img":"newq-art/5071.png","c":"7.2","sda":"Vejen har tre vognbaner og trafik i begge retninger. Hvad gælder?","sfa":"جاده سه خط دارد و از هر دو طرف ترافیک دارد. چه قاعده‌ای برقرار است؟","sen":"The road has three lanes and traffic in both directions. What applies?","st":[{"da":"Jeg må ikke bruge vognbanen længst til venstre.","fa":"نباید از چپ‌ترین خط استفاده کنم.","ok":1,"eda":"Ja. På en vej med tre vognbaner og trafik i begge retninger må den venstre vognbane ikke bruges.","efa":"بله. در جاده‌ی سه‌خطه‌ی دوطرفه، نباید از خط سمت چپ استفاده کرد.","en":"I must not use the lane furthest to the left.","een":"Yes. On a road with three lanes and traffic in both directions the left lane must not be used."},{"da":"Midtervognbanen er kun for min retning.","fa":"خط وسط فقط برای جهت من است.","ok":0,"eda":"Nej. Den deles af begge retninger; vær særligt opmærksom på modkørende i den.","efa":"خیر. هر دو جهت از آن استفاده می‌کنند؛ مراقب ترافیک روبه‌رو در آن باشید.","en":"The middle lane is only for my direction.","een":"No. It is shared by both directions; watch especially for oncoming traffic in it."},{"da":"Den modkørende i midtervognbanen viser, at jeg ikke kan overhale traktoren lige nu.","fa":"خودروی روبه‌رو در خط وسط نشان می‌دهد که الان نمی‌توانم از تراکتور سبقت بگیرم.","ok":1,"eda":"Ja. Midtervognbanen kan bruges til overhaling fra begge retninger.","efa":"بله. خط وسط برای سبقت از هر دو جهت قابل استفاده است.","en":"The oncoming car in the middle lane shows that I cannot overtake the tractor right now.","een":"Yes. The middle lane can be used for overtaking from both directions."}]},{"id":5072,"img":"newq-art/5072.png","c":"7.19","sda":"Du vil parkere i vejkanten på en mørk vej uden for byen om natten. Hvilke lygter skal være tændt, når bilen holder der?","sfa":"می‌خواهید شب کنار جاده‌ای تاریک بیرون از شهر پارک کنید. وقتی خودرو آن‌جا ایستاده، کدام چراغ‌ها باید روشن باشند؟","sen":"You want to park at the edge of a dark road outside town at night. Which lights must be on while the car is parked there?","st":[{"da":"Nærlyset, så modkørende kan se mig tydeligt.","fa":"نور پایین، تا رانندگان روبه‌رو مرا واضح ببینند.","ok":0,"eda":"Nej. Andre lygter end positionslys, baglygter og nummerpladelys må ikke holdes tændt på en holdende bil.","efa":"خیر. در خودروی ایستاده، چراغی جز چراغ موقعیت، چراغ‌های عقب و چراغ پلاک نباید روشن بماند.","en":"The dipped beam, so that oncoming drivers can see me clearly.","een":"No. Lights other than the position lights, rear lights and number-plate light must not be kept on in a standing car."},{"da":"Positionslys (parkeringslys).","fa":"چراغ‌های موقعیت (چراغ پارک).","ok":1,"eda":"Ja. I lygtetændingstiden skal en bil, der holder på vejen, have positionslys, baglygter og nummerpladelys tændt.","efa":"بله. در زمان روشن کردن چراغ‌ها، خودرویی که در جاده ایستاده باید چراغ موقعیت، چراغ‌های عقب و چراغ پلاک را روشن داشته باشد.","en":"Position lights (parking lights).","een":"Yes. During lighting-up time a car standing on the road must have its position lights, rear lights and number-plate light on."},{"da":"Nummerpladelygten.","fa":"چراغ پلاک.","ok":1,"eda":"Ja. Nummerpladelygten hører med til de lygter, der skal være tændt.","efa":"بله. چراغ پلاک جزو چراغ‌هایی است که باید روشن باشند.","en":"The number-plate light.","een":"Yes. The number-plate light is one of the lights that must be on."},{"da":"Baglygterne.","fa":"چراغ‌های عقب.","ok":1,"eda":"Ja. Baglygterne viser dem, der kommer bagfra, at bilen holder der.","efa":"بله. چراغ‌های عقب به کسانی که از پشت می‌آیند نشان می‌دهند خودرو آن‌جاست.","en":"The rear lights.","een":"Yes. The rear lights show those coming from behind that the car is there."}]},{"id":5073,"img":"newq-art/5073.png","c":"7.19","sda":"Du kører på en godt oplyst gade i byen om aftenen. Hvilket lys bruger du?","sfa":"عصر در خیابانی پرنور در شهر می‌رانید. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving on a well-lit street in town in the evening. Which lights do you use?","st":[{"da":"Tågeforlygter, fordi det er mørkt.","fa":"چراغ‌های مه‌شکن جلو، چون تاریک است.","ok":0,"eda":"Nej. I mørke må tågelygter kun bruges i tåge eller under kraftig nedbør.","efa":"خیر. در تاریکی، چراغ مه‌شکن فقط در مه یا بارش شدید مجاز است.","en":"Front fog lights, because it is dark.","een":"No. In the dark, fog lights may only be used in fog or heavy precipitation."},{"da":"Kun positionslys.","fa":"فقط چراغ‌های موقعیت.","ok":0,"eda":"Nej. Under kørsel er positionslys ikke nok; du skal have nærlys.","efa":"خیر. هنگام رانندگی چراغ موقعیت کافی نیست؛ باید نور پایین روشن باشد.","en":"Only the position lights.","een":"No. Position lights are not enough while driving; you must have dipped beam."},{"da":"Fjernlys.","fa":"نور بالا.","ok":0,"eda":"Nej. Fjernlys er forbudt på en godt oplyst vej.","efa":"خیر. نور بالا در جاده‌ی پرنور ممنوع است.","en":"High beam.","een":"No. High beam is forbidden on a well-lit road."},{"da":"Nærlys.","fa":"نور پایین.","ok":1,"eda":"Ja. Fjernlys må ikke bruges på en tilstrækkeligt oplyst vej; så skal du bruge nærlys.","efa":"بله. در جاده‌ی به اندازه‌ی کافی روشن، نور بالا مجاز نیست و باید از نور پایین استفاده کنید.","en":"Dipped beam.","een":"Yes. High beam must not be used on a sufficiently lit road; then you must use dipped beam."}]},{"id":5074,"img":"newq-art/5074.png","c":"7.19","sda":"Du kører i mørke bag en anden bil. Hvilket lys bruger du?","sfa":"در تاریکی پشت خودروی دیگری می‌رانید. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving behind another car in the dark. Which lights do you use?","st":[{"da":"Nærlys, fordi fjernlyset kan blænde føreren foran.","fa":"نور پایین، چون نور بالا می‌تواند راننده‌ی جلویی را خیره کند.","ok":1,"eda":"Ja. Fjernlys må ikke bruges, når du kører efter en, der kan blive blændet.","efa":"بله. وقتی پشت کسی می‌رانید که ممکن است خیره شود، نباید از نور بالا استفاده کنید.","en":"Dipped beam, because the high beam can dazzle the driver ahead.","een":"Yes. High beam must not be used when you are following someone who could be dazzled."},{"da":"Fjernlyset kan blænde gennem bilens spejle.","fa":"نور بالا می‌تواند از طریق آینه‌های خودرو خیره کند.","ok":1,"eda":"Ja. Spejlene kaster dit lys ind i øjnene på føreren foran.","efa":"بله. آینه‌ها نور شما را به چشم راننده‌ی جلویی می‌اندازند.","en":"The high beam can dazzle through the car's mirrors.","een":"Yes. The mirrors throw your light into the eyes of the driver ahead."},{"da":"Fjernlys, så jeg kan se længere frem.","fa":"نور بالا، تا جلوتر را ببینم.","ok":0,"eda":"Nej. Fjernlyset blænder føreren foran gennem spejlene.","efa":"خیر. نور بالا از طریق آینه‌ها راننده‌ی جلویی را خیره می‌کند.","en":"High beam, so that I can see further ahead.","een":"No. The high beam dazzles the driver ahead through the mirrors."}]},{"id":5075,"img":"newq-art/5075.png","c":"7.16","sda":"Hvem må køre på motorvejen?","sfa":"چه کسانی می‌توانند در بزرگراه رانندگی کنند؟","sen":"Who may drive on the motorway?","st":[{"da":"Motorkøretøjer, der kan og må køre mindst 50 km/t.","fa":"وسایل موتوری‌ای که بتوانند و اجازه داشته باشند دست‌کم ۵۰ کیلومتر بر ساعت بروند.","ok":1,"eda":"Ja. Motorvejen er forbeholdt motorkøretøjer, der på vandret vej kan og må køre mindst 50 km/t.","efa":"بله. بزرگراه مخصوص وسایل موتوری‌ای است که در جاده‌ی هموار بتوانند و اجازه داشته باشند دست‌کم ۵۰ کیلومتر بر ساعت بروند.","en":"Motor vehicles that can and may drive at least 50 km/h.","een":"Yes. The motorway is reserved for motor vehicles that can and may do at least 50 km/h on level road."},{"da":"Alle motorkøretøjer, uanset hvor hurtigt de kan køre.","fa":"همه‌ی وسایل موتوری، هر قدر هم سرعتشان باشد.","ok":0,"eda":"Nej. Et motorkøretøj, der ikke kan eller ikke må køre mindst 50 km/t, må ikke bruge motorvejen.","efa":"خیر. وسیله‌ی موتوری‌ای که نتواند یا اجازه نداشته باشد دست‌کم ۵۰ کیلومتر بر ساعت برود، نباید از بزرگراه استفاده کند.","en":"All motor vehicles, however fast they can go.","een":"No. A motor vehicle that cannot or may not do at least 50 km/h must not use the motorway."},{"da":"En lille knallert, der højst kører 30 km/t.","fa":"موپد کوچکی که حداکثر ۳۰ کیلومتر بر ساعت می‌رود.","ok":0,"eda":"Nej. Den kan ikke køre 50 km/t og må derfor ikke køre på motorvejen.","efa":"خیر. نمی‌تواند ۵۰ کیلومتر بر ساعت برود، پس اجازه‌ی رانندگی در بزرگراه ندارد.","en":"A small moped that does at most 30 km/h.","een":"No. It cannot do 50 km/h and therefore may not drive on the motorway."},{"da":"Cyklister, hvis de holder i nødsporet.","fa":"دوچرخه‌سواران، اگر در شانه‌ی اضطراری بمانند.","ok":0,"eda":"Nej. Cyklister må ikke færdes på motorvejen.","efa":"خیر. دوچرخه‌سواران اجازه‌ی رفت‌وآمد در بزرگراه را ندارند.","en":"Cyclists, if they keep to the hard shoulder.","een":"No. Cyclists must not use the motorway."}]},{"id":5076,"img":"newq-art/5076.png","c":"7.16","sda":"Du har lige kørt forbi den frakørsel, du skulle have taget. Hvad gør du?","sfa":"همین الان از خروجی‌ای که باید می‌گرفتید رد شده‌اید. چه می‌کنید؟","sen":"You have just driven past the exit you should have taken. What do you do?","st":[{"da":"Jeg standser i nødsporet og ser på kortet, hvor jeg skal køre.","fa":"در شانه‌ی اضطراری می‌ایستم و روی نقشه نگاه می‌کنم کجا بروم.","ok":0,"eda":"Nej. På motorvejen må du kun standse på de anviste parkerings- og rastepladser eller ved en nødtelefon for at bruge den.","efa":"خیر. در بزرگراه فقط در پارکینگ‌ها و استراحتگاه‌های تعیین‌شده، یا کنار تلفن اضطراری برای استفاده از آن، می‌توانید بایستید.","en":"I stop on the hard shoulder and look at the map to see where to go.","een":"No. On the motorway you may only stop at the designated parking and rest areas, or at an emergency phone in order to use it."},{"da":"Jeg kører videre til den næste frakørsel.","fa":"تا خروجی بعدی ادامه می‌دهم.","ok":1,"eda":"Ja. Du må hverken bakke eller vende på motorvejen; brug den næste frakørsel.","efa":"بله. در بزرگراه نه می‌توانید دنده‌عقب بروید و نه دور بزنید؛ از خروجی بعدی استفاده کنید.","en":"I drive on to the next exit.","een":"Yes. You may neither reverse nor turn round on the motorway; use the next exit."},{"da":"Jeg bakker tilbage i nødsporet til frakørslen.","fa":"در شانه‌ی اضطراری دنده‌عقب تا خروجی برمی‌گردم.","ok":0,"eda":"Nej. Det er forbudt at bakke på motorvejen og på dens til- og frakørselsveje.","efa":"خیر. دنده‌عقب رفتن در بزرگراه و راه‌های ورودی و خروجی آن ممنوع است.","en":"I reverse back along the hard shoulder to the exit.","een":"No. Reversing is forbidden on the motorway and on its slip roads."},{"da":"Jeg vender gennem en åbning i midterrabatten.","fa":"از شکافی در جداکننده‌ی وسط دور می‌زنم.","ok":0,"eda":"Nej. Kørsel over midterrabatten eller gennem åbninger i den er ikke tilladt.","efa":"خیر. رد شدن از روی جداکننده‌ی وسط یا از شکاف‌های آن مجاز نیست.","en":"I turn round through a gap in the central reservation.","een":"No. Driving over the central reservation or through gaps in it is not allowed."}]},{"id":5077,"img":"newq-art/5077.png","c":"7.16","sda":"Du kører bil med trailer på en motorvej med tre vognbaner i din retning. Vogntoget er over 7 m langt. Hvad gælder?","sfa":"با خودرو و تریلر در بزرگراهی با سه خط در جهت خودتان رانندگی می‌کنید. طول مجموعه بیش از ۷ متر است. چه قاعده‌ای برقرار است؟","sen":"You are driving a car with a trailer on a motorway with three lanes in your direction. The combination is more than 7 m long. What applies?","st":[{"da":"Med trailer må jeg køre 130 km/t, når vejen er fri.","fa":"با تریلر وقتی جاده خالی است، می‌توانم ۱۳۰ کیلومتر بر ساعت بروم.","ok":0,"eda":"Nej. Bil med trailer må højst køre 80 km/t, på motorvej dog 100 km/t, hvis vogntoget opfylder betingelserne for det.","efa":"خیر. خودرو با تریلر حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود؛ در بزرگراه اگر مجموعه شرایطش را داشته باشد، ۱۰۰.","en":"With a trailer I may drive at 130 km/h when the road is clear.","een":"No. A car with a trailer may drive at most 80 km/h, though 100 km/h on the motorway if the combination meets the conditions for it."},{"da":"Jeg må kun bruge en af de to vognbaner længst til højre.","fa":"فقط می‌توانم از یکی از دو خط سمت راست استفاده کنم.","ok":1,"eda":"Ja. Vogntog, der er over 7 m lange, må på en motorvej med tre eller flere vognbaner i samme retning kun bruge de to vognbaner længst til højre.","efa":"بله. در بزرگراهی با سه خط یا بیشتر در یک جهت، مجموعه‌های بلندتر از ۷ متر فقط می‌توانند از دو خط سمت راست استفاده کنند.","en":"I may only use one of the two lanes furthest to the right.","een":"Yes. Combinations longer than 7 m may only use the two right-hand lanes on a motorway with three or more lanes in the same direction."},{"da":"Reglen om vognbanerne gælder kun for lastbiler.","fa":"قاعده‌ی خط‌ها فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Den gælder både biler med en tilladt totalvægt over 3,5 t og vogntog, der er over 7 m lange.","efa":"خیر. هم برای خودروهای با وزن کل مجاز بالای ۳٫۵ تن و هم برای مجموعه‌های بلندتر از ۷ متر است.","en":"The lane rule only applies to lorries.","een":"No. It applies both to vehicles with a permitted total weight over 3.5 t and to combinations longer than 7 m."},{"da":"Jeg må bruge vognbanen længst til venstre, når jeg overhaler varevognen.","fa":"وقتی از ون سبقت می‌گیرم، می‌توانم از چپ‌ترین خط استفاده کنم.","ok":0,"eda":"Nej. Forbuddet gælder også, når du vil overhale; her må du blive bag varevognen.","efa":"خیر. این ممنوعیت هنگام سبقت هم برقرار است؛ این‌جا باید پشت ون بمانید.","en":"I may use the left-hand lane when I overtake the van.","een":"No. The ban applies when you want to overtake too; here you must stay behind the van."}]},{"id":5078,"img":"newq-art/5078.png","c":"6.2","sda":"Din bil er gået i stå lige efter et skarpt sving, og du kan ikke flytte den med det samme. Hvad gør du?","sfa":"خودروی شما درست بعد از یک پیچ تند خراب شده و نمی‌توانید فوراً جابه‌جایش کنید. چه می‌کنید؟","sen":"Your car has broken down just after a sharp bend, and you cannot move it straight away. What do you do?","st":[{"da":"Jeg tænder havariblinket.","fa":"چراغ خطر را روشن می‌کنم.","ok":1,"eda":"Ja. Havariblinket advarer de andre trafikanter om, at bilen holder der.","efa":"بله. چراغ خطر به دیگران هشدار می‌دهد که خودرو آن‌جا ایستاده است.","en":"I switch on the hazard lights.","een":"Yes. The hazard lights warn other road users that the car is standing there."},{"da":"Jeg stiller advarselstrekanten op før svinget, så de bagfrakommende bliver advaret i god tid.","fa":"مثلث خطر را پیش از پیچ می‌گذارم تا کسانی که از پشت می‌آیند به موقع باخبر شوند.","ok":1,"eda":"Ja. Trekanten skal stå sådan, at de, der nærmer sig, bliver advaret i god tid; her skjuler svinget bilen.","efa":"بله. مثلث باید طوری باشد که نزدیک‌شوندگان به موقع باخبر شوند؛ این‌جا پیچ خودرو را پنهان کرده است.","en":"I put up the warning triangle before the bend, so that those coming from behind are warned in good time.","een":"Yes. The triangle must stand so that those approaching are warned in good time; here the bend hides the car."},{"da":"Havariblinket er nok, så advarselstrekanten kan blive i bagagerummet.","fa":"چراغ خطر کافی است، پس مثلث خطر می‌تواند در صندوق بماند.","ok":0,"eda":"Nej. En bil, der holder til fare og ikke kan fjernes straks, skal afmærkes med en advarselstrekant.","efa":"خیر. خودرویی که جای خطرناکی ایستاده و نمی‌شود فوراً جابه‌جایش کرد، باید با مثلث خطر مشخص شود.","en":"The hazard lights are enough, so the warning triangle can stay in the boot.","een":"No. A car that stands where it is a danger and cannot be removed at once must be marked with a warning triangle."},{"da":"Jeg sørger for at få bilen flyttet hurtigst muligt.","fa":"ترتیبی می‌دهم که خودرو هر چه زودتر جابه‌جا شود.","ok":1,"eda":"Ja. Et køretøj, der holder til fare, skal fjernes snarest muligt.","efa":"بله. وسیله‌ای که جای خطرناکی ایستاده، باید هر چه زودتر برداشته شود.","en":"I make sure the car is moved as quickly as possible.","een":"Yes. A vehicle standing where it is a danger must be removed as soon as possible."}]},{"id":5079,"img":"newq-art/5079.png","c":"6.2","sda":"Du har grønt lys, men politibetjenten i krydset giver dig tegn til at standse. Hvad gør du?","sfa":"چراغ شما سبز است، ولی مأمور پلیس در تقاطع به شما علامت ایست می‌دهد. چه می‌کنید؟","sen":"You have a green light, but the police officer in the junction signals you to stop. What do you do?","st":[{"da":"Politiets anvisninger går også forud for færdselstavler og afmærkning.","fa":"دستور پلیس بر تابلوها و خط‌کشی‌ها هم مقدم است.","ok":1,"eda":"Ja. Anvisninger fra politiet skal efterkommes før alle andre anvisninger og før færdselsreglerne.","efa":"بله. دستور پلیس پیش از همه‌ی علائم دیگر و پیش از قوانین عمومی رانندگی باید اجرا شود.","en":"The police's directions also take precedence over road signs and markings.","een":"Yes. Directions from the police must be obeyed before all other directions and before the traffic rules."},{"da":"Jeg kører, fordi jeg har grønt lys.","fa":"حرکت می‌کنم، چون چراغم سبز است.","ok":0,"eda":"Nej. Politiets tegn går forud for lyssignalet.","efa":"خیر. علامت پلیس بر چراغ راهنمایی مقدم است.","en":"I drive on because I have a green light.","een":"No. The police officer's signal takes precedence over the traffic light."},{"da":"Jeg skal kun følge betjenten, hvis lyssignalet er slukket.","fa":"فقط وقتی چراغ‌ها خاموش‌اند باید از مأمور پیروی کنم.","ok":0,"eda":"Nej. Politiets anvisninger gælder, uanset hvad lyssignalet viser.","efa":"خیر. دستور پلیس، هر رنگی که چراغ نشان دهد، معتبر است.","en":"I only have to follow the officer if the traffic lights are switched off.","een":"No. The police's directions apply whatever the traffic light shows."},{"da":"Jeg standser, fordi politiets anvisninger går forud for lyssignalet.","fa":"می‌ایستم، چون دستور پلیس بر چراغ راهنمایی مقدم است.","ok":1,"eda":"Ja. Trafikanter skal følge politiets anvisninger, og de skal efterkommes forud for lyssignaler, tavler og afmærkning.","efa":"بله. کاربران راه باید از دستور پلیس پیروی کنند و این دستور بر چراغ، تابلو و خط‌کشی مقدم است.","en":"I stop, because the police's directions take precedence over the traffic light.","een":"Yes. Road users must follow the police's directions, and these must be obeyed before traffic lights, signs and markings."}]},{"id":5080,"img":"newq-art/5080.png","c":"6.2","sda":"Bag dig kommer en ambulance med blå blink og sirene. Hvad gør du?","sfa":"از پشت سر شما آمبولانسی با چراغ آبی چشمک‌زن و آژیر می‌آید. چه می‌کنید؟","sen":"An ambulance with flashing blue lights and siren is coming up behind you. What do you do?","st":[{"da":"Jeg bremser hårdt og standser midt på vejen.","fa":"محکم ترمز می‌کنم و وسط جاده می‌ایستم.","ok":0,"eda":"Nej. Midt på vejen spærrer du for ambulancen, og en pludselig opbremsning kan give en påkørsel.","efa":"خیر. وسط جاده راه آمبولانس را می‌بندید و ترمز ناگهانی ممکن است باعث تصادف شود.","en":"I brake hard and stop in the middle of the road.","een":"No. In the middle of the road you block the ambulance, and sudden braking can cause a collision."},{"da":"Jeg øger farten, så ambulancen ikke skal vente på mig.","fa":"سرعتم را زیاد می‌کنم تا آمبولانس منتظر من نماند.","ok":0,"eda":"Nej. Du skal give plads, ikke køre om kap med ambulancen.","efa":"خیر. باید جا باز کنید، نه این‌که با آمبولانس مسابقه بدهید.","en":"I speed up so that the ambulance does not have to wait for me.","een":"No. You must make room, not race the ambulance."},{"da":"Jeg kører ind til højre og standser om nødvendigt.","fa":"به سمت راست می‌کشم و در صورت لزوم می‌ایستم.","ok":1,"eda":"Ja. Kørende skal om nødvendigt standse for udrykningskøretøjet.","efa":"بله. رانندگان باید در صورت لزوم برای خودروی امدادی بایستند.","en":"I pull over to the right and stop if necessary.","een":"Yes. Drivers must stop for the emergency vehicle if necessary."},{"da":"Jeg gør i god tid plads, så ambulancen kan komme forbi.","fa":"به موقع جا باز می‌کنم تا آمبولانس رد شود.","ok":1,"eda":"Ja. Andre trafikanter skal i god tid holde vejen åben for et køretøj under udrykning.","efa":"بله. دیگران باید به موقع راه را برای خودروی امدادی در مأموریت باز کنند.","en":"I make room in good time so that the ambulance can get past.","een":"Yes. Other road users must keep the road open in good time for a vehicle on an emergency call."}]},{"id":5081,"img":"newq-art/5081.png","c":"7.15","sda":"Du vil køre ind i rundkørslen og fortsætte ligeud. Hvad gælder?","sfa":"می‌خواهید وارد میدان شوید و مستقیم ادامه دهید. چه قاعده‌ای برقرار است؟","sen":"You want to enter the roundabout and carry straight on. What applies?","st":[{"da":"Jeg har ubetinget vigepligt for bilen, der allerede kører i rundkørslen.","fa":"باید بی‌قیدوشرط به خودرویی که در میدان است راه بدهم.","ok":1,"eda":"Ja. Vigepligtstavlen og hajtænderne betyder, at du har ubetinget vigepligt for dem, der kører i rundkørslen.","efa":"بله. تابلوی رعایت حق تقدم و دندان‌کوسه یعنی باید بی‌قیدوشرط به کسانی که در میدان‌اند راه بدهید.","en":"I must give way unconditionally to the car already driving in the roundabout.","een":"Yes. The give-way sign and the shark teeth mean that you must give way unconditionally to those driving in the roundabout."},{"da":"Jeg skal blinke til venstre, når jeg kører ind i rundkørslen.","fa":"هنگام ورود به میدان باید راهنمای چپ بزنم.","ok":0,"eda":"Nej. Skal du ligeud, behøver du ikke blinke, når du kører ind; du blinker til højre, før du kører ud.","efa":"خیر. اگر مستقیم می‌روید، لازم نیست هنگام ورود راهنما بزنید؛ پیش از خروج راهنمای راست می‌زنید.","en":"I must signal left when I enter the roundabout.","een":"No. If you are going straight on, you need not signal as you enter; you signal right before you leave."},{"da":"Bilen i rundkørslen skal holde tilbage for mig, fordi jeg kommer fra højre.","fa":"خودروی داخل میدان باید به من راه بدهد، چون از سمت راست می‌آیم.","ok":0,"eda":"Nej. Højrereglen gælder ikke her, fordi tavlen og hajtænderne giver dig ubetinget vigepligt.","efa":"خیر. قاعده‌ی دست راست این‌جا اعمال نمی‌شود، چون تابلو و دندان‌کوسه شما را مکلف به راه دادن بی‌قیدوشرط می‌کنند.","en":"The car in the roundabout must give way to me because I am coming from the right.","een":"No. The right-hand rule does not apply here, because the sign and the shark teeth make you give way unconditionally."},{"da":"Jeg har også ubetinget vigepligt for cyklisten i rundkørslen.","fa":"به دوچرخه‌سوار داخل میدان هم باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Vigepligten gælder alle, der kører i rundkørslen, også cyklister.","efa":"بله. وظیفه‌ی راه دادن برای همه‌ی کسانی است که در میدان‌اند، دوچرخه‌سواران هم.","en":"I must also give way unconditionally to the cyclist in the roundabout.","een":"Yes. The duty to give way applies to everyone driving in the roundabout, cyclists too."}]},{"id":5082,"img":"newq-art/5082.png","c":"7.15","sda":"Du skal ud ved den næste vej. En cyklist i yderkanten af rundkørslen skal videre rundt. Hvordan forholder du dig?","sfa":"می‌خواهید از خیابان بعدی خارج شوید. دوچرخه‌سواری در لبه‌ی بیرونی میدان می‌خواهد دور را ادامه دهد. چه می‌کنید؟","sen":"You are leaving at the next road. A cyclist at the outer edge of the roundabout is going further round. What do you do?","st":[{"da":"Jeg giver tegn til højre, før jeg kører ud.","fa":"پیش از خروج راهنمای راست می‌زنم.","ok":1,"eda":"Ja. At køre ud af rundkørslen er et højresving, og du skal give tegn i god tid.","efa":"بله. خروج از میدان گردش به راست است و باید به موقع راهنما بزنید.","en":"I signal right before I leave.","een":"Yes. Leaving the roundabout is a right turn, and you must signal in good time."},{"da":"Jeg holder tilbage for cyklisten, der skal videre rundt.","fa":"به دوچرخه‌سواری که دور را ادامه می‌دهد راه می‌دهم.","ok":1,"eda":"Ja. Når du svinger til højre ud af rundkørslen, må du ikke være til ulempe for cyklister, der kører videre.","efa":"بله. وقتی برای خروج از میدان به راست می‌پیچید، نباید مزاحم دوچرخه‌سوارانی شوید که ادامه می‌دهند.","en":"I give way to the cyclist who is going further round.","een":"Yes. When you turn right out of the roundabout, you must not inconvenience cyclists who carry on."},{"da":"Jeg kigger over højre skulder efter cyklister, før jeg kører ud.","fa":"پیش از خروج از روی شانه‌ی راست دوچرخه‌سواران را نگاه می‌کنم.","ok":1,"eda":"Ja. Cyklister kan være i din blinde vinkel i højre side.","efa":"بله. دوچرخه‌سواران ممکن است در نقطه‌ی کور سمت راست شما باشند.","en":"I look over my right shoulder for cyclists before I leave.","een":"Yes. Cyclists may be in your blind spot on the right."},{"da":"Cyklisten skal holde tilbage for mig, fordi jeg blinker.","fa":"دوچرخه‌سوار باید به من راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke forkørselsret.","efa":"خیر. راهنما به شما حق تقدم نمی‌دهد.","en":"The cyclist must give way to me because I am signalling.","een":"No. The indicator does not give you the right of way."}]},{"id":5083,"img":"newq-art/5083.png","c":"7.8","sda":"Du kører med trailer uden for byen bag en lastbil. Hvilken afstand holder du til lastbilen?","sfa":"بیرون از شهر با تریلر پشت یک کامیون می‌رانید. چه فاصله‌ای با کامیون نگه می‌دارید؟","sen":"You are towing a trailer outside town behind a lorry. What distance do you keep to the lorry?","st":[{"da":"Så stor, at jeg ikke kører ind i lastbilen, hvis den bremser.","fa":"آن‌قدر که اگر کامیون ترمز کرد، به آن نخورم.","ok":1,"eda":"Ja. Afstanden til den forankørende skal være så stor, at der ikke er fare for påkørsel, hvis den standser eller sætter farten ned.","efa":"بله. فاصله با جلویی باید آن‌قدر باشد که اگر بایستد یا سرعتش را کم کند، خطر تصادف نباشد.","en":"Large enough that I will not run into the lorry if it brakes.","een":"Yes. The distance to the vehicle ahead must be such that there is no risk of a collision if it stops or slows down."},{"da":"Jeg lægger mig tæt bag lastbilen, så ingen kan køre ind foran mig.","fa":"نزدیک پشت کامیون می‌مانم تا کسی نتواند جلوی من بیاید.","ok":0,"eda":"Nej. Så kan de, der overhaler, ikke komme ind, og du har ikke plads til at bremse.","efa":"خیر. این‌طور سبقت‌گیرندگان جا ندارند و خودتان هم جای ترمز ندارید.","en":"I keep close behind the lorry so that nobody can pull in in front of me.","een":"No. Then those overtaking cannot pull in, and you have no room to brake."},{"da":"Så stor, at biler, der overhaler mig, uden fare kan komme ind mellem mig og lastbilen.","fa":"آن‌قدر که خودروهایی که از من سبقت می‌گیرند، بی‌خطر بتوانند بین من و کامیون جا بگیرند.","ok":1,"eda":"Ja. Køretøjer med en særlig hastighedsgrænse, fx bil med trailer, skal uden for byen holde så stor afstand til den forankørende, at overhalende kan køre ind imellem.","efa":"بله. وسایلی که محدودیت سرعت ویژه دارند، مثل خودرو با تریلر، بیرون از شهر باید آن‌قدر از جلویی فاصله بگیرند که سبقت‌گیرندگان بتوانند بینشان جا بگیرند.","en":"Large enough that cars overtaking me can pull in safely between me and the lorry.","een":"Yes. Vehicles with a special speed limit, such as a car with a trailer, must outside town keep such a distance to the vehicle ahead that overtakers can pull in between."},{"da":"Med trailer må jeg her højst køre 80 km/t.","fa":"با تریلر این‌جا حداکثر می‌توانم ۸۰ کیلومتر بر ساعت بروم.","ok":1,"eda":"Ja. Bil med trailer må højst køre 80 km/t uden for motorvej.","efa":"بله. خودرو با تریلر بیرون از بزرگراه حداکثر ۸۰ کیلومتر بر ساعت می‌تواند برود.","en":"With a trailer I may drive at most 80 km/h here.","een":"Yes. A car with a trailer may drive at most 80 km/h off the motorway."}]},{"id":5084,"img":"newq-art/5084.png","c":"7.8","sda":"En bil kører meget tæt bag dig. Hvordan forholder du dig?","sfa":"خودرویی خیلی نزدیک پشت سر شما می‌آید. چه می‌کنید؟","sen":"A car is driving very close behind you. What do you do?","st":[{"da":"Jeg kører ud mod midten af vejen, så bilen ikke kan overhale.","fa":"به سمت وسط جاده می‌روم تا خودرو نتواند سبقت بگیرد.","ok":0,"eda":"Nej. Du skal holde til højre og gøre det lettere, ikke sværere, at overhale dig.","efa":"خیر. باید سمت راست بمانید و سبقت گرفتن از خودتان را آسان‌تر کنید، نه سخت‌تر.","en":"I move out towards the middle of the road so that the car cannot overtake.","een":"No. You must keep right and make it easier, not harder, to overtake you."},{"da":"Jeg øger farten, så bilen bag mig får mere plads.","fa":"سرعتم را زیاد می‌کنم تا خودروی پشتی جای بیشتری داشته باشد.","ok":0,"eda":"Nej. Du skal ikke lade dig presse til at køre hurtigere, end det er sikkert og lovligt.","efa":"خیر. نباید بگذارید شما را وادار کنند تندتر از حد ایمن و مجاز برانید.","en":"I speed up so that the car behind me gets more room.","een":"No. You must not let yourself be pushed into driving faster than is safe and legal."},{"da":"Jeg bremser kort for at få bilen bag mig til at holde mere afstand.","fa":"کوتاه ترمز می‌کنم تا خودروی پشتی فاصله بگیرد.","ok":0,"eda":"Nej. Du må ikke bremse brat uden grund; det kan give en påkørsel bagfra.","efa":"خیر. نباید بی‌دلیل ناگهانی ترمز کنید؛ ممکن است از پشت به شما بزنند.","en":"I brake briefly to make the car behind keep more distance.","een":"No. You must not brake sharply without reason; it can cause a rear-end collision."},{"da":"Jeg holder ekstra god afstand til bilen foran, så jeg kan bremse roligt, hvis det bliver nødvendigt.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم تا اگر لازم شد، آرام ترمز کنم.","ok":1,"eda":"Ja. Når du kan bremse blødt, får bilen bag dig mere tid til at reagere.","efa":"بله. وقتی بتوانید نرم ترمز کنید، خودروی پشتی وقت بیشتری برای واکنش دارد.","en":"I keep an extra good distance to the car ahead so that I can brake gently if it becomes necessary.","een":"Yes. When you can brake smoothly, the car behind you gets more time to react."}]},{"id":5085,"img":"newq-art/5085.png","c":"7.5","sda":"Du vil bakke ud fra din indkørsel. En høj hæk skjuler fortovet. Hvordan forholder du dig?","sfa":"می‌خواهید با دنده‌عقب از ورودی خانه‌تان بیرون بیایید. پرچین بلندی جلوی دید پیاده‌رو را گرفته است. چه می‌کنید؟","sen":"You want to reverse out of your driveway. A tall hedge hides the pavement. What do you do?","st":[{"da":"Jeg bakker meget langsomt og er klar til at standse.","fa":"خیلی آهسته دنده‌عقب می‌روم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Før du bakker, skal du sikre dig, at det kan ske uden fare eller ulempe for andre; når du ikke kan se, må det kun gå meget langsomt.","efa":"بله. پیش از دنده‌عقب باید مطمئن شوید که برای دیگران خطر یا مزاحمتی ندارد؛ وقتی دید ندارید، فقط باید خیلی آهسته بروید.","en":"I reverse very slowly and am ready to stop.","een":"Yes. Before reversing you must make sure it can be done without danger or inconvenience to others; when you cannot see, you may only go very slowly."},{"da":"Bakkameraet viser alt, så jeg behøver ikke se mig omkring.","fa":"دوربین عقب همه‌چیز را نشان می‌دهد، پس لازم نیست اطرافم را نگاه کنم.","ok":0,"eda":"Nej. Kameraet viser ikke det hele, fx ikke det, der kommer fra siden bag hækken.","efa":"خیر. دوربین همه‌چیز را نشان نمی‌دهد، مثلاً آن‌چه از کنار و پشت پرچین می‌آید.","en":"The reversing camera shows everything, so I do not need to look around.","een":"No. The camera does not show everything, for example not what is coming from the side behind the hedge."},{"da":"Jeg skal holde tilbage for fodgængere på fortovet og for trafikken på vejen.","fa":"باید به عابران پیاده‌رو و به ترافیک خیابان راه بدهم.","ok":1,"eda":"Ja. Når du kører ud fra en ejendom over et fortov, skal du holde tilbage for de gående, og du har ubetinget vigepligt for de kørende.","efa":"بله. وقتی از یک ملک از روی پیاده‌رو بیرون می‌آیید، باید به عابران راه بدهید و بی‌قیدوشرط به رانندگان هم.","en":"I must give way to pedestrians on the pavement and to the traffic on the street.","een":"Yes. When you drive out of a property across a pavement, you must give way to pedestrians, and you must give way unconditionally to traffic."},{"da":"Fodgængerne skal vente, fordi jeg er i gang med at bakke.","fa":"عابران باید صبر کنند، چون من دارم دنده‌عقب می‌روم.","ok":0,"eda":"Nej. Du skal holde tilbage for de gående, når du kører over fortovet.","efa":"خیر. وقتی از روی پیاده‌رو رد می‌شوید، باید به عابران راه بدهید.","en":"The pedestrians must wait because I am already reversing.","een":"No. You must give way to pedestrians when you drive across the pavement."}]},{"id":5086,"img":"newq-art/5086.png","c":"5.2","sda":"Det er frostvejr, og vejen har været tør. Nu nærmer du dig en bro. Hvad skal du være opmærksom på?","sfa":"هوا یخبندان است و جاده تا این‌جا خشک بوده. حالا به یک پل نزدیک می‌شوید. به چه چیزی باید توجه کنید؟","sen":"There is frost, and the road has been dry. Now you are approaching a bridge. What should you be aware of?","st":[{"da":"Glatte veje er kun et problem, når der ligger sne.","fa":"جاده‌ی لغزنده فقط وقتی برف هست مشکل است.","ok":0,"eda":"Nej. Is kan være næsten usynlig på en vej uden sne.","efa":"خیر. یخ روی جاده‌ی بی‌برف تقریباً دیده نمی‌شود.","en":"Slippery roads are only a problem when there is snow.","een":"No. Ice can be almost invisible on a road without snow."},{"da":"Broer bliver først glatte længe efter resten af vejen.","fa":"پل‌ها خیلی دیرتر از بقیه‌ی جاده لغزنده می‌شوند.","ok":0,"eda":"Nej. Det er omvendt: broer bliver ofte glatte først.","efa":"خیر. برعکس است: پل‌ها اغلب زودتر لغزنده می‌شوند.","en":"Bridges only become slippery long after the rest of the road.","een":"No. It is the other way round: bridges often become slippery first."},{"da":"Broen kan være glat, selv om resten af vejen ikke er det.","fa":"پل ممکن است لغزنده باشد، حتی اگر بقیه‌ی جاده نباشد.","ok":1,"eda":"Ja. En bro køles ned både oven- og nedefra og kan derfor fryse til før resten af vejen.","efa":"بله. پل هم از بالا و هم از پایین سرد می‌شود و برای همین زودتر از بقیه‌ی جاده یخ می‌زند.","en":"The bridge may be slippery even if the rest of the road is not.","een":"Yes. A bridge is cooled from both above and below and can therefore freeze before the rest of the road."},{"da":"Jeg kan holde samme fart, fordi vejen har været tør.","fa":"می‌توانم با همان سرعت ادامه دهم، چون جاده خشک بوده.","ok":0,"eda":"Nej. Sænk farten før broen, så du ikke skal bremse eller dreje kraftigt på den.","efa":"خیر. پیش از پل سرعت را کم کنید تا مجبور نشوید روی آن محکم ترمز کنید یا فرمان بدهید.","en":"I can keep the same speed because the road has been dry.","een":"No. Slow down before the bridge so that you do not have to brake or steer hard on it."}]},{"id":5087,"img":"newq-art/5087.png","c":"4.5","sda":"En bold triller ud på vejen mellem to parkerede biler. Hvordan forholder du dig?","sfa":"توپی از میان دو خودروی پارک‌شده به جاده می‌غلتد. چه می‌کنید؟","sen":"A ball rolls out onto the road between two parked cars. What do you do?","st":[{"da":"Jeg bremser og er klar til at standse.","fa":"ترمز می‌کنم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Du skal kunne standse, hvis der pludselig kommer nogen ud på vejen.","efa":"بله. باید بتوانید اگر کسی ناگهان وارد جاده شد، بایستید.","en":"I brake and am ready to stop.","een":"Yes. You must be able to stop if someone suddenly comes out onto the road."},{"da":"Der kan komme et barn løbende efter bolden.","fa":"ممکن است کودکی دنبال توپ بدود.","ok":1,"eda":"Ja. Børn tænker på bolden og ikke på trafikken.","efa":"بله. کودکان به توپ فکر می‌کنند، نه به ترافیک.","en":"A child may come running after the ball.","een":"Yes. Children think about the ball, not about the traffic."},{"da":"Jeg holder øje med, om der er flere børn mellem bilerne.","fa":"مراقبم که بچه‌های دیگری میان خودروها نباشند.","ok":1,"eda":"Ja. Hvor ét barn leger, kan der også være flere.","efa":"بله. جایی که یک کودک بازی می‌کند، ممکن است بچه‌های دیگری هم باشند.","en":"I watch out for more children between the cars.","een":"Yes. Where one child is playing, there may be more."},{"da":"Jeg dytter og kører videre med samme fart.","fa":"بوق می‌زنم و با همان سرعت ادامه می‌دهم.","ok":0,"eda":"Nej. Et barn, der løber efter en bold, reagerer måske ikke på hornet.","efa":"خیر. کودکی که دنبال توپ می‌دود، شاید به بوق واکنشی نشان ندهد.","en":"I sound the horn and drive on at the same speed.","een":"No. A child running after a ball may not react to the horn."}]},{"id":5088,"img":"newq-art/5088.png","c":"4.5","sda":"Cyklisten foran dig rækker venstre arm ud til siden. Hvad betyder det?","sfa":"دوچرخه‌سوار جلوی شما دست چپش را به پهلو دراز کرده است. یعنی چه؟","sen":"The cyclist in front of you holds the left arm out to the side. What does it mean?","st":[{"da":"Cyklisten vil svinge til højre.","fa":"دوچرخه‌سوار می‌خواهد به راست بپیچد.","ok":0,"eda":"Nej. Et højresving vises med højre arm.","efa":"خیر. گردش به راست با دست راست نشان داده می‌شود.","en":"The cyclist is going to turn right.","een":"No. A right turn is shown with the right arm."},{"da":"Cyklisten vil standse.","fa":"دوچرخه‌سوار می‌خواهد بایستد.","ok":0,"eda":"Nej. Den udstrakte venstre arm viser et venstresving, ikke en standsning.","efa":"خیر. دست دراز چپ گردش به چپ را نشان می‌دهد، نه ایستادن.","en":"The cyclist is going to stop.","een":"No. The outstretched left arm shows a left turn, not a stop."},{"da":"Cyklisten vil svinge til venstre.","fa":"دوچرخه‌سوار می‌خواهد به چپ بپیچد.","ok":1,"eda":"Ja. En arm strakt ud til venstre er cyklistens tegn til at svinge til venstre; vent med at overhale.","efa":"بله. دست دراز به چپ علامت گردش به چپ دوچرخه‌سوار است؛ برای سبقت صبر کنید.","en":"The cyclist is going to turn left.","een":"Yes. An arm stretched out to the left is the cyclist's signal for turning left; wait before overtaking."},{"da":"Cyklisten giver mig tegn til at overhale.","fa":"دوچرخه‌سوار به من علامت می‌دهد که سبقت بگیرم.","ok":0,"eda":"Nej. Cyklisten viser, hvad han selv vil gøre; overhal ikke, mens han svinger til venstre.","efa":"خیر. دوچرخه‌سوار نشان می‌دهد خودش چه می‌خواهد بکند؛ وقتی به چپ می‌پیچد، سبقت نگیرید.","en":"The cyclist is signalling me to overtake.","een":"No. The cyclist shows what he himself is going to do; do not overtake while he is turning left."}]},{"id":5089,"img":"newq-art/5089.png","c":"4.4","sda":"Hvad gælder om alkohol og bilkørsel?","sfa":"درباره‌ی الکل و رانندگی چه قاعده‌ای برقرار است؟","sen":"What applies to alcohol and driving?","st":[{"da":"Kaffe og frisk luft får promillen hurtigere ned.","fa":"قهوه و هوای تازه الکل خون را زودتر پایین می‌آورند.","ok":0,"eda":"Nej. Kun tiden får promillen ned; kroppen forbrænder alkohol i sit eget tempo.","efa":"خیر. فقط زمان الکل خون را پایین می‌آورد؛ بدن الکل را با سرعت خودش می‌سوزاند.","en":"Coffee and fresh air bring the level down faster.","een":"No. Only time brings the level down; the body burns alcohol at its own pace."},{"da":"Jeg må ikke køre bil, hvis min promille er over 0,5.","fa":"اگر الکل خونم بیش از ۰٫۵ در هزار باشد، نباید رانندگی کنم.","ok":1,"eda":"Ja. Grænsen er 0,50 promille i blodet eller 0,25 mg pr. liter udåndingsluft.","efa":"بله. حد مجاز ۰٫۵۰ در هزار در خون یا ۰٫۲۵ میلی‌گرم در هر لیتر هوای بازدم است.","en":"I must not drive if my blood alcohol is over 0.5 per mille.","een":"Yes. The limit is 0.50 per mille in the blood or 0.25 mg per litre of exhaled air."},{"da":"Alkohol gør min reaktionstid længere.","fa":"الکل زمان واکنش مرا طولانی‌تر می‌کند.","ok":1,"eda":"Ja. Selv lidt alkohol nedsætter din evne til at opfatte og reagere.","efa":"بله. حتی کمی الکل توانایی شما در دیدن و واکنش را کم می‌کند.","en":"Alcohol makes my reaction time longer.","een":"Yes. Even a little alcohol reduces your ability to notice and react."},{"da":"Jeg kan straffes, selv om min promille er under 0,5, hvis jeg ikke kan køre fuldt betryggende.","fa":"اگر نتوانم کاملاً ایمن رانندگی کنم، حتی با الکل کمتر از ۰٫۵ هم ممکن است مجازات شوم.","ok":1,"eda":"Ja. Det er forbudt at køre, når alkohol gør, at du ikke kan føre bilen på fuldt betryggende måde, uanset promillen.","efa":"بله. اگر الکل باعث شود نتوانید کاملاً ایمن رانندگی کنید، رانندگی ممنوع است، میزانش هر چه باشد.","en":"I can be punished even if my blood alcohol is under 0.5 per mille if I cannot drive in a fully safe manner.","een":"Yes. It is forbidden to drive when alcohol means you cannot drive the car in a fully safe manner, whatever the level."}]},{"id":5090,"img":"newq-art/5090.png","c":"4.4","sda":"Du har høj feber og føler dig sløj, men du skal hente dit barn i børnehaven. Hvad gælder?","sfa":"تب بالایی دارید و حالتان خوب نیست، ولی باید فرزندتان را از مهدکودک بیاورید. چه قاعده‌ای برقرار است؟","sen":"You have a high temperature and feel unwell, but you need to pick up your child from the kindergarten. What applies?","st":[{"da":"Reglen gælder kun sygdomme, som lægen har skrevet ned.","fa":"این قاعده فقط درباره‌ی بیماری‌هایی است که پزشک ثبت کرده.","ok":0,"eda":"Nej. Det afgørende er, hvordan du har det, når du skal køre.","efa":"خیر. مهم این است که وقتی می‌خواهید رانندگی کنید، حالتان چطور است.","en":"The rule only applies to illnesses that the doctor has written down.","een":"No. What matters is how you feel when you are going to drive."},{"da":"Jeg må ikke køre, hvis jeg på grund af sygdom ikke kan køre på fuldt betryggende måde.","fa":"اگر به خاطر بیماری نتوانم کاملاً ایمن رانندگی کنم، نباید برانم.","ok":1,"eda":"Ja. Det er forbudt at køre, når sygdom, svækkelse, overanstrengelse eller mangel på søvn gør, at du ikke kan køre fuldt betryggende.","efa":"بله. اگر بیماری، ضعف، خستگی شدید یا کم‌خوابی نگذارد کاملاً ایمن برانید، رانندگی ممنوع است.","en":"I must not drive if, because of illness, I cannot drive in a fully safe manner.","een":"Yes. It is forbidden to drive when illness, weakness, exhaustion or lack of sleep means you cannot drive in a fully safe manner."},{"da":"Sygdom har kun betydning, hvis jeg også har drukket alkohol.","fa":"بیماری فقط وقتی مهم است که الکل هم خورده باشم.","ok":0,"eda":"Nej. Sygdom alene kan gøre det forbudt at køre.","efa":"خیر. بیماری به‌تنهایی می‌تواند رانندگی را ممنوع کند.","en":"Illness only matters if I have also been drinking alcohol.","een":"No. Illness alone can make it forbidden to drive."},{"da":"Jeg kan godt køre, hvis jeg åbner vinduet og kører langsomt.","fa":"اگر پنجره را باز کنم و آهسته برانم، می‌توانم رانندگی کنم.","ok":0,"eda":"Nej. Det ændrer ikke på, at du ikke er i stand til at køre sikkert.","efa":"خیر. این تغییری در این واقعیت نمی‌دهد که توان رانندگی ایمن ندارید.","en":"I can drive if I open the window and drive slowly.","een":"No. That does not change the fact that you are not fit to drive safely."}]},{"id":5091,"img":"newq-art/5091.png","c":"8.1","sda":"Din medicin har en rød advarselstrekant på pakningen. Hvad gælder?","sfa":"روی بسته‌ی داروی شما مثلث هشدار قرمز هست. چه قاعده‌ای برقرار است؟","sen":"Your medicine has a red warning triangle on the package. What applies?","st":[{"da":"Jeg må aldrig køre bil, mens jeg tager medicinen.","fa":"تا وقتی این دارو را مصرف می‌کنم، هرگز نباید رانندگی کنم.","ok":0,"eda":"Nej. I nogle tilfælde er det tilladt at køre, når medicinen tages som anvist; det afhænger af, hvordan den påvirker dig.","efa":"خیر. در برخی موارد اگر دارو طبق دستور مصرف شود، رانندگی مجاز است؛ بستگی دارد چه اثری روی شما بگذارد.","en":"I may never drive while I am taking the medicine.","een":"No. In some cases driving is allowed when the medicine is taken as directed; it depends on how it affects you."},{"da":"Medicin uden rød advarselstrekant kan aldrig påvirke min kørsel.","fa":"دارویی که مثلث قرمز ندارد، هرگز روی رانندگی‌ام اثر نمی‌گذارد.","ok":0,"eda":"Nej. Trafikfarlig medicin er ofte, men ikke altid, mærket med den røde trekant.","efa":"خیر. داروی خطرناک برای ترافیک اغلب، ولی نه همیشه، با مثلث قرمز مشخص شده است.","en":"Medicine without a red warning triangle can never affect my driving.","een":"No. Medicine that is dangerous in traffic is often, but not always, marked with the red triangle."},{"da":"Medicinen kan påvirke min evne til at køre bil sikkert.","fa":"این دارو ممکن است توانایی‌ام در رانندگی ایمن را تحت تأثیر قرار دهد.","ok":1,"eda":"Ja. Den røde trekant bruges på medicin, der kan være trafikfarlig.","efa":"بله. مثلث قرمز روی داروهایی است که ممکن است در ترافیک خطرناک باشند.","en":"The medicine may affect my ability to drive safely.","een":"Yes. The red triangle is used on medicine that can be dangerous in traffic."},{"da":"Jeg spørger min læge, om jeg kan køre bil, mens jeg tager medicinen.","fa":"از پزشکم می‌پرسم که آیا با مصرف این دارو می‌توانم رانندگی کنم.","ok":1,"eda":"Ja. Lægen kan vurdere, om medicinen gør det usikkert for dig at køre.","efa":"بله. پزشک می‌تواند بسنجد که آیا دارو رانندگی را برایتان ناایمن می‌کند.","en":"I ask my doctor whether I can drive while taking the medicine.","een":"Yes. The doctor can judge whether the medicine makes it unsafe for you to drive."}]},{"id":5092,"img":"newq-art/5092.png","c":"8.1","sda":"Du kører på motorvejen og bliver meget søvnig. Hvad gør du?","sfa":"در بزرگراه رانندگی می‌کنید و خیلی خواب‌آلود می‌شوید. چه می‌کنید؟","sen":"You are driving on the motorway and become very sleepy. What do you do?","st":[{"da":"Jeg kører hurtigere, så jeg hurtigere er fremme.","fa":"تندتر می‌رانم تا زودتر برسم.","ok":0,"eda":"Nej. Højere fart gør det endnu farligere at være træt.","efa":"خیر. سرعت بیشتر، خستگی را خطرناک‌تر می‌کند.","en":"I drive faster so that I arrive sooner.","een":"No. Higher speed makes being tired even more dangerous."},{"da":"Jeg kører ind på rastepladsen og holder pause, gerne med en kort lur.","fa":"وارد استراحتگاه می‌شوم و استراحت می‌کنم، ترجیحاً با یک چرت کوتاه.","ok":1,"eda":"Ja. Kun hvile og søvn hjælper mod træthed.","efa":"بله. فقط استراحت و خواب در برابر خستگی کمک می‌کند.","en":"I pull into the rest area and take a break, preferably with a short nap.","een":"Yes. Only rest and sleep help against tiredness."},{"da":"Jeg drikker en kop kaffe i bilen og kører videre uden pause.","fa":"در خودرو یک فنجان قهوه می‌خورم و بی‌استراحت ادامه می‌دهم.","ok":0,"eda":"Nej. Kaffe kan ikke erstatte hvile; du kan stadig falde i søvn bag rattet.","efa":"خیر. قهوه جای استراحت را نمی‌گیرد؛ هنوز ممکن است پشت فرمان خوابتان ببرد.","en":"I drink a cup of coffee in the car and drive on without a break.","een":"No. Coffee cannot replace rest; you may still fall asleep at the wheel."},{"da":"Jeg skruer op for musikken og åbner vinduet, så går det over.","fa":"صدای موسیقی را بلند می‌کنم و پنجره را باز می‌کنم، خوب می‌شوم.","ok":0,"eda":"Nej. Det hjælper højst et øjeblik; trætheden forsvinder ikke.","efa":"خیر. این حداکثر برای لحظه‌ای کمک می‌کند؛ خستگی از بین نمی‌رود.","en":"I turn the music up and open the window, and then it will pass.","een":"No. That helps for a moment at most; the tiredness does not go away."}]},{"id":5093,"img":"newq-art/5093.png","c":"8.1","sda":"Du holder for rødt lys, og din telefon ringer. Hvad gælder?","sfa":"پشت چراغ قرمز ایستاده‌اید و تلفنتان زنگ می‌زند. چه قاعده‌ای برقرار است؟","sen":"You are waiting at a red light, and your phone rings. What applies?","st":[{"da":"Forbuddet mod håndholdt telefon gælder også, mens jeg holder for rødt lys.","fa":"ممنوعیت تلفن دستی وقتی پشت چراغ قرمزم هم برقرار است.","ok":1,"eda":"Ja. At holde for rødt lys er stadig en del af kørslen.","efa":"بله. ایستادن پشت چراغ قرمز هنوز بخشی از رانندگی است.","en":"The ban on hand-held phones also applies while I am waiting at a red light.","een":"Yes. Waiting at a red light is still part of driving."},{"da":"Jeg kan ringe tilbage, når jeg har parkeret et sikkert sted.","fa":"وقتی جای امنی پارک کردم، می‌توانم تماس بگیرم.","ok":1,"eda":"Ja. Når du holder parkeret, er du ikke længere under kørsel.","efa":"بله. وقتی پارک کرده‌اید، دیگر در حال رانندگی نیستید.","en":"I can call back when I have parked in a safe place.","een":"Yes. When you are parked, you are no longer driving."},{"da":"Jeg må ikke tage telefonen i hånden og tale i den.","fa":"نباید تلفن را با دست بردارم و صحبت کنم.","ok":1,"eda":"Ja. Førere må under kørsel ikke bruge håndholdt telefon eller andre håndholdte kommunikationsapparater.","efa":"بله. رانندگان در حین رانندگی نباید از تلفن یا دیگر وسایل ارتباطی دستی استفاده کنند.","en":"I must not pick up the phone and talk on it holding it in my hand.","een":"Yes. Drivers must not use a hand-held phone or other hand-held communication devices while driving."},{"da":"Jeg må godt skrive en sms, når jeg kører langsomt i kø.","fa":"وقتی در ترافیک آهسته می‌رانم، می‌توانم پیامک بنویسم.","ok":0,"eda":"Nej. Forbuddet gælder al brug af håndholdt telefon under kørsel, også i kø.","efa":"خیر. ممنوعیت شامل هر نوع استفاده از تلفن دستی در حین رانندگی است، در ترافیک هم.","en":"I may write a text message when I am driving slowly in a queue.","een":"No. The ban covers all use of a hand-held phone while driving, in queues too."}]},{"id":5094,"img":"newq-art/5094.png","c":"3.2","sda":"Lastbilen foran dig vil svinge til højre. Hvad skal du være opmærksom på?","sfa":"کامیون جلوی شما می‌خواهد به راست بپیچد. به چه چیزی باید توجه کنید؟","sen":"The lorry in front of you is going to turn right. What should you be aware of?","st":[{"da":"Chaufføren kan have svært ved at se cyklisten ved siden af lastbilen.","fa":"راننده ممکن است دوچرخه‌سوار کنار کامیون را به‌سختی ببیند.","ok":1,"eda":"Ja. Lastbiler har store blinde vinkler, især i højre side.","efa":"بله. کامیون‌ها نقاط کور بزرگی دارند، به‌خصوص در سمت راست.","en":"The driver may find it hard to see the cyclist beside the lorry.","een":"Yes. Lorries have large blind spots, especially on the right-hand side."},{"da":"Lastbilen kan have brug for at trække ud mod venstre for at komme rundt i svinget.","fa":"کامیون ممکن است برای پیچیدن لازم داشته باشد اول کمی به چپ بکشد.","ok":1,"eda":"Ja. Lange køretøjer har brug for meget plads i sving, og baghjulene kører tættere på indersiden af svinget end forhjulene.","efa":"بله. وسایل بلند در پیچ جای زیادی لازم دارند و چرخ‌های عقب نزدیک‌تر از چرخ‌های جلو به داخل پیچ حرکت می‌کنند.","en":"The lorry may need to move out to the left to get round the turn.","een":"Yes. Long vehicles need a lot of room in turns, and the rear wheels run closer to the inside of the turn than the front wheels."},{"da":"Lastbilen kan svinge lige så skarpt som en personbil.","fa":"کامیون می‌تواند به تندی یک سواری بپیچد.","ok":0,"eda":"Nej. En lastbil er lang og har brug for et meget større sving.","efa":"خیر. کامیون بلند است و به پیچ خیلی بازتری نیاز دارد.","en":"The lorry can turn as sharply as a car.","een":"No. A lorry is long and needs a much wider turn."},{"da":"Jeg holder god afstand og kører ikke op i højre side af lastbilen.","fa":"فاصله‌ی خوبی نگه می‌دارم و از سمت راست کامیون جلو نمی‌روم.","ok":1,"eda":"Ja. I højre side af lastbilen kan du blive klemt, når den svinger.","efa":"بله. در سمت راست کامیون ممکن است هنگام پیچیدنش گیر بیفتید.","en":"I keep a good distance and do not drive up on the right-hand side of the lorry.","een":"Yes. On the right-hand side of the lorry you can get squeezed when it turns."}]},{"id":5095,"img":"newq-art/5095.png","c":"3.2","sda":"Du overvejer at overhale et langt vogntog på landevejen. Hvad gælder?","sfa":"در جاده‌ی بیرون شهر به سبقت از یک کامیون با تریلر بلند فکر می‌کنید. چه قاعده‌ای برقرار است؟","sen":"You are considering overtaking a long lorry combination on a country road. What applies?","st":[{"da":"Jeg kan regne med, at chaufføren sætter farten ned, når jeg overhaler.","fa":"می‌توانم مطمئن باشم که راننده هنگام سبقت من سرعتش را کم می‌کند.","ok":0,"eda":"Nej. Du skal selv sikre dig, at overhalingen kan ske uden fare; du kan ikke regne med hjælp fra chaufføren.","efa":"خیر. خودتان باید مطمئن شوید سبقت بی‌خطر است؛ نمی‌توانید روی کمک راننده حساب کنید.","en":"I can count on the driver slowing down when I overtake.","een":"No. You must make sure yourself that the overtaking can be done safely; you cannot count on help from the driver."},{"da":"Jeg lægger mig helt tæt bag vogntoget, så jeg er klar til at overhale.","fa":"کاملاً نزدیک پشت کامیون می‌مانم تا آماده‌ی سبقت باشم.","ok":0,"eda":"Nej. Tæt bag vogntoget kan du ikke se forbi det, og chaufføren kan ikke se dig.","efa":"خیر. نزدیک پشت کامیون نه شما جلو را می‌بینید، نه راننده شما را.","en":"I keep right up close behind the lorry so that I am ready to overtake.","een":"No. Close behind the lorry you cannot see past it, and the driver cannot see you."},{"da":"Luftsuget fra vogntoget kan rykke i min bil, når jeg kører forbi.","fa":"جریان هوای کامیون ممکن است هنگام عبور، خودروی مرا تکان دهد.","ok":1,"eda":"Ja. Hold godt fast i rattet og god afstand til siden.","efa":"بله. فرمان را محکم نگه دارید و از کنار فاصله‌ی خوبی بگیرید.","en":"The air pressure from the lorry may pull at my car as I pass.","een":"Yes. Hold the wheel firmly and keep a good distance to the side."},{"da":"Overhalingen tager længere tid end forbi en personbil, så den modkørende vognbane skal være fri over en længere strækning.","fa":"سبقت از آن بیشتر از سواری طول می‌کشد، پس خط مقابل باید در مسافت طولانی‌تری خالی باشد.","ok":1,"eda":"Ja. Jo længere køretøjet er, jo længere tid er du i den modkørende vognbane.","efa":"بله. هر چه وسیله بلندتر باشد، مدت بیشتری در خط مقابل می‌مانید.","en":"The overtaking takes longer than past a car, so the oncoming lane must be clear over a longer stretch.","een":"Yes. The longer the vehicle, the longer you are in the oncoming lane."}]},{"id":5096,"img":"newq-art/5096.png","c":"5.1","sda":"Vejen har én fælles kørebane i midten og kantbaner i begge sider. En bil kommer imod dig. Hvordan forholder du dig?","sfa":"جاده یک خط مشترک در وسط و خط‌های کناری در دو طرف دارد. خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"The road has one shared driving lane in the middle and edge lanes on both sides. A car is coming towards you. What do you do?","st":[{"da":"Jeg kører midt på vejen og trækker kun ud i kantbanen, når der kommer en modkørende bil.","fa":"وسط جاده می‌رانم و فقط وقتی خودرویی از روبه‌رو می‌آید، به خط کناری می‌روم.","ok":1,"eda":"Ja. På en 2-minus-1-vej kører bilerne i midten; kantbanerne bruges kun til at vige for modkørende.","efa":"بله. در جاده‌ی «۲ منهای ۱» خودروها وسط می‌رانند و از خط‌های کناری فقط برای راه دادن به خودروی روبه‌رو استفاده می‌شود.","en":"I drive in the middle of the road and only move out into the edge lane when an oncoming car comes.","een":"Yes. On a 2-minus-1 road the cars drive in the middle; the edge lanes are only used to make way for oncoming traffic."},{"da":"Jeg kører hele tiden i kantbanen i højre side.","fa":"همیشه در خط کناری سمت راست می‌رانم.","ok":0,"eda":"Nej. Kantbanen er ikke din vognbane; du kører i midten.","efa":"خیر. خط کناری خط شما نیست؛ شما وسط می‌رانید.","en":"I drive in the edge lane on the right all the time.","een":"No. The edge lane is not your lane; you drive in the middle."},{"da":"Er cyklisten i kantbanen, når vi mødes, holder jeg tilbage og standser om nødvendigt.","fa":"اگر هنگام برخورد دوچرخه‌سوار در خط کناری باشد، صبر می‌کنم و در صورت لزوم می‌ایستم.","ok":1,"eda":"Ja. Kantbanen er for cyklister og gående; du må kun trække ud i den, når der er plads.","efa":"بله. خط کناری مال دوچرخه‌سواران و عابران است؛ فقط وقتی جا هست می‌توانید واردش شوید.","en":"If the cyclist is in the edge lane when we meet, I hold back and stop if necessary.","een":"Yes. The edge lane is for cyclists and pedestrians; you may only move out into it when there is room."},{"da":"Jeg sænker farten, fordi vejen er smal, og der kan komme modkørende.","fa":"سرعتم را کم می‌کنم، چون جاده باریک است و ممکن است خودرویی از روبه‌رو بیاید.","ok":1,"eda":"Ja. Vejen giver kun plads til én bil ad gangen i midten.","efa":"بله. جاده هر بار فقط برای یک خودرو در وسط جا دارد.","en":"I slow down because the road is narrow and oncoming traffic may come.","een":"Yes. The road only has room for one car at a time in the middle."}]},{"id":5097,"img":"newq-art/5097.png","c":"10.3","sda":"Hvad må du med et almindeligt kørekort til kategori B?","sfa":"با گواهینامه‌ی معمولی رده‌ی B چه کارهایی مجاز است؟","sen":"What may you do with an ordinary category B driving licence?","st":[{"da":"Køre en minibus med 12 passagerer, hvis den vejer under 3.500 kg.","fa":"رانندگی مینی‌بوس با ۱۲ مسافر، اگر وزنش کمتر از ۳٬۵۰۰ کیلوگرم باشد.","ok":0,"eda":"Nej. Med B må du højst have 8 passagerer, uanset vægten.","efa":"خیر. با B حداکثر ۸ مسافر مجاز است، وزن هر چه باشد.","en":"Drive a minibus with 12 passengers if it weighs under 3,500 kg.","een":"No. With B you may have at most 8 passengers, whatever the weight."},{"da":"Køre bil med en tilladt totalvægt på højst 3.500 kg.","fa":"رانندگی با خودرویی با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم.","ok":1,"eda":"Ja. Kategori B gælder biler med en tilladt totalvægt på højst 3.500 kg.","efa":"بله. رده‌ی B برای خودروهایی با وزن کل مجاز حداکثر ۳٬۵۰۰ کیلوگرم است.","en":"Drive a car with a permitted total weight of at most 3,500 kg.","een":"Yes. Category B covers cars with a permitted total weight of at most 3,500 kg."},{"da":"Have højst 8 passagerer med ud over mig selv.","fa":"حداکثر ۸ مسافر به‌جز خودم سوار کنم.","ok":1,"eda":"Ja. Bilen må højst være indrettet til 8 personer ud over føreren.","efa":"بله. خودرو حداکثر برای ۸ نفر به‌جز راننده ساخته شده باشد.","en":"Carry at most 8 passengers besides myself.","een":"Yes. The car may be built for at most 8 people besides the driver."},{"da":"Trække en hvilken som helst trailer, så længe bilen er under 3.500 kg.","fa":"هر تریلری را بکشم، به شرط آن‌که خودرو کمتر از ۳٬۵۰۰ کیلوگرم باشد.","ok":0,"eda":"Nej. Med B må traileren højst have en tilladt totalvægt på 750 kg, ellers må bil og trailer tilsammen højst veje 3.500 kg.","efa":"خیر. با B وزن کل مجاز تریلر حداکثر ۷۵۰ کیلوگرم است؛ وگرنه مجموع خودرو و تریلر حداکثر ۳٬۵۰۰ کیلوگرم.","en":"Tow any trailer at all as long as the car is under 3,500 kg.","een":"No. With B the trailer's permitted total weight may be at most 750 kg; otherwise the car and trailer together may weigh at most 3,500 kg."}]},{"id":5098,"img":"newq-art/5098.png","c":"7.10","sda":"Du kører forbi denne tavle ind i et område. Hvad gælder?","sfa":"از کنار این تابلو وارد یک محدوده می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign into an area. What applies?","st":[{"da":"Jeg må kun parkere på de særligt afmærkede pladser.","fa":"فقط در جاهای مخصوص علامت‌گذاری‌شده می‌توانم پارک کنم.","ok":1,"eda":"Ja. Parkering må ikke ske uden for særligt afmærkede pladser.","efa":"بله. پارک بیرون از جاهای مخصوص علامت‌گذاری‌شده مجاز نیست.","en":"I may only park in the specially marked places.","een":"Yes. Parking must not take place outside specially marked places."},{"da":"Børn må lege på hele vejens bredde.","fa":"بچه‌ها می‌توانند در تمام عرض خیابان بازی کنند.","ok":1,"eda":"Ja. Det er tilladt at opholde sig og lege på vejen i hele dens bredde, og de kørende skal holde tilbage for de gående.","efa":"بله. ماندن و بازی در تمام عرض خیابان مجاز است و رانندگان باید به عابران راه بدهند.","en":"Children may play across the whole width of the street.","een":"Yes. It is allowed to stay and play on the road across its whole width, and drivers must give way to pedestrians."},{"da":"Når jeg kører ud af området, har jeg ubetinget vigepligt.","fa":"وقتی از این محدوده بیرون می‌روم، باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Kørende har ubetinget vigepligt ved udkørsel fra et opholds- og legeområde.","efa":"بله. رانندگان هنگام خروج از محدوده‌ی اقامت و بازی باید بی‌قیدوشرط راه بدهند.","en":"When I drive out of the area, I must give way unconditionally.","een":"Yes. Drivers must give way unconditionally when leaving a play-and-living area."},{"da":"Jeg må kun køre med meget lav hastighed, normalt under 15 km/t.","fa":"فقط با سرعت خیلی کم، معمولاً کمتر از ۱۵ کیلومتر بر ساعت، می‌توانم برانم.","ok":1,"eda":"Ja. I et opholds- og legeområde må der kun køres med meget lav hastighed (normalt under 15 km/t).","efa":"بله. در محدوده‌ی اقامت و بازی فقط با سرعت خیلی کم (معمولاً زیر ۱۵ کیلومتر بر ساعت) می‌توان راند.","en":"I may only drive at a very low speed, normally under 15 km/h.","een":"Yes. In a play-and-living area you may only drive at a very low speed (normally under 15 km/h)."}]},{"id":5099,"img":"newq-art/5099.png","c":"7.20","sda":"Du skal køre gennem en lang tunnel. Hvad gælder?","sfa":"قرار است از یک تونل طولانی عبور کنید. چه قاعده‌ای برقرار است؟","sen":"You are going to drive through a long tunnel. What applies?","st":[{"da":"Jeg må ikke standse eller parkere i tunnelen, medmindre jeg er tvunget til det.","fa":"در تونل نباید توقف یا پارک کنم، مگر ناچار باشم.","ok":1,"eda":"Ja. Det er forbudt at standse og parkere i en tunnel.","efa":"بله. توقف و پارک در تونل ممنوع است.","en":"I must not stop or park in the tunnel unless I am forced to.","een":"Yes. Stopping and parking in a tunnel are forbidden."},{"da":"Jeg tænder nærlyset, inden jeg kører ind i tunnelen.","fa":"پیش از ورود به تونل نور پایین را روشن می‌کنم.","ok":1,"eda":"Ja. I tunnelen skal du kunne se og blive set; nærlyset tænder også baglygterne.","efa":"بله. در تونل باید ببینید و دیده شوید؛ نور پایین چراغ‌های عقب را هم روشن می‌کند.","en":"I switch on the dipped beam before I drive into the tunnel.","een":"Yes. In the tunnel you must be able to see and be seen; the dipped beam also switches on the rear lights."},{"da":"Jeg tager solbrillerne på, fordi lyset i tunnelen blænder.","fa":"عینک آفتابی می‌زنم، چون نور تونل چشم را می‌زند.","ok":0,"eda":"Nej. Solbriller gør det sværere at se i tunnelen; tag dem af, før du kører ind.","efa":"خیر. عینک آفتابی دیدن در تونل را سخت‌تر می‌کند؛ پیش از ورود آن را بردارید.","en":"I put on my sunglasses because the light in the tunnel dazzles.","een":"No. Sunglasses make it harder to see in the tunnel; take them off before you go in."},{"da":"Går bilen i stå, holder jeg ind til siden, tænder havariblinket og bruger en nødtelefon.","fa":"اگر خودرو خراب شد، کنار می‌کشم، چراغ خطر را روشن می‌کنم و از تلفن اضطراری استفاده می‌کنم.","ok":1,"eda":"Ja. Så advarer du de andre, og nødtelefonen viser straks, hvor du er.","efa":"بله. این‌طور به دیگران هشدار می‌دهید و تلفن اضطراری فوراً محل شما را نشان می‌دهد.","en":"If the car breaks down, I pull in to the side, switch on the hazard lights and use an emergency phone.","een":"Yes. That way you warn the others, and the emergency phone shows at once where you are."}]},{"id":5100,"img":"newq-art/5100.png","c":"7.17","sda":"Du har længe kørt ved siden af en lastbil i vognbanen til højre for dig. Hvordan forholder du dig?","sfa":"مدتی است کنار کامیونی در خط سمت راستتان می‌رانید. چه می‌کنید؟","sen":"You have been driving for a long time beside a lorry in the lane to your right. What do you do?","st":[{"da":"Jeg undgår at blive liggende i lastbilens blinde vinkel.","fa":"از ماندن در نقطه‌ی کور کامیون پرهیز می‌کنم.","ok":1,"eda":"Ja. Chaufføren kan ikke se dig, og lastbilen kan skifte vognbane ind over dig.","efa":"بله. راننده شما را نمی‌بیند و ممکن است کامیون به سمت شما تغییر خط دهد.","en":"I avoid staying in the lorry's blind spot.","een":"Yes. The driver cannot see you, and the lorry may change lanes into you."},{"da":"Chaufføren kan altid se mig i sine spejle.","fa":"راننده همیشه مرا در آینه‌هایش می‌بیند.","ok":0,"eda":"Nej. Lastbiler har store blinde vinkler, som spejlene ikke dækker.","efa":"خیر. کامیون‌ها نقاط کور بزرگی دارند که آینه‌ها پوشش نمی‌دهند.","en":"The driver can always see me in his mirrors.","een":"No. Lorries have large blind spots that the mirrors do not cover."},{"da":"Jeg bliver ved siden af lastbilen, så chaufføren ved, hvor jeg er.","fa":"کنار کامیون می‌مانم تا راننده بداند کجا هستم.","ok":0,"eda":"Nej. Ved siden af lastbilen er netop der, hvor chaufføren kan have svært ved at se dig.","efa":"خیر. درست کنار کامیون جایی است که راننده ممکن است شما را به‌سختی ببیند.","en":"I stay beside the lorry so that the driver knows where I am.","een":"No. Beside the lorry is exactly where the driver may find it hard to see you."},{"da":"Jeg kører forbi lastbilen eller lægger mig bag den.","fa":"یا از کامیون رد می‌شوم یا پشت سرش قرار می‌گیرم.","ok":1,"eda":"Ja. Så kan chaufføren se dig i spejlene, eller du er ude af vejen.","efa":"بله. این‌طور راننده شما را در آینه‌ها می‌بیند یا از سر راه کنار رفته‌اید.","en":"I drive past the lorry or drop back behind it.","een":"Yes. Then the driver can see you in the mirrors, or you are out of the way."}]},{"id":5101,"img":"newq-art/5101.png","c":"7.18","sda":"Du vil parkere i vejkanten omkring 20 m før jernbaneoverkørslen. Hvad gælder?","sfa":"می‌خواهید حدود ۲۰ متر پیش از تقاطع راه‌آهن کنار جاده پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You want to park at the edge of the road about 20 m before the level crossing. What applies?","st":[{"da":"Jeg må parkere, hvis jeg lader havariblinket være tændt.","fa":"اگر چراغ خطر را روشن بگذارم، می‌توانم پارک کنم.","ok":0,"eda":"Nej. Havariblinket giver ikke ret til at parkere, hvor det er forbudt.","efa":"خیر. چراغ خطر اجازه‌ی پارک در جای ممنوع را نمی‌دهد.","en":"I may park if I leave the hazard lights on.","een":"No. Hazard lights do not give a right to park where it is forbidden."},{"da":"Jeg må ikke parkere nærmere end 30 m fra overkørslen.","fa":"نباید نزدیک‌تر از ۳۰ متر به تقاطع پارک کنم.","ok":1,"eda":"Ja. Parkering er forbudt nærmere end 30 m fra en jernbaneoverkørsel.","efa":"بله. پارک در فاصله‌ی کمتر از ۳۰ متر از تقاطع راه‌آهن ممنوع است.","en":"I must not park closer than 30 m to the crossing.","een":"Yes. Parking is forbidden closer than 30 m to a level crossing."},{"da":"Jeg må gerne standse kort for at lade en passager stige ud, hvis det ikke er til fare.","fa":"اگر خطری نداشته باشد، می‌توانم کوتاه بایستم تا مسافری پیاده شود.","ok":1,"eda":"Ja. Forbuddet inden for 30 m gælder parkering; standsning er kun forbudt på selve overkørslen.","efa":"بله. ممنوعیت ۳۰ متر برای پارک است؛ توقف فقط روی خود تقاطع ممنوع است.","en":"I may stop briefly to let a passenger get out, if it is not dangerous.","een":"Yes. The 30 m ban covers parking; stopping is only forbidden on the crossing itself."},{"da":"Forbuddet gælder kun, når bommene er nede.","fa":"این ممنوعیت فقط وقتی است که راه‌بندها پایین‌اند.","ok":0,"eda":"Nej. Forbuddet gælder hele tiden.","efa":"خیر. این ممنوعیت همیشه برقرار است.","en":"The ban only applies when the barriers are down.","een":"No. The ban applies all the time."}]},{"id":5102,"img":"newq-art/5102.png","c":"7.18","sda":"Den eneste ledige plads ved kantstenen er lige ud for en indkørsel til et hus. Du vil parkere. Hvad gælder?","sfa":"تنها جای خالی کنار جدول درست جلوی ورودی ماشین‌روی یک خانه است. می‌خواهید پارک کنید. چه قاعده‌ای برقرار است؟","sen":"The only free space at the kerb is right in front of the driveway to a house. You want to park. What applies?","st":[{"da":"Det er tilladt, når jeg kun holder der i en time.","fa":"اگر فقط یک ساعت آن‌جا بمانم، مجاز است.","ok":0,"eda":"Nej. Forbuddet gælder uanset hvor længe, du parkerer.","efa":"خیر. این ممنوعیت هر قدر هم کوتاه پارک کنید، برقرار است.","en":"It is allowed as long as I only stand there for an hour.","een":"No. The ban applies however long you park."},{"da":"Det er tilladt om natten, når ingen skal ud.","fa":"شب، وقتی کسی بیرون نمی‌رود، مجاز است.","ok":0,"eda":"Nej. Forbuddet gælder hele døgnet.","efa":"خیر. این ممنوعیت در تمام شبانه‌روز برقرار است.","en":"It is allowed at night, when nobody is going out.","een":"No. The ban applies day and night."},{"da":"Det er tilladt, hvis jeg lægger mit telefonnummer i forruden.","fa":"اگر شماره‌ی تلفنم را پشت شیشه بگذارم، مجاز است.","ok":0,"eda":"Nej. Et telefonnummer ændrer ikke på forbuddet.","efa":"خیر. شماره‌ی تلفن ممنوعیت را تغییر نمی‌دهد.","en":"It is allowed if I put my phone number in the windscreen.","een":"No. A phone number does not change the ban."},{"da":"Det er forbudt at parkere ud for ind- og udkørslen til en ejendom.","fa":"پارک جلوی ورودی و خروجی یک ملک ممنوع است.","ok":1,"eda":"Ja. Parkering må ikke ske ud for ind- og udkørsel til og fra en ejendom.","efa":"بله. پارک جلوی راه ورود و خروج یک ملک مجاز نیست.","en":"Parking in front of the entrance and exit of a property is forbidden.","een":"Yes. Parking is not allowed in front of the way in and out of a property."}]},{"id":5103,"img":"newq-art/5103.png","c":"7.18","sda":"Alle pladser ved kantstenen er optaget. Du vil hurtigt hente en vare i butikken. Hvad gælder?","sfa":"همه‌ی جاهای کنار جدول پر است. می‌خواهید سریع چیزی از مغازه بگیرید. چه قاعده‌ای برقرار است؟","sen":"All the places at the kerb are taken. You want to fetch something quickly from the shop. What applies?","st":[{"da":"En bil, der holder ved siden af de parkerede, kan spærre for trafikken og skjule fodgængere.","fa":"خودرویی که کنار خودروهای پارک‌شده بایستد، می‌تواند راه را ببندد و عابران را پنهان کند.","ok":1,"eda":"Ja. Derfor er dobbeltparkering forbudt.","efa":"بله. به همین دلیل پارک دوبل ممنوع است.","en":"A car standing beside the parked ones can block the traffic and hide pedestrians.","een":"Yes. That is why double parking is forbidden."},{"da":"Jeg skal finde en lovlig plads, også selv om det tager længere tid.","fa":"باید جای مجازی پیدا کنم، حتی اگر بیشتر طول بکشد.","ok":1,"eda":"Ja. Du må kun standse og parkere, hvor det er tilladt og ikke til fare eller ulempe.","efa":"بله. فقط جایی می‌توانید بایستید یا پارک کنید که مجاز باشد و خطر یا مزاحمتی نداشته باشد.","en":"I must find a legal place, even if it takes longer.","een":"Yes. You may only stop and park where it is allowed and not dangerous or a nuisance."},{"da":"Jeg må parkere ved siden af en bil, der holder ved kantstenen, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کنار خودرویی که لب جدول ایستاده پارک کنم.","ok":0,"eda":"Nej. Det er forbudt at parkere ved siden af et andet køretøj, der holder ved kørebanens kant.","efa":"خیر. پارک کنار وسیله‌ی دیگری که لب سواره‌رو ایستاده، ممنوع است.","en":"I may park beside a car standing at the kerb if I switch on the hazard lights.","een":"No. It is forbidden to park beside another vehicle standing at the edge of the carriageway."},{"da":"Det er tilladt i op til 3 minutter.","fa":"تا ۳ دقیقه مجاز است.","ok":0,"eda":"Nej. Også en kort standsning skal ske ved kørebanens kant; ved siden af parkerede biler må du hverken standse eller parkere.","efa":"خیر. حتی توقف کوتاه هم باید کنار لبه‌ی سواره‌رو باشد؛ کنار خودروهای پارک‌شده نه می‌توانید بایستید و نه پارک کنید.","en":"It is allowed for up to 3 minutes.","een":"No. Even a short stop must be made at the edge of the carriageway; beside parked cars you may neither stop nor park."}]},{"id":5104,"img":"newq-art/5104.png","c":"7.18","sda":"Du kører over en bro over motorvejen og vil standse og tage et billede af udsigten. Hvad gælder?","sfa":"از روی پلی بالای بزرگراه می‌گذرید و می‌خواهید بایستید و از منظره عکس بگیرید. چه قاعده‌ای برقرار است؟","sen":"You are driving over a bridge over the motorway and want to stop and take a picture of the view. What applies?","st":[{"da":"Det er forbudt at standse og parkere på en bro over en motorvej.","fa":"توقف و پارک روی پل بالای بزرگراه ممنوع است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt på bro over motorvej, i viadukt og i tunnel.","efa":"بله. توقف و پارک روی پل بالای بزرگراه، در زیرگذر و در تونل ممنوع است.","en":"Stopping and parking on a bridge over a motorway are forbidden.","een":"Yes. Stopping and parking are forbidden on a bridge over a motorway, in a viaduct and in a tunnel."},{"da":"Forbuddet gælder kun på selve motorvejen, ikke på broen.","fa":"این ممنوعیت فقط در خود بزرگراه است، نه روی پل.","ok":0,"eda":"Nej. Forbuddet gælder netop på broen over motorvejen.","efa":"خیر. این ممنوعیت دقیقاً روی پل بالای بزرگراه است.","en":"The ban only applies on the motorway itself, not on the bridge.","een":"No. The ban applies precisely on the bridge over the motorway."},{"da":"Jeg må standse kort, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، می‌توانم کوتاه بایستم.","ok":0,"eda":"Nej. Havariblinket gør ikke en forbudt standsning tilladt.","efa":"خیر. چراغ خطر توقف ممنوع را مجاز نمی‌کند.","en":"I may stop briefly if I switch on the hazard lights.","een":"No. Hazard lights do not make a forbidden stop allowed."}]},{"id":5105,"img":"newq-art/5105.png","c":"7.18","sda":"Du vil standse i vejkanten lige i et uoverskueligt sving. Hvad gælder?","sfa":"می‌خواهید درست در یک پیچ بی‌دید کنار جاده بایستید. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the edge of the road right in a blind bend. What applies?","st":[{"da":"Jeg må ikke standse i eller ved et uoverskueligt sving.","fa":"نباید در پیچ بی‌دید یا نزدیک آن بایستم.","ok":1,"eda":"Ja. Standsning og parkering er forbudt i eller ved uoverskueligt vejsving og på eller nær en bakketop.","efa":"بله. توقف و پارک در پیچ بی‌دید یا نزدیک آن و روی تپه یا نزدیک آن ممنوع است.","en":"I must not stop in or near a blind bend.","een":"Yes. Stopping and parking are forbidden in or near a blind bend and on or near a hilltop."},{"da":"Jeg kører videre og standser et sted, hvor der er god oversigt.","fa":"ادامه می‌دهم و جایی می‌ایستم که دید خوبی دارد.","ok":1,"eda":"Ja. Find et sted, hvor andre kan se bilen i god tid.","efa":"بله. جایی پیدا کنید که دیگران خودرو را به موقع ببینند.","en":"I drive on and stop at a place with a good view.","een":"Yes. Find a place where others can see the car in good time."},{"da":"Forbuddet gælder kun om natten.","fa":"این ممنوعیت فقط شب‌هاست.","ok":0,"eda":"Nej. Forbuddet gælder hele døgnet.","efa":"خیر. این ممنوعیت در تمام شبانه‌روز برقرار است.","en":"The ban only applies at night.","een":"No. The ban applies day and night."},{"da":"Andre kan komme rundt i svinget og pludselig have bilen lige foran sig.","fa":"دیگران ممکن است از پیچ بیایند و ناگهان خودرو را درست جلوی خود ببینند.","ok":1,"eda":"Ja. De kan ikke se den holdende bil i tide.","efa":"بله. آن‌ها خودروی ایستاده را به موقع نمی‌بینند.","en":"Others may come round the bend and suddenly have the car right in front of them.","een":"Yes. They cannot see the standing car in time."}]},{"id":5106,"img":"newq-art/5106.png","c":"7.18","sda":"Du kører forbi denne tavle i højre side af vejen. Hvad gælder?","sfa":"از کنار این تابلو در سمت راست جاده رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign on the right-hand side of the road. What applies?","st":[{"da":"Forbuddet gælder i begge sider af vejen.","fa":"این ممنوعیت در هر دو سمت جاده است.","ok":0,"eda":"Nej. Tavlen gælder kun i den vejside, hvor den er sat op.","efa":"خیر. این تابلو فقط در همان سمتی از جاده که نصب شده معتبر است.","en":"The ban applies on both sides of the road.","een":"No. The sign only applies on the side of the road where it stands."},{"da":"Jeg må ikke standse på kørebanen i denne side af vejen.","fa":"در این سمت جاده نباید روی سواره‌رو بایستم.","ok":1,"eda":"Ja. Tavlen (C 61) forbyder standsning på kørebanen, som ikke sker af hensyn til den øvrige færdsel.","efa":"بله. این تابلو (C 61) توقف روی سواره‌رو را، جز به‌خاطر ترافیک، ممنوع می‌کند.","en":"I must not stop on the carriageway on this side of the road.","een":"Yes. The sign (C 61) forbids stopping on the carriageway that is not for the sake of the other traffic."},{"da":"Forbuddet gælder frem til næste vejkryds, hvis det ikke ophæves før.","fa":"این ممنوعیت تا تقاطع بعدی برقرار است، مگر زودتر لغو شود.","ok":1,"eda":"Ja. Standsnings- og parkeringsforbud gælder i færdselsretningen frem til næste vejkryds.","efa":"بله. ممنوعیت توقف و پارک در جهت حرکت تا تقاطع بعدی برقرار است.","en":"The ban applies up to the next junction, unless it is lifted before.","een":"Yes. Stopping and parking bans apply in the direction of travel up to the next junction."},{"da":"Jeg må standse kort for at sætte en passager af.","fa":"می‌توانم کوتاه بایستم تا مسافری پیاده شود.","ok":0,"eda":"Nej. Ved denne tavle er også en kort standsning forbudt.","efa":"خیر. با این تابلو حتی توقف کوتاه هم ممنوع است.","en":"I may stop briefly to let a passenger out.","een":"No. At this sign even a short stop is forbidden."}]},{"id":5107,"img":"newq-art/5107.png","c":"7.9","sda":"Bilen foran dig er ved at trække ud for at overhale en traktor. Hvad gælder for dig?","sfa":"خودروی جلوی شما دارد بیرون می‌کشد تا از یک تراکتور سبقت بگیرد. برای شما چه قاعده‌ای برقرار است؟","sen":"The car in front of you is moving out to overtake a tractor. What applies to you?","st":[{"da":"Jeg venter, til bilen er færdig med sin overhaling.","fa":"صبر می‌کنم تا سبقت آن خودرو تمام شود.","ok":1,"eda":"Ja. Derefter kan du selv vurdere, om du kan overhale uden fare.","efa":"بله. بعد از آن خودتان می‌سنجید که آیا بی‌خطر می‌توانید سبقت بگیرید.","en":"I wait until the car has finished its overtaking.","een":"Yes. After that you can judge for yourself whether you can overtake safely."},{"da":"Jeg kan overhale begge køretøjer på én gang, hvis jeg skynder mig.","fa":"اگر عجله کنم، می‌توانم هم‌زمان از هر دو سبقت بگیرم.","ok":0,"eda":"Nej. Du må ikke begynde, når den foran selv er ved at overhale.","efa":"خیر. وقتی جلویی خودش در حال سبقت است، نباید شروع کنید.","en":"I can overtake both vehicles at once if I hurry.","een":"No. You must not start when the one in front is overtaking itself."},{"da":"Jeg må ikke begynde at overhale, mens bilen foran giver tegn til at overhale.","fa":"تا وقتی خودروی جلو علامت سبقت می‌دهد، نباید سبقت را شروع کنم.","ok":1,"eda":"Ja. Før du overhaler, skal du sikre dig, at den foran ikke giver tegn til at overhale et andet køretøj.","efa":"بله. پیش از سبقت باید مطمئن شوید که جلویی علامت سبقت از وسیله‌ی دیگری نمی‌دهد.","en":"I must not start overtaking while the car in front is signalling to overtake.","een":"Yes. Before you overtake, you must make sure that the one in front is not signalling to overtake another vehicle."},{"da":"Bilen foran skal lade mig komme først, fordi jeg kører hurtigere.","fa":"خودروی جلو باید اجازه دهد اول من بروم، چون تندتر می‌رانم.","ok":0,"eda":"Nej. Det er dig, der skal vente; fart giver ingen ret.","efa":"خیر. شما باید صبر کنید؛ سرعت حقی به شما نمی‌دهد.","en":"The car in front must let me go first because I am driving faster.","een":"No. It is you who must wait; speed gives no right."}]},{"id":5108,"img":"newq-art/5108.png","c":"7.9","sda":"Du har lige overhalet en lastbil. Lidt længere fremme kører endnu en lastbil, som du også vil overhale med det samme. Hvad gælder?","sfa":"همین الان از یک کامیون سبقت گرفته‌اید. کمی جلوتر کامیون دیگری است که می‌خواهید فوراً از آن هم سبقت بگیرید. چه قاعده‌ای برقرار است؟","sen":"You have just overtaken a lorry. A little further ahead there is another lorry that you also want to overtake straight away. What applies?","st":[{"da":"Jeg må blive i venstre vognbane, så længe jeg vil.","fa":"تا هر وقت بخواهم می‌توانم در خط چپ بمانم.","ok":0,"eda":"Nej. Venstre vognbane bruges til at overhale, ikke til at blive i.","efa":"خیر. خط چپ برای سبقت است، نه برای ماندن.","en":"I may stay in the left lane for as long as I like.","een":"No. The left lane is for overtaking, not for staying in."},{"da":"Jeg skal straks trække ind lige foran den første lastbil.","fa":"باید فوراً درست جلوی کامیون اول برگردم.","ok":0,"eda":"Nej. Du må ikke trække ind så tæt, at du generer den, du har overhalet.","efa":"خیر. نباید آن‌قدر نزدیک برگردید که مزاحم وسیله‌ی سبقت‌گرفته شوید.","en":"I must pull in right in front of the first lorry at once.","een":"No. You must not pull in so close that you inconvenience the one you have overtaken."},{"da":"Jeg må blive i venstre vognbane, når jeg straks skal overhale den næste lastbil.","fa":"وقتی قرار است فوراً از کامیون بعدی سبقت بگیرم، می‌توانم در خط چپ بمانم.","ok":1,"eda":"Ja. Du behøver ikke køre tilbage til højre, hvis du straks vil overhale endnu et køretøj, og betingelserne er opfyldt.","efa":"بله. اگر قصد دارید فوراً از وسیله‌ی دیگری سبقت بگیرید و شرایط فراهم است، لازم نیست به راست برگردید.","en":"I may stay in the left lane when I am going to overtake the next lorry straight away.","een":"Yes. You need not move back to the right if you are going to overtake another vehicle straight away and the conditions are met."},{"da":"Ellers skal jeg tilbage til højre, så snart det kan ske uden fare eller ulempe.","fa":"در غیر این صورت باید به محض این‌که بی‌خطر و بی‌مزاحمت باشد، به راست برگردم.","ok":1,"eda":"Ja. Efter en overhaling til venstre skal du holde til højre igen, så snart det kan ske uden fare eller ulempe.","efa":"بله. پس از سبقت از چپ، باید به محض این‌که بی‌خطر و بی‌مزاحمت باشد، دوباره سمت راست بمانید.","en":"Otherwise I must move back to the right as soon as it can be done without danger or inconvenience.","een":"Yes. After overtaking on the left you must keep right again as soon as it can be done without danger or inconvenience."}]},{"id":5109,"img":"newq-art/5109.png","c":"7.9","sda":"Du vil overhale cyklisten, men en bil kommer imod dig. Hvordan forholder du dig?","sfa":"می‌خواهید از دوچرخه‌سوار سبقت بگیرید، ولی خودرویی از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You want to overtake the cyclist, but a car is coming towards you. What do you do?","st":[{"da":"Jeg venter med at overhale, til jeg kan give cyklisten god plads til siden.","fa":"صبر می‌کنم تا بتوانم از پهلو فاصله‌ی زیادی به دوچرخه‌سوار بدهم.","ok":1,"eda":"Ja. Den, der overhaler, skal holde tilstrækkelig afstand til siden.","efa":"بله. سبقت‌گیرنده باید فاصله‌ی پهلوی کافی نگه دارد.","en":"I wait to overtake until I can give the cyclist plenty of room to the side.","een":"Yes. The overtaking driver must keep enough distance to the side."},{"da":"Cyklisten kan svaje, fx i blæst eller for at undgå et hul i vejen.","fa":"دوچرخه‌سوار ممکن است منحرف شود، مثلاً در باد یا برای دور زدن یک چاله.","ok":1,"eda":"Ja. Derfor skal der være god plads mellem bilen og cyklisten.","efa":"بله. به همین دلیل باید بین خودرو و دوچرخه‌سوار فاصله‌ی خوبی باشد.","en":"The cyclist may wobble, for example in the wind or to avoid a hole in the road.","een":"Yes. That is why there must be plenty of room between the car and the cyclist."},{"da":"Jeg kan presse mig forbi, fordi cyklisten fylder så lidt.","fa":"می‌توانم به زور رد شوم، چون دوچرخه‌سوار جای کمی می‌گیرد.","ok":0,"eda":"Nej. En overhaling tæt på cyklisten kan få den til at vælte.","efa":"خیر. سبقت از نزدیک ممکن است دوچرخه‌سوار را زمین بزند.","en":"I can squeeze past because the cyclist takes up so little room.","een":"No. Overtaking close to the cyclist can make them fall."},{"da":"Jeg kører et stykke bag cyklisten, til den modkørende er kørt forbi.","fa":"تا رد شدن خودروی روبه‌رو با فاصله پشت دوچرخه‌سوار می‌رانم.","ok":1,"eda":"Ja. Så kan du overhale med god plads, når vejen er fri.","efa":"بله. این‌طور وقتی جاده خالی شد، با فاصله‌ی خوب سبقت می‌گیرید.","en":"I drive some way behind the cyclist until the oncoming car has passed.","een":"Yes. Then you can overtake with plenty of room when the road is clear."}]},{"id":5110,"img":"newq-art/5110.png","c":"7.9","sda":"Midt på vejen er der en dobbelt spærrelinje. Foran dig kører en langsom traktor. Hvad gælder?","sfa":"وسط جاده خط ممتد دوبل است. جلوی شما تراکتوری آهسته می‌رود. چه قاعده‌ای برقرار است؟","sen":"In the middle of the road there is a double barrier line. A slow tractor is driving in front of you. What applies?","st":[{"da":"Jeg må overhale, hvis jeg kun kører lidt ind over linjen.","fa":"اگر فقط کمی روی خط بروم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Linjen må slet ikke overskrides.","efa":"خیر. اصلاً نباید از این خط عبور کرد.","en":"I may overtake if I only drive a little over the line.","een":"No. The line must not be crossed at all."},{"da":"Jeg må ikke overskride spærrelinjen for at overhale.","fa":"برای سبقت نباید از خط ممتد عبور کنم.","ok":1,"eda":"Ja. En spærrelinje må ikke overskrides, heller ikke for at overhale en langsom traktor.","efa":"بله. از خط ممتد نباید عبور کرد، حتی برای سبقت از یک تراکتور آهسته.","en":"I must not cross the barrier line to overtake.","een":"Yes. A barrier line must not be crossed, not even to overtake a slow tractor."},{"da":"Jeg må overhale, hvis traktoren kører under 30 km/t.","fa":"اگر تراکتور کمتر از ۳۰ کیلومتر بر ساعت برود، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Der er ingen sådan undtagelse.","efa":"خیر. چنین استثنایی وجود ندارد.","en":"I may overtake if the tractor is doing under 30 km/h.","een":"No. There is no such exception."},{"da":"Jeg må overhale, når der ikke er modkørende.","fa":"وقتی ترافیک روبه‌رو نیست، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Spærrelinjen gælder, også når vejen er fri.","efa":"خیر. خط ممتد حتی وقتی جاده خالی است هم معتبر است.","en":"I may overtake when there is no oncoming traffic.","een":"No. The barrier line applies even when the road is clear."}]},{"id":5111,"img":"newq-art/5111.png","c":"7.9","sda":"Du nærmer dig et kryds uden tavler og afmærkning. Foran dig kører en langsom varevogn. Hvad gælder?","sfa":"به تقاطعی بدون تابلو و خط‌کشی نزدیک می‌شوید. جلوی شما ونی آهسته می‌رود. چه قاعده‌ای برقرار است؟","sen":"You are approaching a junction with no signs or markings. A slow van is driving in front of you. What applies?","st":[{"da":"Jeg må overhale, fordi jeg kører på den største vej.","fa":"می‌توانم سبقت بگیرم، چون در جاده‌ی بزرگ‌تر هستم.","ok":0,"eda":"Nej. Her gælder højrereglen; vejens størrelse giver ingen ret.","efa":"خیر. این‌جا قاعده‌ی دست راست برقرار است؛ بزرگی جاده حقی نمی‌دهد.","en":"I may overtake because I am on the bigger road.","een":"No. The right-hand rule applies here; the size of the road gives no right."},{"da":"Jeg må overhale, hvis jeg blinker i god tid.","fa":"اگر به موقع راهنما بزنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Blinklyset ændrer ikke på forbuddet.","efa":"خیر. راهنما ممنوعیت را تغییر نمی‌دهد.","en":"I may overtake if I signal in good time.","een":"No. The indicator does not change the ban."},{"da":"Jeg må ikke overhale varevognen i krydset.","fa":"در تقاطع نباید از ون سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling i vejkryds er forbudt, når der ikke gælder en af undtagelserne, fx at den tværgående trafik har ubetinget vigepligt.","efa":"بله. سبقت در تقاطع ممنوع است، مگر یکی از استثناها برقرار باشد، مثلاً ترافیک متقاطع باید بی‌قیدوشرط راه بدهد.","en":"I must not overtake the van at the junction.","een":"Yes. Overtaking at a junction is forbidden unless one of the exceptions applies, for example that the crossing traffic must give way unconditionally."}]},{"id":5112,"img":"newq-art/5112.png","c":"6.1","sda":"Du kører forbi denne advarselstavle uden for byen. Der er ingen undertavle. Hvad gælder?","sfa":"بیرون از شهر از کنار این تابلوی هشدار رد می‌شوید. زیرش تابلوی کوچکی نیست. چه قاعده‌ای برقرار است؟","sen":"You pass this warning sign outside town. There is no plate under it. What applies?","st":[{"da":"Faren er lige ved tavlen.","fa":"خطر درست کنار تابلوست.","ok":0,"eda":"Nej. Uden for byen står tavlen normalt et godt stykke før faren.","efa":"خیر. بیرون از شهر تابلو معمولاً مسافتی پیش از خطر است.","en":"The danger is right at the sign.","een":"No. Outside town the sign normally stands a good way before the danger."},{"da":"Faren er mindst 1 km fremme.","fa":"خطر دست‌کم ۱ کیلومتر جلوتر است.","ok":0,"eda":"Nej. Er afstanden en anden end normalt, står den på en undertavle.","efa":"خیر. اگر فاصله غیرعادی باشد، روی تابلوی کوچک زیرین نوشته می‌شود.","en":"The danger is at least 1 km ahead.","een":"No. If the distance is other than normal, it is shown on a plate under the sign."},{"da":"Faren er normalt mellem 150 og 250 m fremme.","fa":"خطر معمولاً ۱۵۰ تا ۲۵۰ متر جلوتر است.","ok":1,"eda":"Ja. Uden for tættere bebygget område sættes advarselstavler normalt op mellem 150 og 250 m før farestedet.","efa":"بله. بیرون از مناطق مسکونی، تابلوهای هشدار معمولاً ۱۵۰ تا ۲۵۰ متر پیش از محل خطر نصب می‌شوند.","en":"The danger is normally between 150 and 250 m ahead.","een":"Yes. Outside built-up areas warning signs are normally put up between 150 and 250 m before the danger."},{"da":"Der kan være kreaturer på vejen.","fa":"ممکن است دام روی جاده باشد.","ok":1,"eda":"Ja. Tavlen (A 27) advarer om kreaturer.","efa":"بله. این تابلو (A 27) درباره‌ی دام هشدار می‌دهد.","en":"There may be livestock on the road.","een":"Yes. The sign (A 27) warns of livestock."}]},{"id":5113,"img":"newq-art/5113.png","c":"6.1","sda":"Du har kørt på en strækning med overhalingsforbud og en lokal hastighedsgrænse. Nu kører du forbi denne tavle. Hvad gælder?","sfa":"در مسیری با ممنوعیت سبقت و حد سرعت محلی رانده‌اید. حالا از کنار این تابلو رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You have been driving on a stretch with a no-overtaking ban and a local speed limit. Now you pass this sign. What applies?","st":[{"da":"Overhalingsforbuddet og den lokale hastighedsgrænse er ophævet.","fa":"ممنوعیت سبقت و حد سرعت محلی لغو شده‌اند.","ok":1,"eda":"Ja. Tavlen (C 59) ophæver alle forbudstavler på den forudgående strækning undtagen standsnings- og parkeringsforbud.","efa":"بله. این تابلو (C 59) همه‌ی تابلوهای ممنوعیت مسیر قبلی را، جز ممنوعیت توقف و پارک، لغو می‌کند.","en":"The no-overtaking ban and the local speed limit are lifted.","een":"Yes. The sign (C 59) lifts all prohibition signs on the stretch before it except stopping and parking bans."},{"da":"Et standsnings- eller parkeringsforbud gælder stadig.","fa":"ممنوعیت توقف یا پارک هنوز برقرار است.","ok":1,"eda":"Ja. Standsnings- og parkeringsforbud ophæves ikke af denne tavle.","efa":"بله. ممنوعیت توقف و پارک با این تابلو لغو نمی‌شود.","en":"A stopping or parking ban still applies.","een":"Yes. Stopping and parking bans are not lifted by this sign."},{"da":"Nu gælder der ingen hastighedsgrænse.","fa":"حالا هیچ حد سرعتی وجود ندارد.","ok":0,"eda":"Nej. Den generelle hastighedsgrænse gælder igen, fx 80 km/t uden for byen.","efa":"خیر. حد سرعت عمومی دوباره برقرار است، مثلاً بیرون شهر ۸۰ کیلومتر بر ساعت.","en":"Now there is no speed limit at all.","een":"No. The general speed limit applies again, for example 80 km/h outside town."},{"da":"Tavlen betyder, at vejen snart ender.","fa":"این تابلو یعنی جاده به‌زودی تمام می‌شود.","ok":0,"eda":"Nej. Tavlen handler om forbud, ikke om vejens forløb.","efa":"خیر. این تابلو درباره‌ی ممنوعیت‌هاست، نه مسیر جاده.","en":"The sign means that the road ends soon.","een":"No. The sign is about prohibitions, not about where the road goes."}]},{"id":5114,"img":"newq-art/5114.png","c":"6.1","sda":"Du vil svinge ind på sidevejen med denne tavle for at aflevere en pakke i butikken. Hvad gælder?","sfa":"می‌خواهید وارد فرعی‌ای با این تابلو شوید تا بسته‌ای را به مغازه بدهید. چه قاعده‌ای برقرار است؟","sen":"You want to turn into the side road with this sign to deliver a parcel at the shop. What applies?","st":[{"da":"Jeg må ikke køre ind på vejen med noget køretøj.","fa":"با هیچ وسیله‌ای نباید وارد این راه شوم.","ok":1,"eda":"Ja. Tavlen (C 19) forbyder indkørsel med ethvert køretøj.","efa":"بله. این تابلو (C 19) ورود با هر وسیله‌ای را ممنوع می‌کند.","en":"I must not drive into the road with any vehicle.","een":"Yes. The sign (C 19) forbids entry with any vehicle."},{"da":"Jeg må køre ind, hvis der ikke kommer nogen ud.","fa":"اگر کسی بیرون نیاید، می‌توانم وارد شوم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset om der er trafik.","efa":"خیر. این ممنوعیت، چه ترافیک باشد چه نباشد، برقرار است.","en":"I may drive in if nobody is coming out.","een":"No. The ban applies whether or not there is traffic."},{"da":"Tavlen gælder kun for lastbiler.","fa":"این تابلو فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Den gælder alle køretøjer, når der ikke er en undertavle.","efa":"خیر. وقتی تابلوی زیرین نباشد، برای همه‌ی وسایل است.","en":"The sign only applies to lorries.","een":"No. It applies to all vehicles when there is no plate under it."},{"da":"Jeg må køre ind, når jeg kun skal aflevere en pakke.","fa":"وقتی فقط باید بسته‌ای بدهم، می‌توانم وارد شوم.","ok":0,"eda":"Nej. Et kort ærinde er ikke en undtagelse fra forbuddet.","efa":"خیر. کار کوتاه از این ممنوعیت مستثنا نیست.","en":"I may drive in when I only have to deliver a parcel.","een":"No. A short errand is no exception to the ban."}]},{"id":5115,"img":"newq-art/5115.png","c":"6.1","sda":"Du kører forbi denne tavle ved et kryds. Hvad gælder?","sfa":"در یک تقاطع از کنار این تابلو رد می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign at a junction. What applies?","st":[{"da":"Jeg må heller ikke vende i krydset.","fa":"در این تقاطع دور زدن هم ممنوع است.","ok":1,"eda":"Ja. Forbuddet mod venstresving gælder også vending.","efa":"بله. ممنوعیت گردش به چپ شامل دور زدن هم می‌شود.","en":"I must not turn round at the junction either.","een":"Yes. The ban on turning left also covers turning round."},{"da":"Forbuddet gælder frem til næste kryds.","fa":"این ممنوعیت تا تقاطع بعدی است.","ok":0,"eda":"Nej. Forbuddet gælder kun i det kryds, hvor tavlen er sat op.","efa":"خیر. این ممنوعیت فقط در همان تقاطعی است که تابلو نصب شده.","en":"The ban applies up to the next junction.","een":"No. The ban only applies at the junction where the sign is put up."},{"da":"Jeg må svinge til venstre, hvis der ikke er modkørende.","fa":"اگر ترافیک روبه‌رو نباشد، می‌توانم به چپ بپیچم.","ok":0,"eda":"Nej. Forbuddet gælder, uanset trafikken.","efa":"خیر. این ممنوعیت، ترافیک هر چه باشد، برقرار است.","en":"I may turn left if there is no oncoming traffic.","een":"No. The ban applies whatever the traffic."},{"da":"Jeg må ikke svinge til venstre i krydset.","fa":"در این تقاطع نباید به چپ بپیچم.","ok":1,"eda":"Ja. Tavlen (C 11) forbyder venstresving i det kryds, hvor den står.","efa":"بله. این تابلو (C 11) گردش به چپ را در همان تقاطع ممنوع می‌کند.","en":"I must not turn left at the junction.","een":"Yes. The sign (C 11) forbids turning left at the junction where it stands."}]},{"id":5116,"img":"newq-art/5116.png","c":"6.1","sda":"Før krydset kørte du forbi en tavle med 60 km/t. Efter krydset er der ingen nye tavler. Hvad gælder?","sfa":"پیش از تقاطع از کنار تابلوی ۶۰ کیلومتر بر ساعت رد شدید. بعد از تقاطع تابلوی تازه‌ای نیست. چه قاعده‌ای برقرار است؟","sen":"Before the junction you passed a 60 km/h sign. After the junction there are no new signs. What applies?","st":[{"da":"Grænsen ophører i krydset, ligesom de fleste andre forbud.","fa":"این حد، مثل بیشتر ممنوعیت‌ها، در تقاطع تمام می‌شود.","ok":0,"eda":"Nej. Hastighedsgrænser fortsætter efter kryds; det gør de fleste andre forbud ikke.","efa":"خیر. حد سرعت بعد از تقاطع ادامه دارد؛ بیشتر ممنوعیت‌های دیگر نه.","en":"The limit ends at the junction, like most other bans.","een":"No. Speed limits continue after junctions; most other bans do not."},{"da":"Grænsen på 60 km/t gælder stadig.","fa":"حد ۶۰ کیلومتر بر ساعت هنوز برقرار است.","ok":1,"eda":"Ja. En lokal hastighedsgrænse gælder, til den ophæves af en ophørstavle, en afstand på en undertavle eller en anden grænse.","efa":"بله. حد سرعت محلی تا وقتی تابلوی پایان، فاصله‌ی روی تابلوی زیرین یا حد دیگری آن را لغو کند، برقرار است.","en":"The 60 km/h limit still applies.","een":"Yes. A local speed limit applies until it is lifted by an end sign, a distance on a plate or another limit."},{"da":"Nu gælder 80 km/t, fordi jeg er uden for byen.","fa":"حالا ۸۰ کیلومتر بر ساعت معتبر است، چون بیرون شهرم.","ok":0,"eda":"Nej. Den lokale grænse gælder, indtil den bliver ophævet.","efa":"خیر. حد محلی تا لغو شدنش برقرار است.","en":"Now 80 km/h applies because I am outside town.","een":"No. The local limit applies until it is lifted."}]},{"id":5117,"img":"newq-art/5117.png","c":"7.6","sda":"En bus holder ved stoppestedet foran dig, og passagerer stiger af. Hvordan forholder du dig?","sfa":"اتوبوسی جلوی شما در ایستگاه ایستاده و مسافران پیاده می‌شوند. چه می‌کنید؟","sen":"A bus is standing at the stop in front of you, and passengers are getting off. What do you do?","st":[{"da":"Jeg sænker farten, fordi passagerer kan gå ud på kørebanen foran bussen.","fa":"سرعتم را کم می‌کنم، چون ممکن است مسافران از جلوی اتوبوس وارد سواره‌رو شوند.","ok":1,"eda":"Ja. Når du nærmer dig en bus, der holder for at sætte passagerer af, skal hastigheden være passende lav.","efa":"بله. وقتی به اتوبوسی نزدیک می‌شوید که برای پیاده کردن مسافر ایستاده، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down because passengers may step out into the road in front of the bus.","een":"Yes. When you approach a bus that has stopped to let passengers off, your speed must be suitably low."},{"da":"Blinker bussen til venstre for at køre ud, lader jeg den komme ud.","fa":"اگر اتوبوس برای حرکت راهنمای چپ بزند، می‌گذارم بیرون بیاید.","ok":1,"eda":"Ja. I tættere bebygget område skal du give plads til en bus, der giver tegn til at køre ud fra et stoppested.","efa":"بله. در مناطق مسکونی باید به اتوبوسی که برای حرکت از ایستگاه علامت می‌دهد، جا بدهید.","en":"If the bus signals left to pull out, I let it out.","een":"Yes. In built-up areas you must make room for a bus that signals to pull out from a stop."},{"da":"Jeg kører forbi med uændret fart, fordi bussen holder stille.","fa":"با همان سرعت رد می‌شوم، چون اتوبوس ایستاده است.","ok":0,"eda":"Nej. Netop når bussen holder, kan der komme passagerer ud foran den.","efa":"خیر. درست وقتی اتوبوس ایستاده، ممکن است مسافران از جلویش بیرون بیایند.","en":"I drive past at the same speed because the bus is standing still.","een":"No. It is precisely when the bus is standing that passengers may come out in front of it."},{"da":"Passagererne skal vente, så jeg behøver ikke tage hensyn.","fa":"مسافران باید صبر کنند، پس لازم نیست ملاحظه کنم.","ok":0,"eda":"Nej. Du skal altid vise hensyn over for gående, også dem, der går ud ved en bus.","efa":"خیر. همیشه باید به عابران ملاحظه کنید، از جمله کسانی که کنار اتوبوس وارد جاده می‌شوند.","en":"The passengers have to wait, so I need not take care.","een":"No. You must always show consideration for pedestrians, including those stepping out by a bus."}]},{"id":5118,"img":"newq-art/5118.png","c":"7.6","sda":"Foran dig rider to ryttere i vejkanten. Hvordan forholder du dig?","sfa":"جلوی شما دو سوارکار کنار جاده اسب‌سواری می‌کنند. چه می‌کنید؟","sen":"Two riders on horseback are riding at the edge of the road in front of you. What do you do?","st":[{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du nærmer dig heste på vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به اسب‌ها روی جاده نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down in good time.","een":"Yes. When you approach horses on the road, your speed must be suitably low."},{"da":"Jeg kører forbi i god afstand og roligt.","fa":"با فاصله‌ی زیاد و آرام رد می‌شوم.","ok":1,"eda":"Ja. En hest kan blive bange og springe til siden.","efa":"بله. اسب ممکن است بترسد و به کنار بپرد.","en":"I pass at a good distance and calmly.","een":"Yes. A horse may take fright and jump to the side."},{"da":"Hestene er vant til trafik, så jeg kan køre tæt forbi.","fa":"اسب‌ها به ترافیک عادت دارند، پس می‌توانم از نزدیک رد شوم.","ok":0,"eda":"Nej. Du kan aldrig vide, hvordan en hest reagerer.","efa":"خیر. هرگز نمی‌دانید اسب چه واکنشی نشان می‌دهد.","en":"The horses are used to traffic, so I can drive close past them.","een":"No. You can never know how a horse will react."},{"da":"Jeg undgår at dytte eller give gas tæt ved hestene.","fa":"از بوق زدن یا گاز دادن نزدیک اسب‌ها پرهیز می‌کنم.","ok":1,"eda":"Ja. Pludselige lyde kan skræmme hestene.","efa":"بله. صداهای ناگهانی می‌تواند اسب‌ها را بترساند.","en":"I avoid sounding the horn or revving up close to the horses.","een":"Yes. Sudden noises can frighten the horses."}]},{"id":5119,"img":"newq-art/5119.png","c":"7.6","sda":"Det er mørkt, og to fodgængere går i vejens venstre side og kommer imod dig. Hvordan forholder du dig?","sfa":"هوا تاریک است و دو عابر در سمت چپ جاده به سمت شما می‌آیند. چه می‌کنید؟","sen":"It is dark, and two pedestrians are walking on the left side of the road towards you. What do you do?","st":[{"da":"Jeg sænker farten og giver dem god plads, når jeg kører forbi.","fa":"سرعتم را کم می‌کنم و هنگام عبور جای زیادی به آن‌ها می‌دهم.","ok":1,"eda":"Ja. Du skal give de gående tid til at vige og fornøden plads på vejen.","efa":"بله. باید به عابران فرصت کنار رفتن و جای لازم روی جاده بدهید.","en":"I slow down and give them plenty of room when I pass.","een":"Yes. You must give pedestrians time to step aside and the room they need on the road."},{"da":"Mørkt tøj gør dem svære at se, så jeg må regne med, at der kan være flere.","fa":"لباس تیره دیدنشان را سخت می‌کند، پس باید انتظار داشته باشم عابران دیگری هم باشند.","ok":1,"eda":"Ja. Gående uden refleks ses først meget sent i nærlys.","efa":"بله. عابران بدون شبرنگ در نور پایین خیلی دیر دیده می‌شوند.","en":"Dark clothes make them hard to see, so I must expect that there may be more.","een":"Yes. Pedestrians without reflectors are seen only very late in dipped beam."},{"da":"De går forkert, fordi de går i venstre side.","fa":"اشتباه می‌روند، چون در سمت چپ‌اند.","ok":0,"eda":"Nej. Gående på en vej uden fortov skal gå i venstre side, imod trafikken.","efa":"خیر. عابران در جاده‌ی بدون پیاده‌رو باید سمت چپ و رو به ترافیک راه بروند.","en":"They are walking wrongly because they are on the left side.","een":"No. Pedestrians on a road without a pavement must walk on the left, facing the traffic."},{"da":"Jeg dytter, så de går ud i rabatten.","fa":"بوق می‌زنم تا به کنار جاده بروند.","ok":0,"eda":"Nej. Hornet bruges kun for at afværge fare; sænk i stedet farten.","efa":"خیر. بوق فقط برای دفع خطر است؛ به‌جایش سرعت را کم کنید.","en":"I sound the horn so that they move onto the verge.","een":"No. The horn is only for averting danger; slow down instead."}]},{"id":5120,"img":"newq-art/5120.png","c":"7.6","sda":"Du kommer til et uheldssted, hvor politiet dirigerer trafikken forbi. Hvordan forholder du dig?","sfa":"به محل تصادفی می‌رسید که پلیس ترافیک را از کنارش هدایت می‌کند. چه می‌کنید؟","sen":"You come to the scene of an accident where the police are directing traffic past. What do you do?","st":[{"da":"Jeg standser for at se, hvad der er sket, selv om politiet har styr på det.","fa":"می‌ایستم تا ببینم چه شده، با آن‌که پلیس اوضاع را در دست دارد.","ok":0,"eda":"Nej. Nysgerrige, der standser, kan skabe nye uheld og hindre redningsarbejdet.","efa":"خیر. کنجکاوهایی که می‌ایستند، ممکن است باعث تصادف تازه شوند و کار امداد را مختل کنند.","en":"I stop to see what has happened, even though the police have it in hand.","een":"No. Curious drivers who stop can cause new accidents and hinder the rescue work."},{"da":"Jeg følger politiets anvisninger.","fa":"از دستور پلیس پیروی می‌کنم.","ok":1,"eda":"Ja. Politiets anvisninger skal efterkommes.","efa":"بله. دستور پلیس باید اجرا شود.","en":"I follow the police's directions.","een":"Yes. The police's directions must be obeyed."},{"da":"Jeg sænker farten, når jeg kører forbi uheldsstedet.","fa":"هنگام عبور از کنار محل تصادف سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Forbi et uheldssted skal hastigheden være passende lav.","efa":"بله. هنگام عبور از محل تصادف سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down when I drive past the accident.","een":"Yes. Past an accident your speed must be suitably low."},{"da":"Jeg kører langsomt forbi og filmer uheldet med telefonen.","fa":"آهسته رد می‌شوم و با تلفن از تصادف فیلم می‌گیرم.","ok":0,"eda":"Nej. Du må ikke bruge håndholdt telefon under kørsel, og du skal holde opmærksomheden på vejen.","efa":"خیر. در حین رانندگی نباید از تلفن دستی استفاده کنید و باید حواستان به جاده باشد.","en":"I drive past slowly and film the accident with my phone.","een":"No. You must not use a hand-held phone while driving, and you must keep your attention on the road."}]},{"id":5121,"img":"newq-art/5121.png","c":"7.3","sda":"Du kører i en almindelig personbil uden for tættere bebygget område. Der er ingen hastighedstavler. Hvad er den højst tilladte hastighed?","sfa":"با یک سواری معمولی بیرون از منطقه‌ی مسکونی می‌رانید. تابلوی سرعتی نیست. حداکثر سرعت مجاز چقدر است؟","sen":"You are driving an ordinary car outside a built-up area. There are no speed-limit signs. What is the highest permitted speed?","st":[{"da":"70 km/t.","fa":"۷۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 70 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۷۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"70 km/h.","een":"No. 70 km/h only applies where it is signed."},{"da":"100 km/t.","fa":"۱۰۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 100 km/t er ikke den generelle grænse på landevej.","efa":"خیر. ۱۰۰ کیلومتر بر ساعت حد عمومی جاده‌ی بیرون شهر نیست.","en":"100 km/h.","een":"No. 100 km/h is not the general limit on a country road."},{"da":"90 km/t.","fa":"۹۰ کیلومتر بر ساعت.","ok":0,"eda":"Nej. 90 km/t gælder kun, hvor det er skiltet.","efa":"خیر. ۹۰ کیلومتر بر ساعت فقط جایی است که تابلو داشته باشد.","en":"90 km/h.","een":"No. 90 km/h only applies where it is signed."},{"da":"80 km/t.","fa":"۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Uden for tættere bebygget område er den generelle grænse 80 km/t.","efa":"بله. بیرون از مناطق مسکونی حد عمومی ۸۰ کیلومتر بر ساعت است.","en":"80 km/h.","een":"Yes. Outside built-up areas the general limit is 80 km/h."}]},{"id":5122,"img":"newq-art/5122.png","c":"7.3","sda":"Der er tæt tåge, og du kan kun se omkring 50 m frem. Hvordan forholder du dig?","sfa":"مه غلیظ است و فقط حدود ۵۰ متر جلو را می‌بینید. چه می‌کنید؟","sen":"There is thick fog, and you can only see about 50 m ahead. What do you do?","st":[{"da":"Jeg må bruge tågelygter.","fa":"می‌توانم از چراغ مه‌شکن استفاده کنم.","ok":1,"eda":"Ja. Tågelygter må bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن در مه و بارش شدید مجاز است.","en":"I may use fog lights.","een":"Yes. Fog lights may be used in fog and heavy precipitation."},{"da":"Jeg kører så langsomt, at jeg kan standse på den strækning, jeg kan se.","fa":"آن‌قدر آهسته می‌رانم که بتوانم در فاصله‌ای که می‌بینم بایستم.","ok":1,"eda":"Ja. Du skal kunne standse på den del af vejen, du har udsyn over.","efa":"بله. باید بتوانید در بخشی از جاده که می‌بینید بایستید.","en":"I drive so slowly that I can stop within the distance I can see.","een":"Yes. You must be able to stop within the part of the road you can see."},{"da":"Jeg holder større afstand til bilen foran.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم.","ok":1,"eda":"Ja. I tåge har du brug for mere tid til at reagere.","efa":"بله. در مه به زمان بیشتری برای واکنش نیاز دارید.","en":"I keep a greater distance to the car in front.","een":"Yes. In fog you need more time to react."},{"da":"Jeg tænder fjernlyset for at se længere.","fa":"نور بالا را روشن می‌کنم تا دورتر را ببینم.","ok":0,"eda":"Nej. I tåge reflekteres fjernlyset og blænder dig selv.","efa":"خیر. در مه نور بالا بازتاب می‌شود و خودتان را خیره می‌کند.","en":"I switch on the high beam to see further.","een":"No. In fog the high beam is reflected and dazzles you yourself."}]},{"id":5123,"img":"newq-art/5123.png","c":"7.3","sda":"Der står store vandpytter langs kantstenen, og der går fodgængere på fortovet. Hvordan forholder du dig?","sfa":"کنار جدول چاله‌های بزرگ آب است و عابران در پیاده‌رو راه می‌روند. چه می‌کنید؟","sen":"There are big puddles along the kerb, and pedestrians are walking on the pavement. What do you do?","st":[{"da":"Det er fodgængernes eget ansvar at holde afstand til vandet.","fa":"دور ماندن از آب وظیفه‌ی خود عابران است.","ok":0,"eda":"Nej. Det er den kørendes pligt at undgå at tilstænke andre.","efa":"خیر. وظیفه‌ی راننده است که آب روی دیگران نپاشد.","en":"It is the pedestrians' own job to keep away from the water.","een":"No. It is the driver's duty to avoid splashing others."},{"da":"Jeg sænker farten, så jeg ikke sprøjter vand på dem.","fa":"سرعتم را کم می‌کنم تا آب روی آن‌ها نپاشد.","ok":1,"eda":"Ja. I dårligt føre skal du afpasse hastigheden, så andre så vidt muligt ikke bliver tilstænket.","efa":"بله. در شرایط بد باید سرعت را طوری تنظیم کنید که تا جای ممکن آب روی دیگران پاشیده نشود.","en":"I slow down so that I do not splash water on them.","een":"Yes. In poor conditions you must adjust your speed so that others are not splashed as far as possible."},{"da":"Jeg kører hurtigt forbi, så det er hurtigt overstået.","fa":"تند رد می‌شوم تا زود تمام شود.","ok":0,"eda":"Nej. Høj fart sprøjter mest.","efa":"خیر. سرعت زیاد بیشترین آب را می‌پاشد.","en":"I drive past fast so that it is over quickly.","een":"No. High speed splashes the most."}]},{"id":5124,"img":"newq-art/5124.png","c":"1.2","sda":"Cyklerne på din cykelholder dækker bilens nummerplade og den ene baglygte. Hvad gælder?","sfa":"دوچرخه‌های روی دوچرخه‌بر، پلاک خودرو و یکی از چراغ‌های عقب را پوشانده‌اند. چه قاعده‌ای برقرار است؟","sen":"The bicycles on your bike rack cover the car's number plate and one of the rear lights. What applies?","st":[{"da":"Lasten må ikke skjule nummerpladen eller de påbudte lygter.","fa":"بار نباید پلاک یا چراغ‌های الزامی را بپوشاند.","ok":1,"eda":"Ja. Gods skal anbringes, så påbudte lygter og nummerpladen ikke skjules.","efa":"بله. بار باید طوری گذاشته شود که چراغ‌های الزامی و پلاک پوشانده نشوند.","en":"The load must not cover the number plate or the required lights.","een":"Yes. Goods must be placed so that the required lights and the number plate are not covered."},{"da":"Det er tilladt, hvis jeg højst kører 50 km/t.","fa":"اگر حداکثر ۵۰ کیلومتر بر ساعت بروم، مجاز است.","ok":0,"eda":"Nej. Reglen gælder uanset farten.","efa":"خیر. این قاعده، سرعت هر چه باشد، برقرار است.","en":"It is allowed if I drive at most 50 km/h.","een":"No. The rule applies whatever the speed."},{"da":"Det er tilladt, når cyklerne er spændt godt fast.","fa":"وقتی دوچرخه‌ها محکم بسته شده‌اند، مجاز است.","ok":0,"eda":"Nej. Lasten skal både sidde fast og lade lygter og nummerplade være synlige.","efa":"خیر. بار هم باید محکم باشد و هم چراغ‌ها و پلاک را نپوشاند.","en":"It is allowed when the bicycles are firmly strapped on.","een":"No. The load must both be secure and leave the lights and number plate visible."},{"da":"Jeg kan bruge en ekstra nummerplade på cykelholderen.","fa":"می‌توانم روی دوچرخه‌بر یک پلاک اضافه بگذارم.","ok":1,"eda":"Ja. En ekstra (tredje) nummerplade skal bruges, når bilens bageste nummerplade er helt eller delvis dækket.","efa":"بله. وقتی پلاک عقب خودرو کاملاً یا تا حدی پوشیده است، باید از پلاک اضافه (سوم) استفاده کرد.","en":"I can use an extra number plate on the bike rack.","een":"Yes. An extra (third) number plate must be used when the car's rear number plate is fully or partly covered."}]},{"id":5125,"img":"newq-art/5125.png","c":"1.2","sda":"Du skal til at køre. Hvad skal du som fører holde øje med, at bilen er i orden?","sfa":"می‌خواهید راه بیفتید. به‌عنوان راننده باید مراقب سالم بودن چه چیزهایی در خودرو باشید؟","sen":"You are about to drive. What must you as the driver check that the car is in order?","st":[{"da":"Styretøjet.","fa":"فرمان.","ok":1,"eda":"Ja. Fejl i styretøjet kan gøre bilen umulig at styre.","efa":"بله. عیب فرمان ممکن است هدایت خودرو را ناممکن کند.","en":"The steering.","een":"Yes. A fault in the steering can make the car impossible to steer."},{"da":"Intet; det er kun ejerens ansvar.","fa":"هیچ؛ این فقط وظیفه‌ی مالک است.","ok":0,"eda":"Nej. Ejeren har ansvaret for bilens lovlige stand, men føreren skal også selv kontrollere den.","efa":"خیر. مالک مسئول وضعیت قانونی خودروست، ولی راننده هم باید خودش آن را بررسی کند.","en":"Nothing; it is only the owner's job.","een":"No. The owner is responsible for the car's lawful condition, but the driver must check it too."},{"da":"Bremserne.","fa":"ترمزها.","ok":1,"eda":"Ja. Føreren skal hele tiden påse, at styre-, bremse-, signal- og tegngivningsapparater samt lygter er i forsvarlig stand.","efa":"بله. راننده باید همیشه مراقب باشد فرمان، ترمز، وسایل علامت‌دهی و چراغ‌ها در وضعیت ایمنی باشند.","en":"The brakes.","een":"Yes. The driver must always see to it that the steering, brakes, signalling equipment and lights are in a safe condition."},{"da":"Lygterne og blinklysene.","fa":"چراغ‌ها و راهنماها.","ok":1,"eda":"Ja. Bilen skal kunne ses, og dine tegn skal kunne forstås.","efa":"بله. خودرو باید دیده شود و علامت‌هایتان فهمیده شود.","en":"The lights and the indicators.","een":"Yes. The car must be visible and your signals understood."}]},{"id":5126,"img":"newq-art/5126.png","c":"7.18","sda":"Du kører forbi denne tavle og vil sætte en passager af lidt længere fremme. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید و می‌خواهید کمی جلوتر مسافری را پیاده کنید. چه قاعده‌ای برقرار است؟","sen":"You pass this sign and want to let a passenger out a little further on. What applies?","st":[{"da":"Forbuddet gælder frem til næste vejkryds, når der ikke er andre tavler.","fa":"وقتی تابلوی دیگری نباشد، این ممنوعیت تا تقاطع بعدی برقرار است.","ok":1,"eda":"Ja. Parkeringsforbuddet gælder i færdselsretningen frem til næste kryds.","efa":"بله. ممنوعیت پارک در جهت حرکت تا تقاطع بعدی برقرار است.","en":"The ban applies up to the next junction when there are no other signs.","een":"Yes. The parking ban applies in the direction of travel up to the next junction."},{"da":"Tavlen forbyder også en kort standsning for at sætte en passager af.","fa":"این تابلو توقف کوتاه برای پیاده کردن مسافر را هم ممنوع می‌کند.","ok":0,"eda":"Nej. Det er tavlen med det røde kryds (C 61), der forbyder standsning.","efa":"خیر. تابلوی ضربدر قرمز (C 61) است که توقف را ممنوع می‌کند.","en":"The sign also forbids a short stop to let a passenger out.","een":"No. It is the sign with the red cross (C 61) that forbids stopping."},{"da":"Jeg må godt standse kort for at lade passageren stige ud.","fa":"می‌توانم کوتاه بایستم تا مسافر پیاده شود.","ok":1,"eda":"Ja. Tavlen (C 62) forbyder parkering, ikke en kort standsning for at lade passagerer stige af.","efa":"بله. این تابلو (C 62) پارک را ممنوع می‌کند، نه توقف کوتاه برای پیاده کردن مسافر.","en":"I may stop briefly to let the passenger get out.","een":"Yes. The sign (C 62) forbids parking, not a short stop to let passengers off."},{"da":"Jeg må ikke parkere i denne side af vejen.","fa":"در این سمت جاده نباید پارک کنم.","ok":1,"eda":"Ja. Forbuddet gælder i den vejside, hvor tavlen står.","efa":"بله. این ممنوعیت در همان سمتی از جاده است که تابلو نصب شده.","en":"I must not park on this side of the road.","een":"Yes. The ban applies on the side of the road where the sign stands."}]},{"id":5127,"img":"newq-art/5127.png","c":"7.18","sda":"Du vil parkere på pladsen lige efter krydset, omkring 5 m efter den tværgående vej. Hvad gælder?","sfa":"می‌خواهید در جای خالی درست بعد از تقاطع، حدود ۵ متر بعد از جاده‌ی متقاطع، پارک کنید. چه قاعده‌ای برقرار است؟","sen":"You want to park in the space just after the junction, about 5 m past the crossing road. What applies?","st":[{"da":"Det er forbudt, fordi forbuddet gælder inden for 10 m fra den tværgående kørebanes kant, også efter krydset.","fa":"ممنوع است، چون این ممنوعیت تا ۱۰ متری لبه‌ی سواره‌روی متقاطع است، بعد از تقاطع هم.","ok":1,"eda":"Ja. Standsning og parkering er forbudt i vejkryds og inden for 10 m fra den tværgående kørebanes nærmeste kant.","efa":"بله. توقف و پارک در تقاطع و تا ۱۰ متری نزدیک‌ترین لبه‌ی سواره‌روی متقاطع ممنوع است.","en":"It is forbidden, because the ban applies within 10 m of the edge of the crossing carriageway, also after the junction.","een":"Yes. Stopping and parking are forbidden in a junction and within 10 m of the nearest edge of the crossing carriageway."},{"da":"Holdende biler tæt ved krydset kan tage oversigten fra dem, der svinger.","fa":"خودروهای ایستاده نزدیک تقاطع می‌توانند دید کسانی را که می‌پیچند بگیرند.","ok":1,"eda":"Ja. Derfor skal der være fri oversigt omkring krydset.","efa":"بله. به همین دلیل اطراف تقاطع باید دید آزاد باشد.","en":"Cars standing close to the junction can block the view of those turning.","een":"Yes. That is why there must be a clear view around the junction."},{"da":"Forbuddet gælder kun før krydset.","fa":"این ممنوعیت فقط پیش از تقاطع است.","ok":0,"eda":"Nej. Afstanden regnes fra den tværgående kørebane, så den gælder på begge sider af den.","efa":"خیر. فاصله از سواره‌روی متقاطع حساب می‌شود، پس در هر دو طرف آن برقرار است.","en":"The ban only applies before the junction.","een":"No. The distance is counted from the crossing carriageway, so it applies on both sides of it."},{"da":"Det er tilladt, fordi jeg holder i højre side.","fa":"مجاز است، چون در سمت راست می‌ایستم.","ok":0,"eda":"Nej. Den rigtige side gør ikke afstanden til krydset lovlig.","efa":"خیر. سمت درست، فاصله‌ی کم از تقاطع را مجاز نمی‌کند.","en":"It is allowed because I am standing on the right-hand side.","een":"No. The right side does not make the distance to the junction legal."}]},{"id":5128,"img":"newq-art/5128.png","c":"7.18","sda":"Du vil standse ved kanten af en smal vej. Mellem bilen og spærrelinjen midt på vejen vil der kun være 2 m. Hvad gælder?","sfa":"می‌خواهید کنار یک جاده‌ی باریک بایستید. بین خودرو و خط ممتد وسط جاده فقط ۲ متر فاصله خواهد بود. چه قاعده‌ای برقرار است؟","sen":"You want to stop at the edge of a narrow road. Between the car and the barrier line in the middle of the road there will only be 2 m. What applies?","st":[{"da":"Det er tilladt, hvis jeg tænder havariblinket.","fa":"اگر چراغ خطر را روشن کنم، مجاز است.","ok":0,"eda":"Nej. Havariblinket ændrer ikke på forbuddet.","efa":"خیر. چراغ خطر ممنوعیت را تغییر نمی‌دهد.","en":"It is allowed if I switch on the hazard lights.","een":"No. The hazard lights do not change the ban."},{"da":"Reglen gælder kun for lastbiler.","fa":"این قاعده فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Reglen gælder alle køretøjer.","efa":"خیر. این قاعده برای همه‌ی وسایل است.","en":"The rule only applies to lorries.","een":"No. The rule applies to all vehicles."},{"da":"Jeg må ikke standse her, fordi afstanden til spærrelinjen er under 3 m.","fa":"نباید این‌جا بایستم، چون فاصله تا خط ممتد کمتر از ۳ متر است.","ok":1,"eda":"Ja. Standsning og parkering er forbudt ved siden af en spærrelinje, hvis afstanden mellem køretøjet og linjen er mindre end 3 m.","efa":"بله. توقف و پارک کنار خط ممتد، اگر فاصله‌ی خودرو تا خط کمتر از ۳ متر باشد، ممنوع است.","en":"I must not stop here because the distance to the barrier line is under 3 m.","een":"Yes. Stopping and parking are forbidden beside a barrier line if the distance between the vehicle and the line is less than 3 m."}]},{"id":5129,"img":"newq-art/5129.png","c":"7.18","sda":"Du vil parkere, så du kommer til at holde lige foran en anden bil, der så ikke kan køre ud. Hvad gælder?","sfa":"می‌خواهید طوری پارک کنید که درست جلوی خودروی دیگری قرار بگیرید و آن خودرو نتواند بیرون برود. چه قاعده‌ای برقرار است؟","sen":"You want to park so that you will stand right in front of another car, which then cannot drive out. What applies?","st":[{"da":"Det er forbudt at parkere, så en anden bil ikke kan komme ud.","fa":"پارکی که خودروی دیگری را گیر بیندازد ممنوع است.","ok":1,"eda":"Ja. Parkering må ikke ske, så adgangen til et andet køretøj hindres, eller det ikke kan køre væk.","efa":"بله. پارک نباید راه دسترسی به وسیله‌ی دیگر را ببندد یا مانع حرکتش شود.","en":"It is forbidden to park so that another car cannot get out.","een":"Yes. Parking must not block access to another vehicle or stop it from being driven away."},{"da":"Det er tilladt, når jeg kun er væk i kort tid.","fa":"اگر فقط مدت کوتاهی دور باشم، مجاز است.","ok":0,"eda":"Nej. Også kort tid kan forhindre den anden i at køre.","efa":"خیر. حتی مدت کوتاه هم می‌تواند مانع رفتن دیگری شود.","en":"It is allowed when I am only gone for a short while.","een":"No. Even a short while can stop the other driver from leaving."},{"da":"Det er den andens problem, når jeg holder ved kanten.","fa":"اگر کنار لبه بایستم، مشکل خود اوست.","ok":0,"eda":"Nej. Forbuddet gælder, uanset hvor du holder.","efa":"خیر. این ممنوعیت هر جا بایستید برقرار است.","en":"It is the other driver's problem as long as I stand at the edge.","een":"No. The ban applies wherever you stand."}]},{"id":5130,"img":"newq-art/5130.png","c":"7.18","sda":"Du holder ved kantstenen og skal læsse tunge kasser ud. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و باید جعبه‌های سنگینی را خالی کنید. چه می‌کنید؟","sen":"You are standing at the kerb and need to unload heavy boxes. What do you do?","st":[{"da":"Jeg må stille kasserne på kørebanen, mens jeg bærer dem ind.","fa":"می‌توانم جعبه‌ها را تا بردنشان روی سواره‌رو بگذارم.","ok":0,"eda":"Nej. Kasser på kørebanen er en fare for trafikken.","efa":"خیر. جعبه روی سواره‌رو برای ترافیک خطرناک است.","en":"I may put the boxes on the carriageway while I carry them in.","een":"No. Boxes on the carriageway are a danger to traffic."},{"da":"Jeg holder øje med trafikken, mens jeg står ved bilen.","fa":"وقتی کنار خودرو ایستاده‌ام، مراقب ترافیک هستم.","ok":1,"eda":"Ja. Bilister og cyklister kører tæt forbi bilen.","efa":"بله. رانندگان و دوچرخه‌سواران از نزدیک خودرو رد می‌شوند.","en":"I keep an eye on the traffic while I am standing by the car.","een":"Yes. Drivers and cyclists pass close to the car."},{"da":"Jeg må lade førerdøren stå åben ud mod kørebanen, mens jeg læsser.","fa":"می‌توانم در راننده را رو به سواره‌رو باز بگذارم تا بار را خالی کنم.","ok":0,"eda":"Nej. En åben dør ud mod trafikken kan blive ramt og skabe fare.","efa":"خیر. در باز رو به ترافیک ممکن است ضربه بخورد و خطر ایجاد کند.","en":"I may leave the driver's door open towards the carriageway while I unload.","een":"No. An open door towards the traffic can be hit and cause danger."},{"da":"Jeg læsser ud, så der ikke opstår fare eller unødig ulempe for andre.","fa":"طوری بار را خالی می‌کنم که برای دیگران خطر یا مزاحمت بی‌جا پیش نیاید.","ok":1,"eda":"Ja. Åbning af døre og af- og pålæsning skal ske, så der ikke opstår fare eller unødig ulempe.","efa":"بله. باز کردن در و بار زدن یا خالی کردن نباید خطر یا مزاحمت بی‌جا ایجاد کند.","en":"I unload so that there is no danger or undue inconvenience to others.","een":"Yes. Opening doors and loading and unloading must not cause danger or undue inconvenience."}]},{"id":5131,"img":"newq-art/5131.png","c":"7.9","sda":"Du har grønt lys og kører i venstre af to vognbaner. Den langsomme varevogn i højre vognbane skal også ligeud. Hvad gælder for overhaling i krydset?","sfa":"چراغ شما سبز است و در خط چپ از دو خط می‌رانید. ون آهسته در خط راست هم مستقیم می‌رود. درباره‌ی سبقت در تقاطع چه قاعده‌ای برقرار است؟","sen":"You have a green light and are in the left of two lanes. The slow van in the right lane is also going straight on. What applies to overtaking at the junction?","st":[{"da":"Jeg må overhale, selv om mit lys skifter til gult lige før krydset.","fa":"حتی اگر چراغم درست پیش از تقاطع زرد شود، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Gult lys betyder stop, medmindre du er så tæt på, at en standsning vil skabe fare.","efa":"خیر. چراغ زرد یعنی ایست، مگر آن‌قدر نزدیک باشید که ایستادن خطرناک باشد.","en":"I may overtake even if my light changes to yellow just before the junction.","een":"No. Yellow means stop, unless you are so close that stopping would be dangerous."},{"da":"Jeg må overhale i krydset, fordi færdslen reguleres af lyssignal, hvis det kan ske uden fare.","fa":"می‌توانم در تقاطع سبقت بگیرم، چون ترافیک با چراغ کنترل می‌شود، به شرط آن‌که بی‌خطر باشد.","ok":1,"eda":"Ja. Forbuddet mod overhaling i kryds gælder ikke, hvor færdslen reguleres af lyssignal eller politi.","efa":"بله. ممنوعیت سبقت در تقاطع، جایی که ترافیک با چراغ یا پلیس کنترل می‌شود، اعمال نمی‌شود.","en":"I may overtake at the junction because the traffic is controlled by traffic lights, if it can be done safely.","een":"Yes. The ban on overtaking at junctions does not apply where traffic is controlled by traffic lights or police."},{"da":"Det er altid forbudt at overhale i et kryds.","fa":"سبقت در تقاطع همیشه ممنوع است.","ok":0,"eda":"Nej. Der er undtagelser, fx i kryds med lyssignal.","efa":"خیر. استثناهایی هست، مثلاً تقاطع چراغ‌دار.","en":"Overtaking at a junction is always forbidden.","een":"No. There are exceptions, for example at junctions with traffic lights."},{"da":"Jeg holder øje med fodgængere og cyklister, der kan krydse.","fa":"مراقب عابران و دوچرخه‌سوارانی هستم که ممکن است رد شوند.","ok":1,"eda":"Ja. Også med grønt lys skal du være opmærksom i krydset.","efa":"بله. حتی با چراغ سبز هم باید در تقاطع حواستان جمع باشد.","en":"I watch out for pedestrians and cyclists who may cross.","een":"Yes. Even with a green light you must be attentive at the junction."}]},{"id":5132,"img":"newq-art/5132.png","c":"7.9","sda":"Vejen svinger, og du kan ikke se, om der kommer modkørende. Lastbilen foran dig blinker til højre. Hvad gælder?","sfa":"جاده می‌پیچد و نمی‌بینید خودرویی از روبه‌رو می‌آید یا نه. کامیون جلوی شما راهنمای راست زده است. چه قاعده‌ای برقرار است؟","sen":"The road bends, and you cannot see whether anything is coming. The lorry in front of you is indicating right. What applies?","st":[{"da":"Jeg må overhale, hvis jeg tænder fjernlyset først.","fa":"اگر اول نور بالا را روشن کنم، می‌توانم سبقت بگیرم.","ok":0,"eda":"Nej. Lyset ændrer ikke på, at du ikke kan se de modkørende.","efa":"خیر. چراغ این واقعیت را تغییر نمی‌دهد که ترافیک روبه‌رو را نمی‌بینید.","en":"I may overtake if I switch on the high beam first.","een":"No. The lights do not change the fact that you cannot see oncoming traffic."},{"da":"Jeg må ikke overhale ved det uoverskuelige sving.","fa":"در این پیچ بی‌دید نباید سبقت بگیرم.","ok":1,"eda":"Ja. Overhaling er forbudt, hvor oversigten er begrænset, fx i uoverskuelige sving.","efa":"بله. سبقت جایی که دید محدود است، مثلاً در پیچ بی‌دید، ممنوع است.","en":"I must not overtake at the blind bend.","een":"Yes. Overtaking is forbidden where the view is limited, for example in blind bends."},{"da":"Jeg må overhale, fordi lastbilchaufføren viser, at vejen er fri.","fa":"می‌توانم سبقت بگیرم، چون راننده‌ی کامیون نشان می‌دهد راه باز است.","ok":0,"eda":"Nej. Du skal selv sikre dig, at overhalingen kan ske uden fare; et blink er ikke en garanti.","efa":"خیر. خودتان باید مطمئن شوید سبقت بی‌خطر است؛ چراغ راهنما تضمین نیست.","en":"I may overtake because the lorry driver is showing that the road is clear.","een":"No. You must make sure yourself that the overtaking is safe; an indicator is no guarantee."}]},{"id":5133,"img":"newq-art/5133.png","c":"7.9","sda":"Bilen foran dig kører 75 km/t, og grænsen er 80 km/t. Du overvejer at overhale. Hvad gælder?","sfa":"خودروی جلو ۷۵ کیلومتر بر ساعت می‌رود و حد سرعت ۸۰ است. به سبقت فکر می‌کنید. چه قاعده‌ای برقرار است؟","sen":"The car in front of you is doing 75 km/h, and the limit is 80 km/h. You are thinking of overtaking. What applies?","st":[{"da":"Jeg må ikke køre hurtigere end 80 km/t under overhalingen.","fa":"هنگام سبقت نباید تندتر از ۸۰ کیلومتر بر ساعت برانم.","ok":1,"eda":"Ja. Hastighedsgrænsen gælder også, mens du overhaler.","efa":"بله. حد سرعت هنگام سبقت هم برقرار است.","en":"I must not drive faster than 80 km/h during the overtaking.","een":"Yes. The speed limit also applies while you are overtaking."},{"da":"Det er tilladt at køre hurtigere end grænsen, når jeg overhaler.","fa":"هنگام سبقت مجازم از حد سرعت تندتر بروم.","ok":0,"eda":"Nej. Der er ingen undtagelse fra hastighedsgrænsen ved overhaling.","efa":"خیر. برای سبقت استثنایی از حد سرعت وجود ندارد.","en":"It is allowed to drive faster than the limit when I overtake.","een":"No. There is no exception from the speed limit for overtaking."},{"da":"Overhalingen vil tage lang tid, fordi forskellen i fart er lille.","fa":"سبقت طول می‌کشد، چون اختلاف سرعت کم است.","ok":1,"eda":"Ja. Jo mindre forskel, jo længere er du i den modkørende vognbane.","efa":"بله. هر چه اختلاف کمتر باشد، مدت بیشتری در خط مقابل می‌مانید.","en":"The overtaking will take a long time because the difference in speed is small.","een":"Yes. The smaller the difference, the longer you are in the oncoming lane."},{"da":"Det kan være bedre at blive bag bilen.","fa":"شاید بهتر باشد پشت آن خودرو بمانم.","ok":1,"eda":"Ja. En lang overhaling med lille fartforskel giver meget lidt og øger risikoen.","efa":"بله. سبقت طولانی با اختلاف سرعت کم سود کمی دارد و خطر را بیشتر می‌کند.","en":"It may be better to stay behind the car.","een":"Yes. A long overtaking with little difference in speed gains very little and increases the risk."}]},{"id":5134,"img":"newq-art/5134.png","c":"7.9","sda":"En bil er i gang med at overhale dig, og der kommer en lastbil imod den. Hvordan forholder du dig?","sfa":"خودرویی در حال سبقت از شماست و کامیونی از روبه‌رو به سمتش می‌آید. چه می‌کنید؟","sen":"A car is overtaking you, and a lorry is coming towards it. What do you do?","st":[{"da":"Jeg øger farten, så den overhalende må opgive og trække ind bag mig.","fa":"سرعتم را زیاد می‌کنم تا سبقت‌گیرنده منصرف شود و پشت سرم برگردد.","ok":0,"eda":"Nej. Den, der bliver overhalet, må ikke øge hastigheden.","efa":"خیر. کسی که از او سبقت می‌گیرند نباید سرعتش را زیاد کند.","en":"I speed up so that the overtaking car has to give up and pull in behind me.","een":"No. The driver being overtaken must not increase speed."},{"da":"Jeg sænker farten, så den overhalende hurtigt kan komme ind foran mig.","fa":"سرعتم را کم می‌کنم تا سبقت‌گیرنده زود جلوی من برگردد.","ok":1,"eda":"Ja. Du kan hjælpe med at undgå en farlig situation ved at give plads.","efa":"بله. با جا دادن می‌توانید از یک موقعیت خطرناک جلوگیری کنید.","en":"I slow down so that the overtaking car can quickly pull in in front of me.","een":"Yes. You can help avoid a dangerous situation by making room."},{"da":"Jeg er klar til at bremse, hvis det bliver nødvendigt.","fa":"اگر لازم شد، آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Situationen kan ændre sig hurtigt.","efa":"بله. این موقعیت ممکن است سریع تغییر کند.","en":"I am ready to brake if it becomes necessary.","een":"Yes. The situation can change quickly."},{"da":"Jeg holder så langt til højre som muligt.","fa":"تا جای ممکن سمت راست می‌مانم.","ok":1,"eda":"Ja. Den, der bliver overhalet, skal holde så langt til højre som muligt.","efa":"بله. کسی که از او سبقت می‌گیرند باید تا جای ممکن سمت راست بماند.","en":"I keep as far to the right as possible.","een":"Yes. The driver being overtaken must keep as far to the right as possible."}]},{"id":5135,"img":"newq-art/5135.png","c":"7.9","sda":"Du holder i kø. En cyklist kører op langs højre side af din bil. Hvad gælder?","sfa":"در صف ایستاده‌اید. دوچرخه‌سواری از سمت راست خودرو جلو می‌آید. چه قاعده‌ای برقرار است؟","sen":"You are standing in a queue. A cyclist is riding up along the right side of your car. What applies?","st":[{"da":"Jeg kører tæt ind mod kantstenen, så cyklisten ikke kan komme forbi.","fa":"به جدول نزدیک می‌شوم تا دوچرخه‌سوار نتواند رد شود.","ok":0,"eda":"Nej. Du må ikke spærre for cyklisten; det kan skabe fare.","efa":"خیر. نباید راه دوچرخه‌سوار را ببندید؛ ممکن است خطرناک باشد.","en":"I move close to the kerb so that the cyclist cannot get past.","een":"No. You must not block the cyclist; it can be dangerous."},{"da":"Jeg ser efter cyklister i højre side, før jeg svinger til højre.","fa":"پیش از گردش به راست، دوچرخه‌سواران سمت راست را نگاه می‌کنم.","ok":1,"eda":"Ja. En cyklist kan være i din blinde vinkel i højre side.","efa":"بله. دوچرخه‌سوار ممکن است در نقطه‌ی کور سمت راستتان باشد.","en":"I look for cyclists on the right before I turn right.","een":"Yes. A cyclist may be in your blind spot on the right."},{"da":"Cyklister må overhale biler i højre side.","fa":"دوچرخه‌سواران می‌توانند از سمت راست از خودروها سبقت بگیرند.","ok":1,"eda":"Ja. Cyklister og førere af lille knallert kan overhale andre køretøjer til højre.","efa":"بله. دوچرخه‌سواران و موپدسواران کوچک می‌توانند از سمت راست از وسایل دیگر سبقت بگیرند.","en":"Cyclists may overtake cars on the right.","een":"Yes. Cyclists and riders of small mopeds may overtake other vehicles on the right."},{"da":"Cyklisten gør noget ulovligt.","fa":"دوچرخه‌سوار کار غیرقانونی می‌کند.","ok":0,"eda":"Nej. Cyklister må gerne overhale biler i højre side.","efa":"خیر. دوچرخه‌سواران اجازه دارند از سمت راست از خودروها سبقت بگیرند.","en":"The cyclist is doing something illegal.","een":"No. Cyclists may well overtake cars on the right."}]},{"id":5136,"img":"newq-art/5136.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den, og hvordan forholder du dig?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه و چه می‌کنید؟","sen":"You pass this sign. What does it mean, and what do you do?","st":[{"da":"Der er særlig fare, fordi cyklister kan køre ind på eller over kørebanen.","fa":"خطر ویژه‌ای هست، چون ممکن است دوچرخه‌سواران وارد سواره‌رو شوند یا از عرض آن رد شوند.","ok":1,"eda":"Ja. Tavlen (A 21) advarer om steder, hvor cyklister og førere af lille knallert kører ind på eller over kørebanen.","efa":"بله. این تابلو (A 21) درباره‌ی جاهایی هشدار می‌دهد که دوچرخه‌سواران و موپدسواران کوچک وارد سواره‌رو می‌شوند یا از آن رد می‌شوند.","en":"There is a special danger because cyclists may ride onto or across the carriageway.","een":"Yes. The sign (A 21) warns of places where cyclists and riders of small mopeds ride onto or across the carriageway."},{"da":"Tavlen betyder, at der er cykelsti langs hele vejen.","fa":"این تابلو یعنی در تمام طول جاده مسیر دوچرخه هست.","ok":0,"eda":"Nej. Det er en advarsel om en særlig fare, ikke en oplysning om cykelsti.","efa":"خیر. این هشدار خطر ویژه است، نه اطلاع درباره‌ی مسیر دوچرخه.","en":"The sign means that there is a cycle path all along the road.","een":"No. It is a warning of a special danger, not information about a cycle path."},{"da":"Jeg sænker farten og holder øje med cyklisterne.","fa":"سرعتم را کم می‌کنم و مراقب دوچرخه‌سواران هستم.","ok":1,"eda":"Ja. Ved en advarselstavle skal du være klar til at reagere.","efa":"بله. کنار تابلوی هشدار باید آماده‌ی واکنش باشید.","en":"I slow down and watch the cyclists.","een":"Yes. At a warning sign you must be ready to react."},{"da":"Tavlen betyder, at cyklisterne skal holde tilbage for mig.","fa":"این تابلو یعنی دوچرخه‌سواران باید به من راه بدهند.","ok":0,"eda":"Nej. En advarselstavle siger ikke noget om vigepligt.","efa":"خیر. تابلوی هشدار چیزی درباره‌ی حق تقدم نمی‌گوید.","en":"The sign means that the cyclists must give way to me.","een":"No. A warning sign says nothing about who gives way."}]},{"id":5137,"img":"newq-art/5137.png","c":"6.1","sda":"Du kører forbi denne tavle i skumringen. Hvordan forholder du dig?","sfa":"هنگام غروب از کنار این تابلو رد می‌شوید. چه می‌کنید؟","sen":"You pass this sign at dusk. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Med lavere fart kan du nå at standse, hvis et dyr springer frem.","efa":"بله. با سرعت کمتر، اگر حیوانی بیرون بپرد، به موقع می‌ایستید.","en":"I slow down and am ready to brake.","een":"Yes. At a lower speed you can stop in time if an animal jumps out."},{"da":"Kommer der ét dyr over vejen, kan der komme flere.","fa":"اگر یک حیوان از جاده رد شود، ممکن است بقیه هم بیایند.","ok":1,"eda":"Ja. Hjorte og rådyr går ofte i flok.","efa":"بله. آهوها و گوزن‌ها اغلب گروهی حرکت می‌کنند.","en":"If one animal crosses the road, more may follow.","een":"Yes. Deer often move in groups."},{"da":"Jeg regner med, at der pludselig kan komme dyr ud på vejen.","fa":"انتظار دارم ناگهان حیوانی وارد جاده شود.","ok":1,"eda":"Ja. Tavlen (A 26) advarer om vildt; i skumringen er dyrene særligt aktive.","efa":"بله. این تابلو (A 26) درباره‌ی حیوانات وحشی هشدار می‌دهد؛ هنگام غروب این حیوانات فعال‌ترند.","en":"I expect that animals may suddenly come out onto the road.","een":"Yes. The sign (A 26) warns of wild animals; at dusk they are especially active."},{"da":"Tavlen gælder kun om dagen.","fa":"این تابلو فقط روزها معتبر است.","ok":0,"eda":"Nej. Tavlen gælder hele døgnet, og faren er ofte størst i skumring og mørke.","efa":"خیر. این تابلو در تمام شبانه‌روز معتبر است و خطر اغلب در غروب و تاریکی بیشتر است.","en":"The sign only applies in the daytime.","een":"No. The sign applies day and night, and the danger is often greatest at dusk and in the dark."}]},{"id":5138,"img":"newq-art/5138.png","c":"6.1","sda":"Du kører forbi denne tavle. Hvad betyder den?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه؟","sen":"You pass this sign. What does it mean?","st":[{"da":"Påbuddet ophører ved næste kryds.","fa":"این دستور در تقاطع بعدی تمام می‌شود.","ok":0,"eda":"Nej. Det gælder, indtil det ophæves af tavlen for ophør af mindste hastighed eller en afstand på en undertavle.","efa":"خیر. تا وقتی تابلوی پایان حداقل سرعت یا فاصله‌ی روی تابلوی زیرین آن را لغو کند، برقرار است.","en":"The order ends at the next junction.","een":"No. It applies until it is lifted by the end-of-minimum-speed sign or a distance on a plate."},{"da":"Tavlen angiver den højst tilladte hastighed.","fa":"این تابلو حداکثر سرعت مجاز را نشان می‌دهد.","ok":0,"eda":"Nej. Den højst tilladte hastighed vises på en hvid tavle med rød kant.","efa":"خیر. حداکثر سرعت روی تابلوی سفید با حاشیه‌ی قرمز نشان داده می‌شود.","en":"The sign gives the highest permitted speed.","een":"No. The highest permitted speed is shown on a white sign with a red border."},{"da":"Påbuddet gælder ikke cyklister og førere af lille knallert.","fa":"این دستور برای دوچرخه‌سواران و موپدسواران کوچک نیست.","ok":1,"eda":"Ja. Mindste hastighed gælder kørende bortset fra cyklister og førere af lille knallert.","efa":"بله. حداقل سرعت برای همه به‌جز دوچرخه‌سواران و موپدسواران کوچک است.","en":"The order does not apply to cyclists and riders of small mopeds.","een":"Yes. The minimum speed applies to drivers other than cyclists and riders of small mopeds."},{"da":"Tavlen angiver en mindste hastighed for strækningen.","fa":"این تابلو حداقل سرعت این مسیر را نشان می‌دهد.","ok":1,"eda":"Ja. Den blå runde tavle med et tal (D 55) er et påbud om mindste hastighed.","efa":"بله. تابلوی گرد آبی با عدد (D 55) دستور حداقل سرعت است.","en":"The sign gives a minimum speed for the stretch.","een":"Yes. The round blue sign with a number (D 55) is an order to keep a minimum speed."}]},{"id":5139,"img":"newq-art/5139.png","c":"6.1","sda":"Du kører en varevogn med last på taget; den samlede højde er 3,7 m. Foran viadukten står denne tavle. Hvad gælder?","sfa":"با یک ون که روی سقفش بار دارد می‌رانید؛ ارتفاع کل ۳٫۷ متر است. پیش از پل این تابلو هست. چه قاعده‌ای برقرار است؟","sen":"You are driving a van with a load on the roof; the total height is 3.7 m. This sign stands before the viaduct. What applies?","st":[{"da":"Jeg må køre igennem, hvis jeg kører meget langsomt.","fa":"اگر خیلی آهسته بروم، می‌توانم رد شوم.","ok":0,"eda":"Nej. Lav fart gør ikke køretøjet lavere.","efa":"خیر. سرعت کم وسیله را کوتاه‌تر نمی‌کند.","en":"I may drive through if I go very slowly.","een":"No. Low speed does not make the vehicle lower."},{"da":"Tavlen gælder kun for lastbiler.","fa":"این تابلو فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Tavlen gælder alle køretøjer, der er højere end angivet.","efa":"خیر. این تابلو برای هر وسیله‌ای است که بلندتر از عدد نشان‌داده باشد.","en":"The sign only applies to lorries.","een":"No. The sign applies to every vehicle that is higher than shown."},{"da":"Jeg må ikke køre under viadukten, fordi højden med last er over 3,5 m.","fa":"نباید از زیر پل رد شوم، چون ارتفاع با بار بیش از ۳٫۵ متر است.","ok":1,"eda":"Ja. Tavlen (C 42) forbyder kørsel med køretøjer, hvis højde inklusive læs er større end den angivne.","efa":"بله. این تابلو (C 42) عبور وسایلی را که ارتفاعشان با بار بیش از عدد نشان‌داده است، ممنوع می‌کند.","en":"I must not drive under the viaduct because the height with the load is over 3.5 m.","een":"Yes. The sign (C 42) forbids driving with vehicles whose height including the load is greater than the one shown."},{"da":"Tavlen gælder kun bilens egen højde uden last.","fa":"این تابلو فقط برای ارتفاع خود خودرو بدون بار است.","ok":0,"eda":"Nej. Højden regnes inklusive læs.","efa":"خیر. ارتفاع با احتساب بار حساب می‌شود.","en":"The sign only applies to the car's own height without the load.","een":"No. The height is counted including the load."}]},{"id":5140,"img":"newq-art/5140.png","c":"7.6","sda":"En ældre mand går langsomt over vejen et stykke fra et fodgængerfelt. Hvordan forholder du dig?","sfa":"مرد مسنی دور از گذرگاه عابر آهسته از عرض خیابان رد می‌شود. چه می‌کنید؟","sen":"An elderly man is slowly crossing the road some way from a pedestrian crossing. What do you do?","st":[{"da":"Jeg dytter, så han skynder sig.","fa":"بوق می‌زنم تا عجله کند.","ok":0,"eda":"Nej. Hornet kan forskrække ham, så han falder eller standser midt på vejen.","efa":"خیر. بوق ممکن است او را بترساند تا بیفتد یا وسط خیابان بایستد.","en":"I sound the horn so that he hurries.","een":"No. The horn may startle him so that he falls or stops in the middle of the road."},{"da":"Ældre kan have svært ved at bedømme bilernes fart.","fa":"سالمندان ممکن است سرعت خودروها را به‌سختی بسنجند.","ok":1,"eda":"Ja. De kan også bevæge sig langsommere end ventet.","efa":"بله. ممکن است آهسته‌تر از انتظار هم حرکت کنند.","en":"Elderly people may find it hard to judge the speed of cars.","een":"Yes. They may also move more slowly than expected."},{"da":"Han skal vente, fordi han ikke går i et fodgængerfelt.","fa":"او باید صبر کند، چون از گذرگاه عابر رد نمی‌شود.","ok":0,"eda":"Nej. Også uden for et fodgængerfelt skal du undgå at bringe gående i fare.","efa":"خیر. حتی بیرون از گذرگاه عابر هم نباید عابران را به خطر بیندازید.","en":"He has to wait because he is not on a pedestrian crossing.","een":"No. Even outside a pedestrian crossing you must avoid putting pedestrians in danger."},{"da":"Jeg sænker farten og lader ham komme over.","fa":"سرعتم را کم می‌کنم و می‌گذارم رد شود.","ok":1,"eda":"Ja. Du skal vise særligt hensyn over for ældre og give gående tid og plads.","efa":"بله. باید به سالمندان ملاحظه‌ی ویژه نشان دهید و به عابران وقت و جا بدهید.","en":"I slow down and let him get across.","een":"Yes. You must show special consideration for the elderly and give pedestrians time and room."}]},{"id":5141,"img":"newq-art/5141.png","c":"7.6","sda":"Du kører forbi en række parkerede biler. I en af dem sidder føreren og ser ud til at ville stige ud. Hvordan forholder du dig?","sfa":"از کنار ردیفی از خودروهای پارک‌شده رد می‌شوید. راننده‌ی یکی از آن‌ها نشسته و به نظر می‌رسد می‌خواهد پیاده شود. چه می‌کنید؟","sen":"You are passing a row of parked cars. In one of them the driver is sitting and seems about to get out. What do you do?","st":[{"da":"Jeg sænker farten og er klar til at bremse.","fa":"سرعتم را کم می‌کنم و آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Så kan du standse, hvis døren åbnes, eller føreren træder ud.","efa":"بله. این‌طور اگر در باز شد یا راننده بیرون آمد، می‌توانید بایستید.","en":"I slow down and am ready to brake.","een":"Yes. Then you can stop if the door opens or the driver steps out."},{"da":"Føreren skal se sig for, så jeg behøver ikke gøre noget.","fa":"راننده باید خودش نگاه کند، پس لازم نیست کاری بکنم.","ok":0,"eda":"Nej. Du skal selv være forberedt på, at andre laver fejl.","efa":"خیر. خودتان باید برای اشتباه دیگران آماده باشید.","en":"The driver must look out, so I need not do anything.","een":"No. You must be prepared yourself for others to make mistakes."},{"da":"Jeg kigger efter folk i de parkerede biler.","fa":"به دنبال آدم‌هایی در خودروهای پارک‌شده نگاه می‌کنم.","ok":1,"eda":"Ja. En person i en parkeret bil kan være på vej ud.","efa":"بله. کسی که در خودروی پارک‌شده نشسته، ممکن است در حال پیاده شدن باشد.","en":"I look for people in the parked cars.","een":"Yes. A person in a parked car may be about to get out."},{"da":"Jeg holder god afstand til siden, så jeg ikke rammer en dør, der åbnes.","fa":"از پهلو فاصله‌ی خوبی نگه می‌دارم تا به دری که باز می‌شود نخورم.","ok":1,"eda":"Ja. En dør kan pludselig blive åbnet ud mod kørebanen.","efa":"بله. ممکن است دری ناگهان رو به سواره‌رو باز شود.","en":"I keep a good distance to the side so that I do not hit a door that opens.","een":"Yes. A door may suddenly be opened out into the carriageway."}]},{"id":5142,"img":"newq-art/5142.png","c":"7.6","sda":"En isbil holder ved vejen, og der er børn omkring den. Hvordan forholder du dig?","sfa":"ماشین بستنی‌فروشی کنار خیابان ایستاده و بچه‌ها دورش هستند. چه می‌کنید؟","sen":"An ice-cream van has stopped by the road, and there are children around it. What do you do?","st":[{"da":"Jeg holder øje med begge sider af vejen.","fa":"مراقب هر دو طرف خیابان هستم.","ok":1,"eda":"Ja. Børn kan komme løbende fra den anden side.","efa":"بله. ممکن است بچه‌ها از طرف دیگر بدوند.","en":"I watch both sides of the road.","een":"Yes. Children may come running from the other side."},{"da":"Jeg dytter, så børnene holder sig på fortovet.","fa":"بوق می‌زنم تا بچه‌ها در پیاده‌رو بمانند.","ok":0,"eda":"Nej. Hornet kan få et barn til at gøre noget uventet; sænk i stedet farten.","efa":"خیر. بوق ممکن است کودک را به کار غیرمنتظره‌ای وادارد؛ به‌جایش سرعت را کم کنید.","en":"I sound the horn so that the children stay on the pavement.","een":"No. The horn can make a child do something unexpected; slow down instead."},{"da":"Jeg sænker farten kraftigt og er klar til at standse.","fa":"سرعتم را خیلی کم می‌کنم و آماده‌ی ایستادنم.","ok":1,"eda":"Ja. Når du nærmer dig børn på eller ved vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به بچه‌هایی روی جاده یا کنار آن نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down a lot and am ready to stop.","een":"Yes. When you approach children on or by the road, your speed must be suitably low."},{"da":"Børn kan løbe over vejen uden at se sig for.","fa":"بچه‌ها ممکن است بی‌آنکه نگاه کنند از خیابان رد شوند.","ok":1,"eda":"Ja. Børn tænker på isen og ikke på trafikken.","efa":"بله. بچه‌ها به بستنی فکر می‌کنند، نه به ترافیک.","en":"Children may run across the road without looking.","een":"Yes. Children think about the ice cream, not about the traffic."}]},{"id":5143,"img":"newq-art/5143.png","c":"7.6","sda":"En bil holder i din vognbane med havariblinket tændt. Hvordan forholder du dig?","sfa":"خودرویی با چراغ خطر روشن در خط شما ایستاده است. چه می‌کنید؟","sen":"A car is standing in your lane with its hazard lights on. What do you do?","st":[{"da":"Havariblinket betyder, at bilen snart kører igen, så jeg venter tæt bag den.","fa":"چراغ خطر یعنی خودرو به‌زودی راه می‌افتد، پس نزدیک پشتش صبر می‌کنم.","ok":0,"eda":"Nej. Havariblink er en advarsel; hold god afstand.","efa":"خیر. چراغ خطر هشدار است؛ فاصله‌ی خوبی نگه دارید.","en":"The hazard lights mean that the car will soon drive on, so I wait close behind it.","een":"No. Hazard lights are a warning; keep a good distance."},{"da":"Jeg sænker farten og kører forbi med god afstand, når det kan ske uden fare.","fa":"سرعتم را کم می‌کنم و وقتی بی‌خطر باشد، با فاصله‌ی خوب رد می‌شوم.","ok":1,"eda":"Ja. Havariblinket advarer om fare; der kan være folk ved bilen.","efa":"بله. چراغ خطر از خطر خبر می‌دهد؛ ممکن است کسی کنار خودرو باشد.","en":"I slow down and pass with a good distance when it can be done safely.","een":"Yes. Hazard lights warn of danger; there may be people by the car."},{"da":"Jeg dytter, så bilen flytter sig.","fa":"بوق می‌زنم تا خودرو جابه‌جا شود.","ok":0,"eda":"Nej. Bilen holder sandsynligvis på grund af et problem; dyt hjælper ikke.","efa":"خیر. خودرو احتمالاً به‌خاطر مشکلی ایستاده؛ بوق کمکی نمی‌کند.","en":"I sound the horn so that the car moves.","een":"No. The car is probably standing because of a problem; the horn does not help."},{"da":"Jeg kører forbi med det samme, selv om der kommer en modkørende.","fa":"فوراً رد می‌شوم، حتی اگر خودرویی از روبه‌رو بیاید.","ok":0,"eda":"Nej. Hindringen er i din side, så du skal om nødvendigt standse og lade den modkørende passere.","efa":"خیر. مانع در سمت شماست، پس در صورت لزوم باید بایستید و بگذارید خودروی روبه‌رو رد شود.","en":"I drive past straight away, even though a car is coming the other way.","een":"No. The obstacle is on your side, so you must stop if necessary and let the oncoming car pass."}]},{"id":5144,"img":"newq-art/5144.png","c":"7.12","sda":"Lyset skifter til gult, mens du er 40 m fra krydset og roligt kan standse. Hvordan forholder du dig?","sfa":"چراغ زرد می‌شود، وقتی ۴۰ متر با تقاطع فاصله دارید و می‌توانید آرام بایستید. چه می‌کنید؟","sen":"The light changes to yellow while you are 40 m from the junction and can stop calmly. What do you do?","st":[{"da":"Jeg standser før stoplinjen.","fa":"پیش از خط ایست می‌ایستم.","ok":1,"eda":"Ja. Gult lys betyder stop.","efa":"بله. چراغ زرد یعنی ایست.","en":"I stop before the stop line.","een":"Yes. Yellow means stop."},{"da":"Gult lys gælder kun fodgængere.","fa":"چراغ زرد فقط برای عابران است.","ok":0,"eda":"Nej. Lyssignalet gælder de kørende.","efa":"خیر. این چراغ برای رانندگان است.","en":"Yellow only applies to pedestrians.","een":"No. The traffic light applies to drivers."},{"da":"Gult lys betyder, at jeg skal skynde mig over.","fa":"چراغ زرد یعنی باید عجله کنم و رد شوم.","ok":0,"eda":"Nej. Gult lys betyder stop, ikke kør hurtigere.","efa":"خیر. زرد یعنی ایست، نه تندتر رفتن.","en":"Yellow means that I must hurry across.","een":"No. Yellow means stop, not drive faster."},{"da":"Jeg må kun køre videre, hvis jeg er så tæt på, at en standsning vil skabe fare.","fa":"فقط وقتی می‌توانم ادامه دهم که آن‌قدر نزدیک باشم که ایستادن خطرناک باشد.","ok":1,"eda":"Ja. Den, der er nået så langt frem, at standsning vil medføre fare, behøver ikke standse.","efa":"بله. کسی که آن‌قدر جلو آمده که ایستادن خطر ایجاد کند، لازم نیست بایستد.","en":"I may only drive on if I am so close that stopping would be dangerous.","een":"Yes. Whoever has come so far that stopping would cause danger need not stop."}]},{"id":5145,"img":"newq-art/5145.png","c":"7.12","sda":"Du holder ved stoplinjen, og dit lyssignal viser rødt og gult på samme tid. Hvordan forholder du dig?","sfa":"پشت خط ایست ایستاده‌اید و چراغ شما هم‌زمان قرمز و زرد را نشان می‌دهد. چه می‌کنید؟","sen":"You are waiting at the stop line, and your traffic light shows red and yellow at the same time. What do you do?","st":[{"da":"Jeg holder stille, til lyset bliver grønt.","fa":"تا سبز شدن چراغ می‌ایستم.","ok":1,"eda":"Ja. Rødt og gult lys samtidig betyder stop; det viser, at lyset snart skifter til grønt.","efa":"بله. قرمز و زرد با هم یعنی ایست؛ نشان می‌دهد چراغ به‌زودی سبز می‌شود.","en":"I stay where I am until the light turns green.","een":"Yes. Red and yellow together mean stop; they show that the light will soon change to green."},{"da":"Jeg må køre lidt frem over stoplinjen og vente der.","fa":"می‌توانم کمی از خط ایست جلوتر بروم و آن‌جا صبر کنم.","ok":0,"eda":"Nej. Du skal holde før stoplinjen.","efa":"خیر. باید پیش از خط ایست بایستید.","en":"I may move a little forward over the stop line and wait there.","een":"No. You must wait before the stop line."},{"da":"Jeg må køre, fordi lyset snart bliver grønt.","fa":"می‌توانم حرکت کنم، چون چراغ به‌زودی سبز می‌شود.","ok":0,"eda":"Nej. Du må først køre, når lyset er grønt.","efa":"خیر. فقط وقتی چراغ سبز شد می‌توانید حرکت کنید.","en":"I may go because the light will soon turn green.","een":"No. You may only go when the light is green."},{"da":"Rødt og gult betyder, at jeg må køre, hvis vejen er fri.","fa":"قرمز و زرد یعنی اگر راه باز باشد می‌توانم بروم.","ok":0,"eda":"Nej. Rødt og gult betyder stop, uanset trafikken.","efa":"خیر. قرمز و زرد یعنی ایست، ترافیک هر چه باشد.","en":"Red and yellow mean that I may go if the road is clear.","een":"No. Red and yellow mean stop whatever the traffic."}]},{"id":5146,"img":"newq-art/5146.png","c":"7.12","sda":"Du kommer ad en markvej og skal ud på landevejen. Der er ingen tavler. Hvad gælder?","sfa":"از یک راه خاکی میان مزرعه می‌آیید و می‌خواهید وارد جاده‌ی اصلی شوید. تابلویی نیست. چه قاعده‌ای برقرار است؟","sen":"You are coming along a field road and are going to drive onto the country road. There are no signs. What applies?","st":[{"da":"Traktoren fra venstre skal holde tilbage for mig.","fa":"تراکتوری که از چپ می‌آید باید به من راه بدهد.","ok":0,"eda":"Nej. Du skal holde tilbage for både bilen og traktoren.","efa":"خیر. باید هم به خودرو و هم به تراکتور راه بدهید.","en":"The tractor from the left must give way to me.","een":"No. You must give way to both the car and the tractor."},{"da":"Højrereglen gælder, fordi der ikke er tavler.","fa":"قاعده‌ی دست راست برقرار است، چون تابلویی نیست.","ok":0,"eda":"Nej. Højrereglen gælder ikke for den, der kommer fra en markvej.","efa":"خیر. قاعده‌ی دست راست برای کسی که از راه خاکی مزرعه می‌آید اعمال نمی‌شود.","en":"The right-hand rule applies because there are no signs.","een":"No. The right-hand rule does not apply to someone coming from a field road."},{"da":"Jeg har ubetinget vigepligt for trafikken på landevejen fra begge sider.","fa":"باید بی‌قیدوشرط به ترافیک جاده از هر دو طرف راه بدهم.","ok":1,"eda":"Ja. Kørende ud fra en markvej har ubetinget vigepligt.","efa":"بله. کسی که از راه خاکی مزرعه بیرون می‌آید، باید بی‌قیدوشرط راه بدهد.","en":"I must give way unconditionally to the traffic on the country road from both sides.","een":"Yes. Drivers coming out of a field road must give way unconditionally."}]},{"id":5147,"img":"newq-art/5147.png","c":"7.12","sda":"I krydset uden tavler kommer en cyklist fra højre og en bil fra venstre. Alle skal ligeud. Hvad gælder?","sfa":"در تقاطع بدون تابلو، دوچرخه‌سواری از راست و خودرویی از چپ می‌آید. همه مستقیم می‌روند. چه قاعده‌ای برقرار است؟","sen":"At the junction with no signs a cyclist is coming from the right and a car from the left. Everyone is going straight on. What applies?","st":[{"da":"Bilen fra venstre skal holde tilbage for mig.","fa":"خودروی سمت چپ باید به من راه بدهد.","ok":1,"eda":"Ja. For bilen fra venstre kommer du fra højre.","efa":"بله. برای خودروی سمت چپ، شما از سمت راست می‌آیید.","en":"The car from the left must give way to me.","een":"Yes. For the car from the left, you are coming from the right."},{"da":"Jeg holder tilbage for cyklisten fra højre.","fa":"به دوچرخه‌سوار سمت راست راه می‌دهم.","ok":1,"eda":"Ja. Højrereglen gælder også over for cyklister.","efa":"بله. قاعده‌ی دست راست برای دوچرخه‌سواران هم برقرار است.","en":"I give way to the cyclist from the right.","een":"Yes. The right-hand rule also applies to cyclists."},{"da":"Cyklister skal altid holde tilbage for biler.","fa":"دوچرخه‌سواران همیشه باید به خودروها راه بدهند.","ok":0,"eda":"Nej. Der er ingen regel om, at cyklister altid skal holde tilbage.","efa":"خیر. قاعده‌ای نیست که دوچرخه‌سوار همیشه راه بدهد.","en":"Cyclists must always give way to cars.","een":"No. There is no rule that cyclists must always give way."},{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ingen forkørselsret.","efa":"خیر. مستقیم رفتن حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on gives no right of way."}]},{"id":5148,"img":"newq-art/5148.png","c":"7.7","sda":"En varevogn holder parkeret i den modkørendes side. En modkørende bil skal forbi den. Hvad gælder?","sfa":"ونی در سمت ترافیک روبه‌رو پارک شده است. خودرویی از روبه‌رو باید از کنارش رد شود. چه قاعده‌ای برقرار است؟","sen":"A van is parked on the oncoming side. An oncoming car has to get past it. What applies?","st":[{"da":"Den modkørende skal om nødvendigt standse og lade mig passere.","fa":"راننده‌ی روبه‌رو در صورت لزوم باید بایستد و بگذارد من رد شوم.","ok":1,"eda":"Ja. Er vejen delvis spærret, skal den, i hvis side spærringen er, om nødvendigt standse og lade de mødende passere.","efa":"بله. اگر جاده تا حدی بسته باشد، کسی که مانع در سمت اوست باید در صورت لزوم بایستد و بگذارد مقابلش رد شود.","en":"The oncoming driver must stop if necessary and let me pass.","een":"Yes. If the road is partly blocked, the driver on whose side the obstruction is must stop if necessary and let oncoming traffic pass."},{"da":"Jeg skal standse og lade den modkørende komme forbi varevognen først.","fa":"باید بایستم و بگذارم خودروی روبه‌رو اول از کنار ون رد شود.","ok":0,"eda":"Nej. Hindringen er i den modkørendes side; du har ikke pligt til at standse.","efa":"خیر. مانع در سمت مقابل است؛ شما موظف به ایستادن نیستید.","en":"I must stop and let the oncoming car get past the van first.","een":"No. The obstacle is on the oncoming side; you are not obliged to stop."},{"da":"Den, der blinker først med lyset, har forkørselsret.","fa":"هر که اول چراغ بزند، حق تقدم دارد.","ok":0,"eda":"Nej. Lyssignaler giver ingen forkørselsret.","efa":"خیر. چراغ زدن حق تقدم نمی‌دهد.","en":"Whoever flashes their lights first has the right of way.","een":"No. Flashing lights gives no right of way."},{"da":"Jeg holder alligevel øje med, om den modkørende kører ud foran mig.","fa":"با این حال مراقبم که خودروی روبه‌رو جلوی من بیرون نیاید.","ok":1,"eda":"Ja. Du skal altid være klar til, at andre ikke overholder reglerne.","efa":"بله. همیشه باید آماده باشید که دیگران قوانین را رعایت نکنند.","en":"I still watch whether the oncoming driver pulls out in front of me.","een":"Yes. You must always be ready for others not keeping the rules."}]},{"id":5149,"img":"newq-art/5149.png","c":"7.7","sda":"Du kører med fjernlys i mørke, og en cyklist med lygte kommer imod dig. Hvordan forholder du dig?","sfa":"در تاریکی با نور بالا می‌رانید و دوچرخه‌سواری با چراغ از روبه‌رو می‌آید. چه می‌کنید؟","sen":"You are driving with high beam in the dark, and a cyclist with a light is coming towards you. What do you do?","st":[{"da":"Jeg tilpasser farten til det kortere udsyn med nærlys.","fa":"سرعتم را با دید کوتاه‌تر نور پایین هماهنگ می‌کنم.","ok":1,"eda":"Ja. Farten skal tilpasses de nye sigtforhold, før du blænder ned.","efa":"بله. پیش از رفتن به نور پایین باید سرعت را با دید تازه هماهنگ کنید.","en":"I adjust my speed to the shorter view with dipped beam.","een":"Yes. Your speed must be adjusted to the new visibility before you dip."},{"da":"Jeg skifter til nærlys, så cyklisten ikke bliver blændet.","fa":"به نور پایین می‌روم تا دوچرخه‌سوار خیره نشود.","ok":1,"eda":"Ja. Fjernlys må ikke bruges ved møde med andet køretøj i en afstand, hvor føreren kan blændes; en cykel er også et køretøj.","efa":"بله. هنگام برخورد با وسیله‌ی دیگری در فاصله‌ای که راننده‌اش خیره شود، نور بالا ممنوع است؛ دوچرخه هم وسیله‌ی نقلیه است.","en":"I switch to dipped beam so that the cyclist is not dazzled.","een":"Yes. High beam must not be used when meeting another vehicle at a distance where its driver can be dazzled; a bicycle is a vehicle too."},{"da":"Cyklister bliver ikke blændet, så jeg kan beholde fjernlyset.","fa":"دوچرخه‌سواران خیره نمی‌شوند، پس می‌توانم نور بالا را نگه دارم.","ok":0,"eda":"Nej. En blændet cyklist kan køre ud i vejen eller vælte.","efa":"خیر. دوچرخه‌سوار خیره‌شده ممکن است به وسط جاده برود یا زمین بخورد.","en":"Cyclists are not dazzled, so I can keep the high beam.","een":"No. A dazzled cyclist may ride out into the road or fall."},{"da":"Jeg blinker med fjernlyset, så cyklisten ved, at jeg kommer.","fa":"با نور بالا چراغ می‌زنم تا دوچرخه‌سوار بداند می‌آیم.","ok":0,"eda":"Nej. Blink med fjernlyset blænder også.","efa":"خیر. چراغ زدن با نور بالا هم خیره می‌کند.","en":"I flash the high beam so that the cyclist knows I am coming.","een":"No. Flashing the high beam dazzles too."}]},{"id":5150,"img":"newq-art/5150.png","c":"4.5","sda":"Foran dig kører en gruppe unge cyklister, nogle ved siden af hinanden. Hvordan forholder du dig?","sfa":"جلوی شما گروهی از دوچرخه‌سواران جوان می‌رانند و برخی کنار هم هستند. چه می‌کنید؟","sen":"A group of young cyclists is riding in front of you, some of them side by side. What do you do?","st":[{"da":"Jeg overhaler først, når jeg kan give hele gruppen god plads.","fa":"فقط وقتی سبقت می‌گیرم که بتوانم به کل گروه جای کافی بدهم.","ok":1,"eda":"Ja. En gruppe er længere og bredere end én cyklist.","efa":"بله. یک گروه از یک دوچرخه‌سوار درازتر و پهن‌تر است.","en":"I only overtake when I can give the whole group plenty of room.","een":"Yes. A group is longer and wider than one cyclist."},{"da":"Jeg må regne med, at en af dem pludselig kan svinge ud.","fa":"باید انتظار داشته باشم یکی‌شان ناگهان به وسط بیاید.","ok":1,"eda":"Ja. En cyklist, der kigger sig tilbage, kan være ved at svinge.","efa":"بله. دوچرخه‌سواری که به عقب نگاه می‌کند، ممکن است بخواهد بپیچد.","en":"I must expect that one of them may suddenly swerve out.","een":"Yes. A cyclist looking back may be about to turn."},{"da":"Jeg dytter, så de kører ind til siden.","fa":"بوق می‌زنم تا به کنار بروند.","ok":0,"eda":"Nej. Hornet kan forskrække dem og få nogen til at vælte.","efa":"خیر. بوق ممکن است آن‌ها را بترساند و یکی زمین بخورد.","en":"I sound the horn so that they move to the side.","een":"No. The horn can startle them and make someone fall."},{"da":"Jeg kører tæt forbi for at vise, at de fylder for meget.","fa":"از نزدیک رد می‌شوم تا نشانشان دهم زیادی جا گرفته‌اند.","ok":0,"eda":"Nej. At køre tæt forbi cyklister er farligt.","efa":"خیر. رد شدن از نزدیک دوچرخه‌سواران خطرناک است.","en":"I drive close past to show them that they take up too much room.","een":"No. Driving close past cyclists is dangerous."}]},{"id":5151,"img":"newq-art/5151.png","c":"7.3","sda":"En traktor har kørt jord ud på vejen fra en mark. Hvordan forholder du dig?","sfa":"تراکتوری از مزرعه خاک روی جاده آورده است. چه می‌کنید؟","sen":"A tractor has brought soil out onto the road from a field. What do you do?","st":[{"da":"Jord på vejen er kun farligt, når det regner.","fa":"خاک روی جاده فقط وقتی باران می‌بارد خطرناک است.","ok":0,"eda":"Nej. Også fugtig jord uden regn kan være meget glat.","efa":"خیر. خاک مرطوب حتی بدون باران هم می‌تواند خیلی لغزنده باشد.","en":"Soil on the road is only dangerous when it is raining.","een":"No. Damp soil can be very slippery even without rain."},{"da":"Jeg regner med, at vejen kan være glat.","fa":"انتظار دارم جاده لغزنده باشد.","ok":1,"eda":"Ja. Jord på en fugtig vej kan gøre føret fedtet og glat.","efa":"بله. خاک روی جاده‌ی مرطوب می‌تواند سطح را چرب و لغزنده کند.","en":"I expect that the road may be slippery.","een":"Yes. Soil on a damp road can make the surface greasy and slippery."},{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. I vådt, glat eller fedtet føre skal hastigheden være passende lav.","efa":"بله. در شرایط خیس، لغزنده یا چرب سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. In wet, slippery or greasy conditions your speed must be suitably low."},{"da":"Bremselængden kan blive længere end normalt.","fa":"مسافت ترمز ممکن است بیشتر از معمول باشد.","ok":1,"eda":"Ja. Dækkene får dårligere greb på jord og mudder.","efa":"بله. لاستیک‌ها روی خاک و گل چسبندگی کمتری دارند.","en":"The braking distance may be longer than normal.","een":"Yes. The tyres grip less well on soil and mud."}]},{"id":5152,"img":"newq-art/5152.png","c":"7.3","sda":"Du nærmer dig en bakketop, hvor du ikke kan se, hvad der er på den anden side. Hvordan forholder du dig?","sfa":"به بالای تپه‌ای نزدیک می‌شوید که پشتش را نمی‌بینید. چه می‌کنید؟","sen":"You are approaching a hilltop where you cannot see what is on the other side. What do you do?","st":[{"da":"Jeg holder godt til højre.","fa":"خوب سمت راست می‌مانم.","ok":1,"eda":"Ja. En modkørende kan dukke op over bakken.","efa":"بله. ممکن است وسیله‌ای از روبه‌رو از پشت تپه پیدا شود.","en":"I keep well to the right.","een":"Yes. An oncoming vehicle may appear over the hill."},{"da":"Jeg kører midt på vejen for at se bedre.","fa":"وسط جاده می‌رانم تا بهتر ببینم.","ok":0,"eda":"Nej. Midt på vejen kan du støde sammen med en modkørende.","efa":"خیر. وسط جاده ممکن است با وسیله‌ی روبه‌رو برخورد کنید.","en":"I drive in the middle of the road to see better.","een":"No. In the middle of the road you may collide with an oncoming vehicle."},{"da":"Jeg sænker farten før bakketoppen.","fa":"پیش از رسیدن به بالای تپه سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Foran en bakketop, hvor oversigten er begrænset, skal hastigheden være passende lav.","efa":"بله. پیش از بالای تپه‌ای که دید محدود است، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down before the hilltop.","een":"Yes. Before a hilltop where the view is limited, your speed must be suitably low."},{"da":"Jeg holder farten, så jeg hurtigt kommer over.","fa":"سرعتم را حفظ می‌کنم تا زود رد شوم.","ok":0,"eda":"Nej. Der kan holde en bil eller ligge noget på vejen lige efter toppen.","efa":"خیر. ممکن است درست پشت تپه خودرویی ایستاده یا چیزی روی جاده افتاده باشد.","en":"I keep my speed so that I get over quickly.","een":"No. A car may be standing or something lying on the road just after the top."}]},{"id":5153,"img":"newq-art/5153.png","c":"7.3","sda":"Du kører i et boligkvarter, hvor børn leger på fortovet. Hvordan forholder du dig?","sfa":"در محله‌ای مسکونی می‌رانید که بچه‌ها در پیاده‌رو بازی می‌کنند. چه می‌کنید؟","sen":"You are driving in a residential area where children are playing on the pavement. What do you do?","st":[{"da":"Jeg sænker farten.","fa":"سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Når du nærmer dig børn på eller ved vejen, skal hastigheden være passende lav.","efa":"بله. وقتی به بچه‌هایی روی جاده یا کنار آن نزدیک می‌شوید، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down.","een":"Yes. When you approach children on or by the road, your speed must be suitably low."},{"da":"Et barn kan pludselig løbe ud på vejen.","fa":"ممکن است کودکی ناگهان به خیابان بدود.","ok":1,"eda":"Ja. Børn kan ikke altid vurdere trafikken.","efa":"بله. بچه‌ها همیشه نمی‌توانند ترافیک را بسنجند.","en":"A child may suddenly run out into the road.","een":"Yes. Children cannot always judge the traffic."},{"da":"Jeg er klar til at bremse.","fa":"آماده‌ی ترمز هستم.","ok":1,"eda":"Ja. Så kan du standse hurtigere, hvis et barn kommer ud.","efa":"بله. این‌طور اگر کودکی بیرون آمد، زودتر می‌ایستید.","en":"I am ready to brake.","een":"Yes. Then you can stop sooner if a child comes out."},{"da":"Jeg kan holde 50 km/t, fordi det er tilladt her.","fa":"می‌توانم ۵۰ برانم، چون این‌جا مجاز است.","ok":0,"eda":"Nej. Grænsen er en øvre grænse; nær børn skal farten ned.","efa":"خیر. حد سرعت سقف است؛ نزدیک بچه‌ها باید سرعت را کم کنید.","en":"I can keep to 50 km/h because it is allowed here.","een":"No. The limit is an upper limit; near children your speed must come down."}]},{"id":5154,"img":"newq-art/5154.png","c":"7.3","sda":"Du nærmer dig et sving, hvor du ikke kan se vejen efter svinget. Hvordan forholder du dig?","sfa":"به پیچی نزدیک می‌شوید که جاده‌ی بعد از آن را نمی‌بینید. چه می‌کنید؟","sen":"You are approaching a bend where you cannot see the road after it. What do you do?","st":[{"da":"Jeg kører så langsomt, at jeg kan standse, hvis der er en hindring efter svinget.","fa":"آن‌قدر آهسته می‌رانم که اگر بعد از پیچ مانعی باشد، بتوانم بایستم.","ok":1,"eda":"Ja. Du skal kunne standse på den strækning, du kan se, og foran enhver hindring, der kan påregnes.","efa":"بله. باید بتوانید در فاصله‌ای که می‌بینید و پیش از هر مانعی که قابل انتظار است بایستید.","en":"I drive so slowly that I can stop if there is an obstacle after the bend.","een":"Yes. You must be able to stop within the distance you can see and before any obstacle that can be expected."},{"da":"Jeg kan regne med, at vejen er fri, fordi jeg ikke kan se noget.","fa":"می‌توانم مطمئن باشم راه باز است، چون چیزی نمی‌بینم.","ok":0,"eda":"Nej. Det, du ikke kan se, kan være der.","efa":"خیر. چیزی که نمی‌بینید ممکن است آن‌جا باشد.","en":"I can count on the road being clear because I cannot see anything.","een":"No. What you cannot see may be there."},{"da":"Jeg må køre 80 km/t, fordi det er grænsen.","fa":"می‌توانم ۸۰ برانم، چون حد سرعت همین است.","ok":0,"eda":"Nej. Grænsen er det højeste, du må; i svinget kan det være alt for hurtigt.","efa":"خیر. حد سرعت بیشترین مقدار مجاز است؛ در پیچ ممکن است خیلی زیاد باشد.","en":"I may drive at 80 km/h because that is the limit.","een":"No. The limit is the most you may do; in the bend it may be far too fast."},{"da":"Jeg sænker først farten, når jeg ser en hindring.","fa":"فقط وقتی مانعی ببینم سرعتم را کم می‌کنم.","ok":0,"eda":"Nej. Så kan det være for sent; farten skal ned før svinget.","efa":"خیر. آن وقت ممکن است دیر باشد؛ سرعت باید پیش از پیچ کم شود.","en":"I only slow down when I see an obstacle.","een":"No. Then it may be too late; your speed must come down before the bend."}]},{"id":5155,"img":"newq-art/5155.png","c":"7.3","sda":"Det regner kraftigt i mørke, og du har svært ved at se vejens kanter. Hvordan forholder du dig?","sfa":"در تاریکی باران شدیدی می‌بارد و لبه‌های جاده را به‌سختی می‌بینید. چه می‌کنید؟","sen":"It is raining heavily in the dark, and you find it hard to see the edges of the road. What do you do?","st":[{"da":"Jeg holder større afstand til bilen foran.","fa":"فاصله‌ی بیشتری با خودروی جلو نگه می‌دارم.","ok":1,"eda":"Ja. På våd vej er bremselængden længere.","efa":"بله. در جاده‌ی خیس مسافت ترمز بیشتر است.","en":"I keep a greater distance to the car in front.","een":"Yes. On a wet road the braking distance is longer."},{"da":"Jeg sætter farten ned, fordi sigtbarheden er nedsat.","fa":"سرعتم را کم می‌کنم، چون دید کم شده است.","ok":1,"eda":"Ja. Når sigtbarheden er nedsat på grund af lys- eller vejrforholdene, skal hastigheden være passende lav.","efa":"بله. وقتی نور یا هوا دید را کم می‌کند، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I lower my speed because visibility is reduced.","een":"Yes. When visibility is reduced by the light or the weather, your speed must be suitably low."},{"da":"Jeg holder hastighedsgrænsen, så er det sikkert.","fa":"حد سرعت را رعایت می‌کنم، پس ایمن است.","ok":0,"eda":"Nej. Grænsen gælder gode forhold; i regn og mørke skal farten ned.","efa":"خیر. حد سرعت برای شرایط خوب است؛ در باران و تاریکی باید سرعت را کم کنید.","en":"I keep to the speed limit, and then it is safe.","een":"No. The limit is for good conditions; in rain and darkness your speed must come down."},{"da":"Jeg kører tæt bag bilen foran og følger dens baglygter.","fa":"نزدیک پشت خودروی جلو می‌رانم و چراغ‌های عقبش را دنبال می‌کنم.","ok":0,"eda":"Nej. Bremser den, kan du ikke nå at standse.","efa":"خیر. اگر ترمز کند، به موقع نمی‌ایستید.","en":"I drive close behind the car in front and follow its rear lights.","een":"No. If it brakes, you cannot stop in time."}]},{"id":5156,"img":"newq-art/5156.png","c":"7.12","sda":"Du skal ligeud, og dit signal viser rødt. Signalet for venstresvingsbanen ved siden af viser grøn pil. Hvad gælder?","sfa":"می‌خواهید مستقیم بروید و چراغ شما قرمز است. چراغ خط گردش به چپ کنار شما فلش سبز است. چه قاعده‌ای برقرار است؟","sen":"You are going straight on, and your signal shows red. The signal for the left-turn lane beside you shows a green arrow. What applies?","st":[{"da":"Jeg må køre ligeud, hvis der ikke kommer nogen fra siden.","fa":"اگر کسی از کنار نیاید، می‌توانم مستقیم بروم.","ok":0,"eda":"Nej. Rødt lys betyder stop, uanset trafikken.","efa":"خیر. چراغ قرمز یعنی ایست، ترافیک هر چه باشد.","en":"I may go straight on if nobody is coming from the side.","een":"No. Red means stop whatever the traffic."},{"da":"Jeg holder stille, fordi den grønne pil kun gælder dem, der svinger til venstre.","fa":"می‌ایستم، چون فلش سبز فقط برای کسانی است که به چپ می‌پیچند.","ok":1,"eda":"Ja. Et pilsignal gælder for trafikanter, der vil køre i den retning, pilen viser.","efa":"بله. چراغ فلش‌دار برای کسانی است که می‌خواهند به جهت فلش بروند.","en":"I wait, because the green arrow only applies to those turning left.","een":"Yes. An arrow signal applies to road users going in the direction the arrow shows."},{"da":"Jeg må køre, når bilerne ved siden af kører.","fa":"وقتی خودروهای کنارم حرکت می‌کنند، می‌توانم بروم.","ok":0,"eda":"Nej. Du skal følge signalet for din egen vognbane.","efa":"خیر. باید از چراغ خط خودتان پیروی کنید.","en":"I may go when the cars beside me go.","een":"No. You must follow the signal for your own lane."}]},{"id":5157,"img":"newq-art/5157.png","c":"7.12","sda":"Du kører på en hovedvej. Fra en sidevej med hajtænder ruller en bil langsomt frem mod krydset. Hvordan forholder du dig?","sfa":"در جاده‌ی اصلی می‌رانید. از فرعی‌ای با دندان‌کوسه خودرویی آهسته به سمت تقاطع می‌آید. چه می‌کنید؟","sen":"You are driving on a main road. From a side road with shark teeth a car is rolling slowly towards the junction. What do you do?","st":[{"da":"Jeg skal holde tilbage, fordi bilen kommer fra højre.","fa":"باید راه بدهم، چون خودرو از راست می‌آید.","ok":0,"eda":"Nej. Højrereglen gælder ikke her, hvor sidevejen har hajtænder.","efa":"خیر. این‌جا که فرعی دندان‌کوسه دارد، قاعده‌ی دست راست اعمال نمی‌شود.","en":"I must give way because the car is coming from the right.","een":"No. The right-hand rule does not apply here, where the side road has shark teeth."},{"da":"Jeg holder øje med, om den virkelig standser.","fa":"مراقبم که واقعاً بایستد.","ok":1,"eda":"Ja. Du skal være klar til at reagere, hvis den anden ikke overholder sin vigepligt.","efa":"بله. باید آماده باشید اگر دیگری راه نداد، واکنش نشان دهید.","en":"I watch whether it really stops.","een":"Yes. You must be ready to react if the other driver does not give way."},{"da":"Bilen fra sidevejen skal holde tilbage for mig.","fa":"خودروی فرعی باید به من راه بدهد.","ok":1,"eda":"Ja. Hajtænderne giver bilen i sidevejen ubetinget vigepligt.","efa":"بله. دندان‌کوسه‌ها خودروی فرعی را مکلف به راه دادن بی‌قیدوشرط می‌کنند.","en":"The car from the side road must give way to me.","een":"Yes. The shark teeth make the car in the side road give way unconditionally."},{"da":"Jeg kan regne med, at den holder tilbage, så jeg øger farten.","fa":"می‌توانم مطمئن باشم راه می‌دهد، پس سرعتم را زیاد می‌کنم.","ok":0,"eda":"Nej. Du skal altid være forberedt på, at andre laver fejl.","efa":"خیر. همیشه باید برای اشتباه دیگران آماده باشید.","en":"I can count on it giving way, so I speed up.","een":"No. You must always be prepared for others to make mistakes."}]},{"id":5158,"img":"newq-art/5158.png","c":"7.12","sda":"Du kommer til et rødt lys. Der er en stoplinje på kørebanen et stykke før fodgængerfeltet. Hvor standser du?","sfa":"به چراغ قرمز می‌رسید. روی سواره‌رو کمی پیش از گذرگاه عابر خط ایست هست. کجا می‌ایستید؟","sen":"You come to a red light. There is a stop line on the road some way before the pedestrian crossing. Where do you stop?","st":[{"da":"Lige før fodgængerfeltet, efter stoplinjen.","fa":"درست پیش از گذرگاه عابر، بعد از خط ایست.","ok":0,"eda":"Nej. Stoplinjen viser, hvor du skal standse.","efa":"خیر. خط ایست نشان می‌دهد کجا باید بایستید.","en":"Just before the pedestrian crossing, after the stop line.","een":"No. The stop line shows where you must stop."},{"da":"På fodgængerfeltet, når der ikke er fodgængere.","fa":"روی گذرگاه عابر، وقتی عابری نیست.","ok":0,"eda":"Nej. Du skal så vidt muligt undgå at standse på et fodgængerfelt.","efa":"خیر. تا جای ممکن نباید روی گذرگاه عابر بایستید.","en":"On the pedestrian crossing, when there are no pedestrians.","een":"No. You must as far as possible avoid stopping on a pedestrian crossing."},{"da":"Før stoplinjen.","fa":"پیش از خط ایست.","ok":1,"eda":"Ja. Ved rødt lys skal du standse før stoplinjen.","efa":"بله. در چراغ قرمز باید پیش از خط ایست بایستید.","en":"Before the stop line.","een":"Yes. At a red light you must stop before the stop line."},{"da":"Et sted, hvor fodgængerfeltet er helt frit.","fa":"جایی که گذرگاه عابر کاملاً آزاد بماند.","ok":1,"eda":"Ja. Fodgængerne skal kunne gå over uden at gå uden om din bil.","efa":"بله. عابران باید بتوانند بدون دور زدن خودروی شما رد شوند.","en":"Somewhere the pedestrian crossing is completely clear.","een":"Yes. Pedestrians must be able to cross without walking round your car."}]},{"id":5159,"img":"newq-art/5159.png","c":"7.12","sda":"Du kører ligeud. Fra en sidevej til højre kommer en bil. Der er ingen tavler eller hajtænder. Hvad gælder?","sfa":"مستقیم می‌روید. از فرعی سمت راست خودرویی می‌آید. تابلو یا دندان‌کوسه‌ای نیست. چه قاعده‌ای برقرار است؟","sen":"You are going straight on. A car is coming from a side road on the right. There are no signs or shark teeth. What applies?","st":[{"da":"Jeg har forkørselsret, fordi jeg kører ligeud.","fa":"حق تقدم با من است، چون مستقیم می‌روم.","ok":0,"eda":"Nej. At køre ligeud giver ingen forkørselsret.","efa":"خیر. مستقیم رفتن حق تقدم نمی‌دهد.","en":"I have the right of way because I am going straight on.","een":"No. Going straight on gives no right of way."},{"da":"Højrereglen gælder, selv om sidevejen ser mindre ud.","fa":"قاعده‌ی دست راست برقرار است، حتی اگر فرعی کوچک‌تر به نظر برسد.","ok":1,"eda":"Ja. Kun tavler, afmærkning eller særlige udkørsler (fx fra en ejendom) ændrer det.","efa":"بله. فقط تابلو، خط‌کشی یا خروجی‌های خاص (مثلاً از یک ملک) این را تغییر می‌دهند.","en":"The right-hand rule applies even if the side road looks smaller.","een":"Yes. Only signs, markings or special exits (for example from a property) change that."},{"da":"Jeg skal holde tilbage for bilen fra højre.","fa":"باید به خودروی سمت راست راه بدهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است.","en":"I must give way to the car from the right.","een":"Yes. Without signs or markings the right-hand rule applies."},{"da":"Bilen fra sidevejen skal holde tilbage, fordi den kommer fra en mindre vej.","fa":"خودروی فرعی باید راه بدهد، چون از راه کوچک‌تری می‌آید.","ok":0,"eda":"Nej. En vejs størrelse bestemmer ikke vigepligten.","efa":"خیر. بزرگی جاده حق تقدم را تعیین نمی‌کند.","en":"The car from the side road must give way because it is coming from a smaller road.","een":"No. The size of a road does not decide who gives way."}]},{"id":5160,"img":"newq-art/5160.png","c":"7.14","sda":"Du holder midt i krydset for at svinge til venstre, og lyset skifter til gult. Hvordan forholder du dig?","sfa":"وسط تقاطع ایستاده‌اید تا به چپ بپیچید و چراغ زرد می‌شود. چه می‌کنید؟","sen":"You are waiting in the middle of the junction to turn left, and the light changes to yellow. What do you do?","st":[{"da":"Jeg holder stadig tilbage for modkørende, der ikke kan nå at standse.","fa":"هنوز به خودروهای روبه‌رویی که نمی‌توانند به موقع بایستند راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I still give way to oncoming cars that cannot stop in time.","een":"Yes. When turning left you must not inconvenience oncoming traffic."},{"da":"Jeg kører ud af krydset, når de modkørende er kørt forbi eller standset.","fa":"وقتی خودروهای روبه‌رو رد شدند یا ایستادند، از تقاطع خارج می‌شوم.","ok":1,"eda":"Ja. Du er allerede i krydset og skal ud af det, så snart det kan ske uden fare.","efa":"بله. شما در تقاطع هستید و باید به محض بی‌خطر شدن از آن خارج شوید.","en":"I drive out of the junction when the oncoming cars have passed or stopped.","een":"Yes. You are already in the junction and must get out of it as soon as it can be done safely."},{"da":"Jeg bakker tilbage bag stoplinjen.","fa":"دنده‌عقب تا پشت خط ایست برمی‌گردم.","ok":0,"eda":"Nej. At bakke i et kryds er farligt; trafikken bag dig kører frem.","efa":"خیر. دنده‌عقب در تقاطع خطرناک است؛ ترافیک پشت سرتان جلو می‌آید.","en":"I reverse back behind the stop line.","een":"No. Reversing in a junction is dangerous; the traffic behind you is moving forward."},{"da":"Jeg bliver stående i krydset, til jeg får grønt igen.","fa":"در تقاطع می‌مانم تا دوباره سبز شود.","ok":0,"eda":"Nej. Så spærrer du for den tværgående trafik, når den får grønt.","efa":"خیر. این‌طور راه ترافیک متقاطع را وقتی سبز می‌شود می‌بندید.","en":"I stay in the junction until I get green again.","een":"No. Then you block the crossing traffic when it gets green."}]},{"id":5161,"img":"newq-art/5161.png","c":"7.14","sda":"Du vil svinge til venstre ind på en sidevej. Langs vejens venstre side er der en dobbeltrettet cykelsti. Hvad gælder?","sfa":"می‌خواهید به چپ وارد فرعی شوید. در سمت چپ جاده مسیر دوچرخه‌ی دوطرفه هست. چه قاعده‌ای برقرار است؟","sen":"You want to turn left into a side road. Along the left side of the road there is a two-way cycle path. What applies?","st":[{"da":"Jeg må ikke svinge, før det kan ske uden ulempe for cyklisterne, der kører ligeud.","fa":"تا وقتی برای دوچرخه‌سوارانی که مستقیم می‌روند مزاحمتی نداشته باشد، نباید بپیچم.","ok":1,"eda":"Ja. Er der en dobbeltrettet cykelsti, må du ikke svinge til venstre, før det kan ske uden ulempe for cyklister og knallertkørere, der kører ligeud.","efa":"بله. وقتی مسیر دوچرخه‌ی دوطرفه هست، تا وقتی برای دوچرخه‌سواران و موپدسوارانی که مستقیم می‌روند مزاحمتی نداشته باشد، نباید به چپ بپیچید.","en":"I must not turn until it can be done without inconvenience to the cyclists going straight on.","een":"Yes. With a two-way cycle path you must not turn left until it can be done without inconvenience to cyclists and moped riders going straight on."},{"da":"Jeg ser efter cyklister fra begge retninger.","fa":"دوچرخه‌سواران هر دو جهت را نگاه می‌کنم.","ok":1,"eda":"Ja. På en dobbeltrettet cykelsti kommer cyklisterne både forfra og bagfra.","efa":"بله. روی مسیر دوچرخه‌ی دوطرفه، دوچرخه‌سواران هم از جلو و هم از پشت می‌آیند.","en":"I look for cyclists from both directions.","een":"Yes. On a two-way cycle path cyclists come both from ahead and from behind."},{"da":"Cyklisterne skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سواران باید راه بدهند، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver ingen ret til at svinge.","efa":"خیر. راهنما حق پیچیدن نمی‌دهد.","en":"The cyclists must give way because I am signalling.","een":"No. The indicator gives no right to turn."},{"da":"Jeg holder også tilbage for modkørende biler.","fa":"به خودروهای روبه‌رو هم راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for de modkørende.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید.","en":"I also give way to oncoming cars.","een":"Yes. When turning left you must not inconvenience oncoming traffic."}]},{"id":5162,"img":"newq-art/5162.png","c":"7.14","sda":"Du vil svinge til venstre. En modkørende bil vil svinge til højre ind på samme vej som dig. Hvad gælder?","sfa":"می‌خواهید به چپ بپیچید. خودرویی از روبه‌رو می‌خواهد به راست وارد همان جاده‌ای شود که شما می‌روید. چه قاعده‌ای برقرار است؟","sen":"You want to turn left. An oncoming car wants to turn right into the same road as you. What applies?","st":[{"da":"Vi skal begge standse og vinke hinanden frem.","fa":"هر دو باید بایستیم و به هم اشاره کنیم که اول برو.","ok":0,"eda":"Nej. Reglerne siger, hvem der skal holde tilbage; her er det dig.","efa":"خیر. قانون می‌گوید چه کسی باید راه بدهد؛ این‌جا شما هستید.","en":"We must both stop and wave each other on.","een":"No. The rules say who must give way; here it is you."},{"da":"Jeg holder tilbage for den modkørende, der svinger til højre.","fa":"به خودروی روبه‌رو که به راست می‌پیچد راه می‌دهم.","ok":1,"eda":"Ja. Ved venstresving må du ikke være til ulempe for modkørende, heller ikke dem, der svinger til højre.","efa":"بله. هنگام گردش به چپ نباید مزاحم ترافیک روبه‌رو شوید، از جمله کسانی که به راست می‌پیچند.","en":"I give way to the oncoming car that is turning right.","een":"Yes. When turning left you must not inconvenience oncoming traffic, including those turning right."},{"da":"Jeg har forkørselsret, fordi jeg kom først.","fa":"حق تقدم با من است، چون اول رسیدم.","ok":0,"eda":"Nej. Hvem der kom først, betyder ikke noget.","efa":"خیر. این‌که چه کسی اول رسید، اهمیتی ندارد.","en":"I have the right of way because I got there first.","een":"No. Who got there first does not matter."}]},{"id":5163,"img":"newq-art/5163.png","c":"7.14","sda":"Du vil svinge til venstre ind på en markvej. Bag dig kommer en motorcykel hurtigt. Hvordan forholder du dig?","sfa":"می‌خواهید به چپ وارد یک راه خاکی مزرعه شوید. از پشت موتورسیکلتی با سرعت می‌آید. چه می‌کنید؟","sen":"You want to turn left into a field road. A motorcycle is coming up fast behind you. What do you do?","st":[{"da":"Jeg ser i spejlet og over venstre skulder, før jeg svinger.","fa":"پیش از پیچیدن در آینه و از روی شانه‌ی چپ نگاه می‌کنم.","ok":1,"eda":"Ja. Før du svinger, skal du sikre dig, at det kan ske uden fare for dem, der kører i samme retning.","efa":"بله. پیش از پیچیدن باید مطمئن شوید که برای کسانی که هم‌جهت شما می‌آیند خطری ندارد.","en":"I look in the mirror and over my left shoulder before I turn.","een":"Yes. Before you turn, you must make sure that it can be done without danger to those going in the same direction."},{"da":"Motorcyklen skal altid holde tilbage, fordi jeg blinker.","fa":"موتورسیکلت همیشه باید راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at svinge foran andre.","efa":"خیر. راهنما به شما حق پیچیدن جلوی دیگران را نمی‌دهد.","en":"The motorcycle must always give way because I am signalling.","een":"No. The indicator does not give you the right to turn in front of others."},{"da":"Jeg blinker i god tid og placerer mig ved midten af vejen.","fa":"به موقع راهنما می‌زنم و نزدیک وسط جاده قرار می‌گیرم.","ok":1,"eda":"Ja. Så kan de bagfra se, hvad du vil.","efa":"بله. این‌طور پشت‌سری‌ها می‌بینند چه می‌خواهید بکنید.","en":"I signal in good time and place myself near the middle of the road.","een":"Yes. Then those behind can see what you are going to do."},{"da":"Jeg kan svinge med det samme, fordi jeg har blinket.","fa":"می‌توانم فوراً بپیچم، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Er motorcyklen ved at overhale, skal du vente.","efa":"خیر. اگر موتورسیکلت در حال سبقت است، باید صبر کنید.","en":"I can turn straight away because I have signalled.","een":"No. If the motorcycle is overtaking, you must wait."}]},{"id":5164,"img":"newq-art/5164.png","c":"7.14","sda":"Du svinger til venstre ind på en vej med to vognbaner i din nye retning. Lidt længere fremme skal du til højre. Hvad gælder?","sfa":"به چپ وارد جاده‌ای می‌شوید که در جهت تازه‌تان دو خط دارد. کمی جلوتر باید به راست بپیچید. چه قاعده‌ای برقرار است؟","sen":"You are turning left into a road with two lanes in your new direction. A little further on you are going to turn right. What applies?","st":[{"da":"Det kan være den højre vognbane, når jeg snart skal til højre.","fa":"وقتی به‌زودی باید به راست بپیچم، ممکن است خط راست باشد.","ok":1,"eda":"Ja. Så undgår du et vognbaneskift lige før næste sving.","efa":"بله. این‌طور از تغییر خط درست پیش از پیچ بعدی پرهیز می‌کنید.","en":"It may be the right-hand lane when I am soon going to turn right.","een":"Yes. That way you avoid a lane change just before the next turn."},{"da":"Jeg vælger den vognbane, der passer bedst til trafikken og min videre kørsel.","fa":"خطی را انتخاب می‌کنم که با ترافیک و ادامه‌ی مسیرم بیشتر جور است.","ok":1,"eda":"Ja. Har vejen, du svinger ind på, to eller flere vognbaner i samme retning, svinger du på den måde, der er mest hensigtsmæssig.","efa":"بله. اگر جاده‌ای که واردش می‌شوید دو یا چند خط هم‌جهت دارد، به مناسب‌ترین شکل می‌پیچید.","en":"I choose the lane that best suits the traffic and where I am going next.","een":"Yes. If the road you turn into has two or more lanes in the same direction, you turn in the way that is most suitable."},{"da":"Jeg må skifte vognbane midt i svinget uden at se mig for.","fa":"می‌توانم وسط پیچ بدون نگاه کردن تغییر خط بدهم.","ok":0,"eda":"Nej. Et vognbaneskift skal altid kunne ske uden fare.","efa":"خیر. تغییر خط همیشه باید بی‌خطر باشد.","en":"I may change lanes in the middle of the turn without looking.","een":"No. A lane change must always be done safely."},{"da":"Jeg skal altid ende i den venstre vognbane efter et venstresving.","fa":"پس از گردش به چپ همیشه باید در خط چپ قرار بگیرم.","ok":0,"eda":"Nej. Der er ingen sådan regel, når vejen har flere vognbaner.","efa":"خیر. وقتی جاده چند خط دارد، چنین قاعده‌ای نیست.","en":"I must always end up in the left lane after a left turn.","een":"No. There is no such rule when the road has several lanes."}]},{"id":5165,"img":"newq-art/5165.png","c":"7.14","sda":"Du venter på at svinge til venstre. Den modkørende bil standser og blinker med lyset. Hvordan forholder du dig?","sfa":"منتظر گردش به چپ هستید. خودروی روبه‌رو می‌ایستد و چراغ می‌زند. چه می‌کنید؟","sen":"You are waiting to turn left. The oncoming car stops and flashes its lights. What do you do?","st":[{"da":"Jeg sikrer mig selv, at svinget kan ske uden fare, før jeg kører.","fa":"پیش از حرکت خودم مطمئن می‌شوم که پیچیدن بی‌خطر است.","ok":1,"eda":"Ja. Et lyssignal er efter loven en advarsel og giver dig ingen ret; der kan komme en cyklist bag bilen.","efa":"بله. طبق قانون چراغ زدن هشدار است و حقی به شما نمی‌دهد؛ ممکن است دوچرخه‌سواری پشت آن خودرو بیاید.","en":"I make sure myself that the turn can be done safely before I go.","een":"Yes. By law a light signal is a warning and gives you no right; a cyclist may be coming behind the car."},{"da":"Blinket betyder altid, at jeg kan svinge med det samme.","fa":"چراغ زدن همیشه یعنی می‌توانم فوراً بپیچم.","ok":0,"eda":"Nej. Du ved ikke, hvad den anden mener, og du kan ikke se alt bag bilen.","efa":"خیر. نمی‌دانید منظور او چیست و همه‌چیز پشت آن خودرو را نمی‌بینید.","en":"The flash always means that I can turn straight away.","een":"No. You do not know what the other driver means, and you cannot see everything behind the car."},{"da":"Blinket betyder, at den modkørende har pligt til at holde tilbage for mig.","fa":"چراغ زدن یعنی راننده‌ی روبه‌رو موظف است به من راه بدهد.","ok":0,"eda":"Nej. Det er dig, der skal holde tilbage ved venstresving.","efa":"خیر. هنگام گردش به چپ، این شما هستید که باید راه بدهید.","en":"The flash means that the oncoming driver has a duty to give way to me.","een":"No. It is you who must give way when turning left."},{"da":"Jeg skal køre nu, ellers er jeg til ulempe for den modkørende.","fa":"باید الان بروم، وگرنه مزاحم راننده‌ی روبه‌رو هستم.","ok":0,"eda":"Nej. Sikkerheden går forud; vent, til du kan se, at vejen er fri.","efa":"خیر. ایمنی مقدم است؛ صبر کنید تا ببینید راه باز است.","en":"I must go now, otherwise I am in the oncoming driver's way.","een":"No. Safety comes first; wait until you can see the way is clear."}]},{"id":5166,"img":"newq-art/5166.png","c":"7.13","sda":"Du vil svinge til højre, og lyset er rødt. Der kommer ingen. Hvad gælder?","sfa":"می‌خواهید به راست بپیچید و چراغ قرمز است. کسی نمی‌آید. چه قاعده‌ای برقرار است؟","sen":"You want to turn right, and the light is red. Nobody is coming. What applies?","st":[{"da":"Jeg må svinge, hvis jeg kører meget langsomt.","fa":"اگر خیلی آهسته بروم، می‌توانم بپیچم.","ok":0,"eda":"Nej. Farten ændrer ikke på signalet.","efa":"خیر. سرعت چیزی را درباره‌ی چراغ تغییر نمی‌دهد.","en":"I may turn if I drive very slowly.","een":"No. Speed does not change the signal."},{"da":"Jeg holder stille, til jeg får grønt.","fa":"تا سبز شدن چراغ می‌ایستم.","ok":1,"eda":"Ja. Rødt lys betyder stop, også når du skal svinge til højre.","efa":"بله. چراغ قرمز یعنی ایست، حتی وقتی می‌خواهید به راست بپیچید.","en":"I wait until I get green.","een":"Yes. Red means stop, also when you are going to turn right."},{"da":"Jeg må svinge til højre for rødt, når vejen er fri.","fa":"وقتی راه باز است، می‌توانم با چراغ قرمز به راست بپیچم.","ok":0,"eda":"Nej. Der er ingen regel, der tillader biler at svinge til højre for rødt.","efa":"خیر. هیچ قاعده‌ای پیچیدن خودرو به راست با چراغ قرمز را مجاز نمی‌کند.","en":"I may turn right on red when the road is clear.","een":"No. There is no rule allowing cars to turn right on red."}]},{"id":5167,"img":"newq-art/5167.png","c":"7.13","sda":"Du vil svinge til højre. Bag dig kommer en cyklist i cykelbanen. Hvordan forholder du dig?","sfa":"می‌خواهید به راست بپیچید. از پشت دوچرخه‌سواری در خط دوچرخه می‌آید. چه می‌کنید؟","sen":"You want to turn right. A cyclist is coming up behind you in the cycle lane. What do you do?","st":[{"da":"Cyklisten skal holde tilbage, fordi jeg blinker.","fa":"دوچرخه‌سوار باید راه بدهد، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver ingen ret.","efa":"خیر. راهنما حقی نمی‌دهد.","en":"The cyclist must give way because I am signalling.","een":"No. The indicator gives no right."},{"da":"Jeg skynder mig at svinge, før cyklisten når frem.","fa":"عجله می‌کنم تا پیش از رسیدن دوچرخه‌سوار بپیچم.","ok":0,"eda":"Nej. Det kan føre til en farlig ulykke i krydset.","efa":"خیر. این کار ممکن است به تصادف خطرناکی در تقاطع منجر شود.","en":"I hurry to turn before the cyclist gets there.","een":"No. That can lead to a dangerous accident in the junction."},{"da":"Jeg kigger i spejlet og over højre skulder, før jeg svinger.","fa":"پیش از پیچیدن در آینه و از روی شانه‌ی راست نگاه می‌کنم.","ok":1,"eda":"Ja. Cyklisten kan være i din blinde vinkel.","efa":"بله. دوچرخه‌سوار ممکن است در نقطه‌ی کور شما باشد.","en":"I look in the mirror and over my right shoulder before I turn.","een":"Yes. The cyclist may be in your blind spot."},{"da":"Jeg lader cyklisten køre ligeud forbi, før jeg svinger.","fa":"می‌گذارم دوچرخه‌سوار مستقیم رد شود، بعد می‌پیچم.","ok":1,"eda":"Ja. Ved svingning til højre må du ikke være til ulempe for cyklister, der kører ligeud.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I let the cyclist ride straight on past before I turn.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."}]},{"id":5168,"img":"newq-art/5168.png","c":"7.13","sda":"Du vil svinge til højre ind i en indkørsel over cykelstien og fortovet. Hvad gælder?","sfa":"می‌خواهید به راست وارد ورودی یک خانه شوید که از روی مسیر دوچرخه و پیاده‌رو می‌گذرد. چه قاعده‌ای برقرار است؟","sen":"You want to turn right into a driveway across the cycle path and the pavement. What applies?","st":[{"da":"Fodgængeren skal vente, fordi jeg blinker.","fa":"عابر باید صبر کند، چون راهنما زده‌ام.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre over fortovet foran fodgængeren.","efa":"خیر. راهنما به شما حق نمی‌دهد جلوی عابر از روی پیاده‌رو رد شوید.","en":"The pedestrian must wait because I am signalling.","een":"No. The indicator does not give you the right to cross the pavement in front of the pedestrian."},{"da":"Jeg holder tilbage for fodgængeren på fortovet.","fa":"به عابر پیاده‌رو راه می‌دهم.","ok":1,"eda":"Ja. Når du kører bort fra kørebanen, må du ikke være til fare for gående; over fortovet skal du holde tilbage for dem.","efa":"بله. وقتی از سواره‌رو بیرون می‌روید، نباید عابران را به خطر بیندازید؛ روی پیاده‌رو باید به آن‌ها راه بدهید.","en":"I give way to the pedestrian on the pavement.","een":"Yes. When you leave the carriageway you must not endanger pedestrians; across the pavement you must give way to them."},{"da":"Jeg holder tilbage for cyklisten på cykelstien.","fa":"به دوچرخه‌سوار روی مسیر دوچرخه راه می‌دهم.","ok":1,"eda":"Ja. Du må ikke svinge ind foran cyklisten, så den kommer i fare eller bliver generet.","efa":"بله. نباید جلوی دوچرخه‌سوار بپیچید، طوری که به خطر بیفتد یا اذیت شود.","en":"I give way to the cyclist on the cycle path.","een":"Yes. You must not turn in front of the cyclist so that they are put in danger or inconvenienced."}]},{"id":5169,"img":"newq-art/5169.png","c":"7.13","sda":"Lige før krydset, hvor du skal svinge til højre, kører en cyklist foran dig i højre side. Hvordan forholder du dig?","sfa":"درست پیش از تقاطعی که باید به راست بپیچید، دوچرخه‌سواری جلوی شما در سمت راست می‌رود. چه می‌کنید؟","sen":"Just before the junction where you are going to turn right, a cyclist is riding in front of you on the right. What do you do?","st":[{"da":"Cyklisten skal holde tilbage, fordi bilen er større.","fa":"دوچرخه‌سوار باید راه بدهد، چون خودرو بزرگ‌تر است.","ok":0,"eda":"Nej. Størrelse giver ingen ret.","efa":"خیر. بزرگی حقی نمی‌دهد.","en":"The cyclist must give way because the car is bigger.","een":"No. Size gives no right."},{"da":"Jeg bliver bag cyklisten og svinger, når den er kørt ligeud forbi sidevejen.","fa":"پشت دوچرخه‌سوار می‌مانم و وقتی از کنار فرعی مستقیم رد شد، می‌پیچم.","ok":1,"eda":"Ja. Ved højresving må du ikke være til ulempe for cyklister, der kører ligeud.","efa":"بله. هنگام گردش به راست نباید مزاحم دوچرخه‌سوارانی شوید که مستقیم می‌روند.","en":"I stay behind the cyclist and turn when they have gone straight past the side road.","een":"Yes. When turning right you must not inconvenience cyclists going straight on."},{"da":"Jeg overhaler cyklisten og svinger ind foran den.","fa":"از دوچرخه‌سوار سبقت می‌گیرم و جلویش می‌پیچم.","ok":0,"eda":"Nej. Så kan cyklisten køre ind i siden af bilen.","efa":"خیر. این‌طور ممکن است دوچرخه‌سوار به پهلوی خودرو بخورد.","en":"I overtake the cyclist and turn in front of them.","een":"No. Then the cyclist may ride into the side of the car."}]},{"id":5170,"img":"newq-art/5170.png","c":"7.13","sda":"Du skal svinge til højre i et kryds, hvor vejen har to vognbaner i din retning. Hvordan gør du?","sfa":"باید در تقاطعی بپیچید که جاده در جهت شما دو خط دارد و می‌خواهید به راست بروید. چه می‌کنید؟","sen":"You are going to turn right at a junction where the road has two lanes in your direction. How do you do it?","st":[{"da":"Jeg blinker i god tid.","fa":"به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. Tegn skal gives i god tid før svinget.","efa":"بله. علامت باید به موقع پیش از پیچ داده شود.","en":"I signal in good time.","een":"Yes. Signals must be given in good time before the turn."},{"da":"I god tid før krydset lægger jeg mig i vognbanen længst til højre.","fa":"به موقع پیش از تقاطع به راست‌ترین خط می‌روم.","ok":1,"eda":"Ja. I god tid før et kryds skal du lægge dig i vognbanen længst til højre, hvis du skal svinge til højre.","efa":"بله. اگر می‌خواهید به راست بپیچید، باید به موقع پیش از تقاطع به راست‌ترین خط بروید.","en":"In good time before the junction I move into the lane furthest to the right.","een":"Yes. In good time before a junction you must move into the lane furthest to the right if you are going to turn right."},{"da":"Jeg kan svinge til højre fra venstre vognbane, hvis der er plads.","fa":"اگر جا باشد، می‌توانم از خط چپ به راست بپیچم.","ok":0,"eda":"Nej. Så skærer du ind foran trafikken i højre vognbane.","efa":"خیر. این‌طور جلوی ترافیک خط راست می‌پیچید.","en":"I can turn right from the left lane if there is room.","een":"No. Then you cut in front of the traffic in the right lane."},{"da":"Jeg sænker farten før svinget.","fa":"پیش از پیچیدن سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved kryds skal hastigheden være passende lav.","efa":"بله. در تقاطع سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down before the turn.","een":"Yes. At junctions your speed must be suitably low."}]},{"id":5171,"img":"newq-art/5171.png","c":"7.11","sda":"Du kommer til en stoptavle, men hækkene skjuler udsynet til den tværgående vej. Hvordan forholder du dig?","sfa":"به تابلوی ایست می‌رسید، ولی پرچین‌ها دید جاده‌ی متقاطع را گرفته‌اند. چه می‌کنید؟","sen":"You come to a stop sign, but the hedges hide the view of the crossing road. What do you do?","st":[{"da":"Jeg standser helt ved stoplinjen.","fa":"کنار خط ایست کاملاً می‌ایستم.","ok":1,"eda":"Ja. Ved stoptavlen skal du altid standse ved stoplinjen.","efa":"بله. کنار تابلوی ایست همیشه باید پشت خط ایست بایستید.","en":"I stop completely at the stop line.","een":"Yes. At the stop sign you must always stop at the stop line."},{"da":"Kan jeg ikke se nok, kører jeg langsomt lidt frem og standser igen, hvor jeg kan se.","fa":"اگر به اندازه‌ی کافی نبینم، آهسته کمی جلو می‌روم و جایی که می‌بینم دوباره می‌ایستم.","ok":1,"eda":"Ja. Du har ubetinget vigepligt og må først køre ud, når du kan se, at det kan ske uden fare.","efa":"بله. باید بی‌قیدوشرط راه بدهید و فقط وقتی می‌توانید وارد شوید که ببینید بی‌خطر است.","en":"If I cannot see enough, I edge forward slowly and stop again where I can see.","een":"Yes. You must give way unconditionally and may only drive out when you can see that it is safe."},{"da":"Jeg kører ud, når jeg ikke kan høre biler.","fa":"وقتی صدای خودرویی نمی‌شنوم، وارد می‌شوم.","ok":0,"eda":"Nej. Du kan ikke høre alle trafikanter, fx cyklister og elbiler.","efa":"خیر. صدای همه‌ی کاربران راه، مثلاً دوچرخه و خودروی برقی، را نمی‌شنوید.","en":"I drive out when I cannot hear any cars.","een":"No. You cannot hear all road users, for example cyclists and electric cars."},{"da":"Jeg standser kun, hvis der kommer trafik.","fa":"فقط وقتی ترافیک بیاید می‌ایستم.","ok":0,"eda":"Nej. Ved stoptavlen skal du altid standse.","efa":"خیر. کنار تابلوی ایست همیشه باید بایستید.","en":"I only stop if traffic is coming.","een":"No. At the stop sign you must always stop."}]},{"id":5172,"img":"newq-art/5172.png","c":"7.11","sda":"Du nærmer dig et kryds uden tavler og afmærkning. En høj hæk skjuler vejen til højre. Hvordan forholder du dig?","sfa":"به تقاطعی بدون تابلو و خط‌کشی نزدیک می‌شوید. پرچین بلندی جاده‌ی سمت راست را پنهان کرده است. چه می‌کنید؟","sen":"You are approaching a junction with no signs or markings. A high hedge hides the road to the right. What do you do?","st":[{"da":"Jeg skal kunne standse, hvis der kommer nogen fra højre.","fa":"اگر کسی از راست بیاید، باید بتوانم بایستم.","ok":1,"eda":"Ja. Du kan først se trafikken fra højre, når du er helt fremme ved krydset.","efa":"بله. ترافیک سمت راست را فقط وقتی می‌بینید که کاملاً به تقاطع رسیده باشید.","en":"I must be able to stop if someone comes from the right.","een":"Yes. You can only see the traffic from the right when you are right up at the junction."},{"da":"Jeg skal holde tilbage for trafik fra højre.","fa":"باید به ترافیک سمت راست راه بدهم.","ok":1,"eda":"Ja. Uden tavler og afmærkning gælder højrereglen.","efa":"بله. بدون تابلو و خط‌کشی، قاعده‌ی دست راست برقرار است.","en":"I must give way to traffic from the right.","een":"Yes. Without signs or markings the right-hand rule applies."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Ved vejkryds skal hastigheden være passende lav, især når oversigten er dårlig.","efa":"بله. در تقاطع، به‌ویژه وقتی دید کم است، سرعت باید به اندازه‌ی کافی کم باشد.","en":"I slow down in good time.","een":"Yes. At junctions your speed must be suitably low, especially when the view is poor."},{"da":"Jeg kører igennem, fordi jeg ikke kan se nogen.","fa":"رد می‌شوم، چون کسی را نمی‌بینم.","ok":0,"eda":"Nej. Hækken kan skjule en, der kommer fra højre.","efa":"خیر. پرچین ممکن است کسی را که از راست می‌آید پنهان کند.","en":"I drive through because I cannot see anyone.","een":"No. The hedge may hide someone coming from the right."}]},{"id":5173,"img":"newq-art/5173.png","c":"7.11","sda":"Du kører forbi denne tavle. Hvad betyder den, og hvordan forholder du dig?","sfa":"از کنار این تابلو رد می‌شوید. یعنی چه و چه می‌کنید؟","sen":"You pass this sign. What does it mean, and what do you do?","st":[{"da":"Der kommer en rundkørsel.","fa":"میدانی در پیش است.","ok":1,"eda":"Ja. Tavlen (A 16) varsler en rundkørsel.","efa":"بله. این تابلو (A 16) از میدان خبر می‌دهد.","en":"A roundabout is coming.","een":"Yes. The sign (A 16) warns of a roundabout."},{"da":"Tavlen betyder, at vejen ender.","fa":"این تابلو یعنی جاده تمام می‌شود.","ok":0,"eda":"Nej. Vejen fortsætter gennem rundkørslen.","efa":"خیر. جاده از میان میدان ادامه دارد.","en":"The sign means that the road ends.","een":"No. The road continues through the roundabout."},{"da":"Tavlen betyder, at jeg har forkørselsret i rundkørslen.","fa":"این تابلو یعنی در میدان حق تقدم با من است.","ok":0,"eda":"Nej. Advarselstavlen siger ikke noget om vigepligt; det gør tavlerne ved indkørslen.","efa":"خیر. تابلوی هشدار چیزی درباره‌ی حق تقدم نمی‌گوید؛ تابلوهای ورودی می‌گویند.","en":"The sign means that I have the right of way in the roundabout.","een":"No. The warning sign says nothing about giving way; the signs at the entry do."},{"da":"Jeg sænker farten i god tid.","fa":"به موقع سرعتم را کم می‌کنم.","ok":1,"eda":"Ja. Du skal kunne holde tilbage for dem, der er i rundkørslen, hvis det kræves.","efa":"بله. باید بتوانید در صورت لزوم به کسانی که در میدان‌اند راه بدهید.","en":"I slow down in good time.","een":"Yes. You must be able to give way to those in the roundabout if required."}]},{"id":5174,"img":"newq-art/5174.png","c":"7.11","sda":"Lyssignalerne i krydset er slukket. Ved din vej står en vigepligtstavle, og der er hajtænder. Hvad gælder?","sfa":"چراغ‌های تقاطع خاموش‌اند. در راه شما تابلوی رعایت حق تقدم و دندان‌کوسه هست. چه قاعده‌ای برقرار است؟","sen":"The traffic lights at the junction are switched off. At your road there is a give-way sign and shark teeth. What applies?","st":[{"da":"Jeg har ubetinget vigepligt efter tavlen og hajtænderne.","fa":"طبق تابلو و دندان‌کوسه‌ها باید بی‌قیدوشرط راه بدهم.","ok":1,"eda":"Ja. Når signalet ikke er i drift, gælder tavler og afmærkning.","efa":"بله. وقتی چراغ کار نمی‌کند، تابلو و خط‌کشی معتبرند.","en":"I must give way unconditionally according to the sign and the shark teeth.","een":"Yes. When the signal is not working, the signs and markings apply."},{"da":"Jeg har forkørselsret, fordi signalet er slukket.","fa":"حق تقدم با من است، چون چراغ خاموش است.","ok":0,"eda":"Nej. Et slukket signal giver ingen forkørselsret.","efa":"خیر. چراغ خاموش حق تقدم نمی‌دهد.","en":"I have the right of way because the signal is switched off.","een":"No. A switched-off signal gives no right of way."},{"da":"Alle skal standse helt, som ved en stoptavle.","fa":"همه باید کاملاً بایستند، مثل تابلوی ایست.","ok":0,"eda":"Nej. Vigepligtstavlen kræver ikke fuldt stop, når vejen er fri.","efa":"خیر. تابلوی رعایت حق تقدم، وقتی راه باز است، توقف کامل لازم ندارد.","en":"Everyone must stop completely, as at a stop sign.","een":"No. The give-way sign does not require a full stop when the road is clear."},{"da":"Jeg kører frem med særlig forsigtighed.","fa":"با احتیاط ویژه جلو می‌روم.","ok":1,"eda":"Ja. Andre kan være i tvivl om, hvad der gælder.","efa":"بله. ممکن است دیگران مطمئن نباشند چه قاعده‌ای برقرار است.","en":"I move forward with special care.","een":"Yes. Others may be unsure about what applies."}]},{"id":5175,"img":"newq-art/5175.png","c":"8.1","sda":"Du skal køre en kort tur med en 7-årig pige, der er 125 cm høj, på bagsædet. Hvad gælder?","sfa":"قرار است با دختری ۷ ساله با قد ۱۲۵ سانتی‌متر که روی صندلی عقب نشسته، مسیر کوتاهی بروید. چه قاعده‌ای برقرار است؟","sen":"You are going on a short trip with a 7-year-old girl, 125 cm tall, on the back seat. What applies?","st":[{"da":"Hun skal være spændt fast, også på en kort tur.","fa":"حتی در مسیر کوتاه هم باید کمربندش بسته باشد.","ok":1,"eda":"Ja. Selepligten gælder hele kørslen, uanset hvor kort den er.","efa":"بله. وظیفه‌ی بستن کمربند در تمام مسیر است، هر قدر هم کوتاه باشد.","en":"She must be buckled up, even on a short trip.","een":"Yes. The duty to wear a belt applies to the whole trip, however short."},{"da":"Hun skal bruge godkendt sikkerhedsudstyr, der passer til hendes højde og vægt, fx en selepude med selen.","fa":"باید از تجهیزات ایمنی تأییدشده‌ی متناسب با قد و وزنش استفاده کند، مثلاً تشک‌چه‌ی بالابر با کمربند.","ok":1,"eda":"Ja. Børn under 135 cm skal under kørslen bruge godkendt sikkerhedsudstyr, der passer til barnets højde og vægt.","efa":"بله. کودکان زیر ۱۳۵ سانتی‌متر در حین رانندگی باید از تجهیزات ایمنی تأییدشده‌ی متناسب با قد و وزنشان استفاده کنند.","en":"She must use approved safety equipment that suits her height and weight, for example a booster cushion with the belt.","een":"Yes. Children under 135 cm must use approved safety equipment suited to their height and weight while driving."},{"da":"Hun må sidde uden sele, når hun sidder på bagsædet.","fa":"وقتی روی صندلی عقب نشسته، می‌تواند بدون کمربند بنشیند.","ok":0,"eda":"Nej. Selepligten gælder også på bagsædet.","efa":"خیر. وظیفه‌ی بستن کمربند در صندلی عقب هم هست.","en":"She may sit without a belt when she is on the back seat.","een":"No. The duty to wear a belt applies on the back seat too."},{"da":"Det er mit ansvar som fører, at hun er spændt fast.","fa":"این مسئولیت من به‌عنوان راننده است که کمربندش بسته باشد.","ok":1,"eda":"Ja. Føreren skal påse, at passagerer under 15 år bruger sikkerhedssele.","efa":"بله. راننده باید مراقب باشد مسافران زیر ۱۵ سال کمربند ببندند.","en":"It is my responsibility as the driver that she is buckled up.","een":"Yes. The driver must see to it that passengers under 15 use seat belts."}]},{"id":5176,"img":"newq-art/5176.png","c":"7.4","sda":"Vejen har to vognbaner i din retning før krydset, og du skal ligeud. Hvad gælder?","sfa":"جاده پیش از تقاطع در جهت شما دو خط دارد و می‌خواهید مستقیم بروید. چه قاعده‌ای برقرار است؟","sen":"The road has two lanes in your direction before the junction, and you are going straight on. What applies?","st":[{"da":"Jeg skifter vognbane inde i krydset, hvis den anden vognbane kører hurtigere.","fa":"اگر خط دیگر سریع‌تر حرکت کند، داخل تقاطع خطم را عوض می‌کنم.","ok":0,"eda":"Nej. Et vognbaneskift i krydset kan overraske dem ved siden af dig og skabe fare.","efa":"خیر. تغییر خط داخل تقاطع ممکن است کناری‌ها را غافلگیر کند و خطر بسازد.","en":"I change lanes inside the junction if the other lane is moving faster.","een":"No. A lane change in the junction can surprise those beside you and cause danger."},{"da":"Jeg skal altid bruge den venstre vognbane, når jeg skal ligeud.","fa":"وقتی مستقیم می‌روم، همیشه باید از خط چپ استفاده کنم.","ok":0,"eda":"Nej. Der er ingen sådan regel; vælg den mest hensigtsmæssige vognbane.","efa":"خیر. چنین قاعده‌ای نیست؛ مناسب‌ترین خط را انتخاب کنید.","en":"I must always use the left lane when I am going straight on.","een":"No. There is no such rule; choose the most suitable lane."},{"da":"Jeg kan bruge den vognbane, der passer bedst til trafikken og min videre kørsel.","fa":"می‌توانم از خطی استفاده کنم که با ترافیک و ادامه‌ی مسیرم بیشتر جور است.","ok":1,"eda":"Ja. Skal du ligeud, kan du bruge den vognbane, der er mest hensigtsmæssig.","efa":"بله. اگر مستقیم می‌روید، می‌توانید از مناسب‌ترین خط استفاده کنید.","en":"I can use the lane that best suits the traffic and where I am going next.","een":"Yes. If you are going straight on, you may use the lane that is most suitable."},{"da":"Jeg vælger vognbane i god tid før krydset.","fa":"به موقع پیش از تقاطع خطم را انتخاب می‌کنم.","ok":1,"eda":"Ja. Placeringen skal ske i god tid før vejkrydset.","efa":"بله. قرار گرفتن در خط باید به موقع پیش از تقاطع انجام شود.","en":"I choose my lane in good time before the junction.","een":"Yes. You must take up your position in good time before the junction."}]},{"id":5177,"img":"newq-art/5177.png","c":"7.4","sda":"Mellem din vognbane og vognbanen til venstre er der nu en ubrudt linje. Du vil gerne over i venstre vognbane. Hvad gælder?","sfa":"اکنون بین خط شما و خط سمت چپ یک خط ممتد است. می‌خواهید به خط چپ بروید. چه قاعده‌ای برقرار است؟","sen":"Between your lane and the lane to the left there is now an unbroken line. You would like to move into the left lane. What applies?","st":[{"da":"Linjen gælder kun for lastbiler.","fa":"این خط فقط برای کامیون‌هاست.","ok":0,"eda":"Nej. Linjen gælder alle kørende.","efa":"خیر. این خط برای همه‌ی رانندگان است.","en":"The line only applies to lorries.","een":"No. The line applies to all drivers."},{"da":"Jeg må ikke skifte vognbane over den ubrudte linje.","fa":"نباید از روی خط ممتد تغییر خط بدهم.","ok":1,"eda":"Ja. En spærrelinje adskiller vognbanerne og må ikke overskrides.","efa":"بله. خط ممتد خط‌ها را از هم جدا می‌کند و نباید از آن رد شد.","en":"I must not change lanes across the unbroken line.","een":"Yes. A barrier line separates the lanes and must not be crossed."},{"da":"Jeg må skifte, hvis jeg blinker i god tid.","fa":"اگر به موقع راهنما بزنم، می‌توانم خطم را عوض کنم.","ok":0,"eda":"Nej. Blinklyset gør det ikke tilladt at overskride spærrelinjen.","efa":"خیر. راهنما عبور از خط ممتد را مجاز نمی‌کند.","en":"I may change if I signal in good time.","een":"No. The indicator does not make it allowed to cross the barrier line."}]},{"id":5178,"img":"newq-art/5178.png","c":"7.4","sda":"Du kører forbi denne tavle, og to kørebaner løber sammen længere fremme. Hvad gælder?","sfa":"از کنار این تابلو رد می‌شوید و کمی جلوتر دو سواره‌رو به هم می‌پیوندند. چه قاعده‌ای برقرار است؟","sen":"You pass this sign, and two carriageways join further ahead. What applies?","st":[{"da":"Kørebanerne løber sammen længere fremme.","fa":"سواره‌روها کمی جلوتر به هم می‌پیوندند.","ok":1,"eda":"Ja. Tavlen (B 15) angiver, at kørebaner løber sammen.","efa":"بله. این تابلو (B 15) نشان می‌دهد سواره‌روها به هم می‌پیوندند.","en":"The carriageways join further ahead.","een":"Yes. The sign (B 15) shows that carriageways join."},{"da":"Vi skal under gensidig hensyntagen lette sammenfletningen.","fa":"باید با ملاحظه‌ی متقابل ادغام را آسان کنیم.","ok":1,"eda":"Ja. Ved tavlen skal trafikanterne under gensidig hensyntagen lette sammenfletningen.","efa":"بله. کنار این تابلو کاربران راه باید با ملاحظه‌ی متقابل ادغام را آسان کنند.","en":"We must make the merging easier with mutual consideration.","een":"Yes. At the sign road users must make the merging easier with mutual consideration."},{"da":"Jeg tilpasser farten, så jeg kan flette ind i et hul.","fa":"سرعتم را تنظیم می‌کنم تا در یک فاصله ادغام شوم.","ok":1,"eda":"Ja. Med passende fart og afstand kan begge kørebaners trafik glide sammen.","efa":"بله. با سرعت و فاصله‌ی مناسب، ترافیک هر دو سواره‌رو روان به هم می‌پیوندد.","en":"I adjust my speed so that I can merge into a gap.","een":"Yes. With a suitable speed and distance the traffic from both carriageways can flow together."},{"da":"Den, der kører på den største vej, har altid forkørselsret.","fa":"هر که در جاده‌ی بزرگ‌تر باشد، همیشه حق تقدم دارد.","ok":0,"eda":"Nej. Ved sammenfletning skal begge parter vise hensyn.","efa":"خیر. در ادغام هر دو طرف باید ملاحظه کنند.","en":"Whoever is on the bigger road always has the right of way.","een":"No. When merging, both sides must show consideration."}]},{"id":5179,"img":"newq-art/5179.png","c":"7.1","sda":"Du holder ved kantstenen og vil køre ud. En bil nærmer sig bagfra. Hvordan forholder du dig?","sfa":"کنار جدول ایستاده‌اید و می‌خواهید حرکت کنید. خودرویی از پشت نزدیک می‌شود. چه می‌کنید؟","sen":"You are standing at the kerb and want to drive off. A car is approaching from behind. What do you do?","st":[{"da":"Jeg giver tegn, før jeg kører ud fra kanten.","fa":"پیش از حرکت از کنار جدول علامت می‌دهم.","ok":1,"eda":"Ja. Du skal give tegn før igangsætning fra vejkanten.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید.","en":"I signal before I pull away from the kerb.","een":"Yes. You must signal before pulling away from the edge of the road."},{"da":"Bilen bag mig skal sænke farten, når jeg blinker.","fa":"خودروی پشتی وقتی راهنما بزنم باید سرعتش را کم کند.","ok":0,"eda":"Nej. Blinklyset giver dig ikke ret til at køre ud.","efa":"خیر. راهنما به شما حق حرکت نمی‌دهد.","en":"The car behind me must slow down when I signal.","een":"No. The indicator does not give you the right to pull out."},{"da":"Jeg venter, til bilen er kørt forbi.","fa":"صبر می‌کنم تا آن خودرو رد شود.","ok":1,"eda":"Ja. Du må kun køre ud fra vejkanten, når det kan ske uden fare eller unødig ulempe for andre.","efa":"بله. فقط وقتی می‌توانید از کنار جاده حرکت کنید که برای دیگران خطر یا مزاحمت بی‌جا نداشته باشد.","en":"I wait until the car has gone past.","een":"Yes. You may only pull away from the kerb when it can be done without danger or undue inconvenience to others."},{"da":"Jeg kører hurtigt ud foran bilen.","fa":"سریع جلوی آن خودرو بیرون می‌روم.","ok":0,"eda":"Nej. Bilen kan blive tvunget til at bremse eller svinge ud.","efa":"خیر. ممکن است آن خودرو مجبور به ترمز یا انحراف شود.","en":"I pull out quickly in front of the car.","een":"No. The car may be forced to brake or swerve."}]},{"id":5180,"img":"newq-art/5180.png","c":"7.1","sda":"Du holder ved kantstenen på en stejl vej op ad bakke og skal køre ud. Hvordan forholder du dig?","sfa":"کنار جدول در سربالایی تندی ایستاده‌اید و می‌خواهید حرکت کنید. چه می‌کنید؟","sen":"You are standing at the kerb on a steep road uphill and are going to drive off. What do you do?","st":[{"da":"Det gør ikke noget, at bilen ruller lidt tilbage, når jeg starter.","fa":"اشکالی ندارد اگر خودرو هنگام حرکت کمی به عقب برود.","ok":0,"eda":"Nej. Selv lidt kan være nok til at ramme nogen bag dig.","efa":"خیر. حتی کمی هم ممکن است برای برخورد با کسی پشت سرتان کافی باشد.","en":"It does not matter if the car rolls back a little when I start.","een":"No. Even a little can be enough to hit someone behind you."},{"da":"Jeg giver fuld gas, så jeg hurtigt kommer op ad bakken.","fa":"تا ته گاز می‌دهم تا زود از تپه بالا بروم.","ok":0,"eda":"Nej. Kør roligt ud; fuld gas kan få bilen til at skride eller springe frem.","efa":"خیر. آرام حرکت کنید؛ گاز کامل ممکن است خودرو را بلغزاند یا به جلو پرتاب کند.","en":"I put my foot down so that I get up the hill quickly.","een":"No. Pull away calmly; full throttle can make the car skid or jump forward."},{"da":"Jeg ser mig for og giver tegn, før jeg kører ud.","fa":"پیش از حرکت اطراف را نگاه می‌کنم و علامت می‌دهم.","ok":1,"eda":"Ja. Før igangsætning fra vejkanten skal du give tegn og sikre dig, at det kan ske uden fare.","efa":"بله. پیش از حرکت از کنار جاده باید علامت بدهید و مطمئن شوید بی‌خطر است.","en":"I look around and signal before I pull out.","een":"Yes. Before pulling away from the edge you must signal and make sure it can be done safely."},{"da":"Jeg bruger parkeringsbremsen eller bilens bakkestart, så bilen ikke ruller tilbage.","fa":"از ترمز دستی یا سیستم کمک شروع در سربالایی استفاده می‌کنم تا خودرو به عقب نرود.","ok":1,"eda":"Ja. Ruller bilen tilbage, kan den ramme den bil eller cyklist, der holder bag den.","efa":"بله. اگر خودرو به عقب برود، ممکن است به خودرو یا دوچرخه‌سوار پشتی بخورد.","en":"I use the parking brake or the car's hill-start aid so that the car does not roll back.","een":"Yes. If the car rolls back, it may hit a car or cyclist standing behind it."}]},{"id":5181,"img":"newq-art/5181.png","c":"7.1","sda":"Du vil standse ved kantstenen for at sætte en passager af. Hvordan forholder du dig?","sfa":"می‌خواهید کنار جدول بایستید تا مسافری پیاده شود. چه می‌کنید؟","sen":"You want to stop at the kerb to let a passenger out. What do you do?","st":[{"da":"Jeg ser i spejlet og giver tegn i god tid.","fa":"در آینه نگاه می‌کنم و به موقع علامت می‌دهم.","ok":1,"eda":"Ja. Dem bag dig skal kunne se, at du vil standse.","efa":"بله. پشت‌سری‌ها باید بتوانند ببینند که می‌خواهید بایستید.","en":"I look in the mirror and signal in good time.","een":"Yes. Those behind you must be able to see that you are going to stop."},{"da":"Jeg standser skråt, så jeg hurtigt kan køre ud igen.","fa":"کج می‌ایستم تا زود دوباره حرکت کنم.","ok":0,"eda":"Nej. En skrå bil kan spærre for cyklister og anden trafik.","efa":"خیر. خودروی کج ممکن است راه دوچرخه‌سواران و دیگر ترافیک را ببندد.","en":"I stop at an angle so that I can drive off again quickly.","een":"No. A car at an angle can block cyclists and other traffic."},{"da":"Jeg standser i vejens længderetning tæt ved kørebanens kant.","fa":"در امتداد طول جاده و نزدیک لبه‌ی سواره‌رو می‌ایستم.","ok":1,"eda":"Ja. Ved standsning skal køretøjet anbringes i vejens længderetning ved kørebanens yderkant.","efa":"بله. هنگام توقف، خودرو باید در امتداد طول جاده و کنار لبه‌ی سواره‌رو قرار بگیرد.","en":"I stop lengthwise along the road close to the edge of the carriageway.","een":"Yes. When stopping, the vehicle must be placed lengthwise along the road at the edge of the carriageway."},{"da":"Jeg sikrer mig, at passageren kan stige ud uden fare.","fa":"مطمئن می‌شوم مسافر بی‌خطر پیاده شود.","ok":1,"eda":"Ja. Åbning af døre og afstigning skal ske uden fare eller unødig ulempe.","efa":"بله. باز کردن در و پیاده شدن باید بدون خطر یا مزاحمت بی‌جا باشد.","en":"I make sure that the passenger can get out safely.","een":"Yes. Opening doors and getting out must be done without danger or undue inconvenience."}]},{"id":5182,"img":"newq-art/5182.png","c":"7.2","sda":"Vejen svinger til venstre, og du kan ikke se langt frem. Hvordan placerer du bilen?","sfa":"جاده به چپ می‌پیچد و دور را نمی‌بینید. خودرو را چطور قرار می‌دهید؟","sen":"The road bends to the left, and you cannot see far ahead. How do you position the car?","st":[{"da":"Jeg kører midt på vejen, så jeg kan se længere.","fa":"وسط جاده می‌رانم تا دورتر را ببینم.","ok":0,"eda":"Nej. Midt på vejen risikerer du at møde en modkørende frontalt.","efa":"خیر. وسط جاده خطر برخورد رودررو با خودروی مقابل هست.","en":"I drive in the middle of the road so that I can see further.","een":"No. In the middle of the road you risk meeting an oncoming car head-on."},{"da":"Jeg skærer svinget for at køre mere jævnt.","fa":"پیچ را میان‌بر می‌زنم تا نرم‌تر برانم.","ok":0,"eda":"Nej. Så kommer du over i den modkørendes side, hvor du ikke kan se, hvad der kommer.","efa":"خیر. این‌طور وارد سمت مقابل می‌شوید، جایی که نمی‌بینید چه می‌آید.","en":"I cut the corner to drive more smoothly.","een":"No. Then you move into the oncoming side, where you cannot see what is coming."},{"da":"Jeg holder mig i højre side af min vognbane.","fa":"در سمت راست خط خودم می‌مانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt; i et venstresving kan en modkørende være tæt på midterlinjen.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند؛ در پیچ به چپ ممکن است خودروی روبه‌رو نزدیک خط وسط باشد.","en":"I keep to the right-hand side of my lane.","een":"Yes. Drivers must keep as far right as possible; in a left bend an oncoming car may be close to the centre line."}]},{"id":5183,"img":"newq-art/5183.png","c":"7.2","sda":"Du kører uden for byen på en vej med to vognbaner i din retning og har ikke tænkt dig at overhale. Hvor kører du?","sfa":"بیرون از شهر در جاده‌ای با دو خط در جهت خودتان می‌رانید و قصد سبقت ندارید. کجا می‌رانید؟","sen":"You are driving outside town on a road with two lanes in your direction and are not planning to overtake. Where do you drive?","st":[{"da":"I venstre vognbane, fordi den er hurtigst.","fa":"در خط چپ، چون سریع‌تر است.","ok":0,"eda":"Nej. Du må kun ligge i venstre vognbane, mens du overhaler.","efa":"خیر. فقط هنگام سبقت می‌توانید در خط چپ باشید.","en":"In the left lane, because it is the fastest.","een":"No. You may only be in the left lane while you are overtaking."},{"da":"I den vognbane, hvor der er færrest biler.","fa":"در خطی که خودروی کمتری دارد.","ok":0,"eda":"Nej. Hovedreglen er at holde til højre.","efa":"خیر. قاعده‌ی اصلی سمت راست ماندن است.","en":"In the lane with the fewest cars.","een":"No. The main rule is to keep right."},{"da":"Midt mellem vognbanerne, så jeg kan vælge senere.","fa":"وسط دو خط، تا بعداً انتخاب کنم.","ok":0,"eda":"Nej. Du skal køre inden for én vognbane.","efa":"خیر. باید داخل یک خط برانید.","en":"In the middle between the lanes, so that I can choose later.","een":"No. You must drive within one lane."},{"da":"I højre vognbane.","fa":"در خط راست.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt; venstre vognbane bruges til at overhale.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند؛ خط چپ برای سبقت است.","en":"In the right-hand lane.","een":"Yes. Drivers must keep as far right as possible; the left lane is used for overtaking."}]},{"id":5184,"img":"newq-art/5184.png","c":"7.2","sda":"Vejen har ingen midterlinje, men er bred nok til to biler. Hvordan placerer du dig?","sfa":"جاده خط وسط ندارد، ولی برای دو خودرو جا دارد. خودتان را چطور قرار می‌دهید؟","sen":"The road has no centre line but is wide enough for two cars. How do you position yourself?","st":[{"da":"Jeg giver manden med hunden god plads, når jeg kører forbi.","fa":"هنگام عبور جای زیادی به مرد و سگش می‌دهم.","ok":1,"eda":"Ja. Du skal give gående tid til at vige og fornøden plads.","efa":"بله. باید به عابران فرصت کنار رفتن و جای لازم بدهید.","en":"I give the man with the dog plenty of room when I pass.","een":"Yes. You must give pedestrians time to step aside and the room they need."},{"da":"Jeg kører midt på vejen, når der ikke er en midterlinje.","fa":"وقتی خط وسط نیست، وسط جاده می‌رانم.","ok":0,"eda":"Nej. Så kan du møde en modkørende, der heller ikke kan se dig, fx i svinget.","efa":"خیر. این‌طور ممکن است با خودروی مقابلی روبه‌رو شوید که شما را نمی‌بیند، مثلاً در پیچ.","en":"I drive in the middle of the road when there is no centre line.","een":"No. Then you may meet an oncoming car that cannot see you either, for example in the bend."},{"da":"Jeg er særligt opmærksom på modkørende i svinget.","fa":"در پیچ به ترافیک روبه‌رو توجه ویژه دارم.","ok":1,"eda":"Ja. Uden midterlinje kan modkørende ligge tæt på midten af vejen.","efa":"بله. بدون خط وسط، خودروهای روبه‌رو ممکن است نزدیک وسط جاده باشند.","en":"I pay special attention to oncoming traffic in the bend.","een":"Yes. Without a centre line oncoming cars may be close to the middle of the road."},{"da":"Jeg holder så langt til højre, som forholdene tillader.","fa":"تا جایی که شرایط اجازه دهد سمت راست می‌مانم.","ok":1,"eda":"Ja. Reglen om at holde til højre gælder, også når der ikke er en midterlinje.","efa":"بله. قاعده‌ی سمت راست ماندن حتی وقتی خط وسط نیست برقرار است.","en":"I keep as far to the right as the conditions allow.","een":"Yes. The keep-right rule applies even when there is no centre line."}]},{"id":5185,"img":"newq-art/5185.png","c":"7.19","sda":"Du kører på en mørk landevej uden gadelys. Ingen kommer imod dig, og der kører ingen foran dig. Hvilket lys bruger du?","sfa":"در جاده‌ای تاریک و بدون چراغ خیابان می‌رانید. کسی از روبه‌رو نمی‌آید و کسی هم جلوی شما نیست. از کدام چراغ استفاده می‌کنید؟","sen":"You are driving on a dark country road without street lights. Nobody is coming towards you, and nobody is driving in front of you. Which lights do you use?","st":[{"da":"Jeg blænder ned i god tid, når der kommer en modkørende.","fa":"وقتی وسیله‌ای از روبه‌رو پیدا شد، به موقع نور را پایین می‌آورم.","ok":1,"eda":"Ja. Fjernlys må ikke bruges ved møde, hvor den modkørende kan blændes.","efa":"بله. هنگام برخورد با وسیله‌ای که ممکن است خیره شود، نور بالا ممنوع است.","en":"I dip in good time when an oncoming vehicle appears.","een":"Yes. High beam must not be used when meeting someone who could be dazzled."},{"da":"Fjernlys, når nærlyset ikke lyser langt nok frem til min fart.","fa":"نور بالا، وقتی نور پایین برای سرعتم به اندازه‌ی کافی دور را روشن نمی‌کند.","ok":1,"eda":"Ja. Fjernlys skal bruges, når førerens synsvidde under hensyn til hastigheden ellers er utilstrækkelig.","efa":"بله. وقتی دید راننده با توجه به سرعت در غیر این صورت کافی نیست، باید از نور بالا استفاده کرد.","en":"High beam, when the dipped beam does not reach far enough ahead for my speed.","een":"Yes. High beam must be used when the driver's range of vision would otherwise be too short for the speed."},{"da":"Jeg kører altid med nærlys om natten for ikke at genere nogen.","fa":"شب‌ها همیشه با نور پایین می‌رانم تا مزاحم کسی نشوم.","ok":0,"eda":"Nej. Er udsynet for kort til farten, skal du bruge fjernlys eller køre langsommere.","efa":"خیر. اگر دیدتان برای سرعتتان کوتاه است، باید از نور بالا استفاده کنید یا آهسته‌تر برانید.","en":"I always drive with dipped beam at night so as not to bother anyone.","een":"No. If your view is too short for your speed, you must use high beam or drive more slowly."},{"da":"Fjernlys må kun bruges på motorvej.","fa":"نور بالا فقط در بزرگراه مجاز است.","ok":0,"eda":"Nej. Fjernlys bruges på alle uoplyste veje, når der er behov for det.","efa":"خیر. نور بالا در همه‌ی جاده‌های بی‌چراغ، وقتی لازم باشد، استفاده می‌شود.","en":"High beam may only be used on the motorway.","een":"No. High beam is used on all unlit roads when it is needed."}]},{"id":5186,"img":"newq-art/5186.png","c":"7.19","sda":"Hvad gælder om bilens lys?","sfa":"درباره‌ی چراغ‌های خودرو چه قاعده‌ای برقرار است؟","sen":"What applies to the car's lights?","st":[{"da":"Om dagen må jeg køre helt uden lys.","fa":"روزها می‌توانم کاملاً بدون چراغ برانم.","ok":0,"eda":"Nej. Bilen skal også om dagen køre med lys.","efa":"خیر. خودرو روزها هم باید با چراغ حرکت کند.","en":"In the daytime I may drive with no lights at all.","een":"No. The car must have lights on in the daytime too."},{"da":"I lygtetændingstiden, fra solnedgang til solopgang, skal de påbudte lygter være tændt.","fa":"در زمان روشن کردن چراغ‌ها، از غروب تا طلوع، چراغ‌های الزامی باید روشن باشند.","ok":1,"eda":"Ja. Lygtetændingstiden er fra solnedgang til solopgang.","efa":"بله. زمان روشن کردن چراغ‌ها از غروب تا طلوع آفتاب است.","en":"During lighting-up time, from sunset to sunrise, the required lights must be on.","een":"Yes. Lighting-up time is from sunset to sunrise."},{"da":"Lygtetændingstiden er kun fra midnat til kl. 5.","fa":"زمان روشن کردن چراغ‌ها فقط از نیمه‌شب تا ساعت ۵ است.","ok":0,"eda":"Nej. Den følger solen: fra solnedgang til solopgang.","efa":"خیر. این زمان از خورشید پیروی می‌کند: از غروب تا طلوع.","en":"Lighting-up time is only from midnight to 5 am.","een":"No. It follows the sun: from sunset to sunrise."},{"da":"Også om dagen skal bilen køre med nærlys eller kørelys.","fa":"روزها هم خودرو باید با نور پایین یا چراغ روز حرکت کند.","ok":1,"eda":"Ja. Uden for lygtetændingstiden skal der køres med nærlys eller kørelys.","efa":"بله. بیرون از زمان روشن کردن چراغ‌ها باید با نور پایین یا چراغ روز رانندگی کرد.","en":"In the daytime too the car must drive with dipped beam or daytime running lights.","een":"Yes. Outside lighting-up time you must drive with dipped beam or daytime running lights."}]},{"id":5187,"img":"newq-art/5187.png","c":"7.19","sda":"Det er tørt og klart vejr i mørke. Hvad gælder om tågelygterne?","sfa":"در تاریکی، هوا خشک و صاف است. درباره‌ی چراغ‌های مه‌شکن چه قاعده‌ای برقرار است؟","sen":"It is dry and clear weather in the dark. What applies to the fog lights?","st":[{"da":"Tågebaglygten må altid være tændt i mørke.","fa":"چراغ مه‌شکن عقب در تاریکی همیشه می‌تواند روشن باشد.","ok":0,"eda":"Nej. Den kraftige tågebaglygte blænder dem bag dig i klart vejr.","efa":"خیر. چراغ مه‌شکن پرنور عقب، در هوای صاف پشت‌سری‌ها را خیره می‌کند.","en":"The rear fog light may always be on in the dark.","een":"No. The bright rear fog light dazzles those behind you in clear weather."},{"da":"Jeg må bruge dem i stedet for nærlys, når jeg vil se bedre.","fa":"وقتی بخواهم بهتر ببینم، می‌توانم به‌جای نور پایین از آن‌ها استفاده کنم.","ok":0,"eda":"Nej. Det må de kun i tåge og under kraftig nedbør.","efa":"خیر. این کار فقط در مه و بارش شدید مجاز است.","en":"I may use them instead of dipped beam when I want to see better.","een":"No. They may only do that in fog and heavy precipitation."},{"da":"Tågelygter må bruges, når vejen er våd.","fa":"وقتی جاده خیس است، چراغ مه‌شکن مجاز است.","ok":0,"eda":"Nej. En våd vej er ikke tåge eller kraftig nedbør.","efa":"خیر. جاده‌ی خیس به معنای مه یا بارش شدید نیست.","en":"Fog lights may be used when the road is wet.","een":"No. A wet road is not fog or heavy precipitation."},{"da":"Jeg må ikke bruge dem, fordi der ikke er tåge eller kraftig nedbør.","fa":"نباید از آن‌ها استفاده کنم، چون مه یا بارش شدیدی نیست.","ok":1,"eda":"Ja. Tågelygter må kun bruges i tåge og under kraftig nedbør.","efa":"بله. چراغ مه‌شکن فقط در مه و بارش شدید مجاز است.","en":"I must not use them because there is no fog or heavy precipitation.","een":"Yes. Fog lights may only be used in fog and heavy precipitation."}]},{"id":5188,"img":"newq-art/5188.png","c":"7.16","sda":"Du skal forlade motorvejen ved den næste frakørsel. Hvordan forholder du dig?","sfa":"می‌خواهید در خروجی بعدی از بزرگراه خارج شوید. چه می‌کنید؟","sen":"You are going to leave the motorway at the next exit. What do you do?","st":[{"da":"Jeg sætter farten ned på frakørselsbanen og ikke på motorvejen.","fa":"سرعتم را در خط خروج کم می‌کنم، نه در بزرگراه.","ok":1,"eda":"Ja. Så generer du ikke trafikken på motorvejen.","efa":"بله. این‌طور مزاحم ترافیک بزرگراه نمی‌شوید.","en":"I slow down in the exit lane, not on the motorway.","een":"Yes. That way you do not hold up the traffic on the motorway."},{"da":"Jeg holder øje med farten, fordi frakørselsvejen kan ende i et skarpt sving.","fa":"مراقب سرعتم هستم، چون راه خروجی ممکن است به پیچ تندی برسد.","ok":1,"eda":"Ja. Efter motorvejen føles farten lavere, end den er.","efa":"بله. بعد از بزرگراه سرعت کمتر از مقدار واقعی‌اش حس می‌شود.","en":"I watch my speed because the exit road may end in a sharp bend.","een":"Yes. After the motorway your speed feels lower than it is."},{"da":"Jeg kører ind på frakørselsbanen, så snart den begynder.","fa":"به محض شروع خط خروج واردش می‌شوم.","ok":1,"eda":"Ja. Frakørselsbanen skal benyttes med det samme, når den begynder.","efa":"بله. از خط خروج باید به محض شروعش استفاده کرد.","en":"I move into the exit lane as soon as it begins.","een":"Yes. The exit lane must be used straight away, as soon as it begins."},{"da":"Jeg giver tegn i god tid, før jeg skifter over på frakørselsbanen.","fa":"پیش از رفتن به خط خروج، به موقع راهنما می‌زنم.","ok":1,"eda":"Ja. På motorvej skal du give tegn før et vognbaneskift.","efa":"بله. در بزرگراه پیش از تغییر خط باید علامت بدهید.","en":"I signal in good time before I move over into the exit lane.","een":"Yes. On the motorway you must signal before a lane change."}]},{"id":5189,"img":"newq-art/5189.png","c":"7.16","sda":"Du kører på motorvejen med to vognbaner i din retning. Hvad gælder?","sfa":"در بزرگراهی با دو خط در جهت خودتان می‌رانید. چه قاعده‌ای برقرار است؟","sen":"You are driving on the motorway with two lanes in your direction. What applies?","st":[{"da":"Jeg giver tegn, før jeg skifter vognbane.","fa":"پیش از تغییر خط علامت می‌دهم.","ok":1,"eda":"Ja. På motorvej skal der gives tegn før vognbaneskift.","efa":"بله. در بزرگراه پیش از تغییر خط باید علامت داد.","en":"I signal before I change lanes.","een":"Yes. On the motorway a signal must be given before a lane change."},{"da":"Jeg kører i højre vognbane, når jeg ikke overhaler.","fa":"وقتی سبقت نمی‌گیرم، در خط راست می‌رانم.","ok":1,"eda":"Ja. Kørende skal holde så langt til højre som muligt.","efa":"بله. رانندگان باید تا جای ممکن سمت راست بمانند.","en":"I drive in the right lane when I am not overtaking.","een":"Yes. Drivers must keep as far to the right as possible."},{"da":"Jeg må blive i venstre vognbane, så længe jeg kører 130 km/t.","fa":"تا وقتی ۱۳۰ می‌رانم، می‌توانم در خط چپ بمانم.","ok":0,"eda":"Nej. Fart giver ingen ret til at blive i venstre vognbane.","efa":"خیر. سرعت حق ماندن در خط چپ را نمی‌دهد.","en":"I may stay in the left lane as long as I am doing 130 km/h.","een":"No. Speed gives no right to stay in the left lane."},{"da":"Jeg må køre i nødsporet, når der er kø.","fa":"وقتی صف است، می‌توانم در شانه‌ی اضطراری برانم.","ok":0,"eda":"Nej. Nødsporet er til nødsituationer, ikke til at køre forbi en kø.","efa":"خیر. شانه‌ی اضطراری برای مواقع اضطراری است، نه برای عبور از کنار صف.","en":"I may drive on the hard shoulder when there is a queue.","een":"No. The hard shoulder is for emergencies, not for driving past a queue."}]},{"id":5190,"img":"newq-art/5190.png","c":"6.2","sda":"Hvornår må du bruge bilens horn?","sfa":"کی می‌توانید از بوق خودرو استفاده کنید؟","sen":"When may you use the car's horn?","st":[{"da":"I lygtetændingstiden skal jeg bruge lyssignal i stedet, medmindre faren er overhængende.","fa":"در زمان روشن کردن چراغ‌ها باید به‌جای بوق چراغ بزنم، مگر خطر فوری باشد.","ok":1,"eda":"Ja. I lygtetændingstiden skal fører af motorkøretøj bruge lyssignal i stedet for lydsignal, medmindre faren er overhængende.","efa":"بله. در زمان روشن کردن چراغ‌ها راننده‌ی وسیله‌ی موتوری باید به‌جای بوق چراغ بزند، مگر خطر فوری باشد.","en":"During lighting-up time I must use a light signal instead, unless the danger is immediate.","een":"Yes. During lighting-up time the driver of a motor vehicle must use a light signal instead of the horn, unless the danger is immediate."},{"da":"For at få bilen foran til at køre, når lyset bliver grønt.","fa":"برای این‌که خودروی جلو با سبز شدن چراغ حرکت کند.","ok":0,"eda":"Nej. At skynde på andre er ikke at afværge fare.","efa":"خیر. عجله‌ دادن به دیگران دفع خطر نیست.","en":"To make the car in front go when the light turns green.","een":"No. Hurrying others is not averting danger."},{"da":"Når det er nødvendigt for at forebygge eller afværge fare.","fa":"وقتی برای پیشگیری یا دفع خطر لازم باشد.","ok":1,"eda":"Ja. Lydsignal må kun bruges, når det er nødvendigt for at forebygge eller afværge fare, og ikke længere end nødvendigt.","efa":"بله. بوق فقط وقتی مجاز است که برای پیشگیری یا دفع خطر لازم باشد، و نه بیشتر از حد لازم.","en":"When it is necessary to prevent or avert danger.","een":"Yes. The horn may only be used when it is necessary to prevent or avert danger, and no longer than necessary."},{"da":"For at hilse på en ven.","fa":"برای سلام کردن به یک دوست.","ok":0,"eda":"Nej. Hornet må ikke bruges til andet end at afværge fare.","efa":"خیر. از بوق فقط برای دفع خطر می‌توان استفاده کرد.","en":"To greet a friend.","een":"No. The horn must not be used for anything other than averting danger."}]},{"id":5191,"img":"newq-art/5191.png","c":"6.2","sda":"Du har grønt lys, men en brandbil med blå blink og sirene er ved at køre ind i krydset fra venstre. Hvordan forholder du dig?","sfa":"چراغ شما سبز است، ولی یک ماشین آتش‌نشانی با چراغ آبی و آژیر از چپ وارد تقاطع می‌شود. چه می‌کنید؟","sen":"You have a green light, but a fire engine with flashing blue lights and siren is about to drive into the junction from the left. What do you do?","st":[{"da":"Jeg holder tilbage og lader brandbilen komme igennem.","fa":"صبر می‌کنم و می‌گذارم ماشین آتش‌نشانی رد شود.","ok":1,"eda":"Ja. Kørende skal holde vejen åben for et udrykningskøretøj og om nødvendigt standse.","efa":"بله. رانندگان باید راه را برای خودروی امدادی باز نگه دارند و در صورت لزوم بایستند.","en":"I hold back and let the fire engine through.","een":"Yes. Drivers must keep the road open for an emergency vehicle and stop if necessary."},{"da":"Jeg holder øje med, om der kommer flere udrykningskøretøjer.","fa":"مراقبم که خودروهای امدادی دیگری هم می‌آیند یا نه.","ok":1,"eda":"Ja. Udrykningskøretøjer kører ofte flere sammen.","efa":"بله. خودروهای امدادی اغلب چندتایی با هم می‌آیند.","en":"I watch whether more emergency vehicles are coming.","een":"Yes. Emergency vehicles often come several at a time."},{"da":"Jeg gør det i god tid, så brandbilen ikke skal bremse.","fa":"این کار را به موقع انجام می‌دهم تا ماشین آتش‌نشانی مجبور به ترمز نشود.","ok":1,"eda":"Ja. Vejen skal holdes åben i god tid.","efa":"بله. راه باید به موقع باز نگه داشته شود.","en":"I do it in good time so that the fire engine does not have to brake.","een":"Yes. The road must be kept open in good time."},{"da":"Jeg kører, fordi jeg har grønt lys.","fa":"حرکت می‌کنم، چون چراغم سبز است.","ok":0,"eda":"Nej. Grønt lys giver ikke ret til at spærre for et udrykningskøretøj.","efa":"خیر. چراغ سبز حق بستن راه خودروی امدادی را نمی‌دهد.","en":"I go because I have a green light.","een":"No. A green light gives no right to block an emergency vehicle."}]},{"id":5192,"img":"newq-art/5192.png","c":"7.15","sda":"Du kører ind i en rundkørsel med denne blå tavle. Hvad gælder?","sfa":"وارد میدانی با این تابلوی آبی می‌شوید. چه قاعده‌ای برقرار است؟","sen":"You are entering a roundabout with this blue sign. What applies?","st":[{"da":"Tavlen betyder, at jeg har forkørselsret i rundkørslen.","fa":"این تابلو یعنی در میدان حق تقدم با من است.","ok":0,"eda":"Nej. Tavlen siger kun noget om retningen; ved indkørslen har du her ubetinget vigepligt.","efa":"خیر. این تابلو فقط درباره‌ی جهت است؛ این‌جا هنگام ورود باید بی‌قیدوشرط راه بدهید.","en":"The sign means that I have the right of way in the roundabout.","een":"No. The sign only says something about direction; at the entry here you must give way unconditionally."},{"da":"Jeg må køre den korteste vej til venstre om øen.","fa":"می‌توانم از کوتاه‌ترین راه از سمت چپ جزیره بروم.","ok":0,"eda":"Nej. Det er at køre mod den påbudte retning.","efa":"خیر. این یعنی رانندگی خلاف جهت اجباری.","en":"I may take the shortest way round the island to the left.","een":"No. That is driving against the required direction."},{"da":"Tavlen viser den påbudte kørselsretning i rundkørslen.","fa":"این تابلو جهت اجباری حرکت در میدان را نشان می‌دهد.","ok":1,"eda":"Ja. Den blå tavle (D 12) er et påbud om kørselsretningen i rundkørslen.","efa":"بله. تابلوی آبی (D 12) دستوری درباره‌ی جهت حرکت در میدان است.","en":"The sign shows the required direction in the roundabout.","een":"Yes. The blue sign (D 12) is an order about the direction in the roundabout."},{"da":"Jeg kører rundt med midterøen på min venstre side.","fa":"با جزیره‌ی وسط در سمت چپم دور میدان می‌چرخم.","ok":1,"eda":"Ja. Kørende skal holde til højre for helleanlæg og lignende, så rundkørslen køres mod uret.","efa":"بله. رانندگان باید سمت راست جزیره‌ها بمانند، پس میدان خلاف جهت عقربه‌های ساعت دور زده می‌شود.","en":"I drive round with the central island on my left.","een":"Yes. Drivers must keep to the right of islands and the like, so the roundabout is driven anticlockwise."}]},{"id":5193,"img":"newq-art/5193.png","c":"7.15","sda":"Foran dig i rundkørslen kører en lang lastbil. Hvordan forholder du dig?","sfa":"جلوی شما در میدان یک کامیون بلند حرکت می‌کند. چه می‌کنید؟","sen":"A long lorry is driving in front of you in the roundabout. What do you do?","st":[{"da":"Jeg holder god afstand og kører ikke op ved siden af lastbilen.","fa":"فاصله‌ی خوبی نگه می‌دارم و کنار کامیون نمی‌روم.","ok":1,"eda":"Ja. Ved siden af lastbilen kan du blive klemt, når den svinger.","efa":"بله. کنار کامیون ممکن است هنگام پیچیدنش گیر بیفتید.","en":"I keep a good distance and do not drive up beside the lorry.","een":"Yes. Beside the lorry you may get squeezed when it turns."},{"da":"Lastbilen kan have brug for hele rundkørslens bredde.","fa":"کامیون ممکن است به تمام عرض میدان نیاز داشته باشد.","ok":1,"eda":"Ja. Lange køretøjer skærer svinget og kan køre over den brostensbelagte kant ved midterøen.","efa":"بله. وسایل بلند از داخل پیچ می‌گذرند و ممکن است از روی حلقه‌ی سنگ‌فرش کنار جزیره رد شوند.","en":"The lorry may need the whole width of the roundabout.","een":"Yes. Long vehicles cut the corner and may drive over the cobbled ring by the island."},{"da":"Lastbilen skal holde helt ind til højre kant hele vejen rundt.","fa":"کامیون باید تمام مسیر کاملاً به لبه‌ی راست بچسبد.","ok":0,"eda":"Nej. Det kan en lang lastbil ikke; dens bagende skærer svinget.","efa":"خیر. کامیون بلند نمی‌تواند؛ قسمت عقبش از داخل پیچ می‌گذرد.","en":"The lorry must keep right in to the right edge all the way round.","een":"No. A long lorry cannot do that; its rear cuts the corner."},{"da":"Jeg overhaler lastbilen i rundkørslen.","fa":"در میدان از کامیون سبقت می‌گیرم.","ok":0,"eda":"Nej. I en rundkørsel med én vognbane er der ikke plads til at overhale lastbilen sikkert.","efa":"خیر. در میدان یک‌خطه جای کافی برای سبقت ایمن از کامیون نیست.","en":"I overtake the lorry in the roundabout.","een":"No. In a single-lane roundabout there is no room to overtake the lorry safely."}]},{"id":5194,"img":"newq-art/5194.png","c":"5.2","sda":"Det er efterår, og der ligger våde blade på vejen. Hvordan forholder du dig?","sfa":"پاییز است و برگ‌های خیس روی جاده ریخته است. چه می‌کنید؟","sen":"It is autumn, and there are wet leaves on the road. What do you do?","st":[{"da":"Jeg regner med, at vejen kan være glat.","fa":"انتظار دارم جاده لغزنده باشد.","ok":1,"eda":"Ja. Våde blade kan gøre vejen lige så glat som is.","efa":"بله. برگ‌های خیس می‌توانند جاده را به لغزندگی یخ کنند.","en":"I expect that the road may be slippery.","een":"Yes. Wet leaves can make the road as slippery as ice."},{"da":"Jeg bremser blødt og undgår at dreje brat.","fa":"نرم ترمز می‌کنم و از فرمان دادن تند پرهیز می‌کنم.","ok":1,"eda":"Ja. Bratte manøvrer kan få bilen til at skride.","efa":"بله. حرکات ناگهانی ممکن است خودرو را بلغزاند.","en":"I brake gently and avoid steering sharply.","een":"Yes. Sharp manoeuvres can make the car skid."},{"da":"Blade har ingen betydning for bremselængden.","fa":"برگ‌ها روی مسافت ترمز اثری ندارند.","ok":0,"eda":"Nej. Blade, især våde, nedsætter dækkenes greb.","efa":"خیر. برگ‌ها، به‌ویژه خیس، چسبندگی لاستیک را کم می‌کنند.","en":"Leaves make no difference to the braking distance.","een":"No. Leaves, especially wet ones, reduce the tyres' grip."},{"da":"Jeg sænker farten og holder større afstand.","fa":"سرعتم را کم می‌کنم و فاصله‌ی بیشتری نگه می‌دارم.","ok":1,"eda":"Ja. På glat vej bliver bremselængden længere.","efa":"بله. روی جاده‌ی لغزنده مسافت ترمز بیشتر می‌شود.","en":"I slow down and keep a greater distance.","een":"Yes. On a slippery road the braking distance gets longer."}]},{"id":5195,"img":"newq-art/5195.png","c":"7.8","sda":"Hvordan kan du vurdere, om du holder en passende afstand til bilen foran på landevejen?","sfa":"در جاده‌ی بیرون شهر چطور می‌توانید بسنجید که فاصله‌ی مناسبی با خودروی جلو دارید؟","sen":"How can you judge whether you are keeping a suitable distance to the car in front on a country road?","st":[{"da":"En anden tommelfingerregel er en afstand i meter på det halve af farten, fx 40 m ved 80 km/t.","fa":"قاعده‌ی دیگر فاصله‌ای به متر برابر نصف سرعت است، مثلاً ۴۰ متر در ۸۰ کیلومتر بر ساعت.","ok":1,"eda":"Ja. Begge tommelfingerregler giver omtrent samme afstand.","efa":"بله. هر دو قاعده تقریباً همان فاصله را می‌دهند.","en":"Another rule of thumb is a distance in metres of half the speed, for example 40 m at 80 km/h.","een":"Yes. Both rules of thumb give roughly the same distance."},{"da":"Det er nok, at jeg kan se bilens baglygter.","fa":"کافی است چراغ‌های عقب آن خودرو را ببینم.","ok":0,"eda":"Nej. Afstanden skal være så stor, at der ikke er fare for påkørsel, hvis bilen foran bremser.","efa":"خیر. فاصله باید آن‌قدر باشد که اگر خودروی جلو ترمز کرد، خطر تصادف نباشد.","en":"It is enough that I can see the car's rear lights.","een":"No. The distance must be so great that there is no risk of a collision if the car in front brakes."},{"da":"På våd eller glat vej holder jeg større afstand.","fa":"در جاده‌ی خیس یا لغزنده فاصله‌ی بیشتری نگه می‌دارم.","ok":1,"eda":"Ja. Bremselængden er længere, når vejen er våd eller glat.","efa":"بله. وقتی جاده خیس یا لغزنده است، مسافت ترمز بیشتر است.","en":"On a wet or slippery road I keep a greater distance.","een":"Yes. The braking distance is longer when the road is wet or slippery."},{"da":"Jeg holder mindst 2 sekunders afstand i godt føre.","fa":"در شرایط خوب دست‌کم ۲ ثانیه فاصله نگه می‌دارم.","ok":1,"eda":"Ja. To sekunder er en god tommelfingerregel: når bilen foran passerer et fast punkt, skal du kunne tælle til to, før du selv er der.","efa":"بله. دو ثانیه قاعده‌ی خوبی است: وقتی خودروی جلو از یک نقطه‌ی ثابت رد شد، باید بتوانید تا دو بشمارید تا خودتان به آن برسید.","en":"I keep at least 2 seconds' distance in good conditions.","een":"Yes. Two seconds is a good rule of thumb: when the car ahead passes a fixed point, you should be able to count to two before you get there."}]},{"id":5196,"img":"newq-art/5196.png","c":"7.5","sda":"Du vil vende på en bred vej uden for byen. Hvordan forholder du dig?","sfa":"می‌خواهید در جاده‌ای پهن بیرون از شهر دور بزنید. چه می‌کنید؟","sen":"You want to turn round on a wide road outside town. What do you do?","st":[{"da":"Jeg sikrer mig, at det kan ske uden fare eller ulempe for andre.","fa":"مطمئن می‌شوم که برای دیگران خطر یا مزاحمتی ندارد.","ok":1,"eda":"Ja. Før vending skal du sikre dig, at manøvren kan udføres uden fare eller ulempe for andre.","efa":"بله. پیش از دور زدن باید مطمئن شوید که برای دیگران خطر یا مزاحمتی ندارد.","en":"I make sure that it can be done without danger or inconvenience to others.","een":"Yes. Before turning round you must make sure the manoeuvre can be done without danger or inconvenience to others."},{"da":"Jeg må vende ved bakketoppen, hvis jeg skynder mig.","fa":"اگر عجله کنم، می‌توانم بالای تپه دور بزنم.","ok":0,"eda":"Nej. Ved en bakketop kan du ikke se, om der kommer nogen, så vendingen kan ikke ske uden fare.","efa":"خیر. بالای تپه نمی‌بینید کسی می‌آید یا نه، پس دور زدن بی‌خطر نیست.","en":"I may turn round at the hilltop if I hurry.","een":"No. At a hilltop you cannot see whether anyone is coming, so turning round cannot be done safely."},{"da":"Jeg vender forlæns til venstre.","fa":"رو به جلو و به سمت چپ دور می‌زنم.","ok":1,"eda":"Ja. Vending skal ske forlæns til venstre.","efa":"بله. دور زدن باید رو به جلو و به سمت چپ انجام شود.","en":"I turn round forwards to the left.","een":"Yes. Turning round must be done forwards to the left."},{"da":"Jeg må vende på motorvejen, når der ikke er trafik.","fa":"وقتی ترافیک نیست، می‌توانم در بزرگراه دور بزنم.","ok":0,"eda":"Nej. Vending er altid forbudt på motorvej.","efa":"خیر. دور زدن در بزرگراه همیشه ممنوع است.","en":"I may turn round on the motorway when there is no traffic.","een":"No. Turning round is always forbidden on the motorway."}]},{"id":5197,"img":"newq-art/5197.png","c":"1.2","sda":"Det har frosset i nat, og der er is på bilens ruder. Hvordan forholder du dig, før du kører?","sfa":"دیشب یخبندان بوده و روی شیشه‌های خودرو یخ بسته است. پیش از رانندگی چه می‌کنید؟","sen":"It froze last night, and there is ice on the car's windows. What do you do before you drive?","st":[{"da":"Jeg skraber alle ruderne helt fri.","fa":"همه‌ی شیشه‌ها را کاملاً تمیز می‌کنم.","ok":1,"eda":"Ja. Du skal have frit udsyn til alle sider.","efa":"بله. باید از همه طرف دید آزاد داشته باشید.","en":"I scrape all the windows completely clear.","een":"Yes. You must have a clear view on all sides."},{"da":"Jeg venter med at køre, til ruderne er klare, hvis isen ikke kan skrabes af.","fa":"اگر یخ کنده نشود، صبر می‌کنم تا شیشه‌ها شفاف شوند و بعد راه می‌افتم.","ok":1,"eda":"Ja. Bilen må ikke bruges, før den kan køres uden fare.","efa":"بله. تا وقتی خودرو را نتوان بی‌خطر راند، نباید از آن استفاده کرد.","en":"I wait to drive until the windows are clear if the ice cannot be scraped off.","een":"Yes. The car must not be used until it can be driven without danger."},{"da":"Jeg gør også spejlene og lygterne rene.","fa":"آینه‌ها و چراغ‌ها را هم تمیز می‌کنم.","ok":1,"eda":"Ja. Spejlene skal kunne bruges, og lygterne skal kunne ses.","efa":"بله. آینه‌ها باید قابل استفاده و چراغ‌ها قابل دیدن باشند.","en":"I clean the mirrors and lights too.","een":"Yes. The mirrors must be usable and the lights must be visible."},{"da":"Det er nok at skrabe et lille hul foran føreren.","fa":"کافی است سوراخ کوچکی جلوی راننده باز کنم.","ok":0,"eda":"Nej. Gennem et lille hul kan du ikke se cyklister og biler fra siden.","efa":"خیر. از یک سوراخ کوچک دوچرخه‌سواران و خودروهای کناری را نمی‌بینید.","en":"Scraping a small hole in front of the driver is enough.","een":"No. Through a small hole you cannot see cyclists and cars from the side."}]},{"id":5198,"img":"newq-art/5198.png","c":"1.2","sda":"Bilen er tungt lastet bagi, og nærlyset peger højere end normalt. Hvad gør du?","sfa":"صندوق عقب خودرو پر از بار سنگین است و نور پایین بالاتر از معمول می‌تابد. چه می‌کنید؟","sen":"The car is heavily loaded at the back, and the dipped beam points higher than normal. What do you do?","st":[{"da":"Jeg kører med fjernlys i stedet.","fa":"به‌جایش با نور بالا می‌رانم.","ok":0,"eda":"Nej. Fjernlyset blænder endnu mere.","efa":"خیر. نور بالا حتی بیشتر خیره می‌کند.","en":"I drive with high beam instead.","een":"No. The high beam dazzles even more."},{"da":"Jeg indstiller lygtehøjden, så de modkørende ikke bliver blændet.","fa":"ارتفاع چراغ‌ها را تنظیم می‌کنم تا رانندگان روبه‌رو خیره نشوند.","ok":1,"eda":"Ja. Lygter må ikke bruges, så andre førere kan blændes.","efa":"بله. از چراغ‌ها نباید طوری استفاده کرد که رانندگان دیگر خیره شوند.","en":"I adjust the headlight height so that oncoming drivers are not dazzled.","een":"Yes. Lights must not be used in a way that can dazzle other drivers."},{"da":"Jeg dækker lygterne delvis med tape.","fa":"چراغ‌ها را تا حدی با چسب می‌پوشانم.","ok":0,"eda":"Nej. Det ændrer lyset og gør bilen dårligere at se; brug lygtehøjdeindstillingen.","efa":"خیر. این کار نور را تغییر می‌دهد و دیدن خودرو را سخت‌تر می‌کند؛ از تنظیم ارتفاع چراغ استفاده کنید.","en":"I partly cover the lights with tape.","een":"No. That changes the light and makes the car harder to see; use the headlight levelling control."},{"da":"Det har ingen betydning, når jeg kører med nærlys.","fa":"وقتی با نور پایین می‌رانم، اهمیتی ندارد.","ok":0,"eda":"Nej. Nærlys, der peger for højt, kan blænde lige så meget som fjernlys.","efa":"خیر. نور پایینی که زیادی بالا بتابد، می‌تواند به اندازه‌ی نور بالا خیره کند.","en":"It makes no difference when I am driving with dipped beam.","een":"No. Dipped beam pointing too high can dazzle as much as high beam."}]},{"id":5199,"img":"newq-art/5199.png","c":"7.7","sda":"Vejen er smal, og en bus kommer imod dig. Rabatten i din side er blød. Hvordan forholder du dig?","sfa":"جاده باریک است و اتوبوسی از روبه‌رو می‌آید. شانه‌ی خاکی سمت شما نرم است. چه می‌کنید؟","sen":"The road is narrow, and a bus is coming towards you. The verge on your side is soft. What do you do?","st":[{"da":"Bussen skal bakke, fordi den er størst.","fa":"اتوبوس باید دنده‌عقب برود، چون بزرگ‌تر است.","ok":0,"eda":"Nej. Der er ingen sådan regel; find sammen den sikreste løsning.","efa":"خیر. چنین قاعده‌ای نیست؛ با هم ایمن‌ترین راه را پیدا کنید.","en":"The bus must reverse because it is the biggest.","een":"No. There is no such rule; find the safest solution together."},{"da":"Jeg standser om nødvendigt ved den faste plads og lader bussen passere.","fa":"در صورت لزوم در جای سفت می‌ایستم و می‌گذارم اتوبوس رد شود.","ok":1,"eda":"Ja. Det er sikrere at vente på et fast sted end at køre ud i en blød rabat.","efa":"بله. صبر کردن در جای سفت ایمن‌تر از رفتن به شانه‌ی نرم است.","en":"If necessary I stop at the firm place and let the bus pass.","een":"Yes. It is safer to wait in a firm place than to drive onto a soft verge."},{"da":"Jeg kører ud i den bløde rabat i fuld fart for at give plads.","fa":"با سرعت کامل به شانه‌ی نرم می‌روم تا جا باز کنم.","ok":0,"eda":"Nej. I en blød rabat kan bilen skride ud eller køre i grøften.","efa":"خیر. در شانه‌ی نرم ممکن است خودرو بلغزد یا به گودال برود.","en":"I drive onto the soft verge at full speed to make room.","een":"No. On a soft verge the car may skid or end up in the ditch."},{"da":"Jeg sænker farten og holder så langt til højre, som det kan ske sikkert.","fa":"سرعتم را کم می‌کنم و تا جایی که ایمن باشد سمت راست می‌مانم.","ok":1,"eda":"Ja. Ved møde på smal vej skal hastigheden være passende lav, og du skal holde til højre.","efa":"بله. هنگام برخورد در جاده‌ی باریک سرعت باید به اندازه‌ی کافی کم باشد و باید سمت راست بمانید.","en":"I slow down and keep as far to the right as it can be done safely.","een":"Yes. When meeting on a narrow road your speed must be suitably low, and you must keep right."}]},{"id":5200,"img":"newq-art/5200.png","c":"7.7","sda":"Før en smal bro står denne tavle. Hvad gælder?","sfa":"پیش از یک پل باریک این تابلو هست. چه قاعده‌ای برقرار است؟","sen":"This sign stands before a narrow bridge. What applies?","st":[{"da":"Jeg kører alligevel forsigtigt og er klar til at standse, hvis en modkørende allerede er på broen.","fa":"با این حال با احتیاط می‌رانم و اگر وسیله‌ای از روبه‌رو روی پل باشد، آماده‌ی ایستادنم.","ok":1,"eda":"Ja. En, der allerede er på broen, kan ikke vige.","efa":"بله. کسی که روی پل است، نمی‌تواند کنار برود.","en":"I still drive carefully and am ready to stop if an oncoming vehicle is already on the bridge.","een":"Yes. Someone already on the bridge cannot make way."},{"da":"Jeg skal holde tilbage for de modkørende.","fa":"باید به ترافیک روبه‌رو راه بدهم.","ok":0,"eda":"Nej. Det er tavlen med rød kant og en rød pil op (B 18), der betyder det.","efa":"خیر. تابلوی با حاشیه‌ی قرمز و فلش قرمز رو به بالا (B 18) این معنا را دارد.","en":"I must give way to oncoming traffic.","een":"No. It is the sign with a red border and a red arrow up (B 18) that means that."},{"da":"De modkørende skal holde tilbage for mig.","fa":"ترافیک روبه‌رو باید به من راه بدهد.","ok":1,"eda":"Ja. Tavlen (B 19) betyder, at den modkørende færdsel skal holde tilbage.","efa":"بله. این تابلو (B 19) یعنی ترافیک روبه‌رو باید راه بدهد.","en":"Oncoming traffic must give way to me.","een":"Yes. The sign (B 19) means that oncoming traffic must give way."},{"da":"Tavlen betyder, at broen er ensrettet.","fa":"این تابلو یعنی پل یک‌طرفه است.","ok":0,"eda":"Nej. Der er trafik i begge retninger; tavlen siger, hvem der skal vente.","efa":"خیر. ترافیک در هر دو جهت است؛ تابلو می‌گوید چه کسی باید صبر کند.","en":"The sign means that the bridge is one-way.","een":"No. There is traffic in both directions; the sign says who must wait."}]}]};
